locale "zh_hant"
------------------------------------------------
section "tome-orcs/data/achievements/special.lua"

t("No mercy!", "心狠手辣！", "achievement name")
t("Killed 1000 steam giants civilians.", "殺死 1000 名蒸汽巨人居民。", "_t")
t("Mercy, mercy!", "慈悲爲懷", "achievement name")
t("Killed Talosis without any civilians deaths.", "殺死泰勒西斯但不殺死其他居民。", "_t")
t("This will make a big Omelette!", "搞個大傢伙！", "achievement name")
t("Collected 40 ritch eggs in the Ritch Hive.", "收集 40 枚裏奇蛋", "_t")
t("An Other Brick in the Wall", "特立獨行", "achievement name")
t("Defeated Aeryn in the Gates of Morning without destroying the Observatory nor using ritches help.", "在晨曦之門打敗艾琳，但不摧毀觀星臺，也不借助裏奇的幫助。", "_t")
t("No Steam, No Palace. No Palace, No Palace!", "若無蒸汽，則無宮殿。若無宮殿，亦無宮殿！", "achievement name")
t("Destroyed the Palace of Fumes without first destroying the geothermal valves in the Steam Quarry.", "在不摧毀蒸汽閥的情況下摧毀煙霧宮殿。", "_t")
t("Here, I Think You Dropped This", "這是你掉的麼？", "achievement name")
t("Killed Ureslak the Eternal while wielding Ureslak's Femur.", "拿着烏瑞斯拉克的大腿打敗永恆的烏瑞斯拉克。", "_t")
t("Do not go gentle into that good night", "不要溫和地走進那個良夜", "achievement name")
t("Trapped John.", "捕獲約翰。", "_t")
t("I did not want that!", "非我本意", "achievement name")
t("Tricked Nektosh into killing one of his own people.", "令獨角者納克託什誤殺己方。", "_t")
t("We weren't kidding!", "認真點，這不是個玩笑！", "achievement name")
t("Die to Nektosh's beam without being pinned, stunned, asleep, dazed, or confused.", "在沒有被定身、震懾、沉睡、眩暈或混亂的情況下，被獨角者納克託什的光束殺死。", "_t")
t("Make Him Squirm", "榨乾他", "achievement name")
t("Made Nektosh use up the last of his power, then left the area and ignored him until beating the game. The other Whitehooves will catch on any second now...", "讓納克託什用盡能量，然後離開區域並無視他，直到勝利爲止。  The other Whitehooves will catch on any second now...", "_t")
t("True Savior", "真正的救星", "achievement name")
t("Freed all the Orc Prides without killing a single mind-controlled orc.", "釋放所有獸人部落，並且不殺死任何一名被精神控制的獸人。", "_t")
t("Mender", "修理工", "achievement name")
t("Destroyed the bosses of the Primal Forest without killing any uncorrupted treants.", "殺死原始森林的boss，同時不殺死任何一名未腐化的樹精。", "_t")
t("Sufficiently Advanced Technology", "高科技", "achievement name")
t("Put five points into each of the tinker-crafting talents as any mage class.", "作爲任何法師職業，將每個蒸汽配件製造技能均投入5點技能點數。", "_t")
t("Radiant Horrorc", "光明剋星", "achievement name")
t("While fighting in a Sunwall zone, use a Fiery Salve to reach at least 66% affinity for Fire and Light. Pointing and laughing is optional.", "在晨曦之門的區域內戰鬥時，開啓烈火藥劑，並獲得至少 66% 火焰和光明吸收。", "_t")
t("Blood on the Moon", "月上血痕", "achievement name")
t("Kill all of the Star Gazers within 7 game turns.", "7個遊戲回合內擊殺所有觀星者。", "_t")
t("Once Upon A Time, In the West...", "很久很久以前，在西方...", "achievement name")
t("Hear the Eidolon's retelling of the Scourge from the West's journey.", "聽艾德隆講述西方過去的天災。", "_t")
t("A Fistful of Gold", "一大堆金幣", "achievement name")
t("Buy an item from an AAA.", "從 AAA 買東西。", "_t")
t("For a Few Gold More", "更多金幣", "achievement name")
t("Completely deplete an AAA's stock.", "清空一個AAA的庫存。", "_t")
t("The Good, The Bad, and The Yeti", "紅與黑，與雪人", "achievement name")
t("Use mind-controlled yetis to kill 30 foes.", "使用被精神控制的雪人，擊殺30名敵人。", "_t")
t("Total Annihilation: Redundancy", "完全殲滅：重置版", "achievement name")
t("Wield the Annihilator as an Annihilator.", "作爲殲滅者（職業），裝備殲滅者（武器）", "_t")

------------------------------------------------
section "tome-orcs/data/achievements/story.lua"

t("Across the Narrow Sea", "跨越狹海", "achievement name")
t("Destroyed the Sunwall Outpost to secure a way to the mainland.", "消滅太陽堡壘前哨站，拯救通向大陸的道路。", "_t")
t("Reclaiming Garkul's Heritage", "加庫爾之遺產", "achievement name")
t("Freed the remnants of the Prides from the Internment Camp.", "釋放拘留營中的部落成員。", "_t")
t("The High Lady's Destiny (Finale)", "艾琳的隕落", "achievement name")
t("Crushed High Sun Paladin Aeryn and with her destroyed the bastion of the Sunwall.", "殺死太陽騎士艾琳，並摧毀晨曦之門。", "_t")
t("One Ill Turn Deserves Another", "以眼還眼", "achievement name")
t("The Palace of Fumes stands in ruins, its Council shattered. The Atmos Tribe will not bother the Prides anymore.", "煙霧宮殿被摧毀，議會分崩離析。氣之部族不再威脅你的部落。", "_t")
t("The Dead God Rests", "亡神沉眠", "achievement name")
t("You have defeated the Sher'tul Priest trying to resurrect Amakthel, saving both the Prides and the world.", "你消滅了試圖復活阿馬克泰爾的夏·圖爾牧師，拯救了部落和世界！", "_t")
t("To the Bitter End", "直至最後", "achievement name")
t("You have destroyed the last remnants of the Atmos Tribe, ending their civilization.", "你消滅了氣之部族的最後成員，終結了他們的文明。", "_t")
t("Imp'ing Away", "飛走的小鬼", "achievement name")
t("You have spared the last remnants of the Atmos Tribe, showing mercy where others gave none to the orcs.", "你拯救了氣之部落的最後成員，展現了獸人未曾得到的仁慈。", "_t")

------------------------------------------------
section "tome-orcs/data/birth/classes/empyreal.lua"

t("Empyreal", "高天者", "birth descriptor name")
t("Their most important stats are: Magic and Constitution", "他們最重要的屬性是：魔法和體質。", "_t")
t("#GOLD#Stat modifiers:", "#GOLD# 屬性修正：", "_t")
t("#LIGHT_BLUE# * +0 Strength, +0 Dexterity, +3 Constitution", "#LIGHT_BLUE# * +0 力量 , +0 敏捷 , +3 體質", "_t")
t("#LIGHT_BLUE# * +6 Magic, +0 Willpower, +0 Cunning", "#LIGHT_BLUE# * +6 魔法, +0 意志, +0 靈巧", "_t")
t("#GOLD#Life per level:#LIGHT_BLUE# +0", "#GOLD# 每等級生命加值： #LIGHT_BLUE# +0", "_t")

------------------------------------------------
section "tome-orcs/data/birth/classes/tinker.lua"

t("Tinker", "工匠系", "birth descriptor name")
t("Tinkers use steamtech to power their attacks, defenses, ...", "工程師們使用蒸汽科技來強化攻擊、防禦，……", "_t")
t("Build, experiment, discover. The path of inventions is never over!", "製造、實驗、發現。創造之路永無止境！", "_t")
t("%s healing salve", "%s 治療藥劑", "tformat")
t("simple", "簡單的", "_t")
t("%s frost salve", "%s 寒霜藥劑", "tformat")
t("Sawbutcher", "鏈鋸屠夫", "birth descriptor name")
t("A formidable behemoth of war using steamsaws to improve his deadliness.", "可怕的戰爭巨獸，使用蒸汽鏈鋸增加致命殺傷力。", "_t")
t("Their most important stats are: Strength and Cunning", "他們最重要的屬性是：力量和靈巧", "_t")
t("#GOLD#Stat modifiers:", "#GOLD# 屬性修正：", "_t")
t("#LIGHT_BLUE# * +5 Strength, +0 Dexterity, +1 Constitution", "#LIGHT_BLUE# * +5 力量 , +0 敏捷 , +1 體質", "_t")
t("#LIGHT_BLUE# * +0 Magic, +0 Willpower, +3 Cunning", "#LIGHT_BLUE# * +0 魔法 , +0 意志 , +3 靈巧", "_t")
t("#GOLD#Life per level:#LIGHT_BLUE# 2", "#GOLD#每等級生命加值:#LIGHT_BLUE# 2", "_t")
t("Gunslinger", "槍手", "birth descriptor name")
t("A tinker who dual-wields steamguns to great effect.", "雙持蒸汽槍的工程師。", "_t")
t("Their most important stats are: Cunning and Dexterity", "他們最重要的屬性是：靈巧和敏捷", "_t")
t("#LIGHT_BLUE# * +0 Strength, +4 Dexterity, +1 Constitution", "#LIGHT_BLUE# * +0 力量, +4 敏捷, +1 體質", "_t")
t("#LIGHT_BLUE# * +0 Magic, +0 Willpower, +4 Cunning", "#LIGHT_BLUE# * +0 魔法, +0 意志, +4 靈巧", "_t")
t("#GOLD#Life per level:#LIGHT_BLUE# -1", "#GOLD# 每等級生命加值： #LIGHT_BLUE# -1", "_t")
t("Psyshot", "靈能射手", "birth descriptor name")
t("Bend the mind, bend the tech. All around inspire dread.", "扭曲精神，扭曲科技，一切都是爲了激發恐懼。", "_t")
t("Powerful psionics are able to enter a gestalt with steam generators and technology to enhance their own mental prowess.", "強大的靈能能進入蒸汽科技的格式塔中，以增強其金屬力量。", "_t")
t("The Psyshot combines this ability to gestalt to enhance his mindstar all the while shooting her steamgun to devastate the enemy lines.", "念力射手將這項能力與格式塔結合，來強化靈晶的力量，同時使用蒸汽槍毀滅敵人。", "_t")
t("Their most important stats are: Cunning, Willpower and Dexterity", "他們最重要的屬性是：靈巧、意志和敏捷", "_t")
t("#LIGHT_BLUE# * +0 Strength, +3 Dexterity, +0 Constitution", "#LIGHT_BLUE# * +0 力量 , +3 敏捷 , +0 體質", "_t")
t("#LIGHT_BLUE# * +0 Magic, +3 Willpower, +3 Cunning", "#LIGHT_BLUE# * +0 魔法, +3 意志, +3 靈巧", "_t")
t("Annihilator", "殲滅者", "birth descriptor name")
t("The Annihilator is a master of destruction, wielding the most devastating steamtech inventions to lay waste to their foes.", "殲滅者是破壞的大師，他們掌握着最具破壞力的蒸汽科技成果，可以給他們的敵人帶來無盡的毀滅。", "_t")
t("While normally wielding a steamgun loaded with experimental ammunition and an electrically charged shield, they can equip heavy weapons such as flamethrowers.", "他們通常裝備着裝載着實驗性彈藥的蒸汽槍和一面電力充能的盾牌，但他們也可以裝備像火焰噴射器那樣的重裝武器。", "_t")
t("More adept at technology than most other tinkers, they supplement their weapons with automated turrets, mechanical minions and other such devices.", "他們比其他的工匠更加精通科學技術，他們使用自動炮臺、機械隨從和各種各樣的強大發明來充實自己的武器庫。", "_t")
t("#LIGHT_BLUE# * +0 Strength, +4 Dexterity, +0 Constitution", "#LIGHT_BLUE# * +0 力量 , +4 敏捷 , +0 體質", "_t")
t("#LIGHT_BLUE# * +0 Magic, +0 Willpower, +5 Cunning", "#LIGHT_BLUE# * +0 魔法 , +0 意志 , +5 靈巧", "_t")
t("Research. Tinker. Annihilate.", "研究。製造。殲滅。", "_t")

------------------------------------------------
section "tome-orcs/data/birth/races/orc.lua"

t("Skin", "皮膚", "birth facial category")
t("Facial features", "臉部特徵", "birth facial category")
t("Tatoos", "紋身", "birth facial category")
t("Horns", "角", "birth facial category")
t("Special", "特殊", "birth facial category")
t("Orc", "獸人", "birth descriptor name")
t("Orcs have a long and sad history. They are seen, and are, as an aggressive race that more than one time managed to imperil all of Maj'Eyal.", "獸人擁有久遠而悲傷的歷史。他們是，而且被見證爲多次試圖統治埃亞爾世界的侵略性種族。", "_t")
t("But one year ago the Scourge from the West came and wiped four of the five Prides. And a hundred years ago King Toknor wiped all traces of orcs from Maj'Eyal.", "但是一年前，西方來的災星消滅了四個部落。一百年前，圖庫納國王消滅了馬基埃亞爾本土的所有獸人。", "_t")
t("The orc race is dangerously on the brink of destruction. One wrong move is all that is needed.", "獸人種族處於滅絕邊際，僅僅一步之遙。", "_t")
t("But they are strong and will face whatever is needed to ensure a future of their own!", "但他們意志強大，敢於直面任何磨難，來創造屬於他們的未來！", "_t")
t("Skin Color 1", "皮膚顏色1", "_t")
t("Skin Color 2", "皮膚顏色2", "_t")
t("Skin Color 3", "皮膚顏色3", "_t")
t("Skin Color 4", "皮膚顏色4", "_t")
t("Skin Color 5", "皮膚顏色5", "_t")
t("Demonic Red Skin", "惡魔紅皮膚", "_t")
t("Goggles 1", "護目鏡1", "_t")
t("Goggles 2", "護目鏡2", "_t")
t("Goggles 3", "護目鏡3", "_t")
t("Goggles 4", "護目鏡4", "_t")
t("Jaws 1", "下顎1", "_t")
t("Jaws 2", "下顎2", "_t")
t("Mechbiter 1", "機械牙1", "_t")
t("Mechbiter 2", "機械牙2", "_t")
t("Monocle Left 1", "左側單片眼鏡1", "_t")
t("Monocle Left 2", "左側單片眼鏡2", "_t")
t("Monocle Right 1", "右側單片眼鏡1", "_t")
t("Monocle Right 2", "右側單片眼鏡2", "_t")
t("Tatoos 1", "紋身1", "_t")
t("Tatoos 2", "紋身2", "_t")
t("Tatoos 3", "紋身3", "_t")
t("Demonic Horns 1", "惡魔角1", "_t")
t("Demonic Horns 2", "惡魔角2", "_t")
t("Demonic Horns 3", "惡魔角3", "_t")
t("Demonic Horns 4", "惡魔角4", "_t")
t("Demonic Horns 5", "惡魔角5", "_t")
t("Demonic Horns 6", "惡魔角6", "_t")
t("Demonic Horns 7", "惡魔角7", "_t")
t("Demonic Horns 8", "惡魔角8", "_t")
t("Bikini / Mankini", "比基尼/男性比基尼", "_t")
t("They possess the #GOLD#Orcish Fury#WHITE# which allows them to increase all their damage for a few turns.", "他們擁有 #GOLD#獸人之怒#WHITE# ，讓他們能在幾回合內增加傷害。", "_t")
t("#GOLD#Stat modifiers:", "#GOLD# 屬性修正：", "_t")
t("#LIGHT_BLUE# * +2 Strength, +1 Dexterity, +1 Constitution", "#LIGHT_BLUE# * +2 力量, +1 敏捷, +1 體質", "_t")
t("#LIGHT_BLUE# * -1 Magic, +1 Willpower, +1 Cunning", "#LIGHT_BLUE# * -1 魔法, +1 意志, +1 靈巧", "_t")
t("#GOLD#Life per level:#LIGHT_BLUE# 12", "#GOLD# 每等級生命加值： #LIGHT_BLUE# 12", "_t")
t("#GOLD#Experience penalty:#LIGHT_BLUE# 12%", "#GOLD#經驗懲罰： #LIGHT_BLUE# 12%", "_t")

