section "tome-orcs/data/birth/races/whitehooves.lua"

t("Skin", "皮膚", "birth facial category")
t("Facial features", "臉部特徵", "birth facial category")
t("Horns", "角", "birth facial category")
t("Special", "特殊", "birth facial category")
t("Undead", "不死族", "_t")
t("Grave strength, dread will, this flesh cannot stay still. Kings die, masters fall, we will outlast them all.", "死亡的力量，恐懼的意志，這些肉體不會沉寂。國王去世，主人隕落，我們纔是永生。", "_t")
t("Undead are humanoids (Humans, Elves, Dwarves, ...) that have been brought back to life by the corruption of dark magics.", "不死族是被黑暗魔法復活的人形生物（人類，精靈，矮人…）。", "_t")
t("Undead can take many forms, from ghouls to vampires and liches.", "不死族有多種形態，從食屍鬼、吸血鬼到巫妖。", "_t")
t("Skin Color 1", "皮膚顏色1", "_t")
t("Skin Color 2", "皮膚顏色2", "_t")
t("Skin Color 3", "皮膚顏色3", "_t")
t("Skin Color 4", "皮膚顏色4", "_t")
t("Skin Color 5", "皮膚顏色5", "_t")
t("Skin Color 6", "皮膚顏色6", "_t")
t("Skin Color 7", "皮膚顏色7", "_t")
t("Demonic Red Skin", "惡魔紅皮膚", "_t")
t("Beard 1", "絡腮鬍1", "_t")
t("Beard 2", "絡腮鬍2", "_t")
t("Redhead Beard", "紅色絡腮鬍", "_t")
t("Hair 1", "髮型1", "_t")
t("Hair 2", "髮型2", "_t")
t("Hair 3", "髮型3", "_t")
t("Hair 4", "髮型4", "_t")
t("Redhead Hair 1", "紅髮1", "_t")
t("Redhead Hair 2", "紅髮2", "_t")
t("Horns 1", "長角1", "_t")
t("Horns 2", "長角2", "_t")
t("Horns 3", "長角3", "_t")
t("Horns 4", "長角4", "_t")
t("Demonic Horns 1", "惡魔角1", "_t")
t("Demonic Horns 2", "惡魔角2", "_t")
t("Demonic Horns 3", "惡魔角3", "_t")
t("Demonic Horns 4", "惡魔角4", "_t")
t("Demonic Horns 5", "惡魔角5", "_t")
t("Demonic Horns 6", "惡魔角6", "_t")
t("Demonic Horns 7", "惡魔角7", "_t")
t("Demonic Horns 8", "惡魔角8", "_t")
t("Bikini / Mankini", "比基尼/男性比基尼", "_t")
t("Whitehoof", "白蹄", "birth descriptor name")
t("A clan of minotaurs turned to necromancy when faced with imminent destruction.", "一族米諾陶在面臨迫在眉睫的滅亡危機下，轉化爲了不死族。", "_t")
t("Whitehooves are resilient and magic imbued undead, hardened by their trials and made stronger by their undeath.", "白蹄族是強韌而充滿魔法力量的亡靈，因試驗而硬化，因不死而強大。", "_t")
t("They now seek to help their orc allies, in hope they will help them back.", "他們現在試圖幫助獸人盟友，希望獸人能幫他們回來。", "_t")
t("They have access to #GOLD#special talents#WHITE# and a wide range of undead abilities:", "他們擁有 #GOLD# 特殊天賦 #WHITE# 和一系列不死族能力：", "_t")
t("- silence resistance", "- 沉默抗性", "_t")
t("- bleeding immunity", "- 流血免疫", "_t")
t("- fear immunity", "- 恐懼免疫", "_t")
t("- no need to breathe", "- 不需要呼吸", "_t")
t("- special whitehoof talents: dead hide, lifeless rush, essence drain", "- 特殊白蹄天賦: 亡者之皮，無生突襲，吸取精華。", "_t")
t("#GOLD#Stat modifiers:", "#GOLD# 屬性修正：", "_t")
t("#LIGHT_BLUE# * +3 Strength, -1 Dexterity, +2 Constitution", "#LIGHT_BLUE# * +3 力量, -1 敏捷, +2 體質", "_t")
t("#LIGHT_BLUE# * +2 Magic, -3 Willpower, +1 Cunning", "#LIGHT_BLUE# * +2 魔法, -3 意志, +1 靈巧", "_t")
t("#GOLD#Life per level:#LIGHT_BLUE# 14", "#GOLD# 每等級生命加值： #LIGHT_BLUE# 14", "_t")
t("#GOLD#Experience penalty:#LIGHT_BLUE# 15%", "#GOLD#經驗懲罰： #LIGHT_BLUE# 15%", "_t")

