t("Beard 1", "絡腮鬍1", "_t")
t("Beard 2", "絡腮鬍2", "_t")
t("Beard 3", "絡腮鬍3", "_t")
t("Eyebrows", "眉毛", "_t")
t("Fangs", "尖牙", "_t")
t("Mustache", "八字鬍", "_t")
t("Demonic Horns 1", "惡魔角1", "_t")
t("Demonic Horns 2", "惡魔角2", "_t")
t("Demonic Horns 3", "惡魔角3", "_t")
t("Demonic Horns 4", "惡魔角4", "_t")
t("Demonic Horns 5", "惡魔角5", "_t")
t("Demonic Horns 6", "惡魔角6", "_t")
t("Demonic Horns 7", "惡魔角7", "_t")
t("Demonic Horns 8", "惡魔角8", "_t")
t("Bikini / Mankini", "比基尼/男性比基尼", "_t")
t("Kruk Yeti", "克魯克雪人", "birth descriptor name")
t("Yetis are a towering mass of muscle. While normal yetis are non-sentient beasts this kind is special.", "雪人族具有強大的肉體。通常，他們只是無知覺的野獸，但這種有所不同。", "_t")
t("A few orcs of the Kruk pride have mastered techno-psionics, allowing them to literally hijack a yeti's mind and transfer their own mind inside.", "少數克魯克部落的獸人掌握了靈能，讓他們能操控雪人族的思維，並用自己的意志取代。", "_t")
t("Doing so drains their old knowledge and they need to start afresh, gaining considerable strength in the process; for the good of the Prides.", "這樣做的話，他們舊的知識將失去效力，必須重新開始，在這個過程中他們能獲得強大力量。", "_t")
t("They possess the #GOLD#Algid Rage#WHITE# talent which allows them to encase their foes in blocks of ice.", "他們擁有 #GOLD# 寒冰之怒 #WHITE# 技能，讓他們能將敵人封在冰塊中。", "_t")
t("#GOLD#Stat modifiers:", "#GOLD# 屬性修正：", "_t")
t("#LIGHT_BLUE# * +5 Strength, -3 Dexterity, +4 Constitution", "#LIGHT_BLUE# * +5 力量, -3 敏捷, +4 體質", "_t")
t("#LIGHT_BLUE# * +0 Magic, +1 Willpower, -1 Cunning", "#LIGHT_BLUE# * +0 魔法, +1 意志, -1 靈巧", "_t")
t("#GOLD#Life per level:#LIGHT_BLUE# 13", "#GOLD# 每等級生命加值： #LIGHT_BLUE# 13", "_t")
t("#GOLD#Experience penalty:#LIGHT_BLUE# 12%", "#GOLD#經驗懲罰： #LIGHT_BLUE# 12%", "_t")

------------------------------------------------
section "tome-orcs/data/birth/worlds.lua"

t("Orcs: Embers of Rage", "獸人戰役：餘燼怒火", "_t")
t("The Prides lie in ruins!", "榮耀毀於一旦！", "_t")
t("The Sorcerers have been defeated!", "法師慘遭失敗！", "_t")
t("Orcs in all Var'Eyal are in dismay, hunted by the Sunwall and their newfound allies from the west.", "埃亞爾大陸的獸人們驚慌失措，被晨曦之門和他們新的東方盟友追獵。", "_t")
t("The Scourge from the West is back in the west, but her legacy stays strong: the orc race is once again upon the brink of destruction!", "西方的災星來自西方，又迴歸西方，但她帶來的後遺症如此強大：整個獸人種族再次來到滅亡邊際", "_t")
t("But not all hope is lost.", "即使如此，希望仍存。", "_t")
t("On the isolated Clork Peninsula lies the fifth pride: Kruk's Pride; unseen and unharmed by the Scourge.", "在與世隔絕的克洛爾克半島上棲息着獸人第五部落：克魯克部落；他們並沒有被這場災難傷害。", "_t")
t("Yet not all is great there either, the Sunwall offensive has set up an outpost blocking the way to the mainland.", "不幸的是，晨曦之門建立了前哨站阻斷了通向大陸的道路。", "_t")
t("But the worst threat comes from the peninsula itself, the main inhabitants are not the orcs, but the Atmos Tribe.", "然而，最大的威脅來自半島本身。島上的主要居民並非獸人，而是氣之部落。", "_t")
t("A civilization of steam giants whose mastery of steamtech makes them incredible foes.", "蒸汽巨人的文明掌控蒸汽科技，他們是無比強大的敵人。", "_t")
t("Play an orc, prove your worth! Use steamtech against the giants, reclaim the far east and free it from Sunwall scum!", "用獸人種族進行遊戲，證明你的價值！使用蒸汽科技對抗巨人，回到遠東，並將其從晨曦之門手中奪回！", "_t")
t("Craft your own steamsaws, rocket boots, steam powered armours, and all kind of steamy technology!", "製造自己的蒸汽鋸，火箭靴，蒸汽護甲，以及其他各式各樣的蒸汽科技！", "_t")
t("This is your destiny! For Garkul's Legacy, for the Glory of the Pride!", "這是你的天命！爲了加庫爾的遺產，爲了部落的榮耀！", "_t")

------------------------------------------------
section "tome-orcs/data/chats/aaa.lua"

t("#LIGHT_GREEN#*Before you stands a strange triangular device, some kind of automated storage facility.*#WHITE#", "#LIGHT_GREEN#*你面前有一個奇怪的三角形設備，似乎是某種自動存儲設施。*#WHITE#", "_t")
t("[access store]", "[進入商店]", "_t")
t("[reprogram it to order it to relocate to Kruk Pride]", "[改寫程序，令其遷移至克魯克部落]", "_t")
t("[leave]", "[離開]", "_t")
t("#LIGHT_GREEN#*You tinker with the store bot and manage to activate the relocation function.*#WHITE#", "#LIGHT_GREEN#*你操作了商店設備，執行了遷移程序。*#WHITE#", "_t")
t("[order it to go to Kruk Pride]", "[目的地：克魯克部落]", "_t")

------------------------------------------------
section "tome-orcs/data/chats/aaf.lua"

t([[#LIGHT_GREEN#*Before you stands a strange triangular device, some kind of automated facility.*#WHITE#
It seems to be able to teach you the tinker crafting techniques, but requires input to do so (500 gold and a talent category point).]], [[#LIGHT_GREEN#*你面前有一個奇怪的三角形設備，似乎是某種自動設施。*#WHITE#
	似乎它能教授你製造配件的技巧，但需要你一些投入（500金幣+一點大系點）。]], "_t")
t("[pay 500 gold and a talent category points]", "[支付500金幣和一點大系點]", "_t")
t("#PURPLE#The %s teaches you: #GOLD#Steamtech/Physics#LAST#, #GOLD#Steamtech/Chemistry#LAST# and two starter crafting talents.", "#PURPLE#%s教會你: #GOLD#蒸汽/機械#LAST#, #GOLD#蒸汽/藥劑#LAST#和兩項基礎技能。", "log")
t("[access store]", "[進入商店]", "_t")
t("[leave]", "[離開]", "_t")
t([[The machine gives you a small metallic box labelled as #{italic}#"Automated Portable Extractor"#{normal}#.
It seems to be used to break down metallic items into lumps of metal and infusions into herbs which are used to craft tinkers.

#{bold}#You will have to choose to use it or the Transmogrification Chest when you destroy items. You can choose the default one by using it with no items to destroy.#{normal}#
]], [[機械交給你一個小金屬盒，上面寫着 #{italic}#"便攜式自動提取儀"#{normal}#.
它似乎能將金屬物品轉化爲鐵塊，將紋身轉化爲植物。

#{bold}#你可以選擇使用它或者轉化之盒。在裏面沒有物品時使用它則設置爲默認使用。#{normal}#
]], "_t")
t("[take it]", "[拿走]", "_t")

------------------------------------------------
section "tome-orcs/data/chats/destructicus-lead.lua"

t([[#LIGHT_GREEN#*Several loyal Orcs are eagerly waiting outside the palace to meet you; one steps forward, handing you a set of keys.  The word 'DESTRUCTICUS' is etched into one.*#WHITE#
Chief @playername@!  The Giants are fleeing, and we intercepted a scout carrying this!  We believe they can be used with...  well, you should see for yourself!  Please, come with us to the mountains just south of Kruk Pride!
#LIGHT_GREEN#*This sounds important.  You should probably head there right away!*#WHITE#]], [[#LIGHT_GREEN#*數名忠誠的獸人在宮殿外焦急地等待着你;其中一名獸人走上前，交給你一串鑰匙，上面寫着'毀滅號'。*#WHITE#
@playername@首領! 巨人們在逃跑，我們抓住了一名偵查兵，他身上帶着這個!我們認爲它是用於... 算了，您應該親自來看看! 請跟我來，在部落南部的山脈裏!
#LIGHT_GREEN#*這聽起來非常重要，你應該馬上過去*#WHITE#]], "_t")
t("Lead the way.", "帶路吧。", "_t")

------------------------------------------------
section "tome-orcs/data/chats/destructicus.lua"

t("DESTRUCTICUS!", "“毀天滅地！”", "_t")
t("Fire Imp", "火焰小鬼", "_t")
t("Steam Giant Airship", "蒸汽巨人飛船", "_t")
t("#LIGHT_GREEN#*#{bold}#DESTRUCTICUS, IMPOLITE PENETRATOR OF THE SKY#{normal}# stands before you, and as much as it pains you to admit it, Kaltor's advertisement wasn't flattering enough.  This may be the most unreasonably lethal device you've ever seen.  The sunlight, gleaming off its voratun body, seems dull compared to the intensely glowing mass of unstable runes on its tip; its surface has the ornate grooves of a metal that has been psionically reforged through hours of migraine-inducing concentration.  The bayonet mounted on the launching tube just seems like gloating.  This particular model appears to be equipped with an enclosed, fireproof booth around its control panel, and a built-in tea dispenser in said booth, which your fellow orcs have already taken the liberty of filling with looted Dwarven ale.  It is truly a thing of beauty.*#WHITE#", "#LIGHT_GREEN#*#{bold}#裂天者 毀滅號#{normal}# 站在你面前，讓你痛苦地承認，卡托爾的廣告並不全是垃圾。這是你見過的最無端致命的設備。陽光照耀在它的沃瑞鉭軀殼上，在它邊緣上鑲嵌的強大而不穩定的符文面前黯然失色;它的表面有着金屬歷經數個小時精心打磨而成的華麗溝槽，在發射管上搭載的刺刀能輕盈地上下游走。控制組件上環繞着一層密封的防火隔間，操作室內建的自動飲水機還能提供矮人的佳釀。這簡直就是美的化身。*#WHITE#", "_t")
t("[continue]", "[繼續]", "_t")
t("#LIGHT_GREEN#*You enter the booth, sit down, and insert the key.  #{bold}#DESTRUCTICUS, IMPOLITE PENETRATOR OF THE SKY#{normal}# whirrs to life, its base slightly rotating underneath you.  A strange beaded panel slides in front of you, pins pushing out and pulling back by magnetic force to display the outline of an airship (and a tiny speck), and the words #{italic}#\"AERIAL TARGETS FOUND: 2.\"#{normal}#*#WHITE#", "#LIGHT_GREEN#*你進入了操作室，坐好，插入鑰匙。#{bold}#裂天者 毀滅號#{normal}# 啓動了它的生命,它的基座開始運轉。一塊奇怪的珍珠板從你前方滑過，針伸了出來，被電磁力量控制，顯示出飛船的輪廓（以及一個小黑點）與以下短語：#{italic}#“發現空中目標-數目：2”。#{normal}#*#WHITE#", "_t")
t([[#LIGHT_GREEN#*#{italic}#"OBTAINING SCRYING LOCK...  OBTAINED."#{normal}#
 
The beaded panel is suddenly awash with colors, showing the colossal interior of the airship.  Steam Giant families huddle and weep, sorting through the few belongings they could take with them when fleeing; a guard sits on a pile of luggage and storage crates, head in her hands.  The view pans around the cabin, and you see a few crew members hurrying between the captain's quarters and the engine room, pausing to take worried glances out the window - at you.
 
This airship appears to be evacuating what's left of the Atmos Tribe.  With the press of a single button, you could eradicate the Steam Giant species forever.
 
You press a button labelled #{italic}#"SELECT NEXT TARGET"#{normal}#, and the panel shifts to show a very lost and very confused Fire Imp, flying in the air near nothing of importance.  Firing on it would have little effect whatsoever, aside from showing off DESTRUCTICUS's power in the most harmless way possible.*#WHITE#]], [[#LIGHT_GREEN#*#{italic}#"解除鎖定中...  解除成功."#{normal}#
 
珍珠面板突然充滿色彩，顯示飛船的巨大內部結構。蒸汽巨人們擁擠而哭泣，帶着少量東西逃走。一名守衛用手抱頭，坐在儲藏室前。視角切換到船艙，你看見一些成員匆忙走過船長室和引擎室，偶爾憂慮地瞥向窗外——看向你。
飛船似乎開始計算氣之部落還剩下些什麼。只要按下一個按鈕，你將能永久摧毀蒸汽巨人這個種族。

你按下按鈕 #{italic}#"選擇下個目標"#{normal}#，面板顯示出一個迷茫而混亂的火焰惡魔，在空中無害地飛舞。向他開火沒什麼意義，只是以最無害的方式炫耀毀滅號的力量。*#WHITE#]], "_t")
t("[shoot down the airship]", "[擊落飛船]", "_t")
t("[shoot down the imp]", "[擊落小鬼]", "_t")
t("#LIGHT_GREEN#*Are you SURE you want to ERADICATE THE STEAM GIANTS?*#WHITE#", "#LIGHT_GREEN#*你確認要消滅蒸汽巨人麼?*#WHITE#", "_t")
t("[back]", "[返回]", "_t")
t("#LIGHT_GREEN#*Are you SURE you want to WASTE YOUR SHOT?*#WHITE#", "#LIGHT_GREEN#*你確認要浪費子彈麼?*#WHITE#", "_t")
t([[#LIGHT_GREEN#*The Steam Giants are too great a threat to allow their escape - you will not have them simply return someday to finish what they attempted, and wipe out your Pride.  You press the #{italic}#"PREVIOUS TARGET"#{normal}# button, and fire on the airship.  There is a great roar and a flash of flame; you see its missile flying away from you through the window, as you see it racing towards your view, and the terrified passengers, on the scrying panel.

It reaches its mark, and the panel goes dark as a tremendous, multicolored blast fills your vision through the window.
 
The Steam Giants are no more.
 
The secondary charges from the warhead detonate, as burning debris falls into the sea, and the ongoing display serves as a signal to all the Orcs of Var'Eyal, and anyone else who may be watching: This is the fate of all who would try to eradicate the Orcs.  The previous millennia of oppression, genocide, and bullying are over: your people will never be pushed around like this again.
 
A nagging thought in the back of your head insists that you now know how the Sun Paladins felt, how King Toknor felt, how the halflings felt, how everyone that has always committed such atrocities against the Orcs felt.  It can keep whining all it wants - your people are finally safe.*#WHITE#]], [[#LIGHT_GREEN#*讓蒸汽巨人們逃離太過危險 - 你不能允許他們這樣簡單的離開，然後將來某日再實現其圖謀, 消滅你的部落。你按下#{italic}#"上一名目標"#{normal}# 按鈕，朝飛船開火。一陣巨大的轟鳴聲和一道強烈的火光閃過，你從窗戶裏看見導彈朝目標飛去，飛向你視線遠處，擁擠的飛船裏驚恐的乘客那邊。

導彈到達了目的地，巨大的爆炸堵塞了你透過窗戶的視線，令操作艙的光線變得黑暗低沉。

蒸汽巨人消失了。

第二發導彈帶着火光墜落大海，這場持續的煙火盛宴成爲大陸上所有獸人，甚至所有能看到這一盛景的生物的信號：
這就是所有試圖消滅獸人的種族的命運。千年的壓制、欺凌和屠殺被終結了：你的人民再也不會淪落如斯。

無法擺脫的念頭自你腦後升騰，你現在明白了太陽騎士的感受，明白了圖庫納國王的感受，明白了半身人的感受，明白了所有對曾獸人施以暴行的人的感受。
它能繼續哀訴一切————但你的人民終於安全了。*#WHITE#]], "_t")
t("[leave]", "[離開]", "_t")
t([[#LIGHT_GREEN#*No...  you will not sink to the depths that King Toknor did, that the Sun Paladins did, that so many others have sunk to.  These refugees are not a threat, and could not possibly become one for quite some time...  but it might be for the best that they're made fully aware of what you're capable of, the fate you could've given them through so little effort, and given a display that'll make sure they remember that they owe their lives to your mercy.
 
You target the Fire Imp, and fire the weapon.  With a great roar and a flash of flame, #{bold}#DESTRUCTICUS, IMPOLITE PENETRATOR OF THE SKY#{normal}# races towards the increasingly distressed imp.  It panics, flitting to the side evasively as #{bold}#DESTRUCTICUS, IMPOLITE PENETRATOR OF THE SKY#{normal}# corrects its course to compensate, until it gives up and shrugs dejectedly; you can't hear the scrying panel over the missile's roaring, but you're fairly sure you can see the imp mouthing "this is 'blazing ridiculous."
 
It impacts, and your vision is filled with an enormous, multicolored explosion.  Shrapnel and debris falls harmlessly into a barren mountaintop, and a great booming noise can be heard across the continent.  
 
Taking a swig from a freshly-dispensed mug of ale, you switch the now-empty #{bold}#DESTRUCTICUS, IMPOLITE PENETRATOR OF THE SKY#{normal}#'s targeting controls over to the airship, and you see the giants cheering and hugging, crying in joy and relief.  A few wonder aloud if you meant to do that, but most recognize it as the display of mercy that it is.
 
As the secondary charges go off, the ongoing pyrotechnic display acts as a celebratory signal to the Steam Giants, the Orcs, and anyone else who may be watching: The war is over.  Var'Eyal, and the Orcs who now own it, will know peace for the first time in millennia.*#WHITE#]], [[#LIGHT_GREEN#*不……你不會讓自己踏入那無盡的深淵，踏入那圖庫納國王、太陽騎士和所有其他人都曾陷入的深淵中。

這些難民不再是威脅，很長時間內都不可能成爲威脅……但最好能讓他們充分意識到你的力量，你本能輕易帶來的毀滅命運，向他們展示這一切，讓他們永遠銘記：他們的生死取決於你的仁慈。

你瞄準了火焰小鬼，令武器開火。巨大的轟鳴聲和火光閃過，#{bold}#裂天者 毀滅號#{normal}#朝那隻虛弱的惡魔衝過去。它驚恐無比，試圖躲避，而#{bold}#裂天者 毀滅號#{normal}#相對修正了行進路線，直到它徹底放棄，沮喪地顫抖。在導彈的轟鳴聲中，你不能聽見飛船裏的聲音，不過你能肯定惡魔的嘴型在說'這真滑稽'。

導彈到達了目的地，巨大的爆炸堵塞了你透過窗戶的視線。碎片無害地墜落在山頂，整個大陸都聽見了巨大的爆鳴聲。

痛飲剛分下來的美酒，你將已經空倉的#{bold}#裂天者 毀滅號#{normal}#指向飛船，不出所料看見巨人們歡呼擁抱，在安心和喜悅中痛苦流涕。少數大聲質疑你爲什麼這麼做，而大部分人明白這是仁慈的表示。

第二發導彈帶着火光墜落大海，這場持續的煙火盛宴成爲大陸上所有蒸汽巨人，所有獸人，甚至所有能看到這一盛景的生物的慶典：
戰爭結束了。
千年以來，埃亞爾大陸，以及擁有它的獸人們，第一次明白了和平的意義。*#WHITE#]], "_t")

------------------------------------------------
section "tome-orcs/data/chats/john-surrender.lua"

t("You cannot summon; you are suppressed!", "你不能召喚，你被壓制了！", "logPlayer")
t("HATE!", "仇恨！", "_t")
t("PAIN!", "痛苦！", "_t")
t("REGRET!", "悔恨！", "_t")
t("My love...", "我的愛人…", "_t")
t("I feel so lost.", "我迷失了。", "_t")
t("Please let me die!", "讓我去死吧！", "_t")
t("RAAAAARGGGG!", "額啊啊啊啊啊阿！", "_t")
t("Someday you will pay!", "總有一天你會付出代價的！", "_t")
t("DEATH!", "去死吧!", "_t")
t("*Sobs*", "*哭泣*", "_t")
t([[#LIGHT_GREEN#*The Crimson Templar looks exhausted, nearly dead. You feel the ring attuning to him and suddenly you understand you could absorb his essence to power the ring.*#WHITE#
Go on kill me @playername@! My life is destroyed, my friends are dead, my dear Aeryn is dead. All dead by your murderous hands! Finish me, let me have some #{italic}#rest#{normal}#.]], [[#LIGHT_GREEN#*深紅聖武士看上去極其疲憊，瀕臨死亡。你感覺戒指在和他共鳴，突然你意識到你能吸收他的力量來強化戒指。*#WHITE#
來殺了我吧@playername@! 我的一切都毀了，我的朋友被你們殺了，我的愛人艾琳也死了。都被你無情而殘忍的雙手殺死了！幹掉我吧，讓我就這樣 #{italic}#安息#{normal}#吧。]], "_t")
t("#LIGHT_GREEN#[destroy him to power the ring]#WHITE# So be it!", "#LIGHT_GREEN#[殺死他來強化戒指]#WHITE# 如你所願!", "_t")
t("#LIGHT_GREEN#[bind him to the ring]#WHITE# No, you are more useful alive and broken to me!", "#LIGHT_GREEN#[將他綁定到戒指上]#WHITE# 不，你活着對我更有用!", "_t")
t([[#LIGHT_GREEN#*The malevolent energies around you condensate into the ring, absorbing the last remains of John.
The ring is now much more powerful.*#WHITE#
Aeryn... my love...]], [[#LIGHT_GREEN#*你周圍的邪惡能量凝聚到戒指中，吸收了約翰的剩餘力量。
戒指變得更加強大了。*#WHITE#
艾琳... 我的愛人...]], "_t")
t("#LIGHT_GREEN#[done]#WHITE#", "#LIGHT_GREEN#[完成]#WHITE#", "_t")
t([[#LIGHT_GREEN#*The malevolent energies around you condense into the ring, binding John to it forever.
The ring is now able to summon him for a few turns at will.*#WHITE#
#{bold}#I HATE YOU!#{normal}#]], [[#LIGHT_GREEN#*在你周圍的邪惡能量凝聚到戒指中，將約翰綁定到戒指上。
戒指現在具有召喚他的能力。*#WHITE#
#{bold}#我恨你!#{normal}#]], "_t")

------------------------------------------------
section "tome-orcs/data/chats/john-worldmap.lua"

t([[#LIGHT_GREEN#*As you approach you recognize Outpost Leader John. But there is a kind of terrible darkness, you can feel his hatred crystallize the air.*#WHITE#
@playername@. You malevolent creature! #{bold}#YOU KILLED HER! YOU MURDEROUS DOG!#{normal}#
You #{italic}#dare#{normal}# carry her ring around like a trophy! I can feel it on you. Give it back! DIE!]], [[#LIGHT_GREEN#*當你靠近時，你認出了那是前哨站首領約翰。但他身邊環繞着可怕的黑暗，你能感受到他的仇恨令空氣結晶。*#WHITE#
@playername@ 你這個殘忍的畜生! #{bold}#你殺了她! 你這條殘忍的狗!#{normal}#
你 #{italic}#竟敢#{normal}# 帶着她的戒指作爲戰利品！我能感覺到它在你身上。拿出來，受死吧！！]], "_t")
t("Oh you liked that paladin lady? I loved killing her!", "你喜歡那個女聖騎士？我愛死殺她的感覺了", "_t")
t("She left me no choice; I had to protect #{bold}#my#{normal}# people.", "她令我別無選擇; 我必須保護 #{bold}#我的#{normal}# 族民。", "_t")
t("Whatever.", "還行吧。", "_t")
t("What?", "什麼?", "_t")

------------------------------------------------
section "tome-orcs/data/chats/kaltor-entry.lua"

t([[#LIGHT_GREEN#*As you open the door to the shop, you are greeted by a pair of Steam Giant guards, staring at you and holding their steamguns tightly, at the ready but not aimed at you.*#WHITE#
No sudden moves, @playername@. Kaltor's orders are to consider you a customer for now. Try anything foolish, and you'll be a live demonstration for his newest guns instead.  Understand?]], [[#LIGHT_GREEN#*當你打開商店大門，你被一羣蒸汽巨人警衛包圍，他們盯着你看，手中緊握蒸汽槍，準備就緒，但並沒有瞄準你。*#WHITE#
別亂動， @playername@。卡托爾的指令讓我們將你視爲顧客。做蠢事的話，你將被他最新的槍支毀滅。明白了麼]], "_t")
t("I have gold, you have equipment. This doesn't need to be any more complicated than that.", "我有錢，你們有裝備。沒什麼更復雜的東西。", "_t")
t("Those are some pretty fancy guns. Think it'll be hard to get your blood out of the gears?", "這些槍看起來挺有趣的。你們以爲有了這些裝備，我就不能打得你們頭破血流了麼？", "_t")
t([[#LIGHT_GREEN#*She smiles, relieved but also slightly disappointed.*#WHITE#
Couldn't have said it better myself. Come on in - and try not to scare the other patrons.]], [[#LIGHT_GREEN#*她微微一笑，輕鬆卻似乎有些失望。*#WHITE#
那再好不過。進來吧 - 別嚇到其他顧客。]], "_t")
t("[enter]", "[進入]", "_t")
t([[Good luck with that, savage.
#LIGHT_GREEN#*She smirks, and pulls a cord on the wall beside her as her and her partner duck behind cover; a loud bell rings, and you hear a commotion from further inside the shop.*#WHITE#]], [[祝你好運，野蠻人。
#LIGHT_GREEN#*她假笑着，拉下她身邊牆上的繩子，她的同伴從角落裏出來。一陣鈴響，你聽見商店裏的騷動。*#WHITE#]], "_t")
t("[fight]", "[戰鬥]", "_t")

------------------------------------------------
section "tome-orcs/data/chats/kaltor-shop.lua"

t("Finally a practical giant! Show me your wares.", "終於來了一位有理性的巨人! 給我看看你的貨。", "_t")
t("Die giant scum! For Kruk! For Garkul! For the Pride!", "死吧，巨人渣渣！爲了克魯克！爲了加庫爾！爲了部落", "_t")
t("No need for shopping now.", "現在不需要購物。", "_t")
t([[#LIGHT_GREEN#*A well-dressed giant stands in front of you, covered in expensive jewelry; judging from the poorly-fastened clasp on his necklace, you can assume he acquired it all fairly recently.  He grins as he leans down over the counter to get a good view of you.*#WHITE#
Ah, welcome, @playername@! #LIGHT_GREEN#*he yells in a voice loud enough to catch the attention of all in the shop, as he lifts his head to look around.*#WHITE# Yes, you heard me right, @playername@! The very same one who's been running rampant through the Vaporous Emporium is coming to ME for armaments! I don't think I could've asked for a stronger endorsement! #LIGHT_GREEN#*He looks back down to you, leaning over the counter to point out a glass display case loaded with exotic weaponry and armor.*#WHITE#
Well, I'm not one to turn down anyone with gold, and seeing as you've already made me rich, I'll even give you a discount, down to my pre-attack prices. #LIGHT_GREEN#*He leans in uncomfortably close, staring you in the eyes.* #WHITE#Or, if you came to do here what you did in the Emporium... #LIGHT_GREEN#*He directs his glare toward the multiple well-armed guards staring at you and standing still on the sides of the room.*#WHITE# I'm sure my #{italic}#emergency safety measures#{normal}# would just #{italic}#love#{normal}# an opportunity to try out their shiny new toys.]], [[#LIGHT_GREEN#*一名衣着講究的巨人站在你面前，戴滿昂貴的珠寶；從他鬆垮的項鍊扣上看，你猜測他是最近纔拿到的。他微笑着從櫃檯往下看，注視着你。*#WHITE#
哦，歡迎，@playername@! #LIGHT_GREEN#*他的聲音大的讓店裏所有人都聽見，同時他擡起頭張望四周。*#WHITE# 是的，聽見了麼， @playername@！就是那個在蒸汽商場猖獗無比的傢伙，他到我這來買裝備了!我認爲不會有比這更好的宣傳了! #LIGHT_GREEN#*他轉過頭看你，指出一個玻璃展臺，那上面裝滿異種武器和護甲。*#WHITE#
好吧，我不會拒絕任何帶着錢過來的人，同時你也已經讓我富裕不少了。我還能給你打個折。 #LIGHT_GREEN#*他靠得過近，讓你感覺不太舒服。他直視着你的眼睛。* #WHITE#或者，你也可以試試你在蒸汽商店裏乾的事情...
#LIGHT_GREEN#*他指向周圍和房間裏那些裝備良好的警衛。*#WHITE# 
我相信我的#{italic}#緊急安全保衛#{normal}#一定#{italic}#愛死了#{normal}#每一個嘗試新玩具的機會。]], "_t")
t([[Welcome back, @playername@!  You see this, customers?  This fearsome, savage master of battle was so impressed by my products that he came back for more!
#LIGHT_GREEN#*He points to a new poster on the wall next to him, showing your face and the caption #{bold}#"KALTOR: THE CHOICE OF DESTROYERS!"#{normal}#*#WHITE#

So, what'll it be?]], [[歡迎回來, @playername@! 來看看這個，顧客們?這位可怕而野蠻的戰鬥大師也對我的產品印象深刻，現在他又回來買東西了!
#LIGHT_GREEN#*他指向牆上貼着的新海報,上面是你的臉和一行大字 #{bold}#"卡托爾：破壞者的選擇！"#{normal}#*#WHITE#

那麼，你要做什麼呢?]], "_t")
t([[#LIGHT_GREEN#*Kaltor is busy packing some of his goods away in crates; he hands one to a worker, carrying it out the back door, before turning to you.*#WHITE#
	Make it quick, @playername@. Not to be rude, but there's a private airship out there with my name on it, and I'd rather have a bird's-eye view of what you're about to do than a front-row seat.]], [[#LIGHT_GREEN#*卡托爾忙着打包貨物；他將箱子遞給一個工人帶到後門，然後轉過頭和你說話。*#WHITE#
	快點吧, @playername@. 不是我粗魯，但現在有一艘我的飛船在外面，我更想站在上面鳥瞰你要做的事情，而不是坐在椅子上。]], "_t")
t([[#LIGHT_GREEN#*He frowns in mock disappointment, as he presses a button on his stylish coat; it hisses, and you hear motors whirring*#WHITE#
Oh, what a pity.  Guards?  Ten thousand gold to whoever gets the killing blow.  Store credit, of course.]], [[#LIGHT_GREEN#*他臉上露出失望的深色，按下外套上的按鈕。它發出嘶嘶聲，你聽見引擎的轟鳴。*#WHITE#
真遺憾。警衛？誰殺了他，就有一萬金的賞錢。當然，記在商店賬上。]], "_t")
t("DEATH!", "去死吧!", "_t")

------------------------------------------------
section "tome-orcs/data/chats/kruk-tinker-shop.lua"

t("Welcome @playername@ to my shop.", "@playername@，歡迎來到我的商店。", "_t")
t("Let me see your wares.", "讓我看看你的商品吧。", "_t")
t("I am looking for special training.", "我是來尋求特殊訓練的。", "_t")
t("Sorry, I have to go!", "抱歉，我要走了！", "_t")
t("I can indeed offer some training (talent category Steamtech/Physics and Steamtech/Chemistry) for a fee of 100 gold pieces each.", "我能教你物理學或者化學知識，學費100金一次。", "_t")
t("Please train me in physics.", "教我物理學知識吧。", "_t")
t("The tinker spends some time with you, teaching you the basics of smithing.", "工程師花費時間傳授你鐵匠的基礎知識。", "logPlayer")
t("Please train me in chemistry.", "教我化學知識吧。", "_t")
t("The tinker spends some time with you, teaching you the basics of therapeutics.", "工程師花費時間傳授你藥劑學的基礎知識。", "logPlayer")
t("No thanks.", "不用了，謝謝。", "_t")

------------------------------------------------
section "tome-orcs/data/chats/metash.lua"

t([[#LIGHT_GREEN#*Before you stands an impressive undead minotaur.*#WHITE#
I would like to talk to you.]], [[#LIGHT_GREEN#*在你面前站着一位引人注目的亡靈牛頭人。*#WHITE#
我有一些話想對你說。]], "_t")
t("Yes?", "嗯？", "_t")
t("Your clan is free Metash, the tyrant is no more.", "梅塔什，你的氏族被解放了，暴君已經不復存在。", "_t")
t("Not now.", "暫時不用。", "_t")
t("Soft-foot of the Kruk, I come to give you a warning, an apology, and a plea for help.  An incredible magical force has awakened within one of our elders, Nektosh the One-Horned, and he has gone mad with its power.  Those who stood up against him were reduced to less than ashes by a beam from his horn, a beam that tunneled far up through the rock above him until we could see the sky.  He has convinced some of us that he can use this terrible force to conquer Eyal and terrified others into going along with him; he has announced that his first step will be to lead his followers in an attack on Kruk Pride.", "克魯克部落的軟蹄者，我來到這裏，是爲了給你警告和道歉，並請求你的幫助。我們的長老-獨角者納克託什，他的身上覺醒了一種強大的魔法力量，而他不能承受這股力量，逐漸瘋狂。所有阻擋他的人，都在他的獨角射線下化爲灰燼。他的射線射程極長，能穿過岩石，直至天際。他讓我們中某些人相信，他能用這股強大力量征服埃亞爾世界，同時他恐嚇其他族人和他一起。他宣佈，他的第一步行動將是帶着追隨者們攻擊克魯克部落。", "_t")
t("[listen]", "[聽他說話]", "_t")
t("The rest of us have fled, hiding in caverns across the peninsula...  I cannot in good conscience ask you to face certain death before his magic for our sakes, but striking first may be the only way to save your people.  He appears to be stalling the invasion, buying you some time, but if you cannot catch him off-guard before he finally commits to it...  I've seen his power cut through a mountain like it was a leaf, soft-foot.  There can be no victory against that kind of magic.  Run, hide, and hope he falls victim to an accident or loses the remaining fragments of his sanity that keep him capable of casting spells.", "我們其他人都跑了，藏身在洞穴中... 憑良心說，我不應讓你直面他的魔法，那一定會帶來死亡。但只有搶先下手，才能拯救你的族民。他暫時不會進攻，爲你贏得了一些時間。但如果你不能在他進攻前打他個措手不及...軟蹄者，我曾經看着他的力量洞穿山脈，彷彿穿過一片樹葉般輕鬆。算了，不可能戰勝這種魔法的。跑吧，躲起來，希望他能意外身亡，或者進一步失去理智以至於不能施法吧。", "_t")
t("I will check it out", "我要去看看", "_t")
t("We of the Krimbul Clan have faced our near-certain deaths all too many times, even after our hearts stopped beating; this is the first time we have been shown the kindness of utter salvation by an outsider.  Those who were not enthralled by Nektosh and are not delusionally faithful to his \"cause\" will reclaim the Mana Caves in time; until then, we will join your Pride in your revolution.  You have liberated us, and we will not rest until you are freed of your oppressors as well.", "我們氏族曾無數次直面滅族危機，哪怕是在我們的心臟停止跳動之後；然而，這是第一次，我們被外人的友善所拯救。沒被納克託什和他的藉口迷惑的人馬上將重返魔法洞穴。在此之前，我們將加入你的部落，參與你的革命。你解放了我們，在你們脫離壓迫者之前，我們都不會停下腳步。", "_t")
t("Thanks.", "多謝。", "_t")
t("Hail, @playername@!", "嘿, @playername@!", "_t")
t("Our is free Metash, the tyrant is no more.", "我們自由了梅塔什，暴君被打敗了！", "_t")
t([[I came here to warn the Kruk Pride of the threat Nektosh poses and ask for their help, but they have some more immediate threats to deal with...  We should help them repel these Steam Giants.  They are the only people who have ever treated us with respect and dignity; if they are crushed by the Atmos Tribe or the Allied Kingdoms, we will surely be next.  Their success is our survival.

Unfortunately, they cannot afford to spare the warriors to retake the Mana Caves from that tyrant, and I need to stay here to help them defend their land.  The task of freeing our clan is in your hands, when you feel ready for it.]], [[我來這裏是爲了警告克魯克部落獨角者納克託什的危險，並請求他們的幫助。但他們有更迫切的威脅需要處理...我們應該幫他們抵抗蒸汽巨人。他們是唯一尊重我們的人，如果他們被氣之部落或者聯合王國摧毀，下一個就是我們。他們的成功就是我們的生存希望。

不幸的是，他們現在沒有空閒的戰士來幫我們從暴君手中奪回魔法洞穴。我需要留在這保護他們。解放我們氏族的任務就交給你了，做好準備去吧。]], "_t")
t("Nektosh claims he is the invincible, omnipotent descendant of a unicorn, but I don't believe that bull for a second.  While the great magical power that suddenly awakened within him is as fearsome as it is insanity-inducing,  he has yet to use it to make a shield or teleport himself, and even with his all-powerful beam, his aim isn't always perfect...  I think he has a weakness he's trying to hide.  Fight with courage, fellow Whitehoof, and the Krimbul Clan may be free once more!", "獨角者納克託什聲稱他是無可戰勝無所不能的獨角獸後裔。但他說的每一句話我都不信。自從他體內的恐怖而瘋狂的魔法力量覺醒後，他用能這股力量製造護盾或者傳送，甚至發射強力射線。但他的瞄準能力似乎並不精確...他一定有着某個隱藏的弱點。勇敢戰鬥吧，我的白蹄夥伴，氏族的解放就交給你了", "_t")
t("I will!", "我會的！", "_t")
t([[He...  he found a wand?  And he realized it was running dry, but only after taking over the tribe?  I pity him, but I cannot forgive him for being willing to sacrifice so many Whitehooves and Orcs to escape the consequences of his brief lapse into madness...  still, as a personal request I ask that you not tell others of his last thoughts.  The Nektosh we once knew saved our tribe from the corrupted magic deep under Eyal; he deserves to, at worst, be remembered as one who tragically succumbed to its influence.

Ultimately, though, the choice is yours; it is more important that he is no longer a threat.  There are some who may still cling to the false hope he gave them, but we will retake the Mana Caves from them in time.  We owe you a great debt, and now that we have no more pressing concerns, we can aid Kruk Pride in their rebellion.  Good travels, @playername@.]], [[他...  他找到了一根魔棒？然後等到他掌控了我們氏族，才發現能量快用完了？我對此感到遺憾，但我不能原諒他。爲了逃避自己陷入瘋狂的責任，他準備犧牲這麼多的白蹄族人和獸人……儘管如此，我請求你不要告訴別人他的想法。納克託什是曾經將我們從埃亞爾深處的墮落魔法中拯救出來的英雄，至少，讓大家以爲她是在這種魔法的影響之下光榮犧牲的吧。

當然，選擇權在你手中；重要是他的威脅解除了。雖然仍有人沉醉於他給予的虛假希望中，但我們馬上就能奪回魔法洞穴了。我們都欠你很多。現在，我們緊迫的危機已經解除了，該是幫助克魯克部落的時候了。祝你好運, @playername@。]], "_t")
t("To you too, Metash.", "也祝你好運，梅塔什。", "_t")

------------------------------------------------
section "tome-orcs/data/chats/phonograph.lua"

t("[insert %s]", "[插入 %s]", "tformat")
t("#LIGHT_GREEN#*This machine seems to have a slot for some kind of disks.*#WHITE#", "#LIGHT_GREEN#*這臺機器上有一個槽，似乎能將光盤放進去。*#WHITE#", "_t")

------------------------------------------------
section "tome-orcs/data/chats/shertul-priest.lua"

t([[#LIGHT_GREEN#*Before you stands a tentaculous horror which you recognize for what it truly is. A living #{bold}#Sher'Tul#{normal}#!.*#WHITE#
Who are you, young creature, to stand up to a High Priest of Amakthel? Do you not know that you are before a servant of the Almighty Creator, the Sunfather, the God of Gods, Lord of all Eyal? In the millenia I have lived I have killed whole races like yourself. I have even wrenched the spirits of immortal gods from this world. So who are you, little one, who dare defy me?]], [[#LIGHT_GREEN#*站在你面前的是一個觸手般的恐魔，然後你認出了他，
一個活着的 #{bold}#夏·圖爾人#{normal}#!.*#WHITE#
	
站在阿馬克泰爾的大祭司面前的年輕生物啊，你是誰呢？你難道不清楚，站在你面前的，是偉大的創造者、太陽之父、神上之神、埃亞爾的主人的僕從？千年以來，我曾終結過許多像你這樣的種族，我甚至扭曲過這世界上不朽神明的靈魂。小傢伙，你認爲自己是誰，竟敢妄言打敗我？]], "_t")
t("I... am %s, of the seed of Garkul the Devourer. Garkul taught us to fight legends, and to flinch not from even the most desperate deed. Here and now I face you without fear or hesitation, for the spirit of Garkul burns within me. And in his name I will #{bold}#break#{normal}# you!", "我... 名爲%s, 是吞噬者加庫爾的後裔。 加庫爾教導我們挑戰傳奇，即使面前是絕望和死亡也絕不退縮。現在，我站在這裏面對着你，毫無恐懼，毫不猶豫，因爲加庫爾之意志在我體內燃燒。以他之名，我一定會#{bold}#打敗#{normal}# 你!", "tformat")
t("I... am %s, though I lack my original body my mind is bound to Garkul the Devourer. Garkul taught us to fight legends, and to flinch not from even the most desperate deed. Here and now I face you without fear or hesitation, for the spirit of Garkul burns within me. And in his name I will #{bold}#break#{normal}# you!", "我... 名爲%s, 儘管我失去了原本的身體，我的精神仍屬於吞噬者加庫爾。加庫爾教導我們挑戰傳奇，即使面前是絕望和死亡也絕不退縮。現在，我站在這裏面對着你，毫無恐懼，毫不猶豫，因爲加庫爾之意志在我體內燃燒。以他之名，我一定會#{bold}#打敗#{normal}# 你!", "tformat")
t("I... am %s and I am not mortal! Garkul taught the orcs to fight legends, and to flinch not from even the most desperate deed. We learned that from them! Here and now I face you without fear or hesitation, for cold touch of undeath is within me. And I will #{bold}#break#{normal}# you!", "我... 名爲%s，我超越死亡！加庫爾教導獸人挑戰傳奇，即使面前是絕望和死亡也絕不退縮。我們從他們身上學會了這些！現在，我站在這裏面對着你，毫無恐懼，毫不猶豫，因爲亡靈冰冷的力量在我體內流淌。我一定會#{bold}#打敗#{normal}# 你!", "tformat")
t("I... am %s. Here and now I face you without fear or hesitation, for the utter determination burns within me. And I will #{bold}#break#{normal}# you!", "我...名爲%s。現在，我站在這裏面對着你，毫無恐懼，毫不猶豫，因爲堅定的意志在我體內燃燒。我一定會#{bold}#打敗#{normal}# 你!", "tformat")

------------------------------------------------
section "tome-orcs/data/chats/weissi-machine.lua"

t([[#LIGHT_GREEN#*Before you is an extremely old looking machine. It seems to be infused with some sort of psionic energy; impossible as this sounds.
And it #{bold}#speaks#{normal}# to you!*#WHITE#
Welcome @playername@. We have been waiting for you.]], [[#LIGHT_GREEN#*在你面前的是一臺非常古老的機器。它似乎充滿了某種靈能，聽上去不可思議。
現在，它朝你 #{bold}#說話#{normal}#了！*#WHITE#
你好啊@playername@，我們等你很久了。]], "_t")
t("What are you?", "你是?", "_t")
t("Waiting for me?", "等我?", "_t")
t("What do you need me for?", "你要我幹啥?", "_t")
t("I have muscle tissue for you.", "我有一些肌肉組織要給你.", "_t")
t("[leave]", "[離開]", "_t")
t("#LIGHT_GREEN#*You feel a powerful presence in your mind.*#WHITE#", "#LIGHT_GREEN#*你感覺到大腦裏浮現出強大的預言。*#WHITE#", "_t")
t("I see...", "我明白了...", "_t")
t("Yes. We predict you will be useful to us. If you are not, another will be.", "是的。我們預測你將對我們有所助益。當然，如果你不是，也會有其他人。", "_t")
t([[We require recent yeti muscle tissue from powerful specimens. You will help us, or you will not. Either way they will come to us.
If you do so we shall reward you with petty knowledge so that you may postpone your death.]], [[我們需要強大雪人種族的肌肉組織。你可以幫我們，也可以選擇不幫。這取決於你。
如果你幫了我們，我們將傳授你知識，可以延緩你的死亡。]], "_t")
t("That is... generous of you.", "這真是... 慷慨。", "_t")
t("Talent categories", "技能樹", "_t")
t("Talents", "技能", "_t")
t("Improved core stats", "提升核心屬性", "_t")
t([[#LIGHT_GREEN#*The muscle tissue suddenly vanishes from your inventory.*#WHITE#
Thank you @playername@, this is indeed a suitable specimen. We shall honor our bargain with you. What do you wish to learn?]], [[#LIGHT_GREEN#*肌肉組織突然消失了。*#WHITE#
感謝你@playername@，這真是有趣的物種。你的幫助我們將銘記於心。你想學什麼？]], "_t")
t("What do you wish to learn?", "你想學什麼?", "_t")
t("You cannot use your %s anymore; it is tainted by magic.", "你不能再使用 %s ，它已被魔法所污染。", "logPlayer")
t([[Antimagic is a very special category. If you learn it you will never be able to use arcane powered items or talents again.
Do you still wish to take this path?]], [[反魔法是一系非常特殊的技能。你學習後將不能使用奧術裝備和法術技能。
確定要學習麼？]], "_t")
t("No.", "不。", "_t")
t("Yes!", "好的！", "_t")
t("Select the party member to receive the reward:", "選擇隊伍中獲得獎勵的成員：", "_t")
t("Very well. We can teach you a talent category; which do you want?", "很好，我們能教你一個技能樹；你想要哪種？", "_t")
t("Physical techniques", "戰鬥技術", "_t")
t("Arcane spells", "法術", "_t")
t("Nature/Psionic talents", "自然/靈能", "_t")
t("Hum no let me change my mind.", "啊，不，讓我再想想。", "_t")
t("[Allow training of talent category %s (at mastery %0.2f)]", "[解鎖技能樹 %s (技能等級 %0.2f)]", "tformat")
t("Very well. We can teach you a talent.  Which do you want?", "很好。我們能教授你技能。你想學哪個？", "_t")
t("Very well. We can teach you a talent; which type do you want?", "很好。我們能教授你技能；你想學哪個？", "_t")
t("[%s talent %s (+%d level(s))]", "[%s 技能 %s (+%d 等級)]", "tformat")
t("Improve", "提升", "_t")
t("Learn", "學習", "_t")
t([[Antimagic talents are very special. To learn one means you will never be able to use arcane powered items or talents again.
Do you still wish to take this path?]], [[反魔法技能是非常特殊的。你學習後將不能使用奧術裝備和法術技能。
確定要學習麼？]], "_t")
t("Very well. We can teach you a talent (unlocking the talent category is separate). Which do you want?", "很好，我們能教你一個技能樹(需解鎖)，你想要哪種？", "_t")
t("[Improve %s by +%d]", "[提升 %s +%d]", "tformat")
t("Very well. We can increase one of your core stats by 4, which one?", "很好，我們能強化你一項屬性4點。選擇哪個？", "_t")

