t("This eight legged mechanical construct looks suspiciously like a spider. A huge clonking spider that runs to you at great speed ready to cut you to pieces with its two rotating saws in place of mandibles.", "這是個看上去很像蜘蛛的八腿機械構造體。它正向你飛速衝來並準備用顎部的旋轉鋸刃將你撕成碎片。", "_t")

------------------------------------------------
section "tome-orcs/data/general/npcs/steam-giant-arcane.lua"

t("giant", "巨人", "entity type")
t("steam", "蒸汽", "entity subtype")
t("necropsych's ghost", "通靈師的鬼魂", "entity name")
t("undead", "亡靈", "entity type")
t("ghost", "幽靈", "entity subtype")
t("The spirit of a recently deceased necropsych. It moans painfully but seems impervious to most worldly things.", "這是一個在近期死亡的通靈師的靈魂。它痛苦的哀鳴着，無視現實世界的一切。", "_t")
t("steam giant necropsych", "蒸汽巨人通靈師", "entity name")
t("Covered in arcane runes of death, this steam giant means business.", "這個被死亡符文所覆蓋的蒸汽巨人是個大麻煩。", "_t")
t("#LIGHT_DARK#As %s falls you see its spirit rising for revenge.", "#LIGHT_DARK#當%s倒下時，你看到他的靈魂尋求復仇。", "logSeen")
t("steam giant blood carver", "蒸汽巨人血雕者", "entity name")
t("Blood seems to ooze from the towering giant, yet seemingly to no ill effect.", "儘管血液不停地從這個高大的巨人身上滲出，他看上去卻沒有任何不適。", "_t")

