section "tome-orcs/data/general/npcs/steam-giant-gunner.lua"

t("giant", "巨人", "entity type")
t("steam", "蒸汽", "entity subtype")
t("steam giant gunner", "蒸汽巨人槍手", "entity name")
t("This steam giant is carrying a powerful looking gun.", "這個蒸汽巨人拿着一把看上去威力很強的槍。", "_t")
t("steam giant gunslinger", "蒸汽巨人快槍手", "entity name")
t("This steam giant carries a steamgun in each hand.", "這個蒸汽巨人雙手各拿着一把蒸汽槍。", "_t")
t("steam giant flameshot", "蒸汽巨人火焰射手", "entity name")
t("This steam giant carries a steamgun in each hand. The barrels appear to be flaming.", "這個蒸汽巨人雙手各拿着一把槍管在燃燒的蒸汽槍。", "_t")
t("retaliator of Atmos", "阿特姆斯復仇者", "entity name")
t("This steam giant carries a steamgun in each hand. She is here to eliminate any and all aggression towards the Atmos tribe.", "這個蒸汽巨人雙手各拿着一把蒸汽槍。她來此唯一的目的就是消滅任何對阿特姆斯部落的威脅。", "_t")

