section "tome-orcs/data/general/npcs/steam-giant-warrior.lua"

t("giant", "巨人", "entity type")
t("steam", "蒸汽", "entity subtype")
t("steam giant guard", "蒸汽巨人守衛", "entity name")
t("This titanic figure walks towards you, a massive sword and shield in each hand.", "這個拿着巨型劍盾的龐大人形正在向你走來。", "_t")
t("steam giant berserker", "蒸汽巨人狂戰士", "entity name")
t("This steam giant carries a massive greatsword with both hands, and you see a cloud of thick steam enveloping the blade.", "這個蒸汽巨人雙手拿着一柄無比龐大的大劍，你看到劍刃被厚厚的蒸汽雲團包裹着。", "_t")
t("steam giant yeti rider", "蒸汽巨人雪人騎士", "entity name")
t("Riding atop a massive armored yeti, this steam giant wields a huge greatsword.", "這個拿着大劍的蒸汽巨人騎在一隻重甲雪人身上。", "_t")

