section "tome-orcs/data/general/npcs/steam-spiders.lua"

t("mechanical", "機械", "entity type")
t("arachnid", "蜘蛛", "entity subtype")
t("mecharachnid warrior", "機械蛛武士", "entity name")
t("This eight legged mechanical construct looks suspiciously like a spider. A huge clonking spider that runs to you at great speed ready to cut you to pieces with its two rotating saws in place of mandibles.", "這是個看上去很像蜘蛛的八腿機械構造體。它正向你飛速衝來並準備用顎部的旋轉鋸刃將你撕成碎片。", "_t")
t("mecharachnid flame thrower", "機械蛛噴火者", "entity name")
t("This eight legged mechanical construct looks suspiciously like a spider. The huge flame thrower mounted on its back however is definitively un-spider-like.", "這是個看上去很像蜘蛛的八腿機械構造體。儘管蜘蛛可不會有它背後裝載的巨型火焰噴射器。", "_t")
t("mecharachnid destroyer", "機械蛛毀滅者", "entity name")
t("This eight legged mechanical construct looks suspiciously like a spider. An armed to the teeth, well, mandibles, spider.", "這是個看上去很像蜘蛛的八腿機械構造體。一個武裝到牙齒，呃，顎部的蜘蛛。", "_t")
t("mecharachnid repairbot", "機械蛛維修者", "entity name")
t("This eight legged mechanical construct looks suspiciously like a spider. It seems to be more concerned by its fellow arachnids than by you.", "這是個看上去很像蜘蛛的八腿機械構造體。比起你，它似乎更關心它的同胞們。", "_t")

