section "tome-orcs/data/general/npcs/sunwall-mage.lua"

t("humanoid", "人形生物", "entity type")
t("elf", "精靈", "entity subtype")
t("sun-mage recruit", "太陽法師新兵", "entity name")
t("A mage dressed in glowing robes.", "一個穿着熒光法袍的法師。", "_t")
t("sun-mage", "太陽法師", "entity name")
t("A mage dressed in shining robes.", "一個穿着閃亮法袍的法師。", "_t")
t("anorithil", "星月術士", "entity name")
t("A mage dressed in ornate robes depicting both light and darkness.", "一個穿着同時描繪了光與暗的華麗法袍的法師。", "_t")
t("astral conjurer", "星空咒術師", "entity name")
t("human", "人類", "entity subtype")
t("elven astromancer", "精靈星術師", "entity name")
t("A mage who has studied all there is to know about the stars and their working.", "一個將畢生精力投入到了對星辰及其原理的學習中的法師。", "_t")

