section "tome-orcs/data/general/npcs/sunwall-warrior.lua"

t("humanoid", "人形生物", "entity type")
t("human", "人類", "entity subtype")
t("sunwall guard", "太陽堡壘守衛", "entity name")
t("This guard stands tall and proud, wearing the symbol of the Sunwall.", "這個身着太陽堡壘徽記的守衛挺拔而驕傲的站立着。", "_t")
t("sunwall archer", "太陽堡壘弓箭手", "entity name")
t("elf", "精靈", "entity subtype")
t("You see an archer with his bow drawn back, and a golden sun embossed on his armor.", "你看到了一個拉着弓的射手，他的護甲上有金色太陽的壓紋。", "_t")
t("sun paladin recruit", "太陽騎士新兵", "entity name")
t("The shield of this soldier glows with a bright light. You see a golden sun engraved in its center, and he carries a sword in his other hand.", "這個士兵的盾牌閃耀着強光。你看到盾牌的中央雕刻着一個金色的太陽，同時他的另一隻手拿着一柄劍。", "_t")
t("sun paladin", "太陽騎士", "entity name")
t("The shield and sword of this soldier glow with a bright light. You see a golden sun engraved in the shield's center.", "這個士兵的盾牌與劍都閃耀着強光。你看到盾牌的中央雕刻着一個金色的太陽。", "_t")
t("sunwall vindicator", "太陽堡壘維護者", "entity name")
t("This mean looking soldier of the Sunwall holds steady his big two handed weapon, looking dangerously at you.", "這個看上去十分兇惡的太陽堡壘士兵穩穩地握着一柄雙手劍，他正在用危險的目光看着你。", "_t")

------------------------------------------------
section "tome-orcs/data/general/npcs/titan.lua"

t("giant", "巨人", "entity type")
t("titan", "泰坦", "entity subtype")
t("titan battlesmasher", "泰坦碎顱者", "entity name")
t("This creature looks like one of the steam giants, but nastier, bigger and somehow corrupted by unknown forces. Oh and it is wielding a huge maul too!", "這個生物看上去像是一個蒸汽巨人，但是更巨大，更噁心，並且被某種未知力量腐化了。天啊，他還拿着一個巨錘！", "_t")
t("titanic horror", "泰坦恐魔", "entity name")
t("While a titan usually look like a corrupted steam giant, this one looks more like a giant-sized horrific mass of living flesh.", "儘管一般的泰坦看上去像是一個墮落的蒸汽巨人，這一個看上去更像是一個巨人大小的恐怖血肉團塊。", "_t")
t("titan searing seer", "泰坦炙熱先知", "entity name")
t("Wreathed in arcane flames you can feel the intense psionic forces ripping at your mind emanating from this titan.", "你能感受到從這個被奧術火焰所環繞的泰坦所放射出的強大的精神力量正在你的心靈中迴盪。", "_t")
t("titan vile spewer", "泰坦嘔吐魔", "entity name")
t("The wretched titan's skin is of a sickly green, full of ever-oozing wounds, cracks and pustules. Worms and all kind of vile things crawl over it.", "這個噁心的泰坦的皮膚呈現一種粘乎乎的綠色，滿是不停的流着粘液的傷口，裂縫，和膿皰。蠕蟲和其他各種卑劣的東西在他身上爬來爬去。", "_t")
t("titan dreadnought", "泰坦無畏勇士", "entity name")
t("One of the biggest titans you have seen yet, it is fully clad in deep black stralite full plate, charging menacingly towards you at a terrible pace.", "這是你見過的最大的泰坦，他被一身深黑色的藍鋯石全身甲所覆蓋，正邁着可怕的步伐向你衝來。", "_t")
t("sher'tan", "夏爾泰坦", "entity name")
t("This abomination has the height of any other titan but its features definitively remind you of the few Sher'Tul images you have seen. Your very being rebels to the thought and sheer terror takes hold of your mind.", "這個孽物和其他泰坦差不多高，但是他的特徵讓你回想起了你見過的那些夏·圖爾人圖片。你竭盡全力的抗拒這些想法，你的心靈已被純粹的恐懼所控制。", "_t")
t("gargantuan sher'tan", "龐大的夏爾泰坦", "entity name")
t("This abomination has the height of any other titan but its feature definitively remind you of the few Sher'Tul images you have seen. Your very being rebels to the thought and sheer terror takes hold of your mind.", "這個孽物和其他泰坦差不多高，但是他的特徵讓你回想起了你見過的那些夏·圖爾人圖片。你竭盡全力的抗拒這些想法，你的心靈已被純粹的恐懼所控制。", "_t")

------------------------------------------------
section "tome-orcs/data/general/npcs/troll-pirates.lua"

t("giant", "巨人", "entity type")
t("troll", "巨魔", "entity subtype")
t("troll pirate", "巨魔海盜", "entity name")
t("This is a Troll pirate.", "這是一個巨魔海盜。", "_t")
t("troll marauder", "巨魔掠奪者", "entity name")
t("This lean but muscular troll deftly wields two daggers. He glares at you with eyes filled with cunning.", "這個精壯的巨魔熟練使用着一對匕首。他看向你的目光中滿是狡詐。", "_t")
t("troll captain", "巨魔船長", "entity name")
t("This troll is barking orders to the other trolls around him. He effortlessly holds a longsword in each hand.", "這個巨魔正在咆哮着地對他身旁的巨魔下達命令。他毫不費力的雙手各拿着一柄長劍。", "_t")
t("troll guard", "巨魔守衛", "entity name")
t("This troll carries a large sword and shield, and appears to be wearing segments of armor.", "這隻巨魔拿着巨大的劍盾，身上穿了一些零碎的護甲。", "_t")
t("troll aquamancer", "巨魔控水師", "entity name")
t("This troll is holding a tall staff in one hand. Tendrils of water circle around it.", "這隻巨魔一隻手拿着一柄長杖。他的身邊盤繞着由水組成的觸手。", "_t")

------------------------------------------------
section "tome-orcs/data/general/npcs/undead-drake.lua"

t("undead", "亡靈", "entity type")
t("dragon", "龍", "entity subtype")
t("undead drake hatchling", "亡靈幼龍", "entity name")
t("A skeletal drake hatchling; not too powerful by itself, but if it's anything like living ones, it's probably not alone.", "一隻骷髏幼龍；並不怎麼強，但是如果他們的習性還像活着的時候那樣的話，這裏恐怕有不止一隻。", "_t")
t("undead drake", "亡靈飛龍", "entity name")
t("A skeletal drake, armed with a deadly breath weapon and nasty claws.", "一隻骷髏飛龍，有着致命的吐息和可怕的利爪。", "_t")
t("undead wyrm", "亡靈巨龍", "entity name")
t("The skeleton of a long-lived wyrm, armed with a deadly breath weapon and nasty claws.", "一隻活了很久的巨龍的骷髏，有着致命的吐息和可怕的利爪。", "_t")

