section "tome-orcs/data/general/npcs/whitehooves.lua"

t("undead", "亡靈", "entity type")
t("minotaur", "米諾陶", "entity subtype")
t("whitehoof ghoul", "白蹄屍鬼", "entity name")
t("It is a cross between a human and a bull, but more ... dead.", "他像是人類和公牛組合出來的，除了更……死。", "_t")
t("whitehoof maulotaur", "巨錘白蹄", "entity name")
t("This big undead minotaur is carrying a nasty looking hammer, imbued with lightning.", "這個巨大的亡靈牛頭人拿着一把灌注了閃電的可怕巨錘。", "_t")
t("whitehoof invoker", "白蹄喚魔者", "entity name")
t("Vortexes of sickly arcane energies circle this great undead frame.", "不詳的奧術能量環繞着這個強大的死靈。", "_t")
t("whitehoof hailstorm", "白蹄霜雹使", "entity name")
t("The air seems to freeze and wither around this terrible undead.", "看上去這個可怕的死靈身周的空氣都凍結凋零了。", "_t")

