section "tome-orcs/data/general/npcs/yeti.lua"

t("giant", "巨人", "entity type")
t("yeti", "雪人", "entity subtype")
t("yeti cub", "雪人幼崽", "entity name")
t("This humanoid form is coated with a thick white fur.", "這個類人生物身上長着厚實的白毛。", "_t")
t("yeti", "雪人", "entity name")
t("This large humanoid form is coated with a thick white fur.", "這個大型的類人生物身上長着厚實的白毛。", "_t")
t("yeti warrior", "雪人勇士", "entity name")
t("This huge humanoid form is coated with a thick white fur, with large, vicious claws. It looks angry.", "這個巨大的類人生物身上長着厚實的白毛，和危險的巨爪。他看上去十分憤怒。", "_t")
t("yeti demolisher", "雪人爆破者", "entity name")
t("This huge humanoid form is coated with a thick white fur, with large, vicious claws. Will you welcome the embrace of its large muscular arms?", "這個巨大的類人生物身上長着厚實的白毛，和危險的巨爪。你會喜歡被他肌肉滿滿的雙臂擁抱一下嗎？", "_t")

------------------------------------------------
section "tome-orcs/data/general/objects/boss-artifacts.lua"

t("Yeti-fur Cloak", "雪人毛皮斗篷", "entity name")
t("matted fur cloak", "暗淡無光的毛皮斗篷", "_t")
t("This fur cloak is thick and matted, yet remains incredibly soft to the touch.", "這件毛皮斗篷厚重且暗淡無光，但是摸起來卻不可思議的柔軟。", "_t")
t("Korbek's Spyglass", "庫貝克的小型望遠鏡", "entity name")
t("golden telescope", "金色望遠鏡", "_t")
t("This antique spyglass is weathered from use, but seems well maintained.", "這個年代久遠的小型望遠鏡由於使用過多有些褪色，但是仍然保養得很好。", "_t")
t("Talosis' Counterpoint", "泰勒西斯的反駁", "entity name")
t("ornate gun", "華麗的手槍", "_t")
t("It's said that Talosis never lost an argument. Now you know why.", "據說泰勒西斯從沒有輸過一場爭吵。現在你知道原因了。", "_t")
t("The Twisted Blade", "扭曲之刃", "entity name")
t("vile, twisted steamsaw", "邪惡、扭曲的蒸汽鋸", "_t")
t("You see flecks of gold in this vile mass of twisted steel, implying a once great origin. Whatever glory it once had is long gone, replaced by something far more sinister...", "你在這塊邪惡、扭曲的鐵塊上發現金色的斑點，暗示着它不同尋常的來歷。然而曾經的輝煌，都已經成爲了過去，如今已被更加邪惡的東西取代", "_t")
t("Fully heal yourself. (15 turn cooldown)", "完全治療(15回合冷卻)", "_t")
t("Sunstone", "太陽石", "entity name")
t("warm stone", "溫暖的石頭", "_t")
t("This strange stone shines with the heat of the Sun. Perhaps it could be used to generate more steam?", "這塊奇怪的石頭髮出太陽的光和熱。或許它可以用來產生更多的蒸汽？", "_t")
t("Overseer", "監視者", "entity name")
t("cracked mindstar", "破裂的靈晶", "_t")
t("Fragments of the Mindwall's power still inhabit this cracked, ancient gem.", "意念之牆的力量碎片仍然依附在這塊破裂的古老寶石上。", "_t")
t("reduces mental save", "減少精神豁免", "_t")
t("either mentally dominate or psychically stun (depending on immunities) a nearby target within range %d for %d turns (success depends on Mindpower)", "精神控制或物理震懾（根據免疫類型而定）半徑%d碼內的隨機目標，持續%d回合（成功率基於精神強度）", "tformat")
t("#Source# psychically dominates #target# through %s %s!", "#Source#使用%s%s精神控制#target#!", "logCombat")
t("Ureslak's Focus", "烏瑞斯拉克的意志", "entity name")
t("multi-hued", "混晶石", "entity subtype")
t("crystallized drake heart", "晶化龍心", "_t")
t("This cracked gemstone fell from the remains of the dead Ureslak. It appears to have been turned into a vibrant crystal in whatever process reanimated him.", "這塊有裂痕的寶石從已經死亡的巨龍烏瑞斯拉克身上掉下來。它似乎已經變成了純粹的水晶體。", "_t")
t("Starcaller", "召星者", "entity name")
t("black staff", "黑色的法杖", "_t")
t("A light staff covered in stralite and gems. It seems to reflect the light of the stars even in daylight.", "一把被藍鋯石和寶石覆蓋的輕型法杖。即使在白天，似乎也在反射着星星的光芒。", "_t")
t("Liquid Metal Cloak", "液態金屬披風", "entity name")
t("shiny metallic cloak", "閃亮的金屬披風", "_t")
t("This strange sheet of metal flows with the wind just like a normal cloak. Whoever crafted it was a true master.", "這片奇特的金屬如同普通的披風一樣隨風擺動。打造它的人無疑是一位大師。", "_t")

