section "tome-orcs/data/general/objects/generic-world-artifacts.lua"

t("potion", "藥水", "entity type")
t("potion", "藥水", "entity subtype")
t("Blood of Undeath", "不死之血", "entity name")
t("crimson phial", "猩紅的藥瓶", "_t")
t("This vial of corrupted blood reeks of death and decay. Yet somehow you feel drawn to it... Is it the tentalizing notion of eternal life? Or power? You can not tell, but the urge to drink it is great.", "這瓶腐敗的血散發着死亡和腐爛的氣味。但不知怎的，你覺得被它吸引了……這，就是永恆生命的具象化嗎？還是強大的力量？你說不出來，但你充滿了想喝它的衝動。", "_t")
t("quaff the Blood of Undeath to prepare your body for undeath", "喝下不死之血，讓自己的身體爲不死做好準備", "_t")
t("%s quaffs the %s!", "%s 大口喝下 %s ！", "logSeen")
t("#CRIMSON#You feel the Blood of Undeath rushing through your veins. Your can feel your life wither away a little (-50 maximum life, -120 minimum life).", "#CRIMSON#你感受到不死之血在你的血管裏流淌。你的生命漸漸流逝了（-50最大生命值，-120生命值下限）。", "logPlayer")
