t("power", "能量", "entity subtype")
t("Automated Portable Extractor", "便攜式自動材料提取儀", "entity name")
t([[The APE is a multifunction tinker toolbox. It can store temporarily any amount of items and when requested melt them down using metallurgic and chemical processes.
The metals are melted into lumps of ore to server for the creation of tinkers.
Any remains are melted and turned into valuable materials.]], [[這是一個神奇的儀器。它能臨時存儲當層所有撿到的道具，還能融化任何道具，將其轉化爲金子和相應的材料。
金屬裝備會融化爲相應的礦物塊，用於製作道具。
其他殘餘則會被轉化成金子或者別的有用的物資。]], "_t")
t("melt all the items in the APE at once (also done automatically when you change level)", "立刻融化提取儀內的所有道具（在你切換樓層的時候會自動融化）", "_t")
t("Make the Automated Portable Extractor the default item's destroyer?", "將便攜式自動材料提取儀設置爲默認物品轉化選項？", "_t")
t("You do not have any items to melt in your APE or on the floor.", "便攜式自動材料提取儀和地上沒有任何可以被轉化的物品。", "_t")
t("Melt all %d item(s) on the floor?", "轉化地面上的%d件物品嗎？", "tformat")
t("Melt all %d item(s) in your APE?", "轉化便攜式自動材料提取儀裏的%d件物品嗎？", "tformat")
t("You cannot bring yourself to drop the %s", "你無法丟棄 %s", "logPlayer")
