t("%s healing salve", "%s 治療藥劑", "tformat")
t("heal %d", "治療%d", "_t")
t("%s pain suppressor salve", "%s 痛苦壓制藥劑", "tformat")
t("let you fight up to -%%d life and reduces all damage by %d%%%% for %d turns (takes no time to activate)", "讓你能繼續戰鬥直到-%%d生命值，同時獲得%d%%%%全體傷害抗性。效果持續%d回合，使用不消耗時間。", "tformat")
t("%s frost salve", "%s 寒霜藥劑", "tformat")
t("remove %d physical effects and grants a frost aura (%s cold, darkness and nature affinity)", "清除%d項物理負面效果並製造寒霜光環，獲得%s寒冷、暗影和自然傷害吸收。", "tformat")
t("%s fiery salve", "%s 烈火藥劑", "tformat")
t("remove %d magical effects and grants a fiery aura (%s fire, light and lightning affinity)", "清除%d項魔法負面效果並製造烈火光環，獲得%s火焰、光系和閃電傷害吸收。", "tformat")
t("%s water salve", "%s 靜水藥劑", "tformat")
t("remove %d mental effects and grants a water aura (%s blight, mind and acid affinity).", "清除%d項精神負面效果並製造靜水光環，獲得%s枯萎、精神和酸性傷害吸收。", "tformat")
t("%s unstoppable force salve", "%s 勢不可擋藥劑", "tformat")
t("increases all saves by %d and healing factor by half", "增加全豁免%d點，增加一半治療係數", "_t")
t("armor", "護甲", "entity type")
t("light", "輕甲", "entity subtype")
t("Life Support Suit", "生命支持服", "entity name")
t("advanced medical armour", "高級醫藥裝甲", "_t")
t("\"We've done it, men. We cured death.\"", "我們做到了。我們能治療死亡。", "_t")
t([[You cannot bleed.
When you take damage, if your life is under 20%%, heal for 30%% of your max life. %s]], [[你免疫流血傷害。
當你受到傷害的時候，如果你的生命值低於20%%，將會恢復30%%的最大生命值。%s]], "tformat")
t("(%d turns until ready)", "(%d 回合冷卻完畢)", "tformat")
t("(15 turn cooldown)", "(15回合冷卻時間)", "_t")
t("BODY", "軀體", "entity on slot")
t("%s second skin", "%s 第二皮膚", "tformat")
t("HEAD", "頭部", "entity on slot")
t("%s air recycler", "%s 空氣循環裝置", "tformat")
t("Returns %d air each turn.", "每回合恢復%d空氣。", "tformat")
t("FEET", "腳部", "entity on slot")
t("%s moss tread", "%s 苔蘚之足", "tformat")
t("BELT", "腰帶", "entity on slot")
t("%s fungal web", "%s 真菌之網", "tformat")
t("Heals you for %d life when you use a salve.", "當你使用藥劑的時候，恢復%d生命值。", "tformat")

------------------------------------------------
section "tome-orcs/data/general/objects/world-artifacts.lua"

t("Medical Urgency Vest", "醫療急救背心", "entity name")
t("medical armour", "醫療裝甲", "_t")
t("This light leather armour features a special medical injector.", "這件輕型皮革背心配備有一個裝用的醫療注射器。", "_t")
t("Steam Powered Boots", "蒸汽動力鞋", "entity name")
t("Boots. But with steam power!", "蒸汽動力！", "_t")
t("Generate %d steam each time you walk.", "每當你移動時，獲得%d蒸汽。", "tformat")
t("The more steam the better!", "蒸汽越多越好！", "_t")
t("Steam Powered Helm", "蒸汽動力頭盔", "entity name")
t("A Helmet. But with steam power!", "蒸汽動力！", "_t")
t("Steam Powered Gauntlets", "蒸汽動力手套", "entity name")
t("Gauntlets. But with steam power!", "蒸汽動力！", "_t")
t("Anti-Gravity Boots", "反重力鞋", "entity name")
t("overheating steel greaves", "過熱金屬鞋", "_t")
t([[These boots seem to have been made by a... creative individual who seems to have decided that launching yourself through the air via rocketry qualifies as "anti-gravity".
They look like they will work, though.
Probably.
If you're very careful.]], [[這套鞋子似乎是被一位具有……創造力的大師製造出來的，他似乎認爲用火箭將你發射到空中就是“反重力”了。
看上去這套鞋子能用，大概。
確實有可能。
只要你非常非常小心。]], "_t")
t("These boots have a %d%% chance to fail to operate properly (reduced by Cunning).", "火箭靴有%d%%機率失敗(隨靈巧降低)。", "tformat")
t("jump to a nearby location within range %d, blasting everything within radius 2 (%d burning fire damage, 2 tile knockback) of the jump point and within radius 3 (%d burning fire damage, 3 tile knockback) of the landing point (damage based on Cunning)", "跳向半徑%d碼範圍內的地點，轟炸起跳點附近半徑2碼範圍內的所有敵人 (%d 火焰燃燒傷害，擊退2格)以及落地點附近半徑3碼範圍的所有敵人 (%d 火焰燃燒傷害，擊退3格)（傷害隨靈巧值提升）", "tformat")
t("#LIGHT_RED#You see no place to land near there.", "#LIGHT_RED#那邊你看不見着陸的空間。", "logPlayer")
t("#Source# ignites %s %s, creating a #LIGHT_RED#blast of fire#LAST# that %s!", "#Source#點燃了%s%s，創造出一股#LIGHT_RED#火焰爆炸#LAST#%s!", "logCombat")
t("engulfs %s spectacularly", "，壯觀的火焰吞沒了%s", "tformat")
t("launches %s in the air", "，將%s送上天空！", "tformat")
t("#Source# lands in a #LIGHT_RED#firey explosion#LAST#!", "#Source#引發了#LIGHT_RED#火焰爆炸#LAST#！", "logCombat")
t("Assassin's Surprise", "暗殺奇襲", "entity name")
t("glistening steel gauntlets", "閃耀光輝的鐵手套", "_t")
t("These steel gauntlets feature a hidden contraption embedded in the left index finger that fires poisonous bolts.", "這對鐵手套左手大拇指處有一個精巧的毒箭發射機關。", "_t")
t("fire a poisonous bolt out to range %d that deals %d nature damage and afflicts the target with crippling poison (%d%% fail chance) that deals %d addition nature damage over %d turns (damage based on Cunning)", "朝%d碼外的敵人發射毒液，造成%d自然傷害，並導致目標被致殘毒素(%d%% 行動失敗機率)，在%d回合內造成%d額外自然傷害（傷害受靈巧值加成）", "tformat", {1,2,3,5,4})
t("#Source# fires a bolt of #GREEN#poison#LAST# at #target# from %s %s!", "#Source#使用%s%s朝#target#發射#GREEN#毒液#LAST#！", "logCombat")
t("something", "某物", "_t")
t("Nacrush's Decimator", "納克拉什的屠殺者", "entity name")
t("unwieldy gun", "笨重的槍", "_t")
t("Nacrush was known for a tendency towards overkill.", "納克拉什因其濫殺而聞名。", "_t")
t("Knocks you back when fired.", "開火時擊退自己。", "_t")
t("#Source# recoils from the shot.", "#Source#被反衝力擊退！", "logCombat")
t("Signal", "信號槍", "entity name")
t("red barreled steamgun", "紅色槍管的蒸汽槍", "_t")
t("An odd, stubby gun with a large, red barrel.", "一把奇特、粗短的槍，裝有紅色的槍管。", "_t")
t("Glacia", "冰川", "entity name")
t("frozen gun", "冰凍的槍", "_t")
t("Strange coils encircle this extremely cold gun.", "奇怪的線圈環繞着這把極其冰冷的槍。", "_t")
t("deal cold damage equal to 100 + the higher of your steam or spellpower, and attempt to freeze the target (20% chance).", "造成100+蒸汽強度或法術強度較高項的寒冷傷害，並有20%機率冰凍目標", "_t")
t("Tinkerer's Twinblaster", "工程師的雙重爆破", "entity name")
t("two barreled steamgun", "雙管蒸汽槍", "_t")
t([[This gun seems to be some experiment in firing multiple shots simultaneously.
The design is somewhat rudimentary, but it seems to work.]], [[這把槍使用了實驗性的技術一次射出多發子彈。
設計尚未成熟，但似乎還算能用。]], "_t")
t("Flashpoint", "燃點", "entity name")
t("overheated gun", "過熱的槍", "_t")
t("\"Have you ever looked at some guys and thought 'you know, I really wish they were on fire right now', but you didn't feel like walking all the way over there? Well, there's now a better way!\"", "你是否曾經看到一些人並且想：'你知道嗎，我真的想要燒死這些人'，但是你又不想大費周章，現在有了一個更加方便的方法！", "_t")
t("S.H. Spear", "S.H.長矛", "entity name")
t("engraved steamgun", "被雕刻的蒸汽槍", "_t")
t([[This gun is engraved with a strange material which focuses mental powers.
It seems like your mind will operate even faster with this equipped.]], [[這把槍被一種能強化精神力量的神祕物質雕刻。
裝備着它，你的大腦似乎更加靈敏了。]], "_t")
t("Dreamweaver", "夢想編織者", "entity name")
t("shimmering steamgun", "閃光蒸汽槍", "_t")
t("This isn't so much a gun, as it is the idea of a gun.  You'll be able to remember it pretty easily if you lose it.", "這並不能算是一把槍，因爲它只是一把槍的概念。當你丟掉它時你就記住它了。", "_t")
t("throw the gun and cause it to explode, dealing by %d mind damage (based on Cunning and Willpower) to all targets in an area, attempting to put them to sleep, and disarming yourself for 3 turns", "將槍扔出去引發爆炸，對範圍內的所有敵人造成%d精神傷害（基於靈巧和意志），並試圖催眠它們。你自己會被繳械3回合", "tformat")
t("%s tosses %s %s!", "%s投擲了%s%s!", "logSeen")
t("%s resists the sleep!", "%s抵抗了睡眠！", "logSeen")
t("Thoughtcaster", "思維施法者", "entity name")
t("crystalline handgun", "透明的手槍", "_t")
t("From body, mind. From mind, body.", "從物質中誕生意識。從意識中誕生物質。", "_t")
t("deal %0.2f mind damage (based on Mindpower) in a radius 1 around the target", "在目標範圍1碼半徑內造成 %0.2f精神傷害（基於意志）", "tformat")
t("On hitting with a mindstar, deal physical damage equal to your steampower in radius 1 around the target.", "用靈晶命中時，在半徑1範圍內造成等於蒸汽強度的物理傷害", "_t")
t("Spider's Fangs", "蜘蛛毒牙", "entity name")
t("pouch of envenomed shots", "一袋有毒的彈丸", "_t")
t("A dedicated technician seems to have built pockets of spider venom into these rounds. It's not clear how happy the spiders were about this.", "一位熱心的技師似乎將成噸的蜘蛛毒液注入了這些子彈裏。不知道蜘蛛對此有多麼高興。", "_t")
t("(cooling down: %d turns)", "(冷卻時間: %d 回合)", "tformat")
t("Ready to trigger!", "可以觸發！", "_t")
t("bursts into an cloud of spydric poison, pinning those inside (with a 10 turn cooldown)", "爆發一陣具有定身效果的毒雲，10回合冷卻", "_t")
t("Scattermind", "破碎意志", "entity name")
t("shattered mindstar", "破碎的靈晶", "_t")
t("A linen pouch of jagged mindstar fragments, each radiating a palpable sense of confusion and pain. They must have made up an impressive whole originally, before some cretin turned it to bits.", "一個亞麻布袋中裝着鋸齒狀的靈晶碎片，讓人清晰的感受到混亂和痛苦。在某個混蛋把它打成碎片之前，它一定是一個令人無法忘懷的整體。", "_t")
t("strike the target with one of Mind Sear, Psychic Lobotomy, or Sunder Mind, at random.", "隨機使用以下技能之一打擊目標：心靈光束、精神切斷或碾碎心靈", "_t")
t("Thundercrack", "雷電打擊", "entity name")
t("pouch of copper shots", "一袋銅製彈丸", "_t")
t("Through a combination of magic and airborne probes, these shots incite powerful bolts of lightning to strike your target from above, frying them and those around them!", "這些彈藥通過魔法和探針從天空引導強力的閃電衝擊你的目標，灼燒目標及周邊的單位。", "_t")
t("a bolt of lightning strikes your target, dealing lightning damage to them and fire damage to those around them.", "一道閃電擊中目標，造成閃電傷害，並對周圍生物造成火焰傷害。", "_t")
t("Vindicator", "維序者", "entity name")
t("engraved gun", "雕花的槍", "_t")
t("\"Pesky undead plaguing your village? Necromancers ransacking your burial grounds? The Vindicator is the solution to all your woes!\"", "惱人的不死族在你的村莊傳播瘟疫？死靈法師搜刮你的墓地？維序者可以解決一切。", "_t")
t("release a burst of light dealing damage equal to your cunning plus your magic in a ball of radius 2. If the target is undead, the damage and radius are doubled.", "在半徑2範圍內造成等於靈巧加魔法的光明傷害。若目標爲不死族，傷害和半徑加倍", "_t")
t("Overburst", "強力爆裂", "entity name")
t("wide barreled steamgun", "粗管蒸汽槍", "_t")
t("\"Have you ever fired a shot into a group of monsters and thought 'there must be a better way?' Well now, there is!\"", "你曾經試過向一羣怪獸中發射一粒粒彈藥，然後覺得一定有更好的方法？好了，這就是了。", "_t")
t("Release a burst of shrapnel, dealing physical damage equal to your steampower in a cone from the target of radius 4.", "釋放榴彈，在半徑4錐形範圍內造成等於蒸汽強度的物理傷害", "_t")
t("Murderfang's Surekill", "屠牙的必殺", "entity name")
t([["Murderfang came over yesterday, raving about this idea for a steamgun he had. He described it in great detail, everything, except for how it would actually work.
What do you even grip it by? Insisted I make it though, left some design notes.
They all just say 'make it really flashy'.
 
-Pizurk, Master Tinker]], [[屠牙昨天突然跑過來，和我討論他對蒸汽槍的靈感。他詳細地描述了這把槍的構造，幾乎說了每一點細節，除了一件事——這把槍該怎麼用。
如何才能握住這樣一把槍呢？儘管如此，我還是堅持着把它做出來，雖然有一些設計沒有實現。
他們都說這把槍做的棒極了。

——工匠大師皮茲魯克]], "_t")
t("Burst apart, dealing physical damage equal to 25% of the original damage in a ball of radius 1.", "產生爆炸，在半徑1範圍內造成25%原傷害值的傷害。", "_t")
t("The Long-Arm", "長手", "entity name")
t("long barreled gun", "長管蒸汽槍", "_t")
t("This gun has an absurdly long barrel. You wonder for whom it may have been designed.", "這把槍的槍管長的出奇。你好奇這杆槍到底是爲誰設計。", "_t")
t("Focus your aim on a target, marking them for death - reducing their ranged defense by %d and their resistances by %d%%", "擊中精力瞄準一個目標，準備擊殺對方——降低對方遠程閃避%d，所有抗性%d%%", "tformat")
t("#Source# takes aim at #target# using %s!", "#Source#使用%s瞄準#target#!", "logCombat")
t("Annihilator", "殲滅者", "entity name")
t("gigantic many barreled gun", "巨大的多管蒸汽槍", "_t")
t("This gun features a wheel with several barrels attached and seems to be powered by an engine. It looks... impressive.", "這把槍的轉輪上附有多支槍管，看起來由引擎驅動。看起來令人印象深刻。", "_t")
t("Fire rate increases while firing, up to 5 shots per turn. Resets after 5 turns without firing.", "攻擊頻率隨着射擊而增加，一回合最多射5次。5回合未射擊則效果消失。", "_t")
t("50% chance to reload 1 ammo", "50% 機率裝填1發彈藥", "_t")
t("The Shotgonne", "火槍", "entity name")
t("huge gun", "巨型槍", "_t")
t([[This huge steamgun can be loaded with more than one bullet so that multiple shots can be fired in a nasty cone of death.
It also seems to have been carefully balanced to work like a dual gun set.]], [[這把巨大的蒸汽槍一次能裝填多發子彈，並以錐形彈幕射出。
它精巧的設計令它能被雙手持有。]], "_t")
t("When fired, shoots up to 4 extra shots at random foes with a radius 4 cone centered on the target.", "發射時，在半徑4的錐形範圍內隨機射出至多額外4發子彈。", "_t")
t("Cloak of Daggers", "匕首披風", "entity name")
t("bladed cloak", "佈滿刀刃的披風", "_t")
t("This cloak seems to incorporate a series of blades attached to various spring mechanisms.  Apparently the designer believed that the best defense was an active one.", "這件披風上佈滿了刀刃和機關。顯然製作者認爲'最好的防禦就是進攻'。", "_t")
t("Has a 50%% chance each turn to slash an adjacent enemy for %d physical damage (based on Cunning), making them bleed.", "每回合有50%%機率打擊鄰近的敵人，造成%d物理傷害（基於靈巧），並造成目標流血。", "tformat")
t("#Source#'s %s #GOLD#lashes out#LAST#, cutting #Target#!", "#Source#的%s#GOLD#向外割去#LAST#，切開了#Target#!", "logCombat")
t("Jetpack", "飛行揹包", "entity name")
t("a jetpack", "飛行揹包", "_t")
t("Finally.", "終於。", "_t")
t("Therapeutic Platemail", "醫療型板甲", "entity name")
t("heated armor", "加熱的板甲", "_t")
t("This thick sealed armor utilizes a ventilation system to heal your wounds using a heated mist.", "這個厚重的板甲配備有通風設備，可以使用加熱的薄霧來治療你。", "_t")
t("cleanse up to 3 poisons or wounds detrimental effects", "清除最多3個毒素和流血負面效果。", "_t")
t("Titan", "泰坦", "entity name")
t("A gun sure to turn all to ash. As long as its nearby.", "一把可以摧毀任何事物的槍，以及周邊的一切。", "_t")
t("Golden Gun", "金槍", "entity name")
t("golden gun", "金色的槍", "_t")
t("every third hit always crits.", "第三下攻擊必定暴擊.", "_t")
t("Cautery Sword", "灼燒之劍", "entity name")
t("searing sword", "熾熱的劍", "_t")
t("This sword is equipped with a heated core to add a bit of extra pain to the wounds.", "這把劍的熾熱核心可以讓敵人的傷口感到更加疼痛。", "_t")
t("inflict fire damage based on steampower", "造成基於蒸汽強度的火焰傷害", "_t")
t("Stimulus", "興奮劑", "entity name")
t("injector", "注射器", "entity subtype")
t("autosyringe", "自動注射器", "_t")
t("This injecting unit is complemented by a belt of tiny vials, containing some sickly yellow liquid. The papers describe the contents as 'invigorating' and 'increasing the combat potency.'", "這個注射單元由皮帶栓起的小型藥瓶組成，裏面裝滿了粘稠的黃色液體。論文描述這些液體可以‘使人精力充沛’並‘增加作戰能力’。", "_t")
t("inject yourself with painkillers, reducing all incoming damage by 5. Stacks up to 5 times. When the effect ends, lose 5% of your max life per stack", "朝自己注射鎮痛劑，降低所有傷害5點。最多疊加5次。當效果結束是，每層疊加會讓你損失5%最大生命值", "_t")
t("Qog's Essentials", "寇格的精華", "entity name")
t("strange injector", "奇怪的注射器", "_t")
t("A hypospray full of ...something. There is no telling what you're injecting yourself with.", "一個無針注射器，裏面裝滿了*某種*液體。你完全不知道你給自己注射了什麼。", "_t")
t("Gain a random beneficial effect", "獲得一個隨機增益效果", "_t")
t("Deflector", "偏轉", "entity name")
t("vibrating shield", "顫動的盾牌", "_t")
t("The front plate of this shield vibrates at all times, covering some strange assembly you can't quite make sense of.", "盾牌的正面不停地顫動，似乎有着某種你不理解的節奏。", "_t")
t("Knocks melee attackers away. Distance scales with damage incoming.", "擊退近戰攻擊者。距離和其造成的傷害有關。", "_t")
t("Skysmasher", "破天", "entity name")
t("rocket powered maul", "火箭錘", "_t")
t("The discovery of rockets has proved incredibly dangerous. It is not always clear for whom.", "火箭的發明被證明爲極其危險。尚不清楚對誰。", "_t")
t("Nimbus of Enlightenment", "啓蒙靈氣", "entity name")
t("elaborate cap", "精緻的帽子", "_t")
t([[They are out to get you.
This is not real this is not real this is not real.]], [[他們來了。
這不是真的不是真的不是真]], "_t")
t([[By all accounts, just an ordinary cooking pot with an array of antennae haphazardly soldered onto it. An attached manual contains nothing but fifty pages of deranged gibberish, nonsensical diagrams and lines upon lines of numbers with no apparent pattern or reason to them. 

Putting this on your head may not be the best idea.]], [[從任何角度看，都只是一個裝着天線的平凡的烹飪鍋。附贈的使用手冊寫滿了50頁的瘋言瘋語、錯亂的程序代碼與雜亂無章的數字，沒有任何可用的信息。

直接把它戴在頭上似乎不是個好點子。]], "_t")
t("%s's Shadow", "%s的陰影", "tformat")
t([[itshereitshereitshereitshere
itshereitshereitshereitshere
itshereitshereitshereitshere
itshereitshereitshereitshere]], [[他們來了！
這不是真的不是真的不是真的不是真的真的不是真的不是]], "_t")
t("#F53CBE#%s's shadow awakens!", "#F53CBE#%s的陰影覺醒了!", "logSeen")
t("Pressurizer", "穩壓器", "entity name")
t("heavy lined cloak", "沉重的披風", "_t")
t("This cloak hides and protects a series of powerful steam compressors.", "這件斗篷隱藏並保護着一套蒸汽壓縮機。", "_t")
t("Eastern Wood Hat", "東方森林之帽", "entity name")
t("worn leather hat", "破損的皮帽", "_t")
t("This hat was made from materials from a forest whose name is long since lost, far in the east. It is said to have belonged to one of the first gunslingers.", "這頂皮帽的材料來自於遙遠的樹林，人們早已遺忘了樹林的名字。據說它的主人曾是最早的槍手之一。", "_t")
t("Steamcatcher", "蒸汽捕捉器", "entity name")
t("pipe coated leather hat", "管道覆蓋的帽子", "_t")
t("There's an old saying that most of your body heat escapes through your head. It's not true of body heat, but strangely, is actually true of steam.", "傳說人體熱量大部分從頭部散失。對於體熱來說並不是這樣，但奇怪的是，蒸汽是從頭部散失的。", "_t")
t("On taking fire damage: Gain 5% of the damage as steam.", "受到的火焰傷害5%轉化爲蒸汽。", "_t")
t("Shoes of Moving Quickly", "疾行之鞋", "entity name")
t("rocket powered boots", "火箭動力靴", "_t")
t("Accurately? Less so.", "精確嗎？並不。", "_t")
t("You move 3 spaces at once.", "一次走3格", "_t")
t("Band of Protection", "守護腰帶", "entity name")
t("reinforced belt", "強化的腰帶", "_t")
t("This belt utilizes an enchanted gem to focus a burst of steam into a powerful barrier.", "這個腰帶使用強化的寶石，將涌出的蒸汽聚集萎一個強力的屏障。", "_t")
t("generate a personal shield that absorbs up to %d damage and damages attackers striking the wearer for %d fire damage while it lasts (based on Cunning)", "產生護盾，吸收%d傷害。在護盾破裂前，所有攻擊穿戴者的人會受到%d火焰傷害（基於靈巧值）", "tformat")
t("%s summons a barrier of steam from %s %s!", "%s使用%s%s召喚出蒸汽屏障!", "logSeen")
t("Viletooth", "惡毒鋸齒", "entity name")
t("rusted steamsaw", "生鏽的蒸汽鋸", "_t")
t("This aged looking saw is very rusty, and you think you see a thin layer of... something... on its blades.", "這個上了年頭的鏈鋸嚴重生鏽，而且你發現鋸刃上有一層薄薄的*東西*。", "_t")
t("may infect the target with a random disease", "可能觸發隨機疾病", "_t")
t("Mirrorazor", "鏡面剃刀", "entity name")
t("rippling portal", "泛起波紋的傳送門", "_t")
t([[The experiment of a mad chronomancer, this strange device is a portal into a backwards universe!
That is, everything there spins the opposite direction.
I guess it probably grinds things pretty well.]], [[這是一個瘋狂的時空法師的實驗，這個奇怪的裝置是進入反向宇宙的入口！
也就是說，那裏的一切都朝相反的方向旋轉。
我想它可能磨得很好。]], "_t")
t("scroll", "卷軸", "_t")
t("This parchment contains some lore.", "這張卷軸裏包含了一些手札。", "_t")
t("time-warped paper scrap", "被時間扭曲的紙片", "_t")
t("It came a long way away!", "一張羊皮紙上，記載了一些傳說。", "_t")
t("Screw that!", "糟糕！", "_t")
t("Oh, for the love of...  You're way too busy to deal with this nonsense.  You rev up Mirrorazor again, re-syncing it with the Mirror Universe, and toss the note back in.  A different note flies out the other side, miraculously not torn to shreds by the massive difference in planetary rotations.", "哦，爲了保護你的……你沒有時間處理這些廢話。你重新旋轉了鏡面剃刀，重新和鏡面宇宙建立連接，然後把紙條扔了進去。另一張紙條從另一側飛了出來，奇蹟般地沒有被兩邊轉速的巨大差異撕成碎片。", "_t")
t("#LIGHT_BLUE#Mirrorazor shudders as a note falls out from a different timeline!", "#LIGHT_BLUE#鏡面剃刀顫動着，從裏面拋出了一張來自另一條時間線的紙片！", "saySimple")
t("5 turns after use, mirror yourself across the map (centered around the location you were standing when activated).", "使用後5回合，將自己鏡像到地圖上（以激活時所站的位置爲中心）。", "_t")
t("Razorlock", "連鎖刀片", "entity name")
t("interlocked steamsaws", "連鎖在一起的蒸汽鋸", "_t")
t([[This intricate set of steamsaws lock together in a nearly indecipherable system.
They sure seem sharp though.]], "這套蒸汽鏈鋸以奇特的方式鎖在一起，看上去非常鋒利", "_t")
t("Ramroller", "剃刀平臺", "entity name")
t("a... chariot?", "一個……戰車？", "_t")
t("\"So we were thinking. You know what's better than saws? Really BIG saws. Unfortunately, no one could lift them. So we came up with an innovative new solution: Mount them on a motorized platform, allowing easy transportation and unparalleled cutting power!\"", "我們曾經這麼想：你知道比鋸子更好的是什麼嗎？巨大的鋸子。可惜沒人能夠拿得動它們。所以我們想了一個新穎的主意：將他們安裝在一個移動的平臺上，以便讓我們方便的運輸，並獲得無與倫比的切割能力。", "_t")
t("Moving builds up a stacking movement speed (caps at 25%) and damage bonus (caps at double). Hitting removes the bonus.", "移動會帶來移動速度加成(最高25%)和傷害加成(最高50%)。攻擊後加成消失。", "_t")
t("Overcutter", "超級切割者", "entity name")
t("enormous steamsaw", "大型的蒸汽鋸", "_t")
t("Earlier steamsaws were notably not meant to be used with one hand.", "顯然早期的蒸汽鋸不是爲單手使用設計的。", "_t")
t("Turbocutter", "渦輪切割者", "entity name")
t("red striped steamsaw", "紅色條紋的蒸汽鋸", "_t")
t("\"Have you ever thought your steamsaws were just too slow? Well, have I got the thing for you...\"", "你曾經覺得你的蒸汽鋸太慢了嗎？那麼，我有你需要的東西", "_t")
t("Increases the speed bonus from Saw Wheels by 25%.", "鏈鋸輪滑速度增加25%", "_t")
t("Whipsnap", "鞭笞", "entity name")
t("spring loaded steamsaw", "彈簧式蒸汽鋸", "_t")
t("\"Sick of your pesky enemies hitting you with weapons? Well, with the new spring loaded Whipsnap, you can quickly put a stop to that!\"", "你是否已經厭倦了惱人的敵人用武器攻擊你？那麼，使用裝載了彈簧的鞭笞，你可以迅速制止這一切！", "_t")
t("Pinwheel", "風車", "entity name")
t("spike tipped steamsaw", "尖端裝刺的蒸汽鋸", "_t")
t("\"Create new, exciting connections in other people's lives, such as between their feet and the floor!\"", "在他人的生命中建立全新，有趣的連接，比如他們的腳和地板！", "_t")
t("15% chance to pin the target", "15% 機率定身", "_t")
t("Frostbite", "霜咬", "entity name")
t("icy steamsaw", "冰冷的蒸汽鋸", "_t")
t("Fashioned from magical ice, and perfect for carving ice - especially ice with someone else inside it.", "因爲魔法的冰塊而知名，非常適合雕刻冰塊——尤其是裏面有人的那些。", "_t")
t("The Lumberator", "播種機", "entity name")
t("vined coated steamsaw", "爬滿藤曼的蒸汽鋸", "_t")
t("\"Spread the wonders of nature even quicker than ever with this seed injecting steamsaw! Your former enemies will be freshly grown trees before you even know it!\"", "這臺能夠注射種子的蒸汽鋸可以更快的傳播自然的奇蹟。在你意識到之前，你的敵人體內將會長出一棵樹！", "_t")
t("summon a treant (5 turn cooldown)", "召喚一個樹人 (5回合冷卻)", "_t")
t("You cannot summon; you are suppressed!", "你不能召喚，你被壓制了！", "logPlayer")
t("Not enough space to invoke!", "沒有足夠的空間召喚！", "logPlayer")
t("treant", "樹人", "_t")
t("A very strong near-sentient tree, which has become hostile to other living things.", "一棵有着極強近距離感知的樹，它對周圍的生物造成了威脅。", "_t")
t("Summon", "召喚", "_t")
t("Grinder", "絞肉機", "entity name")
t("bloody steamsaw", "染血的蒸汽鋸", "_t")
t("Originally a kitchen implement used by the giants to saw through tough, frozen carcasses. Something is especially sinister about this example though.", "起初這個鋸子只是被巨人們用來切割堅硬、冰凍的屍體。不過這個例子似乎有一些非常邪惡的暗示。", "_t")
t("On Taking Damage: Blindside the attacker (range 6).", "受傷觸發: 閃電突襲 (範圍 6).", "_t")
t("Overclocked Radius", "超頻", "entity name")
t("distorted steamsaw", "扭曲的蒸汽鋸", "_t")
t([[Faced with the petty quandaries of 'conventional physics', some mad tinker must have coated this sawblade with a fine sheathe of dilated time to maximize its speed.
 
There were ...side effects.]], "在傳統物理學的困境前，某些瘋狂的工程師將時間流嵌入鏈鋸中，以達到最大速度。\\n\\n當然，這樣存在一些小小的副作用。", "_t")
t("Attack speed increases with paradox, up to 250% at 1000 paradox.", "攻擊速度隨紊亂值增加，1000紊亂時爲250%.", "_t")
t("increase paradox by a random amount", "隨機增加紊亂值", "_t")
t("increase paradox by a drastic amount with a chance to do an anomaly (%d%% chance). If anomaly triggers, halve paradox.", "大量增加紊亂值，並有一定機率觸發異常(%d%% 機率)。如果觸發了異常，紊亂值減半。", "tformat")
t("Heartrend", "心臟切割", "entity name")
t([[There is an attached note.
 
'I've spilt the heartsblood of my work, feeling it pound, like a heart, in my palms.
Some people just can't let go until they've bled dry.']], [[上面粘着一頁筆記。
 
'我將我的心血之作分離，感受它的跳動，像心臟一樣跳動，在我的手心裏。
總有些人不到血流盡，不撒手。']], "_t")
t([[All damage dealt by or to you (that is over 1% of max life) bleeds for an additional 20% of the damage as physical damage (ignores most status resistances).
While you are bleeding, Heartrend's damage increases and it gains lifesteal.]], [[你受到與造成的所有超過1%總生命的傷害將觸發流血效果，無視大部分狀態免疫，造成額外20%物理傷害。
當你處於流血狀態時，心臟切割傷害增加並具有吸血效果。]], "_t")
t("If bleed damage per turn is greater than 5% of max life, attacks cleave.", "若每回合流血傷害傷害超過5%最大生命，攻擊變爲劈擊。", "_t")
t("Dethzaw", "死忘鏈據", "entity name")
t("fiery steamsaw", "火焰蒸汽鋸", "_t")
t([[Grushgore the Destroyer was absolutely enthralled when he discovered steamsaws. He immediately kidnapped several tinkerers and forced them to create this for him.
His naming skills have not improved.]], [[毀滅者格魯什戈爾發現蒸汽鏈鋸時十分激動，他立刻抓了幾個工程師，強迫他們爲他做了這個。
他的取名技巧從沒有得到提高。]], "_t")
t("deal a melee attack against all other enemies in a circle around you", "對周圍一圈敵人進行近戰攻擊。", "_t")
t("Galen's Flowing Robe", "蓋倫的科技法袍", "entity name")
t("ample robe", "微妙地法袍", "_t")
t("This robe was worn by the Technomancer Galen, infused with technomancy enchantments it is said to react to techno-spells!", "這身法袍是科技法師蓋倫的創造，加入了科技法術的強化力量，可以對科技法術做出反應！", "_t")
t([[20% chance when casting a technomancy spell (or 10% chance when casting a normal spell) to power-up the internal defense circuits of the robe.
The circuit will do one of:
#AQUAMARINE#if more than one foe is in melee range#LAST#: teleport away all foes
#AQUAMARINE#if below 50% life#LAST#: increase all resistances by 20% for 5 turns
#AQUAMARINE#if below 20 steam#LAST#: supercharge the arcane dynamo to produce 4 more steam per 10 mana spent for 5 turns
#AQUAMARINE#otherwise#LAST#: reset the cooldown of the spell with the highest remaining cooldown
]], [[當你釋放科技法術的時候，你有20%機率（釋放普通法術的時候機率爲10%）激活長袍內部的防禦電路。
防禦電路會帶來以下效果之一：
#AQUAMARINE#如果近戰範圍內有超過一個敵人#LAST#：將所有敵人傳送走
#AQUAMARINE#如果生命值在50%以下#LAST#：提升所有抗性20%，持續5回合
#AQUAMARINE#如果蒸汽值低於20#LAST#：超載奧術發電機，每10點法力值額外產生4蒸汽，持續5回合
#AQUAMARINE#其他情況#LAST#：重置目前剩餘冷卻時間最長的法術的冷卻時間
]], "_t")
t("#PURPLE#%s activates and teleports away all nearby creatures!", "#PURPLE#%s啓動，傳送走了周圍的所有生物!", "logSeen")
t("#PURPLE#%s activates and increases %s's resistances!", "#PURPLE#%s啓動，增加了%s的抗性!", "logSeen")
t("#PURPLE#%s activates and increases %s's arcane dynamo power!", "#PURPLE#%s啓動，增強了%s的奧術發電機的能力!", "logSeen")
t("#PURPLE#%s activates and resets %s's %s cooldown!", "#PURPLE#%s啓動，降低了%s的%s的冷卻時間!", "logSeen")
t("Galen's Will", "蓋倫的意志", "entity name")
t("aether-infused steamsaw", "奧術灌注的鏈鋸", "_t")
t("Saws made of metal? That is no good for a discerning Technomancer so Galen made a saw out of pure arcane forces!", "金屬製作的鏈鋸？挑剔的科技法師可不會滿足於此，所以蓋倫用純奧術力量製造了一把鏈鋸！", "_t")
t("Increases the steam your arcane dynamo generate per 10 points of mana by 2.", "增加你的奧術發電機產生的蒸汽量，每消耗10點法力值產生的蒸汽量增加2。", "_t")
t("Eye of the Lost", "迷失之眼", "entity name")
t("pale mindstar", "蒼白的靈晶", "_t")
t("A strange aura surrounds this mindstar. You feel a presence, but it is obscured, as if it refuses to be found.", "靈晶周圍有一層奇怪的領域。你能感覺到某個存在，但它被遮蔽了，就像它不願意被察覺到一樣。", "_t")
t("reduces mental save", "減少精神豁免", "_t")
t("see all other beings around you for 5 turns", "看到你周圍所有的生物5回合", "_t")
t("Brass Goggles", "銅製護目鏡", "entity name")
t("classy goggles", "經典的護目鏡", "_t")
t("No self respecting craftsman would be caught without them!", "沒有任何一個自愛的工匠會被人發現沒有佩戴它！", "_t")
t("X-Ray Goggles", "X射線護目鏡", "entity name")
t("pitch black goggles", "漆黑的護目鏡", "_t")
t("How do these even work?", "這玩意到底怎麼用?", "_t")
t("see everything. EVERYTHING. For 5 turns, anyway", "看到所有東西。*所有東西*。當然，只有5回合。", "_t")
t("Laser Powered Giant Smasher", "激光驅動巨型粉碎器", "entity name")
t("radiant hammer", "光輝的錘子", "_t")
t("The Laser Powered Giant Smasher, nicknamed the Gloryhammer. You can feel it vibrating with untold power in your hands.", "激光驅動的巨型粉碎器，綽號“光錘”。你能感覺到它在你的手中以無窮的力量震動。", "_t")
t("#PURPLE#You feel the power of the Gloryhammer course through you! It has become fully empowered!", "#PURPLE#你感受到光榮之錘的力量環繞着你！它的力量被完全釋放了！", "logPlayer")
