.maets dezirusserp fo tsrub ro maerts a stime ,hctaw ot gnitrecnocsid rehtar gnieb ot noitidda ni ,hcihw ,ylediw dnetsid ro tuhs laes ot meht lliw nac yeht tub ,lla ta gnihton ro tsim eltneg a rehtie time dna elbisivni ylraen era yeht tser ta ;siht revo lortnoc suoicsnoc detimil evah yehT  .maets dezirusserp gnittime fo elbapac era hcihw stnev dna serop suoremun sah niks rieht - deman era yeht hcihw rof ,maets rieht ylniatrec tsomla si tiart lacisyhp gnihsiugnitsid tsom riehT  .(arakiaD fo stnaig gnorts ylevitpeced tey ,ylgnag eht ot tsartnoc ni) edis ykcots eht no ylthgils dna llat teef 01-8 yeht erew ,ekil kool dluow snamuh tahw ot ralimis ylgnikirts era stnaiG maetS

.ti htiw hcum os hsilpmocca ot meht rof ysae os ti edam taht ytilauq evitiutni siht si ti spahrep ;gnihtaerb sa stnaiG maetS eht ot yllarutan sa semoc taht tnemtsujda dna noitnetta seriuqer dohtem siht tub ,retaw liob ot ecanruf a gnisu yb deveihca eb yllaciteroeht nac tceffe ralimis A  .snoitpartnoc xelpmoc erom dna erom ereht morf dna ,renaelc-enots dezirusserp fo tros a derevocsid yeht ,ereht morf ;eltsihw elpmis a saw "hcet-maets" fo tib tsrif eht taht mialc yeht ,sretsasid rehto dna serif lanoisacco ot tsol neeb evah stxet tsedlo 'stnaig eht hguohtlA  .snoitpartnoc cillatem fo yarra ediw a etarepo dna rewop ot maets siht esu ot woh tuo derugif evah yeht ,ylsuoinegni rehtaR

 (.scrO neeb evah yltnecer tsuj litnu srobhgien ylno rieht sa gniees ,weiv elbadnatsrednu yleritne na si sihT)  .tnasaelpnu dna hsiroob eb ot "secar ressel" eht dnif ylerem ot demialc ot ekops I somtA rehto eht fo tsom ,sredistuo ot od dluoc noitnevretni sselerac rieht tahw dna ,meht ot od dluoc dlrow edistuo eht tahw htob fo raef ot eud saw siht smialc sorysaK rolicnuoC dnarG elihw ;muminim a ot secar rehto htiw snoitcaretni rieht tpek evah yehT  .meht detacidare evah dluow ylerus ti taht rebmun ni wef os dna detartnecnoc os erew yeht rof ,yleritne meht dessim ezalbllepS eht taht meht rof etanutrof ylurt si ti ;sega rof sniatnuom krolC eht ni neddih evah ebirT somtA eht fo stnaiG maetS ehT

.detsat reve evah I ehtnisba tseb eht ekam ot woh denrael evah yeht taht eton laiceps ekam tsum I leef I ,esnes retaerg a ni elpoep somtA eht no stcelfer ti woh yas tonnac I hguohtlA  .("devlovni lla rof gnissarabme ylpeed saw" em llet ylno dluow sorysaK hcihw ,ramalgarT gniK rednu doirep feirb a morf edisa) tropsdoolb dna ycarcomed neewteb esimorpmoc tnerappa na yb nesohc si ,ylgnidrocca ,tnemnrevog riehT  .stnev s'eno morf maets erom tuo ecrof ot elba gnieb ylpmis RO noitcurtsnoc tneiciffe erom hguorht lufrewop erom edam eb nac hcet-maets taht tcaf eht ot gniwo spahrep ,stiusrup lautcelletni sa hcum sa yltcaxe tsomla ssentif lacisyhp eulav yeht taht si ees ot elba saw I gniton htrow thgisni repeed ylno eht ;yats feirb ym gnirud yteicos siht ezylana ylluf ot epoh ton dluoc I  .evitcepsrep hserf emos snezitic sih tnarg ot smodgniK deillA dna llawnuS eht htiw edart nepo nugeb sah ohw ,sorysaK ot gnidrocca ,ytilaer ot noitcennocsid dna yrtsihpos fo niarts a deretsof osla sah ti ,poleved yteicos rieht tel ot ecaep meht nevig sah noitalosi siht elihW

.emoc ot ega na rof su htiw seilla gnirudne eb lliw yeht taht derusne sah [b]SNEVAEH EHT FO REGAVAR TNEDUPMI ,SUTALOMMI[/b] reednammoc ot stpmetta s'redael rieht gnitrawht dna noillebeR kurK eht gnihsurc ni pleh riehT  .sevlesmeht rof seitic rieht ees ot dewolla eb noos lliw flesym naht rehto sredistuo spahrep dna ,nosrep ni meht fo erom teem ot ytinutroppo eht niag noos lliw ew ,spihsria morf deppord stcurtsnoc aiv enod llits si somtA eht htiw tcatnoc ruo fo tsom hguohtla ,esac eht revetahW  ?sesoprup lasopsid rof latropraf yrotarolpxe na gnisu tuoba gnihtemos - layE'jaM fo oreH eht htiw gniteem a degnarra sah eh rof ,regnol yna em ynapmocca tonnac eh em sllet sorysaK  .siht naht erom nrael ot hguone gnol rof meht yduts ot elba ton saw I ,salA]], [[。人族的他究研自親我請邀他，在現。族種多衆些那的悉熟不所人族的他上界世個這解了以用，書的我過讀經曾人本長議斯羅西卡，是的運幸。會機的東遠往通門送傳古遠用使何任有沒乎幾，民平的樣這我像，則否。面一開網兵衛賂賄錢的夠足用能，商富的貫萬纏腰是者或，戚親的人本王國克拉託，民公的壘堡陽太是你非除——便方麼什供提究研的我給有沒並，近接的樣這間之們我，而然！明文的達發度高個一樣這着藏然竟，下底皮眼的們我在就，吧看想想

。安不人令爲頗來起看景場的樣這，汽蒸壓高團一或流氣股一出放，口氣排張擴或閉封動主以可也們他，是但。到不看也麼什脆幹者或，霧薄的柔輕到看稀依能只，的見可不是常通爲行氣排的們他，候時的息休在；制控動主的限有行進爲行的氣排對以可們他。汽蒸的壓高出排中從以可，口風通和孔毛多許有上膚皮的們他——因原的人巨汽蒸爲名命被們他是就這，汽蒸的上身們他是徵特貌外的性志標具最們他。比對的明鮮了成形人巨的壯強地料意人出但高瘦些那拉卡岱與這，胖矮顯稍材身，尺英01-8高身們他，似相地人驚類人與來起看人巨汽蒸

。西東的多樣這現實汽蒸用地鬆輕此如以可們他讓，覺感的觀直種這爲因是正，許或。單簡樣一吸呼同如都說來人巨汽蒸於對切一這而，汽蒸制控、注關細仔者作操要需種這過不，果效的似類到達，汽蒸生產以可也水熱加來子爐用使，上理原。置裝的雜復越來原列系一了明發漸逐後然，法方的面表體物潔清汽蒸壓加用使了明發們他，後之此在。子哨的單簡種一是隻”技科汽蒸“的早最，稱聲們他，了毀摧害災的他其和災火的然偶被錄記字文的早最們人巨些這管盡。法方的置裝屬金的樣各種各縱操和動驅來汽蒸股這用使了到想地妙巧當相們他

（法看種這的們他解理以可全完我，人獸是就居鄰的一唯們他，前之久不到直到慮考）。已而快不人令又野粗又”族種等下“些那得覺是隻們他，法說的人的族部之氣他其從我照按但，響影的樣怎來帶人的界世面外給會能可明發的慎謹不們他怕害也，脅威的成造們它對能可界世部外怕害既們他爲因是這，法說的長議斯羅西卡照按。度限低最到低降動互的間之族種他其與將力盡們他。們他絕滅全完會怕恐害災的樣這，少稀麼這是又口人，中集此如境環存生的們他到慮考，響影的炸爆大法魔到受未從們他，是的運幸；紀世個幾了匿藏中脈山克拉克在人巨汽蒸的族部之氣

。術技的酒艾苦的好最的過嘗所我造釀着握掌還們他，句一提別特要必有還我得覺我，質品要重種某的人族部之氣了映反否是這道知不我管盡。（“的尬尷當相是都說來員人關相有所對事件這”，我訴告只斯羅西卡，期時暫短的治統瑪拉格拉特王國了除）的來出拔選度制的成而合結技競腥血和制體主民由種某過通是，府政的們他，此因。量力體肉的大強，的汽蒸多更出噴中孔氣排從夠能於自來以可[b]也[/b]，計設的效高巧精於源來以可僅不，量力的技科汽蒸的們他，爲因是這許也。要重樣同求追的慧智對和的看壯健體身將們他是就，素因層深的中會社們他，的到意注夠能一唯我，此因。會社的們他析分入深夠能間時有沒並，會機的裏這在留停暫短有隻我於由。角視新全的題問待看些一來帶人族的他給能望希，易貿放開的間之國王合聯與壘堡陽太和了始開近最他，此因。想思的實現離脫，辯詭導倡中會社們他了長助也時同這，間空平和的要需所展發會社們他了給絕隔的界外和管盡，法說的斯羅西卡照按

。友盟的愧無之當中間時段一來未們我是會將們他，明證們我向經已，獻貢的出作所中[b]者虐肆空天的恥無，地動天撼[/b]占強袖領的們他止阻及以，亂叛克魯克碎粉在們他。市城的麗美們他問訪自親可許被，者訪來的外之我了除有會還來未，許也。會機的觸接面對面們他多更和得獲會就快很們我，置裝的來下掉上艇飛從是就，道渠的通溝的一唯間之族部之氣和人分部大們我管盡，樣怎管不？理清圾垃行進來門送傳古遠險探用使關有是像好——會聚場一了好排安經已間之雄英的爾亞埃·基馬和他爲因，了我陪再能不他，我訴告斯羅西卡。了些這有隻現發的我以所，間時的長夠足們他究研會機有沒我，唉]], "_t")
t("races...?", "種族……？", "newLore category")
t("Scholar Graynot's Assessment of the Species, Chapter 48: Steam Giants", "博學者格雷諾特關於人種的調查——第四十八章——蒸汽巨人", "_t")
t([[To think such an advanced civilization was hiding nearly right under our noses!  Not that the proximity made it any easier for me to conduct my research - it seems that unless you're a Sunwall citizen, a blood relative of King Tolak, or a merchant with enough gold to bribe the guards to look the other way, it's nearly impossible for a civilian to use the portal to the East.  Fortunately, Grand Councilor Kasyros himself was shown my writings to give him a basic overview of all the species his people were unfamiliar with, and he requested my presence to study his people.

Steam Giants are strikingly similar to what humans would look like, were they 8-10 feet tall and slightly on the stocky side (in contrast to the gangly, yet deceptively strong giants of Daikara).  Their most distinguishing physical trait is almost certainly their steam, for which they are named - their skin has numerous pores and vents which are capable of emitting pressurized steam.  They have limited conscious control over this; at rest they are nearly invisible and emit either a gentle mist or nothing at all, but they can will them to seal shut or distend widely, which, in addition to being rather disconcerting to watch, emits a stream or burst of pressurized steam.

Rather ingeniously, they have figured out how to use this steam to power and operate a wide array of metallic contraptions.  Although the giants' oldest texts have been lost to occasional fires and other disasters, they claim that the first bit of "steam-tech" was a simple whistle; from there, they discovered a sort of pressurized stone-cleaner, and from there more and more complex contraptions.  A similar effect can theoretically be achieved by using a furnace to boil water, but this method requires attention and adjustment that comes as naturally to the Steam Giants as breathing; perhaps it is this intuitive quality that made it so easy for them to accomplish so much with it.

The Steam Giants of the Atmos Tribe have hidden in the Clork mountains for ages; it is truly fortunate for them that the Spellblaze missed them entirely, for they were so concentrated and so few in number that it surely would have eradicated them.  They have kept their interactions with other races to a minimum; while Grand Councilor Kasyros claims this was due to fear of both what the outside world could do to them, and what their careless intervention could do to outsiders, most of the other Atmos I spoke to claimed to merely find the "lesser races" to be boorish and unpleasant.  (This is an entirely understandable view, seeing as their only neighbors until just recently have been Orcs.) 

While this isolation has given them peace to let their society develop, it has also fostered a strain of sophistry and disconnection to reality, according to Kasyros, who has begun open trade with the Sunwall and Allied Kingdoms to grant his citizens some fresh perspective.  I could not hope to fully analyze this society during my brief stay; the only deeper insight worth noting I was able to see is that they value physical fitness almost exactly as much as intellectual pursuits, perhaps owing to the fact that steam-tech can be made more powerful through more efficient construction OR simply being able to force out more steam from one's vents.  Their government, accordingly, is chosen by an apparent compromise between democracy and bloodsport (aside from a brief period under King Traglamar, which Kasyros would only tell me "was deeply embarassing for all involved").  Although I cannot say how it reflects on the Atmos people in a greater sense, I feel I must make special note that they have learned how to make the best absinthe I have ever tasted.

Alas, I was not able to study them for long enough to learn more than this.  Kasyros tells me he cannot accompany me any longer, for he has arranged a meeting with the Hero of Maj'Eyal - something about using an exploratory farportal for disposal purposes?  Whatever the case, although most of our contact with the Atmos is still done via constructs dropped from airships, we will soon gain the opportunity to meet more of them in person, and perhaps outsiders other than myself will soon be allowed to see their cities for themselves.  Their help in crushing the Kruk Rebellion and thwarting their leader's attempts to commandeer [b]IMMOLATUS, IMPUDENT RAVAGER OF THE HEAVENS[/b] has ensured that they will be enduring allies with us for an age to come.]], [[想想看吧，就在我們的眼皮底下，竟然藏着這樣一個高度發達的文明！然而，我們之間這樣的接近，並沒有給我的研究提供什麼方便——除非你是太陽堡壘的公民，托拉克國王本人的親戚，或者是腰纏萬貫的富商，能用足夠的錢賄賂衛兵網開一面。否則，像我這樣的平民，幾乎沒有任何使用遠古傳送門通往遠東的機會。幸運的是，卡西羅斯議長本人曾經讀過我的書，用以瞭解這個世界上他的族人所不熟悉的那些衆多種族。現在，他邀請我親自研究他的族人。

蒸汽巨人看起來與人類驚人地相似，他們身高8-10英尺，身材稍顯矮胖，這與岱卡拉那些瘦高但出人意料地強壯的巨人形成了鮮明的對比。他們最具標誌性的外貌特徵是他們身上的蒸汽，這就是他們被命名爲蒸汽巨人的原因——他們的皮膚上有許多毛孔和通風口，可以從中排出高壓的蒸汽。他們可以對排氣的行爲進行有限的主動控制；在休息的時候，他們的排氣行爲通常是不可見的，只能依稀看到輕柔的薄霧，或者乾脆什麼也看不到。但是，他們也可以主動封閉或擴張排氣口，放出一股氣流或一團高壓蒸汽，這樣的場景看起來頗爲令人不安。

他們相當巧妙地想到了使用這股蒸汽來驅動和操縱各種各樣的金屬裝置的方法。儘管這些巨人們最早的文字記錄被偶然的火災和其他的災害摧毀了，他們聲稱，最早的“蒸汽科技”只是一種簡單的哨子。在此之後，他們發明了使用加壓蒸汽清潔物體表面的方法，然後逐漸發明了一系列原來越複雜的裝置。原理上，使用爐子來加熱水也可以產生蒸汽，達到類似的效果，不過這種需要操作者仔細關注、控制蒸汽，而這一切對於蒸汽巨人來說都如同呼吸一樣簡單。或許，正是因爲這種直觀的感覺，讓他們可以如此輕鬆地用蒸汽實現這樣多的東西。

氣之部族的蒸汽巨人在克拉克山脈中藏匿了幾個世紀；幸運的是，他們從未受到魔法大爆炸的影響，考慮到他們的生存環境如此集中，人口又是這麼稀少，這樣的災害恐怕會完全滅絕他們。他們盡力將與其他種族之間的互動降低到最低限度。按照卡西羅斯議長的說法，這是因爲他們既害怕外部世界可能對它們造成的威脅，也害怕他們不謹慎的發明可能會給外面世界的人帶來怎樣的影響，但按照我從其他氣之部族的人的說法，他們只是覺得那些“下等種族”又粗野又令人不快而已。（考慮到直到不久之前，他們唯一的鄰居就是獸人，我完全可以理解他們的這種看法）

按照卡西羅斯的說法，儘管和外界的隔絕給了他們社會發展所需要的和平空間，這同時也助長了他們社會中倡導詭辯，脫離現實的思想。因此，他最近開始了和太陽堡壘與聯合王國之間的開放貿易，希望能給他的族人帶來一些看待問題的全新視角。由於我只有短暫停留在這裏的機會，並沒有時間能夠深入分析他們的社會。因此，我唯一能夠注意到的，他們社會中的深層因素，就是他們將身體健壯看的和對智慧的追求同樣重要。也許這是因爲，他們的蒸汽科技的力量，不僅可以來源於精巧高效的設計，[b]也[/b]可以來自於能夠從排氣孔中噴出更多蒸汽的，強大的肉體力量。因此，他們的政府，是通過某種由民主體制和血腥競技結合而成的制度選拔出來的（除了國王特拉格拉瑪統治的短暫時期，卡西羅斯只告訴我，“這件事對所有相關人員來說都是相當尷尬的”）。儘管我不知道這是否反映了氣之部族人的某種重要品質，我覺得我還有必要特別提一句，他們還掌握着釀造我所嘗過的最好的苦艾酒的技術。

唉，我沒有機會研究他們足夠長的時間，所以我的發現只有這些了。卡西羅斯告訴我，他不能再陪我了，因爲他和馬基·埃亞爾的英雄之間已經安排好了一場聚會——好像是有關使用探險遠古傳送門來進行垃圾清理？不管怎樣，儘管我們大部分人和氣之部族之間唯一的溝通的渠道，就是從飛艇上掉下來的裝置，我們很快就會獲得和更多他們面對面接觸的機會。也許，未來還會有除了我之外的來訪者，被許可親自訪問他們美麗的城市。他們在粉碎克魯克叛亂，以及阻止他們的領袖強佔[b]撼天動地，無恥的天空肆虐者[/b]中所作出的貢獻，已經向我們證明，他們將會是我們未來一段時間中當之無愧的盟友。]], "_t")
t("Scholar Graynot's Assessment of the Species, Chapter 83: Wei...", "博學者格雷諾特關於人種的調查——第八十三章——Wei...", "_t")
t("(This note had already caught fire when the paradox anomaly pulled it in from another timeline.  You only had time to read part of the title before it burned away completely.)", "(當時空異常從另一條世界線拉入這條紙條的時候，這張紙條突然着火了。你還沒來得及看完標題，這張紙條已經被燒得一乾二淨。)", "_t")

------------------------------------------------
section "tome-orcs/data/lore/orcs.lua"

t("orc prides", "獸人部落", "newLore category")
t("The Shunned Kruk", "隱逸的克魯克部族", "_t")
t([[Our pride has never been held in high esteem by the others.  We were the backbone of Garkul's army, the supply-runners, the road-builders, the medics tending to the wounded - all roles that had to be done to support those who gloriously fought in the thick of battle...  Alas, all this meant is that the others only barely accepted our necessity, barely concealing their distaste for us "cowards" and "weaklings."  Garkul stood up for us whenever the opportunity arose, so their prejudices were a moot point until his defeat; unfortunately, once the Allied Kingdoms started pushing us back and attacking the fortified towns we'd built in Maj'Eyal, we took the blame for not making them strong enough to hold off all attackers.  "What good are they?"  Rak'shor once asked.  "Even when they're hiding behind us, they still can't make anything worthwhile!"  When it was revealed that our then-leader had held off the Allied Kingdoms at one of their strongholds to buy enough time for most of our Pride's women and children to retreat to Var'Eyal, by way of launching ancient Nargol golems into human ranks via trebuchet, the accusations of cowardice gave way to ones of selfishness and betrayal.  We kept quiet about them, hoping to change their minds when rebuilding Orcish towns in Var'Eyal, hoping that they would come to see reason when they had roofs over their heads and wells to drink from, courtesy of our Pride; it seemed to work for the time being.  We kept our distance from the others, building our own homes in a distant corner of the continent, and only sending small groups out to do minor repair and construction.  The walls we built were strong enough to keep the Sunwall forces from simply walking over them, and that seemed to be enough.

Alas, this acceptance would neither grow nor last.  One fateful night, Grand Architect Kruk came running back after a meeting with the other leaders of the Prides, saying we had to leave immediately, and that the women had to go first.  To this day, we are not entirely certain what drove her to such a panic...  she only told us that we would never want peace with the other Prides if we knew what we were running from, and that we may need that peace someday.  We swiftly built a bridge to the Clork Peninsula over the next few days, looking back over our shoulders towards the other Prides as we worked, and on the night the last Orc made it across, Kruk set it ablaze with burning arrows.  On the distant shore, we could only see the torches of those who we had narrowly escaped.

We barely had time to sigh in relief before a thunderous noise roared above us, and a bright light came down from the sky, lighting us up but leaving the surrounding land dark.  A curious sort of golem fell from it, made of springs and gears rather than runes and stone.  It spoke with a scratchy yet organic-sounding voice, asking what had happened and what had caused the lights and noises in the dead of night; we told it we had fled the mainland for our own safety, and that we were only looking for a place to exist.  Hooks descended from the whirring airship above, dragging the construct back up, and it left without another word.

We found a suitable home on the far side of the mountain range, shielded by the surrounding hills and yet fertile enough to sustain us.  Once we had settled in, the airships and constructs began visiting us more and more often, at first simply watching, then conversing with us and even helping us build homes.  It was not too long until one of the constructs' masters finally came to speak with us in person; he introduced himself as one of the Atmos, the Steam Giants we'd assumed for so long to be merely an ancient myth.  They were a strange people, and one we began to admire as we became fast friends.  Wise and reasoned yet valuing strength, neither overly arrogant nor overly timid...  a bit on the frivolous and eccentric side, but living for countless ages alone on a mountaintop would do that to anyone, we reasoned.  Likewise, they seemed to think of us as their rambunctious but gifted children, and when they began to teach us of their steam-pressure-driven machinery, they were impressed by how quickly we adapted to and improved on it.  They gave us guidance and wisdom, we gave them drive and innovation; we could have become true allies, if we'd only had enough time.

All good things must come to an end, it seems.  One day, a panicked scout ran into our camp and announced that an Orcish army had arrived by boat on the shores of the Clork Peninsula, and was charging toward us with hostile intent.  Whatever they had originally wanted that drove Grand Architect Kruk away, they were no longer content to go without it.

We told the Atmos, and they told us to simply reason with them; they had clearly never been under attack!  We would obtain no assistance from them, not even when our lives clearly depended on it.  Instead, Grand Architect Kruk showed us a series of schematics she'd made, ones that she dared not reveal before for fear of the Atmos seeing them - ones showing how to turn our helpful steam contraptions into hideously effective weaponry.  A harness to wear the great whirling lumber-saws as weapons, portable steam generators so we could power our machinery like the Atmos could without being tethered to a pipe or hose, a means of removing the safety mechanisms on nail-guns and swapping their barrels out so they could fire sling-bullets at incredible speeds, a giant version of the jewelry-plating device they gave us that could electrocute dozens of invaders at once...

We held strong when the other Prides came for us, and we were fighting with weapons they had never encountered before, inflicting wounds they had never learned to tolerate or heal, fighting with forces that they could not hope to even understand, let alone fight.  The shrieking din of sawblades shredding through armor and severing limbs, the screams of Gorbat's wyrm-riders as giant grappling hooks pulled them out of the sky, the smell of Orcish flesh cooked through to the core by lightning or scalded by jets of steam, the rattling of steamguns as they turned an attacking formation into a pile of corpses - these sensations might haunt the nightmares of Atmos and the other Prides, but to us they were the sweet sounds, sights, and smells of victory and safety.  We had prevailed, with only a handful dead on our side before they fled.  Kruk Pride would not be conquered.

The Atmos, however, did not see the dire circumstances we were in.  They did not see the threat we faced, and I doubt that even if the Grand Architect of the Pride had told them what she knew, they would have listened.  All they saw was their tools of creation being used to destroy, their beautiful inventions being used for something so monstrous, their darling clever "children" causing bloody carnage on a scale hundreds of times greater than they'd ever seen.  They denounced us, and those who had begun to mingle with us promptly retreated back to the mountains.  We were no longer welcome using their technology, and perhaps not even living near their mountains.

We will miss their company, their ancient wisdom, and their cautious kindness.  We will not miss their squeamish ignorance and pompous self-righteousness.]], [[我們的部落從來沒有受到其他人的尊重，我們是加庫爾軍隊的支柱，是補給的運送者，道路的建設者，照料傷者的治療師——這些角色都是支持我們的同胞在激烈的戰鬥中光榮作戰必需的……唉，但我們所做的一切，僅僅勉強得到其他人的接受。他們毫不掩飾對我們的厭惡，勉強掩飾着對我們這羣“弱者”和“懦夫”的鄙夷。每當這種矛盾爆發，加庫爾總會挺身而出。所以在他去世前，他們對我們的偏見還有所收斂。然而不幸的是，當聯合王國開始反擊，全力進攻那些我們所建造的堡壘的時候，我們被成爲了千夫所指的對象，因爲我們的堡壘沒法堅固到抵擋一切敵人的程度。“他們到底有什麼用？”拉克·肖這樣說道，“即使他們整天躲在我們身後，他們也什麼事都幹不好！”後來，在他們知道我們當時的領袖在聯合王國的一個要塞抵擋，用投石機把古代納格爾王國的傀儡投放到人類軍隊裏，來爲自己部落的婦女和兒童撤回瓦·埃亞爾爭取足夠時間之後，那些對於我們懦弱的指控，卻又轉變成了“自私”和“背叛”。我們一言不發，希望在重建瓦·埃亞爾的獸人城鎮的時候能改變他們的看法，覺得當他們住在我們建造的屋檐下，從我們的水井中飲水的時候，能理智地感受我們部落的好意；當時，我們以爲這種方法確實奏效了。我們與其他人保持距離，在大陸的遠處一隅建立我們的家園，只送出小隊的人員，做一些輕度的修復和建設工作。我們建造的城牆能將太陽堡壘的部隊擋在外面，這看上去就足夠了。
唉，可是這樣的認可再也沒法增長也不會持續下去了。在一個命運的夜晚，大工匠克魯克在和其他部落首領開完會後跑回來，告訴我們得立即離開，並且女人先走。直到今天我們也沒完全確定，到底是什麼讓她如此慌張……她只是告訴我們，如果我們知道了那是什麼，就再也不想和別的部落和平了，而我們或許有一天需要那份和平。我們在接下來的幾天內，迅速地建了一座通往克拉克半島的橋，一邊建着一邊注意着身後那些部落的動靜。在最後一個獸人通過的當天晚上，克魯克用燃燒箭點着了那座橋。在遠處的海岸線上，我們只能看到自己驚險逃過的追兵手中舉着的火把。
我們剛剛得以放鬆喘息，一個東西在我們頭上發出雷鳴般的呼嘯。一束強光從天上打下，照亮了我們，周圍的地面卻仍然是暗的。一種奇特的傀儡從那東西上降落，它以彈簧和齒輪而不是符文和石頭製成。它用一種沙啞又像是活物發出的聲音說話，問我們發生了什麼，爲何在沉寂的夜晚發出光和噪聲；我們告訴它，我們剛剛爲了自身的安危從大陸逃來，我們只是想找個地方生存。盤旋的飛艇從上面伸下了鉤子，把那個機械拉了回去，然後一言不發地離開了。
我們在山脈的遠端找到了一個合適的家園，以周圍的羣山做防禦，卻又有足夠肥沃的土地來養活我們。我們一入住，那些飛艇和機械就開始越來越頻繁地造訪。他們一開始僅僅是袖手旁觀，後來與我們打起交道，甚至幫我們建造房屋。不久以後，那些機械的一個主人終於親自來和我們會面；他自稱爲氣之部族的一員，也就是蒸汽巨人，我們很長時間都認爲只是古代神話纔有的部族。他們是一羣奇怪的人，我們很快與他們交好並敬愛着他們。他們珍視理性而又重視力量，性格不卑不亢……儘管有時有些輕浮和古怪，不過我們想，獨自在山頂待上長久時光的人都會這麼對待其他人。相應地，他們也認爲我們是他們那難以控制卻又充滿天賦的子女。當他們開始教我們使用那些蒸汽機械科技時，他們對於我們很快適應並改造它的表現充滿了驚喜。他們給予我們指導和智慧，我們給他們動機和靈感；如果有足夠長的時間，我們雙方本可以變成真正的盟友。
然而，好景不長。一天，一個驚慌的斥候跑進大營，告訴我們，一支獸人軍隊走水路到達克拉克半島的海岸上，帶着敵意向我們襲來。不管當初他們把大工匠克魯克趕走的原因是什麼，他們現在已經決心要將我們趕盡殺絕。
我們告訴氣之部族，他們卻跟我們說只要和獸人軍隊談談就行；這些巨人們從來沒有受過攻擊！在我們這樣生死存亡的罐頭，我們從那些巨人那裏得不到任何援助。相反，大工匠克魯克給我們展示了一系列她的設計圖，這是一些她之前不敢公開，生怕氣之部族看到的東西————這些設計能把我們那些有益又奇特的蒸汽裝置，變成可怕又有效的武器。其中有一種揹帶，能把那些旋轉的巨大鏈鋸當做武器裝備；便攜的蒸汽發生器，讓我們可以和氣之部族的巨人一樣輕鬆地驅動機械，而不用向他們那樣連接氣管或噴管；一個把射釘槍的保險裝置取消，同時把槍管翻轉到外面的方案，這樣能讓它們以難以置信的高速發射投石索彈藥；一個巨人們給我們的珠寶電鍍設備的巨型版本，可以同時電擊大量的入侵者……
當其他獸人部落襲來時，我們組成了強力的防禦部隊，揮舞着他們從未見過的武器戰鬥，造成了他們從未知道如何忍受和治癒的傷勢，使用着他們沒法理解更不用說掌控的力量。鏈鋸發出尖嘯，撕碎護甲切斷肢體；巨大的鉤子抓住了加伯特的龍戰士的身軀，只聽到他們從空中墜落的哀嚎；獸人們被電擊或是被蒸汽流燙傷，四周散發出血肉被灼燒的氣味；蒸汽槍發出砰砰聲，將敵陣化爲一堆屍體————這些景象對於氣之部族和其他獸人部落來說是可怖的噩夢，但對於我們，這些甜美的聲音、景象和味道代表了勝利和安全。我們獲得壓倒性的勝利，只有極少的陣亡，而它們則落荒而逃。克魯克部落不會被征服。
然而氣之部族看不到我們所處的危急局面。他們看不到我們面臨的威脅。而且我懷疑，即使大工匠告訴他們這一切，他們也不會聽我們的話。他們看到的，卻是自己創造性的工具用來毀滅，他們美麗的發明變成了如此可怕的東西，他們親愛的聰慧“子女”們，造成了遠超自己所見過場面百倍的血腥屠殺。他們譴責我們，那些本來準備和我們共同居住的巨人們也迅速地撤回了山裏。他們不再歡迎我們使用他們的技術，甚至不歡迎我們住在他們的羣山附近。
我們會想念他們的陪伴，他們古老的智慧，和他們那謹慎的善意。我們不會想念他們那令人心煩的無知和浮誇的自以爲是。]], "_t")

------------------------------------------------
section "tome-orcs/data/lore/palace-fumes.lua"

t("palace of fumes", "煙霧宮殿", "newLore category")
t("a reminder", "一個公示", "_t")
t([[A Reminder to Our Constituents:

Any votes for an individual candidate for office cease to be valid once the primaries are over, and the field has been narrowed down to two (or rarely three, in a close race) candidates.  At this point, you cannot vote for your candidate; instead, a competition will be held, after which its victor will be awarded with the position.  The vote you are submitting now determines how they will be competing.  While we cannot enforce how or why you vote, we request that you respect the spirit of our system, and select a competition which reflects the candidates' capability to handle the responsibilities of the Chief Councilor position.]], [[敬告廣大選民:
初選結束後，任何向個人的投票將會不再有效，名額會被削減到兩名（如果票數接近，有時會是三名）候選人。在那個時候，您將不能爲您的候選人投票；相對應的，將會舉行一個比賽，勝利者會獲得職位。您現在的投票將會決定他們競爭的方式。我們不能強制要求您投票的方式或動機，但我們仍然請求您尊重我們體制的精神，選擇一個能夠反映出候選人作爲議長履行職責的能力的合適的比賽項目。]], "_t")
t("a wrinkled pamphlet", "一本起皺的小冊子", "_t")
t([[A Plea from the Volunteer's Bureau of Gaming:

Once again, we find ourselves faced with an election for the competition of Chief Councilor.  While this is the most prestigious position in our government, it should not be forgotten that is also arguably the most complex, and the one bearing the greatest responsibility for the fate of our people.  A Chief Councilor's duties require not only cautious, reasoned foresight, but a quick wit to get emergencies under control in little time; yet, he or she must be aware of the precedent set or the unintended consequences of such decisive action, never acting rashly or out of ill temper.  Such a leader would wield our citizens and our military like a drunkard with a glass bottle, not caring if his weapon is shattered in the process. He or she must be able to develop creative solutions to problems but be open to outside advice, to be a character judge capable of selecting his or her most valuable acquaintances and a persuader to convince them to do the tasks for which they are most suited...  suffice to say, there are a great many mental skills required.  Accordingly, the competition should be one that tests all these skills.

This election, we are formally endorsing the board game [i]Automobiles and Automatons v9.8,[/i] a refined variant of the game introduced last year in a competition for the Marshall of the City Guard.  Its "oil-punk" science-fantasy setting, although perhaps easy to brush off as irrelevant to our reality, has its own consistent internal rules, forcing its players to learn a new status quo and work with it, as our leaders must be willing to learn from ongoing events and rapidly adapt to them; yet, since the game has been out for a year already and there are already numerous books about strategies for it, it also tests our candidates' long-term memory, as our leaders must be able to remember our history, to repeat our ancestors' successes but not their failures.  The rules of v9.8 are somewhat, but not entirely, different from those of previous versions, making these strategy books only partially accurate, just as our ancestors' wisdom only reflected the world they lived in, not the increasingly different one of the present.

v9.8 uses the "Crumbling Divide" map, providing a barrier that eliminates the possibility of an aggressive player gaining an early victory, tests the players' ability to plan in the long term, and yet due to the presence of non-player foes on either side, they still must be able to make plans in the short-term that will ensure their survival and leave them in an advantageous position when the barrier fades.  Non-player foes follow a predictable set of rules, eliminating luck as a factor, and our necropsychs have found a method of copying the same spiritual consciousness into two figurines, meaning that both players will be using identical sets of Negotiator figurines to demonstrate their diplomatic finesse.  (As always, the figurines are designed to release their spirits after no more than one month, ensuring that this process is as humane as possible to the deceased.)

The consumer edition of this game, v6.0, has won countless awards for its engaging and challenging play, with special attention given to the diverse array of viable strategies and skills tested by it.  Both sides agreed it was a fair game in the Marshall's election, as v1.0; v9.8 is unlikely to disappoint as a method of selecting our next leader.  Vote for [i]Automobiles and Automatons v9.8[/i] this year, and you will not be let down by its winner.]], [[遊戲志願者局的請願：

又一次，我們面臨着選舉議長的比賽了。這是政府中最有名望的職位，但也別忘了它可以說是最複雜的職位，承擔着我們人民命運的最大責任。一個議長不僅需要謹慎而理性的遠見，也需要在短期內解決緊急事態的急智；並且，他或她必須明白這些決定的成功先例以及非預期後果，行動既不冒進也不出於心血來潮。否則，這樣的領袖會像是一個醉鬼拿着玻璃瓶那樣，輕率地對待我們的人民和軍隊，而不關心那武器是否會破碎。他或她必須能創造性地解決問題，同時包容外界的建議，還要做一個知人者，能選出他或她身邊最具價值的人才，以及一個說客，能說服這些人去做他們最適合的工作……可以說，成爲議長需要很多精神上的技能。因此，這個競賽必須要考驗所有這些技能。

這次選舉，我們隆重推出桌面遊戲[i]汽車與機器人第9.8版[/i]，一款去年曾用於選出城市衛兵團長的遊戲的改良版。它基於“石油朋克”的科幻設定，或許會被認爲與現實不符而被人忽略，但它有着它嚴謹的內部規則，會迫使其玩家學習新的環境並掌握它，就像我們的領袖們也必須願意從正在進行的事件中學習並迅速適應它們；並且，由於這個遊戲已經推出了一年，有無數關於遊戲策略的書已經被出版，玩這個遊戲也能測試候選人的長時記憶，因爲我們的領袖必須得以史爲鑑知興衰。9.8版本的規則和之前的版本略有不同，但卻並非完全不同。這樣，那些策略書籍僅僅是部分準確的，就像我們祖先的智慧只能反映他們所處的時代，而不是面臨鉅變的今日。

9.8版本使用“破碎兩極”地圖，地圖中有一個結界，這消除了那些具有侵略性的玩家獲得快速勝利的可能性，測試了玩家們長期謀劃的能力，而且因爲兩側都有非玩家敵人，他們仍然要有短期計劃，以保證生存，並在結界消散後佔據優勢。非玩家的敵人遵循可預測的規則，排除了運氣因素，我們的通靈師也找出了一個把相同意識複製到兩個模型中的辦法，這意味着雙方玩家都會使用相同的談判者模型來體現他們的外交手腕。（和往常一樣，這個模型被設計成在使用後一個月內解放裏面的靈魂，以確保這一過程對於亡者來說盡量人道。）

這一遊戲的消費者版本，6.0版，以它令人沉浸又富於挑戰的遊戲性已獲得了無數獎項，尤其因它不同類型的多變策略，以及其對多種技能的綜合考驗備受矚目。在1.0版本的遊戲用於選出衛兵隊長時，雙方都同意遊戲是公平的；作爲選出我們下一個領袖的方式，9.8版本絕對不會令人失望。今年，投[i]汽車與機器人第9.8版[/i]一票吧，你不會爲它的勝者而失望的！]], "_t")
t("a fading poster", "一個發舊的海報", "_t")
t([[Councilor Tantalos, unlike that cowardly wimp Chief Councilor Kasyros, knows just what to do to solve the steam shortages, and isn't afraid to do it!  Even though he can't reveal his plan yet for security reasons, the Geothermal Authority and our military's highest generals have assured us that his plan would work, without requiring us to ration steam usage or regulate our appliances; let's see Tantalos show that old geezer what-for, and end this drought for good!

VOTE FISTICUFFS]], [[坦塔洛斯議員，不像卡西羅斯議長那位懦弱的窩囊廢。他知道該如何解決蒸汽短缺的問題，也不怕去執行這一方案！即使由於安全原因，他現在還不能公佈計劃，地熱局和我們軍隊高級將領已經向我們保證，他的計劃一定會奏效，我們再也無需節省蒸汽用量或是用機器時精打細算；讓我們看看坦塔洛斯怎樣讓那個老東西難堪，並永遠結束蒸汽枯竭！

[b]請投肉搏戰[/b] ]], "_t")
t("Kasyros' resignation speech", "卡西羅斯的辭職演說", "_t")
t([[My fellow councilors,

In this time of increasing vent-drought, it is tempting for us to seek the easy way out.  I understand that at this point, I am powerless to prevent our new Chief Councillor's plans to take the promising vents under the Kruk orcs, but should we fail, you may be tempted to compensate by approaching that...  entity who called itself "the Loyalist."  I am of the opinion that this would be a foolish decision.

Do you remember the Official Histories' record of when we first interacted with the lesser races?  They spoke of them as an entertaining, jovial bunch, friends and companions with our own people.  How naive we were back then...  but when our ancestors saw their true nature, the brutality they were capable of, they recorded these acts in detail.  They did not, however, explicitly tell us not to trust the Orcs.  They did not explicitly tell us that they are pests to be avoided, or a scourge to be eradicated, or a pitiful, fallen reminder of why letting the lesser races use our discoveries will only end in tragedy.  They simply recorded what they learned, and allowed future generations to come to those conclusions themselves, compared with their own observations - and in our grandparents' case, by unfortunate personal experience.  Even through the distress and feelings of betrayal at the time, even though opinions ran in every direction from fury to sorrow at the lesser races' barbarism, not one of the Councilors responsible for recording events gave in to editorialism.  Perhaps we would be in a better situation if they had, so we would have not repeated their mistake of trust, but they stayed fair nonetheless.

Going even further back, they spoke of relations with our now-distant kin, the Sturmos Tribe.  Though the records describe a strained relationship, the mentions of their boorish behavior are recorded in a matter-of-fact nature, and interspersed with the mentions of their advanced metallurgy techniques and other such valuable things we gained from cooperating with them.  Although their current state of Great Firestorm-induced exile to the mountains of Maj'Eyal makes it a rather moot point, the fact still stands that if we were somehow in a position to trade with them, we could rely on the Official Histories for a trustworthy indication of, at a minimum, how they [i]used[/i] to behave.

The examples go on; the Official Histories have remained dispassionate and fair, and a reliable metric for making decisions.  Not once did our forefathers allow their biases to influence their recordings.  Not once did a fervent political movement manage to compromise their integrity.  Not one chapter of these texts can be safely and fully discredited as the subjective, unfair writings of a dominant political party, or the deluded ramblings of a movement influenced by some banal philosophical fad.

(Obviously, the mercifully brief reign of King Traglamar is an exception, but it should be clear why this was a special case and not worthy of further consideration.)

My point is, the Official Histories have a very well-proven track record.  Every single time but once, they have given a solid analysis of the evidence.  Every single time but once, they have refrained from outright suggesting a course of action.  And only once have they allowed something as subjective as a gut feeling into their reports.

Do you know what they say about the meeting with the Loyalist?  After a brief description of the events of the meeting - a strange creature approaching the Council of the time, demonstrating its power by using a small wand to blast a hole halfway to Eyal's core (a wand which he then handed them as though it were a child's cheaply-made toy), stating it could offer us a source of near-infinite energy in return for a rather inconvenient magical artifact.  When they turned it down, the creature gave a speech recorded in verbatim detail: "It hardly matters.  I have all the time in the world to wait for your people to trip over their own hubris and shatter.  If you will not allow me to save you, then I need only sift through the shards of your ruined cities to find it."

Our forefathers say this creature gave them a means of contacting it again, but outright refuse to say what it was; the only reason we still know how to reach it is the yearly messages dropped on the Palace's front steps.  After mentioning that, they wrote this:

"Do not trust this Loyalist.  When we look upon him, we feel something deep within us, older than ourselves, telling us that he is simply... [i]wrong[/i].  His intentions with the Eye, an artifact with incredible power that we have yet to successfully harness, cannot be good for anyone, least of all ourselves.  Never give him the Eye, and continue our work of trying to find a means of destroying it.  Never accept any other deal he offers.  If you are ever unfortunate enough to see him as well, you will immediately understand why we say this."

Perhaps political discourse has gotten a bit...  muddier in recent years.  With the bickering and sniping of modern-day debates, it can be hard to believe that past Councilors had ideas other than their careers in mind, that a vehement display of emotion would be something other than political posturing.  But even if those Councilors were just as petty and selfish as we are, they did not let it affect the Official Histories, not once.

I intend to trust the only advice our ancestors gave us in the Official Histories.  I beg of you all to do so as well.]], [[議員同志們, 在這一出氣口枯竭加劇的時期，一個簡易的解決方法是極具誘惑性的。我明白，目前我已經無力阻止我們的新議長去奪取克魯克獸人地盤底下的那些有前景的出氣口，但是一旦我們失敗了，你們也許會試圖去接近那個……自稱“忠誠者”的個體來補救這一切。我個人認爲這會是個愚蠢的決定。

你們還記得，在正史中我們第一次與那些下等種族接觸時的記載嗎？上面寫着，它們是一羣有趣又快活的人，是我們的朋友和同伴。我們那時可真是天真啊……但是當我們的祖先們看到了他們的真實本性和他們潛在的殘暴之後，祖先們把這些詳盡記錄下來。然而他們沒有明確地告訴我們不要信任獸人。他們沒有直接告訴我們這個種族是要遠離的害蟲，或是一個要消滅的禍害，也沒有留下一個可悲的警示，告訴我們讓那些下等種族使用我們的發明創造只會導致悲劇。祖先們只是把他們學到的記錄下來，讓後人對照自己的觀察結果，得出自己的結論————這是我們的祖父母輩以不幸的個人經驗而體會到的。即使他們悲傷着，感覺到被背叛，即使思緒萬千，對下等種族的野蠻感到震怒又哀憐，當時那些負責記錄事件的議員們，沒有一個抒發個人觀點。或許，假如他們願意表達這種觀點，我們可能會處於一個更好的處境，不會再重複他們輕信的錯誤，不過無論如何，他們仍然保持了公正的記述。

再往前追溯，祖先們談論過與我們今日的遠親風暴部族。儘管這些紀錄中描述了我們與他們緊張的關係，對他們本性中的粗野舉動的記述確實完全實事求是的。而且，記錄中還提到了關於他們先進冶金技術的論述，以及其他和他們合作獲得的好處。儘管一場巨大的火風暴後，他們至今流亡於馬基埃亞爾的羣山中，讓與他們打交道的想法不太可能實現，但如果我們一旦有機會與他們交易，正史還是提供了一個可靠的指示，至少，也能告訴我們他們[i]曾經[/i]如何。

這樣的例子還有許多；正史一直以來都是冷靜而不偏不倚的，是做決定的一個可靠標尺。前人們從來不讓個人的偏見影響他們的紀錄。這一紀錄的誠實也從來未在狂熱的政治運動中妥協。在這些文字中，沒有一個章節可以被論定爲某個優勢政黨的主觀臆斷，或是受某個陳腐的哲學思潮影響的胡言亂語。

（顯然，特拉格拉瑪王短暫的仁政除外，但是要明白這是特例，不值得進一步討論。）

我認爲正史對以往的事情有非常可靠的紀錄。除了一次以外，他們都對證據進行了可靠的分析；除了一次以外，他們都剋制住自己，沒有直接給出行動方案。只有這一次，他們在報告中透露出了本能感受這樣主觀的東西。

你們知道他們怎樣描述與“忠誠者”的會面嗎？簡短地討論了幾件事後，那個奇怪的生物接近了當時的議會，用一根小小的魔杖，炸出一個半途通往埃亞爾核心的洞，來展示他的力量（它接下來把這個魔杖隨意地交給了議會成員，就像把它當是兒童的劣質玩具），聲稱它可以爲我們提供一個近乎無窮的能源，而他只需要一個令人感到不便的魔法古物爲交換。在他們拒絕後，那個生物發表了看法，原文如下：“這不怎麼要緊。我有世界上所有的時間等待你們的人民因爲自己的驕傲摔得粉身碎骨。如果你不讓我來拯救你們的話，我只需要從你們文明的廢墟中找到它。”

我們的祖先寫下，這個生物給了他們再次與它聯絡的方式，但祖先們拒絕了寫下這一聯絡方式是什麼；我們仍然知道怎樣與它聯繫的原因，在於在一條在煙霧宮殿前門留下的年度總結信息。在提到這以後，他們寫道：

“別相信這個‘忠誠者’。當我們擡頭看他時，我們感覺到在自己內心深處，有一種比自己要古老的存在，告訴我們他是……[i]錯誤的[/i]。他對於‘眼’，一個有我們至今沒有成功掌控的強大力量的古物，抱着意圖，這不可能對任何人有好處。永遠別給他‘眼’，而且要繼續找到一種銷燬‘眼’的方法。永遠別接受他給出的其他交易。如果你們有一天也不幸地要見他，你們會立即明白爲什麼我們這麼說。

或許這幾年，政治爭端變得有些……令人頭腦混亂了。今日的辯論中到處都是口角和中傷，讓人很難相信，過去的議員們腦海裏會考慮超越他們職業生涯以外的東西，那種激昂的感情表達也不僅僅是政治上的裝腔作勢。不過即使那些議員們像我們一樣器量狹小而自私，他們也未曾影響過正史的記錄，一次也沒有。

我想要信任祖先們在正史中給出的唯一建議。我也請求你們都這樣。]], "_t")
t("excerpts from a Council meeting transcript (1)", "一份議會文字記錄片段 (1)", "_t")
t([[The Steam Council has been called to order, with Chief Councilor Tantalos presiding.  

TANTALOS: "Greetings, my fellow- heh, now [i]lesser[/i] Councilors!  It is my pleasure to finally lead the proceedings.  The agenda for today..." Ruffles through papers. "Is irrelevant, for I have a solution to every malady mentioned therein.  The first order--"

KASYROS: "With all due respect, Chief Councilor, the agenda--"

TANTALOS: "Is.  [i]Irrelevant.[/i]  Tormak?  You've been scrying on potential sources of geothermal energy, would you care to inform the others where you see the most potential?"

TORMAK: Sighs. "Right under the Kruk orcs, unfortunately.  It's a promising source for sure, the magma powering it hasn't drained out like it has under us, but digging there would...  well, we all know how quickly they turned construction tools into weapons to rival our own.  If we went in there with the state-of-the-art mining equipment necessary to--"

TANTALOS: Laughter. "Mining equipment!  What manner of fool do you take me for?  Palaquie, tell me what's going through the minds of those silly little waist-height warriors, rummaging through the mainland for Orcish rebels." Holds up hand to silence Councilor Emeritus Kasyros. "This IS relevant, I assure you."

PALAQUIE: "Discontent...  revolving around hidden, long-fermented resentment. Some want the Kruk exterminated, others imprisoned.  Neither can afford direct intervention, but some form of support will assuredly be available."

TANTALOS: "So, with the right negotiation, we can get these tinies, who have [i]endless[/i] experience fighting Orcs, to assist us and make any sort of action in Kruk territory more manageable.  At a bare minimum, we can obtain weaponry that has long proved sufficient for slashing Orcish throats...  although we'll need it custom-fit for our size, naturally."

PALAQUIE: "They have a race whose armor would work.  A tight fit, but sufficient."

TANTALOS: "Even better!  And...  Kasyros, I'm going to let [i]you[/i] tell me what the people care about most.  I'm sure your bruises are adequate reminders of the citizens' will?"

KASYROS: [Statement was deemed excessively profane and stricken from the record by 4-2 vote.]

TANTALOS: "Such undignified conduct!  All because you can't accept that the public wants their steam back.  More than they want those filthy little greenskins around, more than they fear getting their hands dirty, more than they want [i]your[/i] way of doing things.  So!  It's resolved that we have much to gain from this, it's resolved that we have or can obtain the means to carry it out, and it's resolved that it is what the voting public desires.  I see no need for further debate.  Nashal, I'd like to speak to you after this about a wand.  Meeting adjourned."

[At this time, Councilor Kasyros gave a lengthy speech before officially resigning from the Council.  It has been recorded in a separate document.] ]], [[在坦塔洛斯議長的主持下，蒸汽議會正式開會。

坦塔洛斯：“你們好啊，我的同……哈，現在是[i]下級[/i]議員們！這是我的榮幸，能夠終於主事。今日的議程……”翻動手中的文件。“無關緊要，因爲我已經爲所有要解決的問題有了一個對應的方案。首先————”

卡西羅斯：“尊敬的議長, 議程————”

坦塔洛斯： “這是[i]無關緊要。[/i] 的。托馬克？你一直在占卜潛在的地熱能源，你能告訴大家哪裏最有潛力嗎？”

托馬克：嘆氣。“不幸的是，就在克魯克獸人的地盤底下。那確實是個有潛力的源頭，提供能源的岩漿可不像我們地盤底下的都枯竭了，但是在那裏挖掘會……好吧，我們都知道他們能多快的把建築工具變成能威脅我們的武器。如果我們把能用來開採的最新式採礦工具帶過去————”

坦塔洛斯：大笑。“採礦工具！你把我當成是怎樣的傻瓜？帕拉奎，告訴我那些在大陸上到處搜尋獸人反叛者的齊腰高的小傻戰士們在想什麼。”舉起手打斷榮譽終身議員卡西羅斯。“我保證，真的無關緊要。”

帕拉奎：“不滿……以及隱藏的，長期發酵的怒火。有些人想消滅克魯克獸人，也有人想監禁他們。不論是那種，我們都沒法直接介入，不過確實可以提供某種支持。”

坦塔洛斯：“那麼，在恰當的協商後，我們可以讓那些有[i]無數[/i]獸人作戰經驗的小東西，來協助我們，讓在克魯克獸人境內的一切行動更易掌控。最少，我們可以取得那些已被長期證明能割斷獸人喉嚨的武器裝備……自然，我們確實得想法子改成我們的尺寸。”

帕拉奎：“他們有個種族，護甲可以給我們用。穿起來有點緊，但是足夠了。”

坦塔洛斯：“那就更好了！還有……卡西羅斯，我想讓[i]你[/i]告訴我人民最在意什麼。我敢肯定，你身上的傷痕一定能提醒你，公民們的意志是什麼，對吧？”

卡西羅斯：[這一表述被視作過分的褻瀆，以4比2的投票，通過從記錄中削除。]

坦塔洛斯：“真是不成體統的發言啊！只是你們不能接受羣衆想要回他們的蒸汽。比起想要那些狡猾的小綠人們在身邊，比起他們害怕把自己的手弄髒，比起想要以[i]你們[/i]的方法做事，更想要蒸汽。所以！這決定了我們從這方案裏獲益良多，決定了我們有或能找到解決困難的方式，也決定了這是選民們想要的。我看不需要進一步討論了。納沙爾，之後我想跟你討論一個魔杖的事情。散會。”

[同時，卡西羅斯議員也在從議會正式辭職時做了一個不短的演講。演講被另一個文件記載。] ]], "_t")
t("excerpts from a Council meeting transcript (2)", "一個議會文字記錄片段 (2)", "_t")
t([[(Ink has been spilled on this transcript - you can only read certain passages.)

???: "[...]ame me for this!  YOUR mechanics examined that airship, YOUR equipment was used to repair it, and it's YOUR fault it went down!"

NASHAL: "Yes, and I told you to call the attack off the moment I heard the news - the Loyalist's wand as a fire-support tool was far too valuable to conduct the invasion without it.  But no, Palaquie had to insist on going right then--"

PALAQUIE: "My visions do not lie.  It was the best way forward.  Our odds of success at that point, low as they were, were still better than if we had let Pendor's inflexible, time-dependent plan sit and--"

PENDOR: "DON'T YOU EVEN START, YOU YETI-LOVI--[...]"

[...]

Motion made to record the statement that Councilor Pendor would not know decent equipment if it shot or stabbed him in the face passed, 3-1, with Councilor Tantalos abstaining.

Motion made to record the statement that Councilor Tormak's robes smell of absinthe and vagrants passed, 3-1, with Councilor Tantalos abstaining.

Motion made to begin an official inquiry passed 3-1, with Councilor Tantalos abstaining.  The first order of business at the next session will be determining whether or not Councilor Nashal's state-of-the-art mining and extracting equipment is capable of extracting her head from her--

[...]

TANTALOS: "If you are all quite finished with this rubbish...  How bad is the situation, exactly?  I want details and facts, not blame."

TORMAK: "You don't want blame because this whole thing was YOUR idea!  It's YOUR fault we--"

Motion to censure Councilor Tantalos for defenestrating Councilor Tormak has failed, 1-1 (tie broken by Chief Councilor status), with Palaquie, Nashal, and Pendor abstaining.

[...]

TANTALOS: "So, a few wastrels in the marketplace are gone, and the Kruk have moved on to the mainland.  As far as I am concerned, they are not presently our responsibility - these 'Allied Kingdoms' and 'Sunwall' folk can deal with them.  Thanks to Pendor's scouts, we have a weapon we can point at the Kruk Pride homeland as a deterrent, which should buy us even more time.  We should use this time to bolster our defenses...  and consider additional options.  Meeting adjourned."

PALAQUIE: "Additional options?"

TANTALOS: "The meeting has been adjourned.  You should be training our necropsychs, Councilor."]], [[（墨水被灑在這個記錄上————你只能讀到一些段落。）

？？？：“[...]怪我！那架飛船是你的機械師檢查的，是在用你的設備修理它，也是因爲你的錯它才墜落！”

納沙爾：“是嗎，我在聽到那個消息時也告訴你了要取消攻擊————忠誠者的魔杖作爲火力支援工具太珍貴了，我們進攻的時候絕對離不了它。但不，帕拉奎非要堅持向右轉————”

帕拉奎：“我眼前的景象不會作假。那是前進最好的方法。我們那時的成功機率雖然低，還是強於假如讓潘多爾做主，用那個不靈活，依靠時機的方案————”

潘多爾：“你再說一句看看，你這個戀雪人————[……]”

[……]

記錄下“潘多爾議員不知道什麼是優良的設備，除非親自射到或者刺到他臉上”的表述的動議以3比1的投票通過，議員坦塔洛斯棄權。

記錄下“托馬克議員的長袍聞起來有苦艾酒和流浪漢的味道”的表述的動議以3比1的投票通過，議員坦塔洛斯棄權。

進行官方調查的動議以3比1的投票通過，議員坦塔洛斯棄權。接下來進行調查的第一部分，將會決定是否納沙爾議員的最新式採礦和提取工具能夠將她的頭從她的————

[……]

坦塔洛斯：“如果你們都鬧夠了……到底情況都多糟糕？我想要細節和事實，而不是抱怨。”

托馬克：“你不想要抱怨是因爲整件事都是你的主意！這是你的錯所以我們————”

譴責坦塔洛斯議員把托馬克議員扔出窗外的動議未被通過（1比1，平局被議長否決），議員帕拉奎、納沙爾和潘多爾棄權。

[……]

坦塔洛斯：“所以，商場裏的那些飯桶死了，克魯克獸人已經開始在大陸行動。據我所知，這目前不是我們應當擔心的————那些“聯合王國”和“太陽堡壘”的傢伙們可以對付。多虧了潘多爾的斥候，我們有了一個武器，可以作爲一個威懾力量對準克魯克部落的老家，這會給我們爭取更多的時間。我們應該用這段時間加強守備……並考慮其他方案。散會。”

帕拉奎：“其他方案？”

坦塔洛斯：“已經休會了。你現在應該去訓練我們的通靈師，議員。”]], "_t")
t("excerpts from a Council meeting transcript (3)", "一個議會文字記錄片段 (3)", "_t")
t([[TANTALOS: "Tell the others of the unfortunate developments, Palaquie."

PALAQUIE: "The Kruk Orcs, under %s, appear to have pushed to the last bastion of the Sunwall forces...  none of my visions predict this ending favorably for anyone of non-Orcish descent.  With the Sunwall gone, there will be no further distractions for the Kruk.  In short, the Sunwall are doomed - and we are next."

TANTALOS: "Where there's a will, Palaquie, there's a way.  What of the Migratory Leviathan?  Nashal, do you have any idea where--"

NASHAL: "About that...  Kasyros stole it when everything started going to slag.  We'd take it back, but he's using it to evacuate civilians.  We'd end up using too many bullets on our own people that belong in the Kruk Orcs."

TANTALOS: "Unfortunate, but we'll surely be able to convict him of treason once this all blows over.  Pendor, you've been working with our marksmen - how are they doing?"

PENDOR: "Scared scrapless, Your Honor, but they're learning quick.  I managed to snatch up some newer Flameshot rifles from Kaltor's surplus, and our Retaliators are as strong as ever."

TANTALOS: "Splendid to hear.  And what of that backup weapon you had mentioned - what was that name again, #{bold}#DESTRUCTICUS, IMPOLITE PENETRATOR OF-#{normal}#"

TORMAK: "It's gone.  The mages I sent with Pendor's runners...  their invisibility spells were inadequate.  The Orcs found them...  if it's any consolation, they don't appear to have realized what the keys are for, or what it's capable of.  I'm...  I'm sorry."

Lengthy pause.

TANTALOS: "...I think it's time."  Removes a briefcase from behind the podium, and opens it to show the other Councilors its contents, before closing it and holding it again.  Councilors Palaquie, Tormak, and Nashal audibly gasp.  Motion to strike all description of its contents from the record passed, 3-2.

TORMAK: "You can't be serious!  How is that going to make the situation BETTER?"

PALAQUIE: "It cannot."

NASHAL: "I can't agree with this, Councilor Tantalos, your predecessor had a point--"

TANTALOS: Pounds fist, breaking podium.  "That doddering old coward knew NOTHING!"  Pause; sighs.  "None of us do.  All we know is, this eye's almost certainly useful for more than making declogging draught from its tears, and the person who wants it is the type of person who casually digs holes to the center of Eyal.  We've tried everything; the time for a last resort has come, and we are in dire need of a miracle.  This... 'Loyalist' is the only possible source of miracles around, and if infinite energy and blasting holes through the planet are within his capabilities, then disposing of these barbarians should be quite simple."

PALAQUIE: "If our ancestors are to believed, this could result in a fate worse than our own destruction--"

TANTALOS: "Would everyone who doesn't have any #{italic}#better#{normal}# ideas cease their jabbering before I cease it #{italic}#for them?#{normal}#"

[Silence.]

TANTALOS: "As I thought.  Nashal, prepare the G.E.M. and a retinue of guards and mechanics.  There is business I must attend to.  Meeting adjourned."]], [[坦塔洛斯：“告訴大家現在的不利形勢，帕拉奎。”

帕拉奎：“克魯克獸人，在%s的帶領下, 看上去已經攻到太陽堡壘軍的最後一個堡壘了……我的各個預測景象都不會傾向於任何非獸人血統的一方獲取勝利。太陽堡壘陷落後，對於克魯克獸人就沒有什麼阻礙了。簡而言之，太陽堡壘氣數已盡————而我們是下一個。”

坦塔洛斯：“帕拉奎，有志者事竟成。“遷徙的利維坦”怎麼樣了？納沙爾，你知不知道它在————”

納沙爾：“那個啊……在事態變得糟糕的時候，卡西羅斯偷走了它。我們想要把它奪回來，但是他正在用它撤離平民。如果那樣的話，我們會把大量本應用在克魯克獸人身上的子彈，射向我們自己的人民的。”

坦塔洛斯：“真不走運，不過一切結束後我們會以叛國罪流放他的。潘多爾，你最近在訓練我們的槍手吧————他們怎樣了？”

潘多爾：那羣廢物們嚇的不輕，尊敬的議長，但是他們進步得很快。我從卡爾託剩下的貨物中收集了一些新式的噴火步槍，而我們的復仇者部隊處在巔峯狀態。”

坦塔洛斯：“聽起來真不錯。那個你提到過的備用武器————叫什麼來着，#{bold}#毀天滅地，無禮的天空……#{normal}#”

托馬克：“它不見了。那些我派給潘多爾的傳令兵的法師……他們的隱形咒語不準。獸人們找到了他們……運氣好的話，他們不知道鑰匙是用來做什麼的，或者武器能做什麼。我……我很抱歉。”

漫長的沉默。

坦塔洛斯：“……我認爲是時候了。”從講臺後拿出一個手提箱，打開給其他議員看裏面的東西，又合上它把它收起來。帕拉奎、托馬克和納沙爾議員都發出喘氣聲。清除有關箱子裏東西的記錄的動議以3比2通過。

托馬克：“你別開玩笑吧！這東西怎麼能改善現在的情況？”

帕拉奎：“它不能。”

納沙爾：“我不能同意這樣做，坦塔洛斯議員, 您的前任的觀點確實有道理————”

坦塔洛斯：揮拳砸桌子，把講臺砸爛了。“那個走不穩路的老懦夫什麼也不知道！”停頓；嘆氣。“我們也都不知道。我們知道的是，這個眼的作用肯定不僅僅是用它的淚水來做清淤藥水，而想要它的人，是那種可以隨心所欲挖出通向埃亞爾地心的洞的人。我們已經試過了所有方案；最後掙扎的時刻來臨了，我們相當渴望一個奇蹟。這個……“忠誠者”是我們身邊唯一可能的奇蹟來源，如果無限能源和在星球中間穿洞在他的能力限度之內，那麼把那羣野蠻人趕走應該非常簡單。”

帕拉奎：“如果我們的祖先可信的話，這可能比我們自身的毀滅更糟糕————”

坦塔洛斯：“你們這些想不出#{italic}#更好#{normal}#主意的人能不能閉上嘰嘰喳喳的嘴，在我來#{italic}#幫你們#{normal}#閉上之前？”

[沉默。]

坦塔洛斯：“這就對了。納沙爾，準備好GEM，隨從的守衛和機械師。我還有要做的事情。散會。”]], "tformat")

------------------------------------------------
section "tome-orcs/data/lore/pocket-time.lua"

t("Maltoth", "瑪爾託斯", "_t")
t("a human", "一個人類", "_t")
t("paradox mage", "時空法師", "_t")
t("him", "他", "_t")
t("he", "他", "_t")
t("He", "他", "_t")
t("his", "他的", "_t")
t("her", "她的", "_t")
t("she", "她", "_t")
t("She", "她", "_t")
t("pocket of distorted time", "袋中扭曲的時間", "newLore category")
t("a telepathic message <Rough Drafts>", "心靈傳訊《粗略的草稿》", "_t")
t([[<? Lore.init_pocket_time_data() ?>Once upon a time, there was a Halfling alchemist by the name of <?=Lore.pocket_time_winner.name?>.  Alongside her trusty golem, she marched into the Trollmire, disposing of all foes in her path; when she encountered Prox, though, and he bent down to roar mere inches from her face, well inside a bomb's blast radius, she panicked and pulled a vial off her belt--

Once upon a time, there was a Dwarven berserker by the name of <?=Lore.pocket_time_winner.name?>.  Fleeing through the halls of Reknor as his friend was cut down by Orcish warriors, he ran face-first into a couple of them and--

Once upon a time, there was a Cornac rogue by the name of <?=Lore.pocket_time_winner.name?>.  His traps made short work of Prox, but when Bill the Stone Troll tossed him around his lair, he lost his bearings and stepped on--

Once upon a time--

Once upon a time, there was a great hero, a Dwarven Stone-Warden by the name of <?=Lore.pocket_time_winner.name?>, who began her adventure swearing incomprehensibly about unfairness before shrugging and continuing onward.  She escaped from Reknor with her closest companion, used her natural powers to purge the Deep Bellow and The Maze of the corrupting forces therein, rescued a strange new creature called a "yeek" from the clutches of the murderous Subject Z, and even shrugged off boulders thrown at her by the giants of Daikara as she inexorably pushed forward, slaying so many threats that had harmed so many people before her.  She uncovered the long-lost Conclave Vault and put the last of the original Ogres to rest, rescued a damsel from the clutches of the Sect of Kryl-Feijan, and finally found herself standing at the gates of the tower of Dreadfell, her skills honed by her trials and laden with exotic equipment found in her travels.  Climbing through the waves of shambling undead, she finally faced The Master head-on, when a skeletal warrior struck her from behind.  A stunning blow from its warhammer struck her right where she'd applied a wild infusion, the only one she had.  Dazed and stumbling, trying to invoke its power, she only became lucid when a terrible cold crept up her limbs, encasing her in ice--

Once upon a time, there was a Thalore summoner by the name of <?=Lore.pocket_time_winner.name?>, who began her adventure right next to a snake that was unnaturally skilled with temporal magic--

Once upon a time, there was a terrible villain, an Ogre reaver by the name of <?=Lore.pocket_time_winner.name?>, who found himself fascinated by the corrupted crystalline structures of the Spellblaze Caverns.  He first drowned a Last Hope guard in the dead of night to steal her enchanted ring, then began to leave a trail of destruction throughout the land, feeding on the strength of those hewn with his battleaxe or impaled with his longsword, and growing ever more powerful with every death he caused.  He joined the cause of the Grand Corruptor in an assault on Zigur to ensure that nothing could stop his arcane plagues from spreading, then took the Heart of the Sandworm Queen to Spellblaze-tainted lands to pervert its natural blessing into a blighted font of suffering.  He sat and watched as a cult sacrificed a maiden to summon their demonic master just so he could kill it himself, and salivated at the prospect of traveling to the Far East and seeing four armies' worth of Orcs broken and bleeding, tumors and boils spreading across their skin as the life slowly left their eyes.  The finest soldiers of Vor Pride could do nothing to prevent him from raiding their armory, but one crippled and diseased Orc pulled himself up against its sealed doors and begged him not to open them; he simply laughed before crushing his skull under his boot as he walked toward it, then kicked the door down, only to feel his bone armor disintegrate under a storm of breath attacks from an army of unspeakably powerful multi-hued wyrms.  Even <?=Lore.pocket_time_winner.name?> knew when he had to flee from a fight, and clenched his fist as he charged his Phase Door rune; when the blinding flash of light cleared, he found himself mere inches from--

Once upon a time, there was a Doomelf by the name of <?=Lore.pocket_time_winner.name?>, freed from demonic mind-control by a lucky meteor strike, who set out to use her new-found powers to escape the orbital hell on which she was trapped.  Investigators and mutilators, designed for torturing captives but far too frail for direct combat, fell under her infernal blade nearly as easily as the unaltered Children of Ruby who had few skills outside clerical work, and soon she began to feel that the demonic magic she had been imbued with may have made her nearly unstoppable.  When a demonic statue called out to her, she thought nothing of trying to absorb more of its power, barely even noticing when the statue called forth a Champion of Urh'Rok--

Once upon a time, there was a Shalore Adventurer by the name of <?=Lore.pocket_time_winner.name?>, who was quite certain of what he was doing.  He'd learned an extremely uncommon set of abilities - great talent with unarmed martial arts, some psychic potential to swing a staff in the air while leaving his hands free, stone magic that used his punches as a focus to blast foes with a hailstorm of earthen missiles - and once he had enough practice to master a few of these, he started effortlessly destroying any foe he faced... until he encountered the Weirdling Beast.  The battle was intense, and soon, both were on the verge of death, on opposite sides of the fortress's foyer; the Adventurer knew he couldn't afford to rush in close to finish the beast off, so he launched a pair of earthen missiles at it instead.  However, the moment they left his hands, he felt the grip of hard bone around his waist, legs, and back, pulling him at an incomprehensible speed into the Weirdling Beast's grasp.  Perhaps <?=Lore.pocket_time_winner.name?> could have survived an ensuing fistfight, but he had been pulled faster than his own missiles could fly, and now he found himself between the stony projectiles and their original target--

Once upon a time, a great spirit put down its pen and closed its notebook, sighing in frustration.]], [[<? Lore.init_pocket_time_data() ?>從前，有個半身人鍊金術師叫做<?=Lore.pocket_time_winner.name?>。和她可靠的傀儡一起，她向巨魔沼澤前進，把擋住她的敵人消滅殆盡；不過當她遇到了普洛克斯時，他彎下腰來在離她臉幾英寸的地方大吼，正好在炸彈的爆炸範圍之內，她慌張起來把一個鍊金瓶從腰帶上拽開———— 

從前，有個矮人狂戰士名叫<?=Lore.pocket_time_winner.name?>。在瑞庫納的大廳逃離時，在他的朋友被獸人戰士砍倒後，他直接向幾個獸人正面衝去，然後————

從前，有個科納克人盜賊名叫<?=Lore.pocket_time_winner.name?>。他的陷阱很快解決了普洛克斯，但當岩石巨魔比爾在他的巢穴裏把他扔了出去，他失去平衡踩在了————

從前————

從前，有個大英雄，一個矮人岩石守衛名叫<?=Lore.pocket_time_winner.name?>，在開始她的旅程時發表了一番關於不公平的費解的話，然後聳肩繼續前進。她與最親近的同伴一道從瑞庫納逃離，使用了她的自然能力清除了無盡深淵與迷宮裏的墮落之力，從嗜殺的實驗體Z的魔掌中拯救了一個奇怪的叫做“奪心魔”的新生物，甚至在勢不可擋地推進時，甩開了岱卡拉的巨人向她扔去的巨石，消滅了傷害了以往許多人的威脅。她發現了失落的孔克雷夫地下實驗室，讓最後幾個最初被造出來的食人魔安息，從卡洛·斐濟邪教徒的魔掌中救出了一個姑娘，最終站在了恐懼王座的塔門前，技藝百經錘鍊，滿載旅程中找到的各種珍奇裝備。她一邊往上爬，一邊與一波波蹣跚的不死生物而戰，她終於見到了吸血鬼領主迎面而來。這是，一個骷髏戰士從後襲來。當她想用她僅有的那一個狂暴紋身時，它的戰錘揮擊震懾了她。當她因震懾而失去平衡，想要激活紋身的力量，一陣可怕的寒流涌遍了她的四肢，把她包裹在冰塊之中時，她才清醒過來————

從前，有個自然精靈召喚師叫做<?=Lore.pocket_time_winner.name?>, 在一條蛇旁開始了旅程，這條蛇不自然地精通時間魔法————

從前，有個可怕的惡棍，一個食人魔收割者叫做<?=Lore.pocket_time_winner.name?>，他發現自己爲魔法大爆炸影響的山洞中被污染的晶體結構着迷。他首先在夜深人靜之時淹死了一個最後的希望的守衛，偷走了她的附魔戒指，然後在大陸上一路留下他毀滅的軌跡，吸取着被他雙手斧砍死或被他的長劍穿透的對手的力量，在造成一場場死亡的同時變得更強大。他參與了大腐化者的事業來襲擊伊格，來確保沒人能阻止他的奧術瘟疫散播，之後把沙蟲女王的心臟帶到魔法大爆炸污染的土地上，來把它的自然祝福腐化成一種枯萎的苦難力量。他對一個邪教獻祭少女來召喚他們的惡魔主人袖手旁觀，這樣他能親自殺死它。他旅行到遠東，看到四支獸人大軍潰散而流血，腫塊和瘡遍佈他們的皮膚，同時生命緩慢地從眼中流失而垂涎不已。沃爾部落最好的戰士對於他劫掠兵器庫而無可奈何，但一個瘸腿而病弱的獸人堵在封印的門前求他別打開；他只是大笑，走向門，踩過獸人的頭，在靴子下碾碎，之後把門踢倒，突然感覺到他的骨盾在一羣無可言喻地強大的七彩龍的吐息風暴中解體。即使是<?=Lore.pocket_time_winner.name?>也知道什麼時候該從戰鬥中逃跑，在激活相位門符文的同時握緊了拳頭；當刺眼的閃光消失時，他發現自己幾英尺外就是————

從前，有個魔化精靈叫<?=Lore.pocket_time_winner.name?>，由於一個好運天降的落星從惡魔的心靈控制中解脫，出發去用她新得到的力量來從她被困住的軌道地獄中逃脫。那些調查員和切割者是被設計來折磨囚徒，他們對於近身戰鬥來說過於脆弱，在她的烈火之刃面前，幾乎就像是那些未被轉變的，除了文書工作外沒什麼技能的紅寶石之子那樣輕鬆倒下，很快，她開始感覺她體內被灌注的惡魔魔法說不定已讓她接近無敵。當她看到一個惡魔雕像時，她除了想吸收更多力量外沒想別的，根本沒注意到雕像召喚了一個烏魯洛克的精英衛兵————


從前，有個永恆精靈冒險者叫<?=Lore.pocket_time_winner.name?>，他對於自己在做什麼非常確信。他學會了一套相當不尋常的能力————了不起的空手武術天賦，一種在空中揮動法杖的心靈潛能，用拳擊觸發的石系魔法來用暴風般的石彈來擊退敵人們————一旦他在這些方面都有了一些實戰經驗，他開始秒殺所有遇到的敵人……直到他遇到了異形觸手。戰鬥非常激烈，不一會兒，雙方都在死亡的邊緣上，位於要塞前廳的兩端；冒險者知道他沒法衝上前近距離解決那野獸，因此他取而代之地向它發射了一雙石彈。然而，當石彈從手中離開時，他感到堅硬的骨爪緊緊環繞腰、腿和後背，以一種無可理喻的速度把他拖入異形觸手的手掌心。或許<?=Lore.pocket_time_winner.name?>可能會在接下來的近身拳擊中活下來，但他被拖動的速度快於石彈的飛行，現在他發現自己處在這些石制投射物和他們原來的目標之間————

從前，一個偉大的靈魂放下了它的筆，合上了它的筆記本，沮喪地嘆氣。]], "_t")
t("a telepathic message <The Tale of Maj'Eyal>", "心靈傳訊《馬基埃亞爾的傳說》", "_t")
t([[<? Lore.init_pocket_time_data() ?>Once upon a time, there was <?=Lore.pocket_time_winner.race?> <?=Lore.pocket_time_winner.class?> by the name of <?=Lore.pocket_time_winner.name?>.  <?=Lore.pocket_time_winner.HeShe?> came from humble beginnings, dealing with minor threats like the mad nature-guardian Norgos or yet another reincarnation of Kor'Pul, but as <?=Lore.pocket_time_winner.heshe?> traveled throughout the land, <?=Lore.pocket_time_winner.heshe?> grew stronger and more skilled, and began to take on ever more fearsome opponents.  <?=Lore.pocket_time_winner.HeShe?> purged the corrupted horrors of Yiikgur and claimed the long-forgotten flying fortress for <?=Lore.pocket_time_winner.himher?>self, but even this was a mere stepping stone on the way to the tower of Dreadfell.  The Master, a necromancer of terrible power and even more terrible sadism, waited for <?=Lore.pocket_time_winner.himher?> there with an army of the undead, clutching an ancient weapon of incredible power...  but <?=Lore.pocket_time_winner.name?> bravely pressed on, cutting through the hordes of skeletons and ghouls, prevailing where so many others had failed.  Eventually, <?=Lore.pocket_time_winner.heshe?> stood victorious over the vampire's body, and took the Staff of Absorption with <?=Lore.pocket_time_winner.himher?>, safely away from undead hands.  Maj'Eyal was safe once more.

Unfortunately, what awaited <?=Lore.pocket_time_winner.himher?> next was a quest with even greater stakes.  Orcs, a once-thought-vanquished threat, had reappeared in force in Maj'Eyal!  Despite <?=Lore.pocket_time_winner.name?>'s best efforts to store the staff in a safe place, the orcs stole it, and <?=Lore.pocket_time_winner.name?> was forced to follow them all the way through an ancient, impossibly advanced Farportal to get it back.  The portal crackled and whirled as <?=Lore.pocket_time_winner.name?> held up the Orb of Many Ways to activate it; <?=Lore.pocket_time_winner.heshe?> took a deep breath, closed <?=Lore.pocket_time_winner.hisher?> eyes, and a moment later, <?=Lore.pocket_time_winner.heshe?> became the first person to go from Maj'Eyal to Var'Eyal, the distant continent of the Far East, in centuries.

A long-lost band of allies, the people of Sunwall, awaited <?=Lore.pocket_time_winner.himher?> there - as did four armies of orcs!  Once again, though, <?=Lore.pocket_time_winner.name?> refused to back down when the fate of the world was in <?=Lore.pocket_time_winner.hisher?> hands.  Blessed by High Paladin Aeryn, <?=Lore.pocket_time_winner.heshe?> set out to reclaim the Staff of Absorption from the Orcish Prides.  Storms of fire and ice assaulted <?=Lore.pocket_time_winner.himher?> on <?=Lore.pocket_time_winner.hisher?> way to challenge the grand magus Vor, a foe who could call forth the heavens themselves to pulverize <?=Lore.pocket_time_winner.himher?>, but his meteors weren't enough to stop <?=Lore.pocket_time_winner.himher?>; the dragon-tamers of Gorbat Pride, master wyrmics with unparalleled control over the forces of Nature, merely gave <?=Lore.pocket_time_winner.name?> the opportunity to become the world's most accomplished dragonslayer.  The bone fortress of Rak'Shor Pride crumbled as <?=Lore.pocket_time_winner.heshe?> put its inhabitants to rest, and even when orcs stood in <?=Lore.pocket_time_winner.hisher?> way to do what orcs are best known for at Grushnak Pride, their brute force with strength and steel was simply not strong enough.
<? if not Lore.pocket_time_winner.sacrifice then ?>
But right as <?=Lore.pocket_time_winner.heshe?> set out to climb the tower, <?=Lore.pocket_time_winner.heshe?> got an urgent message from High Paladin Aeryn!  <?=Lore.pocket_time_winner.HeShe?> journeyed across the wastes of Eruan with haste, arriving at another farportal.  Without a thought to where it led, <?=Lore.pocket_time_winner.name?> rushed in at her orders; <?=Lore.pocket_time_winner.heshe?> found <?=Lore.pocket_time_winner.himher?>self in a vast plain of fire and magma, with a narrow stretch of land leading far into the distance.  Behind <?=Lore.pocket_time_winner.himher?>, <?=Lore.pocket_time_winner.heshe?> heard clanging and crashing - the orcs were after <?=Lore.pocket_time_winner.himher?> even here, and the Sun Paladins were valiantly holding the line to keep them away.  They told <?=Lore.pocket_time_winner.himher?> to do one thing: run!  And run <?=Lore.pocket_time_winner.heshe?> did, cutting through and sidestepping countless great red drakes in the process, the glowing magma spitting and bubbling on either side of the perilous stony bridge.  At the end, <?=Lore.pocket_time_winner.heshe?> caught the sight of the Staff for the first time since Maj'Eyal - and the culprits were, surprisingly, a human and an elf!  These two sorcerers, driven by a combination of good intentions, sheer madness, and tragic love, had manipulated the Orc Prides into stealing the staff for them - to what end, <?=Lore.pocket_time_winner.heshe?> still did not know.  Nonetheless, the spell they were channeling was thwarted, and <?=Lore.pocket_time_winner.heshe?> returned to the East victorious, ready to assault the sorcerers' lair of the High Peak.

Threats even greater than any <?=Lore.pocket_time_winner.heshe?> had faced before awaited <?=Lore.pocket_time_winner.himher?>.  The tower itself was trying to stop <?=Lore.pocket_time_winner.himher?>, changing conditions assaulting <?=Lore.pocket_time_winner.hisher?> defenses on each floor, combined with an army of every foe imaginable, but <?=Lore.pocket_time_winner.heshe?> would not be hindered, and pushed past everything on <?=Lore.pocket_time_winner.hisher?> final ascent.  On the top floor, <?=Lore.pocket_time_winner.heshe?> was finally met with the sorcerers, Argoniel and Elandar, face-to-face.  They told <?=Lore.pocket_time_winner.himher?> of their plans with the staff, ones far more dangerous than mere global domination - no, they sought to bring back a threat that only the long-gone Sher'Tul could have dealt with.  A threat long forgotten, lost and tumbling between the stars: Gerlyk, a god driven mad from isolation.  They had to be stopped!

Fortunately, <?=Lore.pocket_time_winner.name?> did not go into this battle alone.  High Paladin Aeryn arrived to fight by <?=Lore.pocket_time_winner.hisher?> side, and the four of them clashed in a fight for the fate of Eyal.  Even with Argoniel's fearsome bone-armor whirling around her, even with Elandar's impressive spells flying through the air, even with the portals summoning foes of all sorts to join the battle...  in the end, the forces of good prevailed.  The sorcerers were defeated, and the portal was sealed, forever.

Eyal had been saved, thanks to <?=Lore.pocket_time_winner.name?>.  Most of the world may not have known what happened at the top of High Peak, but they were in the grips of peril, and were now free of it.  None can say what our champion did after that...  but whatever it was, <?=Lore.pocket_time_winner.heshe?>, and all life on Eyal, lived happily ever after.
<? else ?>
Threats even greater than any <?=Lore.pocket_time_winner.heshe?> had faced before awaited <?=Lore.pocket_time_winner.himher?> in the tower of High Peak.  The tower itself was trying to stop <?=Lore.pocket_time_winner.himher?>, changing conditions assaulting <?=Lore.pocket_time_winner.hisher?> defenses on each floor, combined with an army of every foe imaginable, but <?=Lore.pocket_time_winner.heshe?> would not be hindered, and pushed past everything on <?=Lore.pocket_time_winner.hisher?> final ascent.  Alas, the most trying challenge of these was on the penultimate floor: High Paladin Aeryn.  The Gates of Morning had been destroyed, because <?=Lore.pocket_time_winner.name?> didn't manage to stop the ritual of the Charred Scar, despite the calls to help <?=Lore.pocket_time_winner.heshe?> heard.  She blamed <?=Lore.pocket_time_winner.name?> for this, and the two fought...  but Aeryn relented once <?=Lore.pocket_time_winner.heshe?> realized <?=Lore.pocket_time_winner.heshe?> had been beaten.

On the top floor, <?=Lore.pocket_time_winner.heshe?> was finally met with the sorcerers, Argoniel and Elandar, face-to-face.  They told <?=Lore.pocket_time_winner.himher?> of their plans with the staff, ones far more dangerous than mere global domination - no, they sought to bring back a threat that only the long-gone Sher'Tul could have dealt with.  A threat long forgotten, lost and tumbling between the stars: Gerlyk, a god driven mad from isolation.  They had to be stopped!

The three of them clashed in a fight for the fate of Eyal.  Even with Argoniel's fearsome bone-armor whirling around her, even with Elandar's impressive spells flying through the air, even with the portals summoning foes of all sorts to join the battle...  in the end, the forces of good prevailed.  The sorcerers were defeated, and the portal was sealed, forever...  but at a terrible cost.  <?=Lore.pocket_time_winner.name?> had seen the farportal - the sorcerers had managed to charge it with too much energy, and the Staff alone was not enough to stop it.  <?=Lore.pocket_time_winner.HeShe?> selflessly made the ultimate sacrifice, using <?=Lore.pocket_time_winner.hisher?> life to destroy the portal.

None on Eyal would ever know of <?=Lore.pocket_time_winner.hisher?> sacrifice, or that they were ever in danger...  but thanks to our champion, they could live happily ever after.
<? end ?>
<? if Lore.pocket_time_winner.is_yeek then ?>[i]...Well, let's just assume that's how it went, anyway.  The alternative would make it quite difficult to tell the next story.[/i]<? end ?>
]], [[<? Lore.init_pocket_time_data() ?>從前，有一位名叫<?=Lore.pocket_time_winner.name?>的<?=Lore.pocket_time_winner.race?> <?=Lore.pocket_time_winner.class?>。<?=Lore.pocket_time_winner.HeShe?>出身卑微，開始只進行一些簡單的冒險，例如瘋狂的自然守護者諾爾格斯或者是卡·普爾的另一個化身。隨着<?=Lore.pocket_time_winner.heshe?>繼續周遊各地的旅行，<?=Lore.pocket_time_winner.heshe?>變得越來越強大，越來越熟練，開始嘗試挑戰越來越強大的對手。<?=Lore.pocket_time_winner.HeShe?>清除了佔據伊克格的恐魔，並佔領了這個被遺忘已久的飛行堡壘，作爲下一步攻入恐懼王座的據點。“領主”，一個有着強大的力量和虐待慾望的恐怖死靈法師，正帶領着一支龐大的不死軍隊在那裏等待着<?=Lore.pocket_time_winner.himher?>，手握一把具有強大力量的遠古神器……但是<?=Lore.pocket_time_winner.name?>勇敢地向前前進，穿過成羣的骷髏和食屍鬼，在許多人失敗的地方獲得了成功。最終，<?=Lore.pocket_time_winner.heshe?>光榮地站在食屍鬼領主的屍體之上，手中拿着死靈大軍手中奪回的吸能法杖，馬基埃亞爾再次恢復了和平。

然而，等待着<?=Lore.pocket_time_winner.himher?>的則是更加危險的挑戰。獸人，一個認爲已經被戰勝已久的威脅，重新出現在了馬基埃亞爾的土地上！儘管 <?=Lore.pocket_time_winner.name?>努力將法杖存在了安全的地方，獸人們還是設法偷走了它，<?=Lore.pocket_time_winner.name?>不得不追隨着他們，穿過發達到讓人難以置信的遠古傳送門，試圖追回法杖。<?=Lore.pocket_time_winner.name?>手握着多元水晶球，深吸一口氣，穿過劈啪作響的傳送門漩渦，那一瞬間， <?=Lore.pocket_time_winner.heshe?>成爲第一個從馬基·埃亞爾到達瓦·埃亞爾的人，那是和馬基·埃亞爾分割了幾個世紀的遠東大陸。

在那裏等待着<?=Lore.pocket_time_winner.himher?>的，有着失落已久的盟友，太陽堡壘的人們——也有四支龐大的獸人軍隊。又一次，世界的命運落在了<?=Lore.pocket_time_winner.hisher?>手中，而<?=Lore.pocket_time_winner.himher?>絕不願朝困難屈服。在接受了高階太陽騎士艾琳的祝福之後，<?=Lore.pocket_time_winner.heshe?>出發前去進攻獸人部落，奪回被奪走的吸能法杖。與大魔導師沃爾的戰鬥充滿了火焰和冰霜的風暴，那是可以召喚來自天空的力量來試圖毀滅對手的強大敵人，但是沃爾的隕石也無法阻擋<?=Lore.pocket_time_winner.himher?>的勝利。加伯特部落的馴龍師和高階龍戰士對自然力量的掌控無出其右，但這只是讓<?=Lore.pocket_time_winner.name?>成爲了世界上最偉大的屠龍者。隨着拉克·肖部落高大的白骨堡壘轟然倒下，<?=Lore.pocket_time_winner.heshe?>讓死者們終於得到了安息。最終，以獸人中最強大的力量著稱的格魯希納克部落的精英部隊也倒在了<?=Lore.pocket_time_winner.hisher?>面前。
<? if not Lore.pocket_time_winner.sacrifice then ?>
但是正當<?=Lore.pocket_time_winner.heshe?>攀爬高塔之前，<?=Lore.pocket_time_winner.heshe?>收到了來自高階太陽騎士艾琳的緊急消息。<?=Lore.pocket_time_winner.HeShe?>急忙穿越了艾露安的廢墟，到達了另一座遠古傳送門的面前。沒有任何猶豫，<?=Lore.pocket_time_winner.name?>衝進了傳送門中；<?=Lore.pocket_time_winner.heshe?>發現自己身處一片火焰和岩漿的焦灼峽谷，狹長的土地通往遠方。在<?=Lore.pocket_time_winner.himher?>身後，<?=Lore.pocket_time_winner.heshe?>聽見了兵器的碰撞聲：那是追隨<?=Lore.pocket_time_winner.himher?>到達這裏的獸人軍隊，太陽騎士們正嚴守防線，試圖阻止敵軍靠近。那些太陽騎士只告訴<?=Lore.pocket_time_winner.himher?>一件事：快跑！於是，<?=Lore.pocket_time_winner.heshe?>不顧一切地奮勇向前衝去，穿過和避開無數的紅色巨龍，灼熱的岩漿在危險的石橋兩側噴涌而出。最終，<?=Lore.pocket_time_winner.heshe?>的眼前終於又出現了吸能法杖的身影——然而，令人驚訝的是，真正的幕後黑手竟然是一個精靈和一個人類！那兩位法師，在良好的意圖，無盡的瘋狂和悲劇性的愛的驅使之下，操縱獸人部落偷取法杖給他們——他們的目的到底是什麼，<?=Lore.pocket_time_winner.heshe?>仍然尚不清楚。然而，他們所施展的法術被阻止了，<?=Lore.pocket_time_winner.heshe?>勝利回到了遠東大陸，準備突襲這兩位法師位於巔峯高塔的最終堡壘。

在那裏等待着的，是遠勝於<?=Lore.pocket_time_winner.heshe?>之前所見過的一切的恐怖挑戰。高塔本身正在試圖阻擋着<?=Lore.pocket_time_winner.himher?>，在每一層不斷切換着環境，對<?=Lore.pocket_time_winner.hisher?>的防禦做出挑戰。在每一層，都有着一切可能出現的可怕怪物的嚴加守衛，但是<?=Lore.pocket_time_winner.heshe?>毫不畏懼，奮勇向前，擊敗了一切敵人，最終到達了頂層。在頂層，<?=Lore.pocket_time_winner.heshe?>終於見到了那兩位法師，埃蘭達和艾格尼爾。他們告訴了<?=Lore.pocket_time_winner.himher?>有關法杖的真正計劃，這比征服世界還要可怕的多——不，他們將要召回只有消失已久的夏·圖爾人才能應對的遠古威脅。那是被世人遺忘，流浪在羣星中的恐怖：蓋裏克，在長期的隔絕之中陷入了無盡的瘋狂。他們的計劃必須被阻止！

幸運的是，<?=Lore.pocket_time_winner.name?>並未獨自戰鬥。高階太陽騎士艾琳來到了這裏，與<?=Lore.pocket_time_winner.hisher?>並肩作戰，這四個人將會爲了埃亞爾的未來展開一場曠世之戰。艾格尼爾恐怖的骨盾環繞在她的四周，埃蘭達強大的法術在空中撕裂一切，四周的傳送門不斷召喚各種敵人加入戰場……然而最終，正義終於得到了勝利。法師們被打敗了，傳送門也被永久封印了。

埃亞爾的命運被<?=Lore.pocket_time_winner.name?>拯救了。這個世界上的大部分人，還不曾知道在巔峯上發生了什麼，不知道世界曾經那樣危在旦夕，但現在已經重現了和平。沒有人知道，我們的英雄在之後去了哪裏……但是，無論如何，<?=Lore.pocket_time_winner.heshe?>，以及埃亞爾的所有生靈，一直幸福地生活了下去。
<? else ?>
在那裏等待着的，是遠勝於<?=Lore.pocket_time_winner.heshe?>之前所見過的一切的恐怖挑戰。高塔本身正在試圖阻擋着<?=Lore.pocket_time_winner.himher?>，在每一層不斷切換着環境，對<?=Lore.pocket_time_winner.hisher?>的防禦做出挑戰。在每一層，都有着一切可能出現的可怕怪物的嚴加守衛，但是<?=Lore.pocket_time_winner.heshe?>毫不畏懼，奮勇向前，擊敗了一切敵人，最終到達了頂層。在最後一層，出現的挑戰者是出人意料的：高階太陽騎士艾琳。晨曦之門被摧毀了，因爲<?=Lore.pocket_time_winner.name?>未能阻止法師們在灼燒之痕舉行的儀式。艾琳將責任歸咎於<?=Lore.pocket_time_winner.name?>的身上，他們進行了激烈的戰鬥……然而最後，艾琳被擊敗了。

在頂層，<?=Lore.pocket_time_winner.heshe?>終於見到了那兩位法師，埃蘭達和艾格尼爾。他們告訴了<?=Lore.pocket_time_winner.himher?>有關法杖的真正計劃，這比征服世界還要可怕的多——不，他們將要召回只有消失已久的夏·圖爾人才能應對的遠古威脅。那是被世人遺忘，流浪在羣星中的恐怖：蓋裏克，在長期的隔絕之中陷入了無盡的瘋狂。他們的計劃必須被阻止！

這三個人將會爲了埃亞爾的未來展開一場曠世之戰。艾格尼爾恐怖的骨盾環繞在她的四周，埃蘭達強大的法術在空中撕裂一切，四周的傳送門不斷召喚各種敵人加入戰場……然而最終，正義終於得到了勝利。法師們被打敗了，傳送門也被永久封印了……但是，付出的代價是慘重的。<?=Lore.pocket_time_winner.name?>看到了遠古傳送門的景象——兩位法師爲它注入了太多的能量，光使用吸能法杖已經無法阻止它了。<?=Lore.pocket_time_winner.HeShe?>無私地做出了犧牲，使用<?=Lore.pocket_time_winner.hisher?>的生命作爲代價，摧毀了傳送門。

在埃亞爾，沒有人知道是<?=Lore.pocket_time_winner.hisher?>犧牲拯救了他們，甚至對他們曾經出於怎樣的危機渾然不知……然而，正是因爲這位英雄的努力，他們才能夠和平幸福地生活了下去。
<? end ?>
<? if Lore.pocket_time_winner.is_yeek then ?>[i]……好吧，我們假設事情就是這樣的。如果不這樣的話，要想講下一個故事就變得太困難了。[/i]<? end ?>
]], "_t")
t("a telepathic message <The Eidolon>", "靈能傳訊<艾德隆>", "_t")
t([[<? Lore.init_pocket_time_data() ?>Once upon a time, there was a spirit known as the Eidolon, older than anything on Eyal.  Some called it a savior, a bringer of order and justice; others, a dark god, spreading terror for its own amusement.  Such mortal classifications are hopelessly inadequate to describe the incomprehensibly far-sighted motivations of a being nearly as old as time itself...  but if you were to ask the Eidolon, it would call itself a storyteller.

Whether the story exists only in its own head or is reflected across the Shandral system, none can say - but the Eidolon needed heroes for its story, as it always has.  Today, the hero it needed was a master of battle, the likes of which had not been seen since the age of Garkul the Devourer.  It considered a few different options, deeming many failures, some potentially adequate with a few mistakes forgiven, and only one to be finally chosen.  Its chosen protagonist met every challenge put before <?=Lore.pocket_time_winner.himher?>, sometimes with ease, often with difficulty, occasionally escaping through luck alone, but eventually stood atop the High Peak, having saved Eyal from the greatest threat it had ever faced<? if Lore.pocket_time_winner.sacrifice then ?> by sacrificing <?=Lore.pocket_time_winner.himher?>self to shut down the Sorcerers' farportal<? end ?>.
<? if not Lore.pocket_time_winner.sacrifice then ?>
And what then?  A master of battle has nothing to do once the battle is won.  <?=Lore.pocket_time_winner.HeShe?> could've sought out harder foes, but the only ones <?=Lore.pocket_time_winner.heshe?> would be likely to find would either be pointless to face, or outright harmful to the citizens of Eyal; they would add nothing to the story.  The Eidolon could have introduced a foe strong enough to finally destroy <?=Lore.pocket_time_winner.himher?>, but what kind of ending would that be?  Instead, the Eidolon decided to let its protagonist retire as <?=Lore.pocket_time_winner.heshe?> wished...  whether <?=Lore.pocket_time_winner.heshe?> chose to descend to inevitable doom in the Infinite Dungeon, to attempt to slay impossible foes like Atamathon and Linaniil, or to simply retire and live out the rest of <?=Lore.pocket_time_winner.hisher?> days in the reclaimed Sher'Tul fortress.  In any case, the story was over; there wasn't any room left for the rest of <?=Lore.pocket_time_winner.name?>'s life.<? end ?>

Of course, a character like that can't simply be thrown away.  The story may be over, but it can be told again and again, and as such there would be as many Heroes of Maj'Eyal as there were people who'd listen to the story, each hearing it and imagining it slightly differently from the next.  Even the storyteller would dream up more situations for the Hero of Maj'Eyal, always wondering - what if I found an even match for this first warrior?  Don't I owe <?=Lore.pocket_time_winner.himher?> the reward of a fight <?=Lore.pocket_time_winner.heshe?> would be eager to participate in, and one that would give <?=Lore.pocket_time_winner.himher?> the challenge <?=Lore.pocket_time_winner.heshe?> craved so dearly?  Wouldn't such a duel be worth writing about?  And so, it kept <?=Lore.pocket_time_winner.name?> in mind, promising to remember <?=Lore.pocket_time_winner.himher?> whenever it found or created a threat worthy of <?=Lore.pocket_time_winner.himher?>.

[b]<?=player.name?>[/b], you crave the thrill and tension of a close fight as much as <?=Lore.pocket_time_winner.heshe?> does.  I owe this opportunity to you in life, and the Scourge from the West in <?=Lore.pocket_time_winner.hisher?> legend; all I ask in return is that the two of you give me a battle that the people of Eyal will sing songs about.]], [[<? Lore.init_pocket_time_data() ?>從前，有一個叫做艾德隆的靈魂，比埃亞爾的一切都要古老。有人稱之爲救世主，是秩序和正義的使者；也有人稱之爲黑暗之神，傳播恐怖以自娛自樂。這樣的凡人分類，是無可救藥地不足以描述一個幾乎和時間一樣古老的人的不可思議的動機的……但是，如果你親自問他的話，他會自稱是一個講故事的人。

不管這個故事是隻存在於它的腦海裏，還是反映在整個珊德拉星系之中，沒有人知道——但是，艾德隆的故事裏需要英雄，一直都是這樣。今天，他所需要的英雄是一位戰鬥的大師，一位從吞噬者加庫爾的時代以來就未曾出現的大師。他會綜合考慮各種各樣的可能性，面對無數的困難，有些可能允許一部分的錯誤，但是最終只會選擇一個。被它所選中的主角戰勝了擺在<?=Lore.pocket_time_winner.himher?>面前的一切挑戰，有時舉重若輕，有時艱難取勝，也有的時候則透過運氣勉強通過。但最終，<?=Lore.pocket_time_winner.himher?>站在了巔峯之上，<? if Lore.pocket_time_winner.sacrifice then ?>通過犧牲<?=Lore.pocket_time_winner.himher?>的生命來關閉了法師的遠古傳送門<? end ?>，從而把埃亞爾從其所面臨的最大的威脅面前解救出來。
<? if not Lore.pocket_time_winner.sacrifice then ?>
之後呢？在戰鬥勝利之後，這位爲戰鬥而生的大師就無事可做了。<?=Lore.pocket_time_winner.HeShe?> 本可以找到更加強大的敵人，但<?=Lore.pocket_time_winner.heshe?>很快發現自己面對的東西要麼毫無意義，要麼只會對埃亞爾的世界有害，不會給故事增添任何內容。艾德隆也可以創造一個強大到足以擊敗<?=Lore.pocket_time_winner.himher?>的敵人，但這又是什麼樣的結局呢？最終，艾德隆決定遵循<?=Lore.pocket_time_winner.heshe?>的意願，讓這位英雄從此退休……無論<?=Lore.pocket_time_winner.heshe?>選擇前往無盡地下城尋求無窮無盡的挑戰，去挑戰像阿塔瑪森或是萊娜尼爾這樣幾乎不可能擊敗的恐怖敵人，還是就此在夏·圖爾堡壘中度過餘生。無論是哪一種，這個故事都結束了，<?=Lore.pocket_time_winner.name?>的故事就此走到了盡頭。<? end ?>

當然，這樣的角色不能簡單地被拋棄。故事可能已經結束了，但它可以一次又一次地被講述。這樣一來，每有一個願意聽故事的，就會出現一位馬基·埃亞爾的英雄。每個人都聽到了故事，並且對它的想象與下一個略有不同。即使是講故事的人，也會爲馬基·埃亞爾的英雄設想更多的場景，總是在想——我是否能給這第一位戰士找到一位勢均力敵的對手呢？我是否正欠<?=Lore.pocket_time_winner.himher?>一個獎賞，一場真正能夠讓<?=Lore.pocket_time_winner.heshe?>興奮地參與的戰鬥，一個<?=Lore.pocket_time_winner.himher?>渴望已久的終極挑戰呢？這樣的戰鬥，難道不值得記述下來嗎？因此，它將<?=Lore.pocket_time_winner.name?>的名字在腦海中記錄下來，願意一直牢記住<?=Lore.pocket_time_winner.himher?>，直到它找到或者創造了一位真正能夠和<?=Lore.pocket_time_winner.himher?>勢均力敵的對手。

[b]<?=player.name?>[/b]，你和<?=Lore.pocket_time_winner.heshe?>一樣，有着對於真正熱血的戰鬥的刺激和緊張的渴望。我不僅欠缺你一個這樣尋求挑戰的機會，也欠缺了那位西方災星書寫<?=Lore.pocket_time_winner.hisher?>傳奇的機會；現在，我希望你們之間能夠開展一場真正能夠讓所有埃亞爾人永遠傳頌的史詩戰鬥。]], "_t")

------------------------------------------------
section "tome-orcs/data/lore/primal-forest.lua"

t("primal forest", "原始森林", "newLore category")
t("a warning sign", "警告標牌", "_t")
t([[WARNING - READ THIS!

---

This forest is the site of a massive and ongoing ecological disaster.  As far as I can tell (and as a Mender, I have at least [i]some[/i] clue of what I'm talking about), Eyal's trying to fight off an infection, and the infection's fighting back for all it's worth.  Given the indiscriminate hostility of the local treants, we can assume the infection's winning, if only slightly; it's concentrated most of its power into a handful of crystalline avatars at the top of the great tree.  Best case scenario, Eyal's pushing them out like splinters, and destroying these avatars will eliminate the problem; worst case, the tree is already infected down to its roots, and these avatars are its spores, growing until they're ready to leave the tree and spread elsewhere.  I came to destroy these crystals myself, but I wasn't counting on the treants turning on me as well; since you're reading this, congratulations!  This is your responsibility now.

My advice?  Head through the portal to Shatur and call for backup.  I don't have that option, as that'd require incriminating myself by admitting that I was in Var'Eyal without a pass (you wouldn't judge me if you knew how much the trolls were paying for cheerblossom).  I can assure you that the others there are considerably more dedicated and competent than I am, even if only as a group; together, they'll be able to control this infection and treat the wounds it's left behind.  If you go in alone, you'll likely get ripped apart by the treants before you can even reach the trunk - and more are waking up every passing minute.  Unless you're the Hero of Maj'Eyal or Garkul's reanimated corpse, you'll be walking into your own grave.  Let the professionals handle this.

If you insist on going in, though, here's what I know:

-The treants, unfortunately, are no longer concerned with discerning friend from foe.  Anything not stemming from Nature is a potential source of the infection in their eyes, and must be purged before they can slumber once more.  I know that saying "please" isn't exactly sufficient for asking you not to defend yourself...  just try to keep the damage to a minimum, so they can heal the land once ravaged by this sickness.  If you want to avoid them, get off the ground level and into the canopy as soon as you can; they won't animate if they don't see anything on the forest floor to attack.  Also, do NOT try to take a core sample!  Trust me on this - as much as I wanted to know how deep the infection had spread, whether it was all the way through the tree or if it had pushed it all to the top, it attracted the treants to me like Shaloren to a stupid decision.  

-The destructive agent in question is a group of animated arcane crystals, of the type previously documented in the Scintillating Caverns.  The exact processes involved in their formation are still unclear, but it's a safe assumption that they're connected to the massive surge of blight introduced by the Spellblaze, and proof that even now, the damage is most likely worse than we can ever be sure of.  Expect to take powerful blasts of every kind of magic if you're not exceptionally evasive; fortunately, although they frequently teleport, they are completely immobile between blinks.  If one teleports near you, either take cover, or destroy it before it can reposition itself.

-The consequences of letting this go unchecked would be disastrous.  Even if this great tree's growth IS a sign of the planet successfully fighting the infection off by pushing it out, the crystalline avatars could simply climb down, bury themselves, and sicken Eyal once more.  And if Eyal's losing...  as much as I loathe to say it, perhaps those Shaloren pyromaniacs could do some good for once in their all-too-long lives, and cauterize the area down to the roots.  Provided, of course, that they can figure out how to do so without blowing up the sun.

I wish you luck, and thank you for doing what I cannot.  There are reasons why this is a risk I cannot afford to take, but it's probably best for both of us that you assume I'm a coward.  It's not too far from the truth.

With unending gratitude,
(This is where I would sign my name, were I an utter moron.)

PS: If you wouldn't mind doing me a personal favor, please destroy any written articles you find.  They spilled out of my bag as I fled; I'm already a coward, and I'd rather not be a litterer as well.]], [[[b]警告——請注意！[/b]

---

這座森林正經受着一場巨大的生態災難。對此，我能說的就是，埃亞爾的力量正在這裏對抗某種外界的感染，而這種外界的感染也正在全力反擊回去（我是一名修復者，請相信我能說這些還是[i]有點根據[/i]的）。看看旁邊這些不分青紅皁白地胡亂攻擊的狂暴的樹人，你就能看出，這種感染的力量目前佔着上風，儘管這一優勢十分微小。這種感染的力量，大部分集中在面前這棵巨樹的樹冠中的幾個水晶化身裏面。在最好的情況下，埃亞爾正在把它們像插進身體的碎片一樣推出來，只要摧毀這些化身，就可以完全解決這個問題；而最壞的情況下，這棵樹已經被一直感染到根部了，而這些化身只是這種感染的孢子，它們正在慢慢生長，準備離開這棵巨樹，將感染傳播到世界的每個角落。我本來是想來摧毀這些水晶的，但我沒想到，這些樹人也對我發起了攻擊。既然你已經看到了這裏，恭喜你！現在解決這件事就是你的責任了。

你問我的建議是什麼？趕緊從傳送門跑回夏特爾，找人來幫忙吧。我可不能這麼幹，因爲這樣等於讓我不打自招地承認，我在沒有通行證的情況下混進了瓦·埃亞爾（如果你知道那羣巨魔願意爲鼓舞之花掏多少錢，你肯定不會指責我的）。我可以向你保證，他們絕對比我更加盡責，更加專業，而且他們還是團隊行動。這樣的話，他們一定有辦法控制這裏的感染，癒合它所留下的創口。如果你就這麼一個人衝進去，估計你在走到那棵巨樹的樹幹之前，就已經被狂暴的樹人們羣毆致死了——而且，你每在這裏繼續待下去，就會不斷產生新的樹人。除非你是馬基·埃亞爾的英雄，或者是加庫爾本人降世，否則你簡直就是自尋死路。還是讓專業人士來幹這事吧。

如果你不聽我的話堅持要進去的話，那麼，我來告訴你我知道的事情：

——不幸的是，那些樹人現在已經完全失去了分辨敵我的能力。他們把一切不來源於自然的東西都視作潛在的感染源，只有把你們完全消滅乾淨，他們纔會安心入睡。我知道，在這裏說一堆“請”字是絕對沒法讓你放棄自衛的念頭的……不過，請你還是儘量把你所造成的破壞降低到最低限度，這樣的話他們還有機會治癒這片飽受摧殘的土地。如果你想要避免和它們交戰，請你儘快離開地面，爬到大樹的樹冠上去。因爲它們只會在看到周圍地上有東西的時候纔會活動起來。另外，[b]不要[/b]試圖拿走它們的核心！請相信我——雖然我也很想知道這種感染到底擴散到了多麼深的地方；到底是已經侵入了樹幹，還是正在被推到樹冠的地方。只要你一把那東西拿出來，周圍的樹人就會跟永恆精靈看到幹蠢事的機會一樣，爭先恐後地圍過來。

——目前看來，造成了這種破壞的罪魁禍首，是一羣會動的奧術水晶，有記載說它們曾經在閃光洞穴中出現過。它們到底是在什麼樣的狀況下如何形成的，目前我們尚不知曉。但是我們有理由推斷，它們與魔法大爆炸中所涌出的大量的枯萎能量息息相關。這向我們證明，即使到了現在，魔法大爆炸的破壞仍然比我們想象中的要更加嚴重。如果你沒有高超的躲避技巧，請做好被各種強大魔法輪番轟炸的準備；不過，幸運的是，儘管他們可以經常進行傳送，但是他們在傳送的間隔中無法移動。因此，如果有一個奧術水晶傳送到了你的身邊，建議你要麼找個掩體躲起來，要麼就在它再次傳送之前趕緊幹掉它。

——如果我們再不採取行動的話，後果將會是不堪設想的。儘管這棵巨樹的形成本身就是這顆星球試着對抗這種感染，將感染推出自己的身體的舉措。但這些水晶化身仍然可以輕鬆地從樹冠上爬下，埋入土中，再一次讓埃亞爾陷入疾病。如果埃亞爾輸了的話……儘管我不想這麼說，但恐怕只能說，那些老不死的永恆精靈縱火狂，大概還能做一些他們生命中爲數不多的對社會有益的事情，把這塊地方掘地三尺，化爲一片廢土。當然，這還要建立在他們能夠想到一個不需要炸掉太陽的解決方案的前提之上。

祝你好運，感謝你能幫我做到這些我做不到的事情。我不能親自冒這樣的險，也是有自己的苦衷的，但你乾脆直接把我當成一個懦夫好了，這對我們兩個人都比較好。反正，這和真實的情況區別也不大。

無上感激，
（如果我是一個十足的白癡，我就會在這裏寫下我的名字）

另：如果你不介意幫我做一些小事的話，請幫我銷燬掉你所找到的所有文本。那些紙是在我匆忙逃跑的時候從我的包裏掉出來的。我已經是一個懦夫了，可不想再成爲一個亂丟垃圾的人。]], "_t")
t("a pamphlet 'Eyal Needs You!'", "一本小冊子 《埃亞爾需要你！》", "_t")
t([[EYAL NEEDS YOU!

The damage left in the Scintillating Caverns, in Norgos' Lair, and in countless other places has only now become clear, after the Hero of Maj'Eyal made them safe to explore once more.  Now that peace has been brought to these lands, Eyal is beginning to heal - but with the arrival of our magic-using cousins from the East and the Allied Kingdoms' growing acceptance of magic, the balance may once more tip towards ruin - but YOUR help can keep Eyal healthy!  Join the Menders, and start helping the planet today!

LEARNING AND OBSERVING

Our founders, once Guardians of Shatur, have always known the importance of maintaining a balanced ecosystem.  Do your hobbies include birdwatching, exploring the wilderness, and taking in the sights of natural flora?  We can provide you with a list of animals, plants, and fungi of interest; simply go out and write down where you explored, when, and how many of these species you saw.  Our experienced naturalists can use this information to track migration patterns and monitor the spread or decline of those species, allowing us to take action if one becomes endangered or invasive; already, they're working to restore the balance disrupted by the Hero of Maj'Eyal's constant slaying of local wildlife.  Change is inherent to the natural order; our experts know to only step in if a change would drastically and destructively hurt the ecosystem.  Nature solves most of its problems on its own, but occasionally we may need to hold its hand (particularly in response to mutations caused by unchecked use of arcane magic).  If you'd like to learn more about the natural order, we have a diverse community of knowledgeable naturalists who are happy to answer questions or provide a more thorough education.

REPAIRING AND HEALING

Volunteers who prefer a more hands-on approach can expect to start making a difference right away, by joining our reclamation and decontamination efforts.  It's no secret that the Hero of Maj'Eyal's many battles took their unfortunate toll; many places are still littered with magic-contaminated objects or bodies, and in some places the ground itself has been polluted by the residual effects of these spells.  (This is, of course, to say nothing of the trees burned down, etc. by beasts and ne'er-do-wells trying to stop the Hero!)  You can help by destroying dangerously magical objects, planting trees, slaying ecologically-disruptive beasts (such as Norgos), and participating in cleansing rituals to speed up the healing process.

ABILITY, RESPONSIBILITY, AND ACCEPTANCE

The wilds of Eyal are a dangerous place; we do not expect our scholars to go into them defenseless!  For those who are already accustomed to use of the arcane, our partnership with the Living Fossils allows us to identify safe and responsible methods of using magic, and provide them with an introduction to the ways of Nature, and those who are already adept with Nature can always hone their skills with our veteran members.  If you have no ability with either, you're in luck!  We're eager to show you how to accept Nature's favors to defend yourself.  Anyone can learn to summon loyal beasts or channel wyrmic strength if they're willing to try!  These abilities can be used without giving up your attunement to the arcane, but you may find that you don't need your spells anymore, once you've seen how effective Nature's power is.  We will never force you to give up magic, but if you happen to be looking for a greater commitment, speak to your instructor about following the path of the oozemancer.
]], [[ [b]埃亞爾需要你！[/b]

在馬基·埃亞爾的英雄掃清了閃光洞穴、諾爾格斯巢穴、和世界各處數不清的場所，讓人們可以在那些安全的地方探索之後，人們終於開始正視魔法大爆炸對那裏所造成的傷害。儘管這些地方現在已經變得和平，埃亞爾正在逐漸恢復——但是，由於我們那些使用魔法的東部同胞的到來，以及聯合王國越來越接受奧術魔法使用的影響，自然和魔法之間的平衡被漸漸破壞，世界瀕臨毀滅的邊緣——但是，[b]你的[/b]幫助可以讓埃亞爾保持健康！請加入修復者，從今天開始，幫助這顆星球吧！

[b]學習與觀察[/b]

我們的創始人曾是夏特爾的一名守護者，他一直深切瞭解有關維持一個平衡的生態系統的重要性。你喜歡觀鳥，探索大自然，欣賞多姿多彩的植物嗎？我們可以向你提供一系列有關各種奇珍異獸、以及奇特的植物和真菌的列表。只要你在四處探索，記錄下各種觀察到的生物的分佈和數量。我們那些富有經驗的自然學家可以使用這些信息來追蹤這些生物遷徙的模式，觀察它們的擴散和消亡。這樣，如果有一種生物瀕臨滅絕或受到入侵，我們就可以立即採取行動。現在，我們正在修復那些因爲馬基·埃亞爾的英雄對自然生物的殺戮，而遭到破壞的各地脆弱的生態平衡。改變是自然重要的組成部分，因此我們的專家只會在生態系統面臨毀滅性嚴重威脅的時候，纔會選擇介入。大自然能夠自己解決它大部分的問題，但有時，我們也需要親自向大自然伸出援手，例如應對那些因爲不恰當的奧術魔法使用造成的變異物種。如果你想要更多瞭解大自然的秩序和平衡，我們有一個多元化的，知識淵博的自然學家羣體。他們十分樂意回答你的各種問題，乃至向你提供深入的教育。

[b]修復與治療[/b]

對於那些更加喜歡親自動手的志願者，你們可以加入我們的修復和淨化事業，立刻給這個世界帶來改變。馬基·埃亞爾的英雄的衆多戰鬥也帶來了許多不幸的損失，這並不是一個祕密。許多地方到處了被魔法污染的物件和屍體，還有些地方的土地仍然被殘留的魔法所污染。當然，更不用說，還有那些野獸和不負責任的蠢貨試圖阻止英雄的時候，被他們燒燬的森林！你可以通過摧毀危險的魔法物品，重新種植樹木，殺死那些破壞生態的野獸（比如諾爾格斯）以及參加我們的淨化儀式，來加快這個世界癒合的進程。

[b]能力、責任與認可[/b]

埃亞爾的野外是一個危險的場所；我們可不希望我們的學者手無寸鐵地走進荒野！對於那些已經習慣於使用奧術魔法的人，我們和那些活化石的合作，讓我們可以辨別出正確和理性的使用魔法的做法，並向你們展示自然之道的基礎。對於那些已經精通自然力量的人，你們可以和我們的老成員之間相互切磋，磨練技巧。如果你兩者都不瞭解的話，那麼你就走運了！我們十分樂意向你展示如何使用自然的力量來保護自己。只要你願意嘗試，每個人都有機會掌握召喚忠誠野獸的能力，或是引導巨龍的力量！這些能力在你不放棄奧術魔法的情況下，也可以盡情使用。但是我想，當你見到大自然的力量是多麼有效而強大的時候，你就再也不想使用你過去使用的那些魔法了。我們絕不會強迫你放棄魔法，但是，如果你想要追求更多獻身於自然事業的話，也可以和我們的導師交談，我們向你介紹軟泥使的力量。]], "_t")
t("'On Tolerance'", "《有關容忍》", "_t")
t([[We recognize that times are changing.  Within a year, the Allied Kingdoms have gone from begrudgingly tolerating magic to openly embracing it, due to the influence of our rediscovered allies in the East.  Furthermore, if the reports are to be believed, the ecosystem of Var'Eyal remains healthy and intact, despite millennia of continuous magic-use.  Therefore, our views and approach must change with the times; we are not ignorant to new knowledge.

At this point, it should go without saying that reckless use of magic is a dire threat to...  everything, more or less.  Eyal has yet to fully recover from even the rampant necromancy of the Age of Dusk, let alone the Spellblaze itself.  Eliminating all use of magic is the only way to be safe from this situation repeating...  but it is possible that lesser uses of arcane magic do not have any inherent corrupting or harmful effect, judging from the Sun Paladins and Anorithil.  They have, contrary to our long-held beliefs, managed to use magic responsibly and safely.  We are not so blind as to deny that this is an incredible reassurance.  That said, this proves nothing about the most terrible potential of magic.  Maybe no Sun Paladin or Anorithil has yet sunk to the depths of depravity of the Age of Dusk sorcerers, or the tragically reckless mages responsible for the Spellblaze, but that is no indication that their magic does not have the potential for abuse.  

Fortunately, there is an alternative available!  With the proper respect, care, and concentration given to Nature, one can be rewarded with powers rivaling or besting the popular uses of magic.  On the civilian level, summoned fireflies can replace magical lighting, regeneration salves can replace healing spells, and accelerated crop growth makes for a far more nutritious diet than conjured foodstuffs.  For martial purposes, there's very little that can stand up to the powers of Nature.  An experienced disciple of Eyal can summon loyal beasts faster than any mage can blast them, crush spellswords of all types with draconic might, or dissolve a necromancer's army in a tide of corrosive ooze.  And if the disciple in question is familiar with the practices of the Ziguranth...  We do not condone their approach to defending nature, but their techniques speak for themselves when facing a hostile mage.  The best part about these abilities, though, is that they are self-limiting!  There is no potential for a runaway chain reaction, or a lone megalomaniac destroying much of Eyal.  The planet willingly gives us its power, and is conscious enough to take it away if we start abusing its gifts.  Even the most powerful of Wilders cannot abuse their power to the perverse degree that a necromancer can.

Thus, we're putting our efforts into two areas.  The first is advocacy of Natural alternatives to magic, talking to spellcasters to determine what they use magic for and figuring out ways to use Nature's abilities to do the same task just as well (if not more so).  We've continued the Ziguranth efforts to make all-natural replacements for Ogric runes (we predict that life expectancy is now only reduced by 40% with our newest mixtures), developed fertilizing recipes that outperform arcane methods of producing food, created wells near desert settlements otherwise dependent on water magic, and developed so many other techniques and applications that make magic just as obsolete as it is hazardous.  The second is minimizing the harm done by the arcane, by educating spellcasters on the safe, responsible, and Nature-conscious use of magic.  Not every spellcaster is evil, and in fact, some may enrich the lives of those around them!  Runic magic is at least somewhat self-limiting, and we are working with the Living Fossils guild in hopes of developing a new type of magic, one inherently linked to and limited by Nature.  Their stone-wardens have maintained perfect harmony with Nature despite constant use of the arcane; if this is truly the way forward, then we shall welcome it with open arms.
]], [[我們必須承認，現在世道變了。在不到一年的時間裏，在東方重新發現的那些盟友的影響之下，聯合王國已經開始從不情願地容忍魔法，迅速轉變爲公開接受魔法的使用。此外，如果那些報導確認屬實的話，儘管在那裏的人們長期使用魔法長達幾千年，瓦·埃亞爾的生態系統仍然健康而完整。因此，我們絕不能對新知識一無所知，我們的觀點和方法必須隨着時代而改變。

在這種情況下，某種意義上，我們必須拋棄過去那種，認爲魯莽的使用魔法是對……世間一切的最大威脅的觀點了。黃昏紀裏死靈魔法的猖獗使用，對埃亞爾所造成的影響至今還沒有恢復，更不用說魔法大爆炸的影響了。消除所有魔法的使用，看起來是避免這種狀況重演的唯一方法……但是，從太陽騎士和星月術士的情況來看，少量使用奧術魔法，本身並不會對世界帶來任何腐蝕和有害的影響。與我們長期以來的信念相反，他們成功地，安全而負責任地控制了魔法的使用。我們絕不能盲目地否認，這對我們是一種難以置信的安慰。儘管如此，這並不否認，魔法仍然可能造成極其可怕的後果。可以說，太陽騎士和星月術士，遠遠沒有墮落到黃昏紀法師那樣邪惡的程度過，也並不像那些引發魔法大爆炸的法師一樣，魯莽到可悲。但是這並不能表明，他們的魔法沒有遭到濫用的可能性。

幸運的是，我們還有另一種選擇！只要給予大自然足夠的尊重，關心和專注，人們就可以獲得和普遍應用的魔法匹敵，乃至更強的力量。在民用領域，召喚螢火蟲可以替代魔法燈籠，治療藥劑可以替代治療魔法，而加速穀物成熟的技術做出來的菜餚，可比法師製作的魔法食品對身體健康多了。在軍用領域，很少有人能夠抵擋自然強大的力量。那些埃亞爾忠實的學徒，可以比法師的火球速度更快地召喚忠誠的獸羣，用巨龍的力量粉碎各種類型的魔法劍，或是用一股腐蝕性的粘液，瞬間融解死靈法師的軍團。另外，如果那些學徒還了解那些伊格蘭斯曾經使用過的力量的話……我們不能容忍他們爲了保衛自然做出的一系列舉措，但他們的技術在面對敵對法師的時候，總是能夠脫穎而出。有關這些自然能力，最重要的一點是，它們是會進行自我約束的！他們絕對不會像奧術魔法一樣，引發一場失控的連鎖反應，在妄自尊大的狂妄中給埃亞爾大部分的地方帶來毀滅。這顆星球自願給予了我們力量，當我們開始濫用它們的時候，它就會有意識的從我們的身邊拿走。即使是最強大的野性系能力者，也不會像死靈法師一樣，把他們的力量濫用到如此反常的程度。

因此，我們目前的事業有兩個主要的目標。第一個目標是推廣使用自然力量代替法術的方法。我們要和那些法師交談，知道他們用魔法來做什麼，然後想辦法用自然的力量來達成同樣的目標，乃至做的更好。我們繼續伊格蘭斯把食人魔的符文替換成純天然產品的努力（現在，使用我們的新技術，預計只會減少40%的壽命），發展新的肥料技術，讓它們遠遠超出使用奧術力量生產食物的方法，還有在沙漠地區創造水井，讓那些地方不再只能依靠水魔法。我們創造了各種各樣其他使用自然力量的技術與應用，讓過去那些使用魔法的方法看上去既落後又危險。第二個目標是最大限度地減少奧術魔法造成的危害，我們會教育法師，如何安全地、負責任地、有保護自然的意識地去使用魔法。並不是每個法師都是邪惡的，他們中的許多人，都可以給他們身邊人的生活帶來好處！符文魔法就是某種意義上有自我限制能力的魔法，我們也在和那個活化石組織合作，希望能夠開發出一種新的魔法，一種和自然聯結，受自然約束的魔法。那些岩石守衛就是這樣的例子，他們經常使用奧術力量，卻仍然和自然之間保持着完美的平和。如果這就是我們前進的道路，我們將張開雙臂歡迎它。]], "_t")
t("a leaf-bound journal", "一本被樹葉包裹的筆記", "_t")
t([[[i](You see here a leaf-bound journal; the moment you open it, it begins to wither and crumble.  You manage to rip out one page; it is still disintegrating, but slowly enough that you can read it before it turns to dust.)[/i]

Another vandalized poster.  Calling us traitors, collaborators, declaring themselves the True Ziguranth.  Fools, the lot of them.

When I established the Menders, it wasn't because I thought the arrival of a handful of magic-users who also happen to be decent people disproved anything taught in Zigur or my childhood in Shatur.  It wasn't because I suddenly forgot that anything derived from arcane magic, no matter whether or not it's wrapped up in some mumbo-jumbo about the heavens, carries the risk of mutating into something that could put the Spellblaze to shame.  It was because those maniacs had ignored the shifting political tides for so long that they found themselves sliding into irrelevance, then went and skipped directly over irrelevance into pariahdom with that foolhardy assassination attempt.  They can blame the Far East all they want, but that was only the last nail in the coffin, alongside widespread acceptance of runes and alchemists operating openly across the continent.

I can appreciate their dedication.  I can appreciate their frustration, and how seeing the world treating magic-use as normal would just make them want to get more violent - but the fact is, the raid on Zigur was a mercy kill, preventing the fanatics from making us look even worse in the public eye.  We are long past the point where intimidation can get us anywhere - so we need to try a new approach.  If reminding the world of the horrors of magic isn't working anymore, the Spellblaze and the Age of Dusk being too faded from public memory, then we need to remind them of the wonders of Nature instead, wonders they can see for themselves, today.  If the public won't believe that magic is evil, they can believe that Nature is better.  If we can't make magic taboo, we can make magic obsolete...  and all of this gathers support we'd otherwise lack, curious minds waiting to be taught the beauty of Nature and warned of the hazards of the arcane.

So maybe the old guard's been overrun with Thaloren, youths, and others who care a great deal more about loving nature than hating magic.  I don't see why this is a problem - making Nature stronger will make it more capable of resisting the damage magic may inflict.  We've allowed the idea of supporting Nature over magic to survive the Allied Kingdoms' treaty with the Gates of Morning, the raid on Zigur, and the attacks on Ziguranth patrols.  We've established ourselves as a selfless, charitable organization working for the good of all, a reputation that will grant us significantly more credibility than our previous public image of a band of crazed fanatics.

Perhaps most meaningfully of all, there are [i]far[/i] more Menders now than there were Ziguranth in the last century.  These allies will help us support Nature to an incredible degree, and we've started offering volunteer courses in classical anti-magic training, allowing them to further refine our techniques for dealing with rogue mages.  If and when arcane magic causes another catastrophe, these allies will rally behind us as we defend Nature from those who threaten it...  And, who knows, maybe we actually CAN teach mages to show a sane level of restraint without wiping them all out.  I'm keeping my eyes open for ways to make that happen, no matter how unlikely they may be.

In the meantime, paying off Stone Warden trainers and buying enough mindstars and herbal infusions for our initiates isn't cheap.  I'm not proud of what I'm doing to pay the bills, and am fully aware of what it'd do to the organization if someone saw me, but this is the fastest and easiest money I've ever made.  Ten minutes of concentration, a few hours to re-establish my equilibrium, and I can grow enough cheerblossom to cover our expenses for a week.]], [[[i](你看到了一本被書頁包裹的筆記；當你打開他的時候，他就開始慢慢枯萎，碎裂。你努力撕下了一頁，它仍然在慢慢分解，但是分解的速度慢到你能夠讀完，才最終化成了塵土。)[/i]

又有一張海報被他們毀壞了。他們稱我們爲叛徒、通敵者，宣稱自己纔是真正的伊格蘭斯。他們這羣傻瓜。

我建立修復者的理由，並不是因爲那些碰巧上是好人的魔法使用者的到來，就能顛覆我過去在夏特爾和伊格的時候所受到的一切教育。這也不是因爲我已經遺忘了，任何從奧術魔法之中產生的力量，不管是否被他們包裹在有關天空的一系列繁文縟節裏，仍然有着被人扭曲，產生比魔法大爆炸更加可怕的災難的危險性。這一切都是因爲，那羣瘋子一直以來都無視着政治潮流中發生的巨大轉變，不知道自己已經變成了無關緊要的局外人。然後，他們那場莽撞的暗殺行動，徹底讓他們的地位從局外人成爲了賤民。他們儘管可以把他們所遭受的不幸都歸咎於遠東的人，但這只是他們棺材板上的最後一顆釘子而已，而沒有意識到早在更早之前，符文已經在這片大地上廣泛使用，鍊金術師在各處公開營業了。

我很欣賞他們的奉獻精神。我也很能理解他們的挫敗感，他們看到，這個世界越來越將魔法的使用看做稀鬆平常的事，而變得越來越暴力——但是，實際上，伊格被摧毀對我們來說可以說是一種安樂死，這避免了那些狂熱分子進一步在公衆面前破壞我們的形象。我們早就應該知道，光靠暴力威懾是不能解決一切問題的——因此，我們必須嘗試一種新的辦法。既然黃昏紀和魔法大爆炸這樣的過去，早就已經在公衆的視野之中淡忘。過去警告世人魔法的恐怖的方法，已經不再能夠起到作用。那麼，我們應該改爲向他們展示自然力量所創造的奇蹟，不同於他們今天所看到的奇蹟。既然公衆已經不相信魔法是邪惡的了，我們應該向他們展現，自然是更好的。如果我們不能讓魔法成爲禁忌，我們可以讓魔法成爲一種過時的技術……而這一切可以吸引無數我們過去所忽視的支持者，我們將可以在他們充滿好奇心的心靈中展現自然的美好，並警告奧術魔法帶來的恐怖。

所以，那些過去的守護者，現在已經被自然精靈，年輕人，還有更多比起對魔法的痛恨，更關心對自然的熱愛的人所代替。我不認爲這裏有什麼問題——讓自然的勢力更加強大，才能抵擋魔法所造成的傷害。我們高舉着“自然勝過魔法”的旗號，從聯合王國與晨曦之門的條約、對伊格的襲擊，以及對伊格蘭斯巡邏隊的搜捕中倖存下來。我們建立了一個無私的慈善組織，爲所有人的利益而工作。這一聲譽，比起過去一羣狂熱的極端分子的公衆形象，在大衆面前更加可信地多。

另外，最重要的是，我們招募的修復者的數量，已經[i]遠遠超過[/i]伊格蘭斯一個世紀裏招募的成員的數量。這些盟友對我們在保護自然事業上的支持達到了一個難以相信的程度。我們已經開始了向他們提供傳統的反魔法訓練的志願課程，讓他們進一步錘鍊自己對抗遊蕩法師的能力。如果奧術魔法造成了另一次災難，這些盟友將會追隨我們成爲我們保護自然免受威脅的堅強後盾……另外，誰知道呢，也許我們[b]真的可以[/b]教會那些法師，學會一點理性的剋制，而不需要把他們全部殺光。我會一直尋求實現這種目標的方法，不管它的可能性有多麼渺茫。

與此同時，支付岩石守衛訓練師的工資，以及給我們的新成員購買足夠的靈晶和自然紋身的價格可不便宜。我知道我支付賬目的方法不太光彩，我也知道如果被人看到這事，我的組織會受到多麼壞的影響，但是這是我能找到的賺錢最快最容易的方法了。只要十分鐘的專注，再花上幾個小時來恢復我的失衡值，我種出的鼓舞之花就足夠支付我們一個禮拜的開銷了。]], "_t")

------------------------------------------------
section "tome-orcs/data/lore/quarry.lua"

t("steam quarry", "蒸汽採石場", "newLore category")
t("a very old journal (1)", "非常古老的日誌 (1)", "_t")
t([[This is a matter most vexing.  Our digging was going well (if not particularly productively), and those fellows over in Geothermal Surveying told us they'd found a possible heat source, quite near an existing tunnel - but the miners started refusing to go there.  Copious complaints about assorted lesser maladies - nosebleeds, tremors, and general feelings of fear and unease.  On the other hand, a couple claim the vapors down there have done wonders for their clogged pores.

Firing one as an example didn't work, and I have neither the time nor the inclination to get a bunch of layabouts to do their jobs.  I'm bringing in a yeti handler and excavating the whole area.]], [[這是最令人煩惱的事情。我們的挖掘工作進行的很順利，可以說十分卓有成效。那些進行地熱勘測的同事告訴我們，他們找到了一個潛在的熱源，就在一個現有的隧道附近——但是礦工們都拒絕去那裏，他們都抱怨自己得了各種小病——流鼻血、哆嗦、還有各種各樣恐懼和不安造成的感覺。不過，還有一對夫婦說那裏的蒸汽治好了他們多年的排氣孔堵塞的毛病。

光靠解僱他們來殺雞儆猴是沒有用的，我既沒有時間也沒有意願讓這羣懶鬼好好幹完他們的工作。我準備叫來一個雪人操縱師，讓他們完成開採任務。]], "_t")
t("a very old journal (2)", "非常古老的日誌 (2)", "_t")
t([[Now I've had to fire a yeti handler as well.  The other workers tell me that the yetis would clutch their heads and hurl themselves into the chasm after no more than a few minutes of work in the promising area; we tried replacing the yetis, but then the handler developed a nosebleed as well, and then refused to do more work.

And this incompetent fool was using a psychic controller!  I would expect this performance from a child attempting it free-hand, but a trained and properly equipped professional should be able to command an entire team of yetis!

I've filed a request for a special order, along with one for the handler's license to be torn up and cast into the chasm.  It's time for drastic measures.]], [[現在我把雪人操縱師也開除了。其他工人告訴我們，那些雪人在工作區域內沒呆幾分鐘，就開始猛抓自己的頭，最後跳入了深淵。我們想要換一個雪人，但是那個操縱師也開始流鼻血了，他拒絕繼續幹下去。

這個無能的傻瓜居然還帶着一個精神控制儀！我還以爲這樣糟糕的表現是一個小孩空手乾的呢，要知道一個訓練有素，裝備精良的專業人士，起碼有能力操控一整隊的雪人！

我已經申請了一道特別的命令，還要申請把那個操縱師的執照撕個粉碎，扔到深淵裏面。現在是採取嚴厲措施的時候了。]], "_t")
t("a very old journal (3)", "非常古老的日誌 (3)", "_t")
t([[I don't like automatons.  Machines that operate by themselves, with no personal input...  why, they don't require any skill or ability to operate!  You need only rely on what someone else has done by inventing it!  Mark my words, our dependence on these things will be the death of us, making us weak in body and mind...  but I must admit, they have gotten the job done.  Only a few days after we brought in these arachnoid contraptions, they excavated enough of the offending cavern (and presumably purged enough of whatever pollutant was down there) that living workers are once again willing to work in the nearby areas.  I don't care if it was superstition or what, because we're going to make quota for this month - those caves had a lot of vents to work with!

Still not sure why the Council confiscated the cargo from the third machine we sent down there, but whatever.  Those uppity do-nothings can keep the gold or jewels or whatever was in there.
]], [[我不喜歡自動化。那些機器居然可以自己行動，不需要人的干涉……爲什麼，這根本不需要任何操縱的技巧和能力！你只需要依賴那些發明它的人所做的事情就可以了！說實話，過分依賴這種東西肯定會給我們帶來末日，這會讓我們的身體和精神都變得虛弱……但我必須承認，它們確實完成了任務。在我們帶回來這些機械蜘蛛之後，沒過幾天，它們就開鑿完成了那個有問題的洞穴。看來它清理掉了裏面藏着的不知道是什麼污染物的東西，現在工人們又重新願意在這裏幹活了。我纔不在乎這是不是迷信，因爲我們還要完成這個月的任務呢——這些洞穴裏有着這麼多我們所需要的地熱口！

我現在也不知道，爲什麼議會要沒收掉我們送到這裏的第三臺機器所挖掘出的東西，但是管他呢。不管裏面是什麼黃金珠寶，就讓那些高高在上的廢物拿去玩吧。]], "_t")

------------------------------------------------
section "tome-orcs/data/lore/slumbering-caves.lua"

t("slumbering caves", "沉睡洞穴", "newLore category")
t("a journal (1)", "一份日誌 (1)", "_t")
t("O #CRIMSON#AMAKTHEL#LAST#!  Rightful ruler of all touched by the sun's light or the core's warmth!  In the era of gods, You innovated when others remained stagnant.  The others were content to work with the same mold - a head, thin skin, a jointed endoskeleton - but You, You had scores of ideas, and even the common threads between them were testaments to flexibility, invention, and adaptability!  The others struggled with stiff, fragile limbs, an easily obstructed windpipe, and one huge mass of vulnerabilities above their torso; You found this form wanting, and proved Your place as the supreme deity by continuing to improve on it.  You gave us arms and legs we could twist into any useful shape we could dream of, and instead of dreadfully fragile eyes and throats, we can see, eat, and breathe through our skin, skin laden with neurons rather than one centralized brain.  Even today, even when unconscious and dismembered, You continue to invent, Your Magic of Creativity tweaking the other gods' creations to see what results.  You are not merely a god of light - You are a god of enlightenment, and all who create owe it to You.", "啊，#CRIMSON#阿馬克泰爾#LAST#！你是陽光普照的大地之上，被地熱所溫暖的世界深處的一切的崇高主宰！在諸神的紀元中，你在其他人停滯不前之時開啓了偉大的創新。其他諸神滿足於同樣的模板——一種由一個頭，薄薄的皮膚，有關節的內骨骼組成的結構——但是你，你有着偉大的創意和想象，你無數的創造的唯一共同點，就是對靈活性，創造性和適應性無盡的追求！當其他的造物受困於僵硬脆弱的四肢，容易堵塞的氣管和軀幹上方巨大的脆弱部位的時候，你這位至高的神仍然在不斷地改進這我們的身軀來證明自己的才華。你給我們創造的四肢可以扭曲成我們想要的任何有用的形狀。我們沒有眼睛和喉嚨這樣致命的弱點，可以使用我們的皮膚來看見，進食和呼吸，我們也沒有集中的大腦，而是分佈在皮膚之中的神經元。即使在今天，即使你已經被肢解，失去意識，你仍然在繼續着創造，你創造的魔法不斷調整和改進着其他神祇的創造。你不僅是光明之神——你是啓蒙之神，所有的造物者都受到了你的啓迪。", "_t")
t("a journal (2)", "一份日誌 (2)", "_t")
t([[Great #CRIMSON#AMAKTHEL#LAST#, forgive me, for I could not prevent the actions of my brethren.  I tried.  We tried.  When they spoke of committing the Great Sin, we argued ferociously, until Caldizar and his apostates did it before we could react in time.  We did our best to avenge this foul deed, and used the Magic of Creativity on as many as we could, blessing them with new forms, and blessing ourselves such that we could do battle with their fortresses; alas, it was nonetheless a war we eventually lost, for what chance did we have against weaponry, power, and mercilessness to which even You fell?  Please, Your Brilliance, understand that we did everything we could.  

Our planet lay in ruins, with even the apostates abandoning Eyal for other worlds.  Every one of Your followers fought to our deaths...  except me, coward that I was in those days.  Now, I am all that remains, along with the apostates we blessed with Your magic.  I will not beg for Your forgiveness; as an inventor You are concerned with results over words, and I will prove to You that my moment of weakness will soon have a wondrous result.  With the sinful apostates gone, You will have the time to secure this world for Yourself, purging the creations of the lesser gods...  and preparing to exact justice on the sinners when they return.  
]], [[偉大的#CRIMSON#阿馬克泰爾#LAST#，請原諒我，我沒能阻止我的同胞犯下的惡行。我盡力了。我們盡力了。當它們提出那項沉重的罪行的時候，我們激烈反抗，然而凱爾帝勒的那些背教者黨羽在我們還沒來得及反應之前搶先犯下了滔天大罪。我們盡最大的努力爲他們的惡行復仇，將我們掌握的創造魔法使用到了最大的限度，將他們賦予新的形態，也轉化了我們自己，這樣我們才能和他們的堡壘抗衡。儘管如此，我們仍然在這場沒有希望的戰爭中失敗了，我們怎樣才能抗衡他們那連你都無法戰勝的強大武器、火力以及殘忍？請饒恕我們，偉大的神，明白我們已經盡力了。

我們的星球化爲了廢墟，連背教者也離開了埃亞爾，前往了其他世界。你的每一位追隨者都戰鬥到死……只有我，因爲懦弱而存留至今。現在，我們一族只剩下我，還有那些被我們使用你的魔法祝福的背教者們。我沒有臉面請求你的憐憫，你是一位發明者，你關心的是結果而非言辭，我會親自向你證明，我現在的懦弱將會帶來一個美好的結果。那些犯下罪行的背教者已經離開了，你將終於有機會親自奪回這個世界，清除那些劣等神祇的低劣造物……並且準備好對那些罪人實施正義的制裁。
]], "_t")
t("a journal (3)", "一份日誌 (3)", "_t")
t([[The work continues, and soon all shall know the name of their new god.  Even handling the one Hand that I have makes me weep for the sins of my brothers, and yet eager to see their work undone...  The bowels of Eyal shall be the forge in which You will be remade, the newly-drained magma channels above shall be its fire.

I can barely bring myself to tell You the indignity I suffer through in service to You...  Unfit savages, ones not of Your creation and thus undeserving of Your mercy, are in possession of one of the last two pieces of Your body.  I met with the "Atmos," and offered them a tiny fraction of Your approval and power in return for it, far more than enough to make up for the geothermal vents emptied to fuel Your rebirth; they fear Your blessings, and rejected my offer.  They are a proud tribe, one that has been proud for so long that they never noticed that they no longer had anything to be proud of.  I have seen such pride before only once, and it is even more misplaced by the Atmos.  They will remain blind and defiant until the moment they fall, and I shall simply wait to sift through the fragments of their dead civilization.

I am sorry, my god - were I in a better position, Your rebirth would not be contingent on #{italic}#negotiating#{normal}# with the unworthy souls trespassing in Your world...  but I cannot afford the risk of using force.  Perhaps it is some minor consolation that You will now be able to personally show them Your fury.]], [[這項工作還在繼續，不久，所有人都會知道他們新神的名字。當我手中拿着你的手的時候，我爲我弟兄的罪而哭泣，而卻急切地想要見到他們的罪行被恢復…埃亞爾的伸出將會成爲你重新改造這個世界的鍛爐，而那些被排空的岩漿通道將會成爲鍛爐中的烈火。

我簡直無法向您描述，在我爲您效力的時候，受到了怎樣的屈辱……那些低劣的野蠻人，既不是你的造物，也不配得你的憐憫，卻強奪着你的身軀最後的兩塊中的一塊。我和那些“氣之部族”的傢伙見了一面，承諾用你的力量的一小部分換取它，這遠遠超出了離排空埃亞爾的地熱通道來完成你的復活儀式的代價；然而，他們畏懼你的祝福，竟然拒絕了我的提案。他們是一羣驕傲的野蠻人，驕傲了太久，甚至已經忘了自己沒有什麼值得驕傲的東西了。我過去只見過一次這樣的驕傲，就連他們也沒有氣之部族那樣不合時宜。就讓他們繼續盲目地對事態視而不見，直到自取滅亡爲止吧，到那時候，我只需要在他們文明的廢墟中得到那份碎片。

我很抱歉，我的神——如果我還有過去的力量，你的重生的事業，絕不會受到和那些不配進入你的新世界的劣等存在之間的小小#{italic}#談判#{normal}#的干擾……但是，我不能承擔使用武力帶來的風險。將來，你將可以親自向他們展示你的憤怒，希望這樣能構成你的安慰。]], "_t")
t("a journal (4)", "一份日誌 (4)", "_t")
t([[The foolish creations of the lesser gods have simply handed me Your mouth, in return for a few of the apostates' trinkets!  Unearthed by Dwarves, brought from a distant land by Humans, offered to me by Trolls...  None were aware of how they were helping You, so do not spare these humanoids Your wrath.  They deserve cleansing as much as the Giants, Elves, and other creatures from the lesser gods, creatures that still refuse Your blessing.

The Giants are beginning to falter, as the creations of the pettier gods inevitably do.  As amusing as it would have been to watch them demonstrate their inferiority by tearing at each others' throats, the Orcs have brought them ruin and pushed them to desperation even sooner.  They will reconsider my offer, and then...  ]], [[那些劣等神祇的愚蠢造物，就這樣簡單地把你的嘴交到了我的手上，而它們想要的僅僅是一堆背教者的小玩具！被矮人發現，被人類從遙遠的土地上帶來，被巨魔交到了我的手中……他們中間沒有人知道自己是在幫助你，所以也不要憐惜對這些傢伙釋放你的憤怒。他們和巨人、精靈以及其他劣等神祇的造物，那些仍然拒絕你的祝福的生物，只配得到徹底的清除。

那些巨人開始動搖了，這就是那些弱小神祇的可悲造物不可避免的命運。儘管看着他們互相撕破彼此的喉嚨來戰士自己的可悲和渺小是一件十分有趣的事情，那些獸人卻給他們帶來了直接的毀滅，並加速了他們陷入絕望的進程。他們一定會重新考慮我的提議，然後……]], "_t")
t("a journal (5)", "一份日誌 (5)", "_t")
t([[This is a time of celebration...  The Atmos have brought us a gift.  I no longer require their cooperation as a people; a handful of Blessed guards (including, in poetic irony, some of the former heretics) will suffice to keep the degenerates from disturbing Your return.  It will only be mere days until You are whole again...  You are an artist, and this world shall be Your canvas.  The degenerates will weep first at Your beauty when they behold You, then for the fate of their world, and then when they realize their sins and the fate they deserve.

I will not beg You for redemption or forgiveness.  My species has already proven itself to be a treacherous, prideful mistake.  All I beg for is to live long enough to see Your masterpiece.]], [[這是一個值得慶祝的時刻……氣之部族的人給我們帶來了一份大禮。我們不再需要他們作爲個人的合作；一羣被祝福的守衛（諷刺的是，包括了一些過去的背教者）將會足以阻止那些腐朽者干擾你的迴歸。只需要幾天的時間，你就可以恢復健康……你是一個藝術家，而這個世界就是你的畫板。當那些腐朽者真正親眼看到你的時候，他們首先會爲你的無上美麗哭泣，接下來會爲他們世界的命運哭泣，最後，他們將會爲意識到自己深刻的罪行和所應配的審判命運而哭泣。

我不會乞求你的救贖和寬恕。我們的族人已經向你證明，我們只是一個危險的，驕傲的錯誤。我想你懇求的唯一一樣東西，就是親自見證你傑作的誕生。]], "_t")
t("a journal (6)", "一份日誌 (6)", "_t")
t([[the fragments reform
the visage of genius and beauty is once more
the glory of #CRIMSON#AMAKTHEL#LAST# is nigh
the reckoning of the sinners is nigh
the heretics the apostates the degenerates
#CRIMSON#AMAKTHEL#LAST#'s wrath shall be delectable
against the scum trespassing on His world
against those who refuse His vision
against those #CRIMSON#futile fools#LAST# who try to #CRIMSON#interfere#LAST#

change it, #CRIMSON#AMAKTHEL#LAST#
change all You see to fit Your designs
play with it, alter the degenerates, see what happens, learn from it
the world is but a block of marble, You are the sculptor
and Your vision will be seen on Eyal once more
and #CRIMSON#none shall speak the name %s again#LAST#
it shall not even be granted the dignity of being used as an example

and once this world is Your masterpiece
we will find the heretics together

#{italic}#There are several pages filled with "they will burn" written repeatedly.  You throw them away.  You throw #CRIMSON#yourself away.  You will burn.  You will burn you will burn you will burn you will#LAST##{normal}#

this is the first day of a new existence
#{italic}##CRIMSON#and you are not worthy of seeing its dawn#LAST##{normal}#
]], [[你的碎片已經集結
你智慧和美麗的容貌再次顯現
#CRIMSON#阿馬克泰爾#LAST#的榮光已經降臨
罪人的喪鐘已經敲響
那些背教者、叛徒和腐朽者
#CRIMSON#阿馬克泰爾#LAST#的憤怒將無可抵擋
摧毀一切踏入他美麗世界的渣滓
摧毀一切拒絕他美好願景的蠢材
摧毀一切膽敢#CRIMSON#干涉#LAST#他復活的#CRIMSON#徒勞的傻瓜#LAST#

改變這個世界吧，#CRIMSON#阿馬克泰爾#LAST#
按你心中的景象設計這個世界
玩弄這個世界，改變那些腐朽者，見證那些結果，然後從中學習
這個世界是一塊石材，而你是雕刻者
你的願景將會重新改變整個埃亞爾
#CRIMSON#沒有人將會再次說出%s的名字#LAST#
它甚至不配作爲唾棄的對象而被銘記

當這整個世界成爲你的傑作的時候
我們將親自對背教者發動復仇

#{italic}#接下來的書頁寫滿了“他們將在烈火中燃燒”。你把它們扔了出去。你把#CRIMSON#自己扔了出去。你將在烈火中燃燒。你將在烈火中燃燒 你將在烈火中燃燒 你將在烈火中燃燒 你將在烈火中#LAST##{normal}#

這將會是新紀元的第一日
#{italic}##CRIMSON#而你，不配見到新世界的黎明#LAST##{normal}#
]], "tformat")

------------------------------------------------
section "tome-orcs/data/lore/sunwall.lua"

t("sunwall", "太陽堡壘", "newLore category")
t("a page from Commander Trelle's journal", "指揮官特瑞爾日記的一頁", "_t")
t([[We've done it... we've finally done it. Well, granted, our %s did much of the work, but the result is the same: neither the East nor the West will ever need to fear Orcish rule again. The Prides have been crushed, the survivors have been contained, and our patrols are mopping up the few remaining bands of futile stragglers. Our long-lost allies from the West have come to support us with materials and manpower, and we can finally turn this entire continent into something beautiful. For the first time, Sunwall will not be the solitary bastion of civilization on Var'Eyal.

And yet...

There is one group that remains.  A tiny Orcish pride, really more of a small town, managed to evade our savior's wrath...  a single weed on the edges of our pristine garden, a troubling ember threatening to set the whole continent aflame.  King Tolak has noble aims in trying to set a better example than his vengeful father, but I doubt he'd risk redeeming the Orcs if he'd been through what we have.  The Allied Kingdoms don't know what it's like to live in fear of the Prides, knowing that at any moment they could overrun the Sunwall and take our heads as trophies.  They've got a farportal to hide behind, and don't have to think about their homes and families falling to the same horror that we've been struggling against for our entire lives.  If they did...  suffice to say, they wouldn't have bothered putting up a comfortable camp for the surviving Orcs until the continent was truly safe.

By the Sun...  why would our High Paladin agree to this treaty?  After what we've all been through...

The Orcish scouts are getting bolder.  They've been approaching closer before fleeing, and coming more frequently.  They haven't engaged us yet, but it's only a matter of time...  and all I'm allowed to do is sit and wait on this ugly little bridge, as the West watches from a continent away.  Staring at an open wound, waiting for it to become infected, because they'd rather make a pretty little bow out of the bandages.]], [[我們做到了…我們終於做到了。儘管這主要是我們的%s的功勞，但結果是一樣的：無論是東方和西方大陸，都再也不用擔心獸人的威脅了。撕打獸人部落已經被完全粉碎，殘餘的生還者也都被關押了起來，我們的巡邏隊四處掃蕩他們的殘兵敗將。我們等待已久的來自西方的古老盟友終於現身，用大量的材料和人力來幫助我們，我們終於可以開始建設這片美麗的大陸。這是前所未有的勝利：太陽堡壘再也不是是瓦·埃亞爾上文明和希望的唯一堡壘了。

然而，儘管如此…

還有一小撮敵人存留了下來。那是一個小小的獸人部落，只有一個小鎮的大小，卻逃脫了我們救世主的憤怒……他們像是我們美麗花園中的雜草，雖然是星星之火，卻也有可能產生燎原之勢。比起他父親對獸人的嚴酷報復，托拉克國王有着崇高的目的，想要在世人面前樹立一個更好的榜樣。但我對此深表懷疑，如果讓他經歷一下我們這麼多年經歷的苦難，他是否還會甘冒讓獸人捲土重來的風險。聯合王國根本不知道生活在獸人部落的恐懼下的生活是什麼樣的，他們隨時可能把太陽堡壘夷爲平地，把我們的頭顱當做炫耀的獎盃。他們可以安全地躲在傳送門後面，不需要擔心他們家鄉的親人會經歷和我們一樣的恐怖，不知道我們這麼多年來都是在爲我們的生命而戰鬥。如果他們真的體驗一下我們的生活…可以說，在整個大陸完全和平之前，他們絕對不會現在一樣，讓那些該死的獸人戰俘在舒服的拘留營裏吃好喝好的。

以太陽的名義……爲什麼至高太陽騎士要同意這種不平等的條約？我們已經戰鬥了這麼多年了……

獸人的探子越來越接近邊境了。他們每次逃跑回來之後都越來越大膽，來的次數也越來越多了。他們還沒有和我們正式交戰過，但是這也只是時間問題……我什麼也不準做，只能呆呆地等在這裏，看守着這個骯髒的小橋，而那羣西方大陸人還在一個大陸之外安睡着。我們就這樣什麼也不做，呆呆看着被敵人劃開的傷口，靜靜等着它感染化膿，因爲那些人還要在本應包紮的地方系一個可愛的小蝴蝶結呢。]], "tformat")
t("hero", "英雄", "_t")
t("heroine", "女英雄", "_t")
t("a letter addressed to Outpost Leader John", "一封寫給前哨站隊長約翰的信", "_t")
t([[Sir,

The Orcs grow more impudent every day.  Surely you've noticed too - their scouts growing closer, the smoke of their forges drifting over the mountains alongside the clanging of metal being pounded into weaponry, the guttural shouts of their training drills...  Are you really going to obey this suicidal treaty, and keep us from acting until their swords are already through our throats?
If you were to... [i]see[/i] an approaching assault force, I would verify your report. Legally, we would be untouchable for defending ourselves.  Please, ensure that this inevitable conflict is at least one that gives us the tactical advantage of surprise, not them.

-Cmdr. Trelle]], [[閣下，

獸人的舉動一天比一天更加放肆起來了。我想你一定也已經看到了——他們的探子越來越近，他們鍛爐的濃煙飄過山脈，伴隨着鐵匠鍛打武器發出的叮叮之聲，還有他們演習時發出的憤怒戰吼……你真的還要遵循這種自殺性的條約，繼續按兵不動，直到他們的劍穿透你的喉嚨嗎？
如果你能夠…說你[i]看到了[/i]他們的襲擊部隊就行，我一定會替你證明的。按照法條，我們進行自衛是絕對合法的。既然我們都知道這場衝突是不可避免的，請你至少讓我們獲得突襲的戰術優勢，而不是他們。

指揮官特瑞爾]], "_t")
t("a letter addressed to Commander Trelle", "一封寫給指揮官特瑞爾的信", "_t")
t([[Trelle,

I respect your intentions and your dedication to our safety, which is the only reason I'm not handing this letter over to Aeryn right this second.  Do you have the faintest clue what this treaty is buying us?  Do you really think we could have kept the Prides' remnants from banding together and becoming, at a minimum, a massive thorn in our side for the next few decades without King Tolak's help? Even if I disagreed with Aeryn that the Orcs deserve a chance of redemption, this treaty is ensuring an [i]extraordinary[/i] amount of help from a nation that, last year, still tolerated roving gangs of mage-lynchers.

I'll spare you the speech about insubordination, lying, and bypassing the chain of command, because a: technically you were "only" asking me to commit those crimes, and b: I've got better things to do than write up a full-blown reprimand for someone who I'm [i]certain[/i] knows exactly what they're doing wrong.  Instead, I'll cut to the chase: Never even think of pulling something like this again.  I'm saving your letter, and if you're ever involved in a questionable use of force, I'm submitting it as evidence.  I thought you were better than this.

-Outpost Leader John]], [[特瑞爾，

我敬重你的愛國之心和你爲保衛太陽堡壘做出的奉獻，否則，我現在就已經把你的這份信直接交給艾琳女士了。這個條約給我們帶來了什麼，你對此到底有沒有一丁點認識？你難道真的以爲，光靠我們的力量，沒有托拉克國王的幫助，我們可以這麼快掃清四大部落的殘餘，而不是讓它們的殘部捲土重來，至少成爲我們接下來幾十年中的心腹大患嗎？儘管我和艾琳女士在有關獸人是否應該有懺悔的機會上有所分歧，這個條約是我們從聯合王國那裏獲得[i]巨量[/i]援助的最重要的保障。而這個國家，就在去年，還在被一羣流竄的反魔法師極端分子引發的內亂所蹂躪。

我不想和你講有關抗命、撒謊以及不服指揮的廢話。因爲第一，原理上你“只是”在建議我違反軍紀而已；第二，我有更有價值的事情去做，而不是對你這個我[i]完全[/i]知道做錯了什麼的傢伙，寫一篇長篇大論的斥責。相反，我會直截了當的告訴你：再也不要給我弄出來這樣的東西了，想也不要想。我會保留你的信件，如果你敢介入任何不恰當使用武力的行爲，我就會把它作爲證據提交。我相信你會當個聰明人。

-前哨站隊長約翰]], "_t")
t("a large, embossed envelope", "一個大大的，有壓花的信封", "_t")
t([[#{bold}#TO WHOM IT MAY CONCERN:#{normal}#

Whereas, it can be assumed with 100% certainty that the individual reading this note is the most esteemed authority of the group residing on the bridge connecting Var'Eyal and the Clork Peninsula, as the construct trusted to deliver this message cannot be coerced to decode it;
and whereas, our observation balloons tell us that this organization is one of high culture and civilization, one comprised of several different species, and would be open to friendly negotiation;
and whereas, the Orcs have none of the aforementioned qualities, and their continued presence on the Clork Peninsula either directly causes or can lead to countless difficulties and unpleasant situations for both of our groups;
and whereas, cooperation in the immediate future would be beneficial to both of us, as would a longer period of peace between our two cultures;
it is therefore imperative that I, and the rest of our species, introduce ourselves.

I am Chief Councillor Tantalos, and I represent the people of #{bold}#Atmos#{normal}#; the orcs call us "Steam Giants" when not using a slew of impolite pejoratives, and we find the name amusing enough to accept it.  The Clork Peninsula is our land, as we have resided here in peace for many thousands of years, before becoming overrun with these distasteful ruffians.  We have been content to let them roam in the undesirable backwater territories of this peninsula, while we looked down from our rightfully elevated places, but various unfortunate circumstances have forced our hand.

We have invented technology #{bold}#far#{normal}# more impressive than yours, or that of any of the remaining miniature races.  Our plebeian citizens are accustomed to luxurious appliances which even your king lacks; our military has abominable weaponry which puts an untrained commoner on even footing with a skilled archer, and lets a moderately experienced marksman kill with range and precision that all but the most powerful archmages would be envious of.  Our people are strong, stronger than any of yours even on a per-pound basis, let alone the advantages of towering over you child-like creatures.  We have countless valuable natural resources, and our many, talented artisans will quickly become accustomed to making smaller garments, jewelry, and bottles of fine spirits for export (among many other high-quality goods).  It should be clear that your diminutive people have much to gain from us; all we wish, for the time being, is for the Clork Peninsula to remain #{bold}#our#{normal}# land, and perhaps that you may grant us some martial or material assistance in #{italic}#addressing#{normal}# the Orcish inconvenience.

We should meet, and discuss this in more detail, or I can arrange to let you borrow an artifact that will allow us to communicate.  Please give your reply to this construct post-haste.

Regards,
#{italic}#-Tantalos#{normal}#]], [[#{bold}#致有關人士:#{normal}#
運送這份信件的機械裝置無法被強制解碼，因此，我們可以100%地確定，閱讀這份信的你，將會是管理連接瓦·埃亞爾和克拉克半島橋樑的團體的最高領袖。
與此同時，根據我們的觀察氣球得到的結果，這個組織具有發達的文化和高度的文明，由多個不同的種族組成，並且可以和我們進行友好談判；
並且，那些獸人沒有之前提到的任何品質，他們在克拉克半島上的持續存在，存在直接導致或間接造成我們兩個羣體的無數困難和不愉快的情況；
鑑於此，在不久的將來進行合作，實現我們兩種文明之間的長期和平，對我們雙方都有利；
因而，謹在此代表我和我的種族，向你們進行自我介紹。

我是首席議員坦塔羅斯，我代表#{bold}#氣之部族#{normal}#的人民；獸人在不使用一連串不禮貌的貶義詞的時候，將我們叫做蒸汽巨人，而我們覺得這個名字很有趣而接受了它。克拉克半島是我們的領土，在這些可惡的暴徒闖入之前，我們早就在這裏和平地生活了幾千年。我們曾經滿足於讓他們在半島上不受歡迎的落後地區四處遊蕩，而我們居住在高處俯瞰他們，但是，一系列不幸的事件，讓我們不得不出手。

我們有着#{bold}#遠勝#{normal}#你們的技術，比其他任何種族都要令人印象深刻。我們的普通百姓，有着比你們國王更加豪華的器具。我們的軍隊有着可怕的軍備，可以讓沒有經過訓練的普通人與最精銳的弓箭手比肩，而經驗豐富的射手有着匹敵最強大的大法師的射程和精度。我們的人民是強大的，即使是計算力量和體重的比例，也比你們任何人都要強壯，跟不用說我們高聳的身軀和你們戰鬥就像對待小孩一樣。我們的國內物產豐盈，無所不有，大量的精工巧匠，善於製造服飾、珠寶和最優質的白酒，以及大量其他出口產品。可以說，你們這些矮小的人可以從我們這裏得到無數的好處；我們唯一的訴求，就是希望克拉克半島繼續是#{bold}#我們自己#{normal}#的領土，並且，如果你們考慮到#{italic}#解決#{normal}#獸人問題的迫切性，就給我們一點物質和軍事的援助吧。

我們應該親自見面，更詳細地討論這個問題。我也可以借給你一件讓我們遠程交流的神器。請儘快回覆這份信。

此致,
#{italic}#-坦塔洛斯#{normal}#]], "_t")
t([[Well.  Turns out this peninsula's also home to an entire civilization of giants lurking in the mountains.  If we weren't so short on troops, my scouts would all be fired.  I appear to have accidentally deceived this construct into mistaking me for Aeryn, John, and King Tolak all at once, and while I am obligated to pass this letter on to them...  on further discussion with this Chief Councilor Tantalos, we have both realized that we can wait to inform them, as this presents an opportunity that neither of us can afford to waste.

Now, officially, both we and the Allied Kingdoms have a policy of capturing the remaining Orcs and taking them to the internment camp rather than killing them (when possible), which would require a far more decisive advantage than this outpost has.  Officially, we are to stay right where we are, containing the potential threat of the Kruk Pride rather than moving into their territory before they can amass their forces.  Officially, it would be forbidden for us to do anything about this problem until it's too late.  But...

#{italic}#Officially,#{normal}# the Atmos don't exist, and we have no knowledge of them whatsoever.  Officially, if a couple of Allied Kingdoms supply ships headed for the internment camp #{italic}#just happened#{normal}# to be waylaid by a hired band of pirates who #{italic}#got lucky#{normal}# and struck them just between their naval patrol routes, it'd be #{italic}#such a shame,#{normal}# and the Atmos couldn't be blamed if that armor and weaponry found itself in their hands.  Officially, we are not to leave our post under any circumstances, and if a mysterious band of giants descended from the mountains, crushed the Kruk Pride in their homeland, and forced them to flee, it would be against our orders to do anything about it, aside from eliminate any refugees who flee to our bridge; officially, this wouldn't impede the Atmos' negotiations with the Allied Kingdoms and Sunwall after this incident, because they couldn't have known we'd pursue a goal as naive as waiting to take the Orcs alive, and would grant them an uncontested claim to Kruk territory.

Unofficially?  I'm going to #{italic}#enjoy#{normal}# this.]], [[好吧。看來這麼長時間都沒人發現，這個半島裏還居住着一個在山中隱居的巨人文明。如果不是因爲我們實在是兵源不足，真想讓這些廢物哨兵統統滾蛋。好吧，看來無意間，這個奇怪的機器把我當成了約翰隊長、艾琳女士和國王托拉克……雖然原理上我大概有義務把這封信交給他們，不過，在和首席議員坦塔洛斯單獨探討過一次之後，我們都意識到，現在沒有時間去通知他們了，擺在我們面前的就是一個不應該被浪費的天賜良機。

現在，從官方立場上，我們和聯合王國都應該儘可能把抓到的獸人送進拘留營，而不能直接殺掉他們，這對我們這座前哨站的防守十分不利。官方的說法是，我們需要保持現狀，繼續坐視克魯克部族不斷增長的威脅，而不能夠搶在他們集結兵力之前進攻他們的領地。按照官方的做法，我們什麼都做不了，直到一切都爲時已晚。但是……

#{italic}#官方地說，#{normal}#，既然我們之前根本就沒有人發現他們，氣之部族是不存在的。官方來說，如果一艘前往拘留營的聯合王國的補給船，#{italic}#不幸#{normal}#被一羣僱傭兵海盜攔下了，而它們#{italic}#正好#{normal}#避開了海軍的巡邏路線，那真的只能說是#{italic}#太遺憾了#{normal}#。如果他們運送的武器和裝備正好跑到了氣之部族的手裏，那也沒有什麼奇怪的。按照官方說法，我們從來沒有離開我們的前哨站一步，只有一羣傳說中的巨人從山中出現，摧毀了克魯克部族的家園，讓他們被迫逃離。畢竟，我們什麼也沒有幹，最多隻是自衛地幹掉那些衝向這座橋的難民而已。官方立場上，這場事件不會妨礙氣之部族日後和聯合王國和太陽堡壘的談判，他們肯定不知道，我們居然還曾經有過想要活捉那些獸人的天真到可笑的計劃，而且我們還幫助他們捍衛了對克魯克部族領地無可爭辯的主權。

非官方說法？我想我會#{italic}#好好享受#{normal}#這一切的。]], "_t")
t("a torn page from John's journal", "約翰日記上的一頁", "_t")
t("Aeryn, my love...  I fear Trelle may be right, but I will hold this bridge without resorting to betraying you.  Still, though, I will remain vigilant of approaching attacks, and prepare to strike first if a battle really does seem inevitable.  As long as I stand, no Orc will ever harm you again.  We will have a bright and shining future ahead of us, walking hand in hand into the dawn of a new, peaceful age...  and while I hope the Kruk Pride has a place there, I will not let them put this new age in jeopardy.", "艾琳，我的愛人…我開始擔心，特瑞爾說的可能是對的，但我會堅守這座橋，絕不會背叛你的信賴。儘管如此，我還是會對即將到來的襲擊充滿警惕，如果這場戰爭真的不可避免，我也會準備先發制人。只要我還在這裏，我絕對不會讓任何獸人傷害你。我們會共同開啓一個光明璀璨的未來，攜起手，走向一個和平的新時代的黎明……儘管我也希望克魯克部族也能成爲這樣的新時代的一份子，但是，我絕不會容許他們把這樣的新世界置於危險之中。", "_t")
t("King Tolak's Condemnation", "托拉克國王的宣戰書", "_t")
t([[(As you approach the farportal, a herald emerges, holding an envelope; he doesn't quite hand it to you as much as throw it at you from a safe distance, then salutes and retreats back into the swirling rift.  The letter bears the royal seal of the Allied Kingdoms.)

%s...  I think I'm beginning to understand why you have acted this way.  At first, I was...  well, not as much surprised as disappointed.  I'd thought that showing your people mercy was the right decision.  That my father had been too consumed by rage, that the Orcs could be truly be better people if we gave them a chance, and if you were shown how much of a better place Eyal could be if you were to cooperate with us.  That no matter what my father, my mother, and my allies had told me, the Orcish race contained, somewhere deep down, the same potential for learning, growth, and beauty present in Humans, Halflings, Elves, Dwarves, and Ogres.

But now...  I see no good in you.  So many are dead, because I couldn't bring myself to admit that some people are beyond redemption.  Because I thought all you needed was a second chance, that you had goals other than blind, bloody revenge, that you'd see that we had held you in the grip of our absolute mercy, and opted to offer you an open hand rather than crush you as easily as clenching our fist.

I will not make the same mistake again.

You've shown me that the Orcish heart is empty of everything but lust for death and destruction, that no matter how good a future is laid out in front of you, you will discard it simply for the thrill of battle against the reasonable people who want this better future to come.  You've shown me that the prejudices I've strived to transcend were right all along.  You've shown me that my father's only mistake was not going far enough - a continent free of Orcs is not enough to keep us safe.  Instead, your kind must be purged from all of Eyal - and the battle to make this happen is inevitable, for you will continue pushing for it no matter how much we try to make peace an option.  And yet...  you've made me understand the reason of this approach, of treating everyone else like an irrational threat to your existence, for it is the only proper way for us to treat you.

You won't get another second chance from us.  Instead, we'll give you the only thing you've ever wanted: a battle.  Through this portal waits the army of the Allied Kingdoms, once foes or begrudging co-inhabitants who have grown into true allies because we have a desire for peace and cooperation that your kind will never know.  We wait on an open battlefield, ready to demonstrate our combined might.  The Shaloren of Elvala prepare spells as the Ogres grip their clubs tighter; the Halflings and Humans of Derth and Last Hope have forgotten their age-old rivalry, working together to brew alchemical bombs and build great golems, or take up positions with a bow or sling; the Dwarves of Iron Throne and the Thaloren of Shatur, not even proper allies with us before now, realize you are too great a threat to go neglected, and now our ranks are lined with Wilders summoning countless beasts and treants, and fierce warriors who will #{italic}#not#{normal}# be moved.  Even the forces of the Sunwall have joined us, a contingent of their finest warriors sent to reinforce our lines and quickly train our soldiers in the magical techniques they've honed over the years, using you irredeemable savages as their sharpening stones.

I shall be waiting in the front line of this glorious alliance, sword in hand.  I, King Tolak the Fair, son of Toknor who once purged your people from Maj'Eyal, I who once fought to spare your kind from slavery or extinction, now eagerly await the opportunity to finish what he started.  If I die, Toknor's bloodline dies with me; this is a risk I am willing - no, #{italic}#excited#{normal}# to take, to settle the fate of all civilized peoples of Eyal, once and for all.

You want your revenge on my father's people, foul cur?  #{italic}#Come and get it.#{normal}#

(You admit, it is rather tempting...  but the guaranteed safety of your people takes priority, and besides, you wouldn't put it past the Allied Kingdoms to have a team of archers and slingers waiting to snipe everyone who came through, one by one.  You destroy the portal, eliminating King Tolak's army as a threat, and ensuring Sun Paladin Aeryn won't be getting any reinforcements.  Time to take advantage of your newfound privacy, and finish off the Sunwall forces, once and for all...)]], [[當你走近遠古傳送門，前面走來了一位傳令官，他的手中拿着信封；他沒有把信直接交給你，而是從稍遠一點的距離朝你扔了過來，然後敬禮，退回了傳送門的漩渦之中。信件上蓋着聯合王國的皇家印章。)

%s……我想，我開始明白，你們爲什麼會要這麼做了。一開始，我……說實話，比起驚訝我更多的失望。我以爲向你的人民展示慈悲是一個正確的選擇。我的父親曾經被仇恨吞噬，而我以前相信，給你們獸人一個機會，你們會成爲更好的人。如果你願意與我們合作，我們可以共同把埃亞爾變成一個更加美好的世界。不管我的父母，我的盟國曾經告訴我們什麼樣的東西，我相信，獸人種族的心中，深深埋藏着一種潛能，和我們人類、半身人、精靈、矮人和食人魔一樣，可以學習、成長，變得更加美好。

但是現在看來……你們的身上沒有任何一點優點。因爲我過去相信，像你們這樣的人沒有任何救贖和悔改的可能，這麼多人獻出了生命。我曾經以爲，我們可以再給你一個機會。只要我們用絕對的仁慈對待你們，向你伸出友誼之手，而不是握拳輕輕把你們碾碎。你們就會向我們展示，除了盲目血腥的復仇之外，你們還有着更加美好的目標。

我再也不會犯同樣的錯誤了。

你們清楚地向我展現，獸人的鐵石心腸中什麼也沒有，只有對死亡和毀滅的無盡慾望。無論把多麼美好的未來擺在你們的面前，你們都會毫不在意地捨棄，只爲了屠戮那些希望這種美好未來成真的真誠理性的人。你告訴我們，我曾經試圖克服的，加在你們身上的偏見，都是正確的。你告訴我，我父親的唯一錯誤，就是做的還不夠——只把你們獸人從一個大陸上掃除還遠遠不夠。現在，你們的種族會從埃亞爾上滅絕——這場戰爭將會是不可避免的，因爲無論我們多少次提出了和平的提案，你們都對此不屑一顧。直到現在……你讓我明白了了你們行動的理由。既然你們狂躁得把其他所有人都當做對你們生存的威脅，那唯一合理的方法就是用同樣的態度對待你們。

你們已經沒有任何機會了。現在，我要給你們一件你們最嚮往的禮物：戰爭。在這座傳送門外，是聯合王國的雄兵。他們曾經因爲仇恨和嫉妒而相互攻擊，現在卻結成了牢不可破的聯盟。因爲我們知道和平與合作的重要性，而你們這種卑劣的種族永遠不會明白這件事。我們會在一片開闊的戰場上等待你們，向你們展示我們團結的力量。埃爾瓦拉的永恆精靈準備了強大的法術，食人魔們高舉他們的棍棒。來自德斯和最後的希望的半身人和人類也在場，他們千年的仇恨早已彌合，團結一致，手持弓箭和投石索，帶領着高大的傀儡和鍊金炸彈。鋼鐵王座的矮人和夏特爾的自然精靈，他們過去甚至不是我們的盟友，但是現在，他們知道了你們巨大的威脅之後，決心再也不會置身事外。我們的隊伍中有着呼喚獸羣的自然之力強大召喚師，和意志#{italic}#絕不#{normal}#動搖的熱誠的展示。太陽堡壘的戰士們也加入了我們。他們派出了一支精銳的戰士來強化我們的戰士，訓練我們戰士使用他們鑽研多年的魔法技能，你們這些愚頑不化的野獸，將會成爲我們王者之師的磨刀石。

我會親自出現在我們光榮聯盟的前線手持利劍，御駕親征。我，公正之王托拉克，是清除了馬基埃亞爾的獸人一族的獅心王圖庫納王之子。我曾經四處奔走，希望救你們的種族免遭奴役和滅絕，現在，我只希望完成我父親未竟的使命。如果我光榮戰死，圖庫納的光榮血脈就將在這裏終結，這就是我所甘願承受的賭注——不，#{italic}#萬分期待#{normal}#的賭注，我所賭的將會是埃亞爾所有文明種族的命運，一勞永逸地將其解決。

你想要對我父親的人民復仇，對吧，卑劣的雜種？#{italic}#來啊，有種來戰啊！#{normal}#

（你承認，這是一個十分有誘惑力的提議……但是，考慮到你的族人的安全是首要的。你可不像貿然進入這樣的圈套，門後是無數瞄準目標的聯合王國的弓箭手和投石者，正準備逐個狙擊從傳送門裏冒出來的每一個人。你摧毀了傳送門，確保托拉克的軍隊不會成爲你的威脅，也確保太陽騎士艾琳不再能夠得到來自西方大陸的援助。現在，是時候利用這個短暫的機會，一勞永逸地解決掉太陽堡壘的部隊了）]], "tformat")
t("Sun Paladin report", "太陽騎士的報告", "_t")
t([[Lady Aeryn,

My apologies, but you're going to have to go back to King Tolak empty-handed - we still don't have any idea how the smugglers are getting through.  The best evidence we've got is some rumbling in the desert near the Dominion Port (which is still too heavily guarded for a direct attack before the Allied Kingdoms can grant us full assistance), suggesting geomantic tunnel formation, but that could just as easily be the few of Briagh's spawn that the Hero of Maj'Eyal didn't mop up.  Scrying spells aren't helping either - there's some sort of counter-scrying ward being applied, but it's so well-hidden that we can't tell where on the continent it's coming from or how many entities are being affected by it.  The only thing that seems certain is that they've got another farportal hacked together - the only one we know of is right in the middle of Gates of Morning, and I'd like to think that we're not so incompetent we wouldn't notice a steady stream of slavers and bootleggers strolling past 70% of us.  If they're actually using that one, then they're using the best invisibility spell we have ever seen.

...Haven't ever seen?  Whatever.

Anyway, my advice is to request permission to send a few Shining Inquisitors to King Tolak to assist in the investigations on his end.  However they're evading detection here in the East, they either can't use it in the West or simply let their guard down once they're back home, judging from the rising arrest rates - we can help the Allied Kingdoms hit the weak link of this chain, and have the Inquisitors keep an eye on things in Maj'Eyal while they're at it.  Not that I don't trust that King Tolak intends to honor his commitment to keep those foul Ziguranth from ever pulling off anything like the Sunset Massacre again, but...  well, if a farportal altar made it onto the black market under the Allied Kingdoms' watch, possibly courtesy of a mad alchemist who lived practically next door to the King, I don't have too much faith in their ability to drag a bunch of clandestine fanatics into the light, out from the cover of that supposedly-benign Menders group.  I'm sure they're trying their hardest; all I'm suggesting is that we do the same.]], [[艾琳女士，

我很抱歉，但我們恐怕只能空着手去見托拉克過忘了——有關那些走私販子到底是怎麼從我們眼皮子底下過去的，我們現在對此還是一頭霧水。我們現在的唯一證據，就是有關巨魔帝國港口一帶沙漠中發出的轟隆隆的聲音，恐怕有人在地下修築隧道。他們防守森嚴，沒有聯合王國的幫助，我們恐怕不能獨立攻擊那裏。但是，也有可能這只是一羣還沒有被來自馬基埃亞爾的英雄消滅的，布萊亞族羣沙龍的活動導致的。即使使用探測魔法，我們仍然一無所獲——一定是有人佈置了某種反探測的魔杖，但是它們被藏得很好。我們根本不知道這種東西藏在廣闊大陸的那些角落，以及有多少東西受到了它們的影響。我們可以唯一確認的是，它們大概是想辦法啓動了另一個遠古傳送門——我們唯一知道的一個就是晨曦之門的遠古傳送門，但我想我們的守衛也不至於無能到沒有注意到有奴隸販子和走私販子在我們的城市裏面晃悠，繞過了我們70%的兵力。如果真的有這樣的事的話，那麼只能說，它們大概用了我們所見過的最強力的隱身魔法。

……或許，既然是隱身魔法，應該改成說“所還沒見過的最強力的隱身魔法”？算了，管他呢。

不管怎麼樣，我建議向國王托拉克提議，向他那裏送出幾位日光裁判官，在他那邊協助執行調查任務。不管這些傢伙在東方大陸怎樣逃避我們的偵查，他們大概沒法在西方大陸這麼做，或者因爲回到了自己大陸而過於輕敵。正因如此，他們更容易在那裏被抓到——我們可以幫助聯合王國打擊他們鏈條上最弱的一環，然後他們逃回馬基·埃亞爾之後，讓留在西方大陸的裁判官收拾他們。我並非不相信託拉克國王會信守他的承諾，盡全力阻止那些卑劣的伊格蘭斯，避免再度引發日落大屠殺這樣的慘劇，但是……好吧，就在聯合王國的眼皮底子下，一個遠古傳送門祭壇出現在了黑市上，而這一切恐怕都歸功於住在國王隔壁的一個半瘋的鍊金術師……我實在是不相信，他們有能力撕下那羣帶着自稱“修復者”的組織佯裝“溫和”的假面具，揭露那羣藏身其中的狂熱恐怖分子的真面目。我想，既然那羣傢伙絕對是動真格的，而我們也必須全力以赴。]], "_t")
t("journal of High Sun Paladin Aeryn", "至高太陽騎士艾琳的日記", "_t")
t([[This is it...  the day I've dreaded for most of my life is here, and yet it still comes as a shock.  I expected it for almost every day of my life...  until last year.  The Scourge from the West defeated the Prides, raced down the Charred Scar, and stormed the tower of High Peak to fight by my side against a threat far greater than I dreamed possible.  We'd been reunited with a cooperative and nearly-unified Maj'Eyal, led by a king willing and able to help us in any way, armed with a plan to keep the orcs completely under control...  it's as if the Sun had begun to creep over the horizon to start the dawn of peace in Var'Eyal, right before going dark forever and taking the moons with it.  The love of my life is presumed dead; the candle in the night of the years before has been snuffed out. Nothing - no plan that hasn't been shattered, no inspiration that hasn't fallen, no hope that hasn't turned to despair - is left to guide me.

I must be that light for my allies' sake.  I must be strong, resolute, giving them whatever tiny amounts of hope I can.  Not only to keep their morale up and give us a chance of prevailing against the unstoppable menace which the Sunwall has stood against for ages...  but so that their last thoughts in death might be that their sacrifice has saved us all.  Maybe one of them will be right.

All I can hope is that King Tolak has learned something about the Orcs, before his kingdom falls as well.  I do not begrudge him, everything he did was rooted in wisdom and kindness...  and would have worked for any species but the Orcs.  They are the sole exception that deserves no mercy.]], [[這一切……發生在我面前的一切，是我在一生中都在恐懼的場景，但這一切仍然讓我無比震驚。過去的幾乎每一日，我都以爲這一切很快就要到來……但直到去年，事情出現了變化。來自西方大陸的英雄，擊敗了四大獸人部落，隻身勇探灼燒之痕，攻上巔峯之塔，與我一同與和我過去遠遠無法想象強大的敵人並肩作戰，並親自擊敗了他們，這一切都是我做夢也沒有想到的場景。我們終於和我們失去已久的盟友團聚，那是由一位慷慨善良的國王領導的，一個和平而統一的馬基埃亞爾。他們願意全力幫助我們，指定了一個讓獸人的威脅始終在我們控制之下的計劃……回想起來，這一切就好像太陽緩緩從地平線上升起，彷彿要給瓦·埃亞爾帶來和平的曙光，但緊接着，永恆的黑暗降臨，就連最後閃爍的月光也被黑暗籠罩。我的愛人恐怕已經死了；曾經在我生命的黑暗中照耀多年的點點燭光，就這樣熄滅在無盡的黑夜中。什麼都沒有了——所有過去的計劃都被踐踏了，所有過去的夢想都化爲了泡影，所有過去照耀的希望，現在都變成了絕望——已經沒有誰能指引我了。

爲了我的戰友，我必須成爲他們希望的光芒。我必須振作起來，堅強，堅定，將我所有的任何一點微小的希望，一同分享給他們。這不僅是爲了保持他們的士氣。太陽堡壘獨自對抗着這種無法抵擋的恐怖威脅，已經堅持屹立了數個世紀，這是我們勝利的最後希望和機會……要讓他們相信，他們臨死之前的最後的願望，是希望他們的犧牲能夠拯救我們所有人。我無比希望，至少有一個人的努力是沒有白費的。

我唯一希望的是，在他自己的國家也走向毀滅之前，托拉克國王能夠從獸人的身上吸取一點教訓。我並不準備苛責他，他所做的一切都深切的紮根於他的智慧和仁慈……對一切其他種族來說，他做的都沒有錯。但獸人是一個唯一的例外，他們不配得到我們的任何仁慈。]], "_t")
t("kindness", "善意", "_t")
t([[I stuck up for you. I wanted to forgive you, to give you time and safety to see we meant no harm.  I forgave you for the ages we spent in fear, the lives we lost, for I imagined I could have been tempted to do the same in your position.

Now I see where kindness and mercy get me.]], [[我曾爲你挺身而出。我曾經那麼多次原諒你，想給你更多時間，想給你想要的安全感，讓你證明你不是那樣充滿惡意。我曾經原諒你讓我們生活在恐懼中幾個世紀的痛苦，原諒在你們屠刀下逝去的無數生命，因爲我曾經以爲，如果把我放在你的位置上，我也有可能會做出同樣的選擇。

現在看吧，看看我的善意和仁慈給我換來了什麼。]], "_t")
t("hope", "希望", "_t")
t([[You took everything from me.  You took the dawn of a beautiful future, you took the fires of hope and happiness, you took the kind, guiding light of my love Aeryn and put out the glow of the life we deserved to have together.  The light is gone...  but you have given me darkness in return.  And you're about to know that darkness very, very well.  Embracing it fully rather than shutting it out...  It's so easy to use these powers now.  I've felt them before, but I had no hate to use as their inspiration, no true misery to pour into the minds deserving, no empty void inside me to drain your hopes and confidence into.  You've fixed that for me.

My heart still beats, but you have taken my life nonetheless.  You'll understand shortly.]], [[你奪走了我的一切。你奪走了美好未來的曙光，你奪走了希望和幸福的火花，你奪走了我愛人艾琳身上善良的指引之光，熄滅了這份我們應得的美好的生命之光。光芒熄滅了……而你還給我們的，則是無盡的黑暗。現在，該由你來親身體會一下這份黑暗了。請你好好享受一下，我們所經歷的一切吧……我過去曾經感受到過這種力量，但我沒有這樣徹骨的仇恨來作爲它的燃料，沒有切身的痛苦親自注入靈魂之中，沒有那份我胸中無限的虛空，足以熄滅一切希望和渴求。現在，我可以輕鬆地使用這種力量了。是你親自糾正了我。

我的心臟還在跳動，但你已經奪走了我生命的一切。你很快就會嚐到這一切的感受的。]], "_t")
t("suffering", "痛苦", "_t")
t([[Fall.  Suffer.  Lose the hope that drives you, or whatever brutish instinct suffices for it in your abominable mind.  Feel the pain you caused me, and know that it will never, ever stop...  you can feel it eroding your will to keep going, can't you?

When your shattered mind succumbs to the pain you gave me, I will take it for my own.  I'll give you back just a little of the hope and love I took, so when you're a mere passenger in your own body, I can watch that light grow dark, as you watch your own body finding everyone you love and killing them slowly and painfully.  Their last words will be cursing your name, and you will be both powerless to stop it, and all too aware that it's your own fault for not preventing it sooner.

Then, and only then, will you fully understand what you did to me.]], [[沉淪吧。痛苦吧。失去一切驅使你的希望，包括你可憎心靈的一切野蠻的本能吧。請好好感受一下你給我帶來的痛苦，直到這一切的痛苦都永遠，永遠不會停止……你能感受到，這正在一點點侵蝕着你繼續前進的意志，對吧？

我會看着你的心靈一點點被你所給予我的痛苦摧垮，然後將其掌握在我的手中。我會稍微返還給你一點點我所奪走的希望與愛，讓你成爲困在你軀殼中的無力的囚徒。這樣，我就可以親自看着你的心靈的光芒一點點熄滅，你殘留的軀殼，將會親眼看着你所珍惜的人，被我緩慢而痛苦地親手殺死。他們最後的遺言，將會是絕望詛咒你的名字，而你只能無能爲力地看着這一切發生，無法阻止，知道這都是因爲你的過錯，因爲你沒能早點阻止這一切的發生。

這樣，只有經過這樣，你纔會真正明白，你對我所做的一切對我意味着什麼。]], "_t")

------------------------------------------------
section "tome-orcs/data/lore/weissi.lua"

t("lost city", "失落之城", "newLore category")
t("telepathic message (1)", "心靈傳訊 (1)", "_t")
t([[As you descend the stairway down, you find yourself faced with what appears to be a solid wall of stone, a natural dead-end in a cave.  You start to turn around and walk back up, when you hear a crescendo of cracking and rumbling behind you; you turn back and see the stone falling away, revealing a smooth, white door, which promptly slides into the floor.  The doorway leads to a white hallway of indeterminate construction; rather than having fixed lighting, every square inch of the walls, floors, and ceiling slowly illuminates to a comfortable (if slightly teal-tinged) glow.  It should be beautiful, clean, peaceful, and serene...  and yet your instincts are screaming at you to get out as soon as you can and forget what you've seen here.  A few open panels on the walls reveal an assortment of inscrutable machinery, incorporating a variety of unidentifiable magical and psionic artifacts, yet one appears to be a sort of crushing device made with steam-tech, an invention that is surely newer than these ruins...  the crushing device abruptly activates when you ponder it, pressing minerals into a freshly-formed mindstar-like crystal.  A voice, one that should be soothing but disturbs you on a deeper level than you can translate into conscious thought, enters your mind as the crystal flickers:

"Welcome, %s.  We've been expecting you.  Unfortunately, we can't join you, but we can assure you that what lies ahead can only help you in your quests.  The door will seal behind you to ensure your safety, and reopen the moment you want to leave.  Come.  Learn, discover, and realize how our plans are advantageous to both of us."

Well...  that isn't terribly reassuring.  You hesitantly step forward, expecting a trap and ready to turn around and bolt at a moment's notice--

The floor disappears from under you, and yet after falling only an inch, you suddenly feel weightless.  You turn; the freshly-formed mindstar, already beginning to crack, is glowing intensely.  "We know that isn't terribly reassuring.  We don't care if you WERE expecting a trap, and if we truly wanted to kill you, bolting at a moment's notice wouldn't be fast enough.  In fact, it'd be very easy indeed."  You are abruptly thrown near the bottom of the pit towards a series of spikes by telekinetic force, then stop, held motionless inches above them.  "Clearly, we don't want you dead or even slightly harmed," the voice from inside your head says, as the spikes retract into the pit floor and you slowly levitate back into the illuminated halls.  "Now that we've established that...  let us help you."  You float to the top, and find yourself standing on solid ground as the floor rematerializes under you and the telekinetic force vanishes, moments before the mindstar shatters.

Nonetheless, you feel you shouldn't be here.  The fact that this place exists at all feels...  wrong.
]], [[你拾階而下，發現自己面前是一堵堅實的石牆，看上去是洞穴到了盡頭。你開始轉頭往上走，突然聽到身後逐漸增強的破裂聲和隆隆聲；你轉身，發現石頭脫落了，眼前出現一個光滑的白色門，迅速地滑入地板。門通向一個建築風格難以識別的白色大堂；這裏沒有照明的燈具，每一寸牆、地板和天花板都緩慢由暗到亮地發光，直到光照變成了令人舒適的青綠色爲止。這裏的景象的確是美麗、潔淨、平和而靜謐的……然而你的本能在向你尖叫，讓你從這離開，越快越好，然後忘掉你在這看過的東西。牆上有幾個露出的操作板顯示出這裏有不少令人難以理解的機器，裝有好幾種難以分辨的魔法和靈能古物，不過有一個看上去是蒸汽科技做成的粉碎設備，比其他遠古遺蹟絕對要新的多……當你對着它深思時，粉碎設備突然啓動了，把礦物壓成一塊新的靈晶般的水晶。在水晶開始閃爍時，有個聲音進入了你的心靈，有着舒緩的語調，但令你在思維的深處感到不安，卻也無法有意識地說出到底是什麼原因：

“歡迎你，%s。我們一直在等你。不幸的是，我們不能與你同行，但我們可以保證你前方的事物只會幫助你完成你的任務。後面的門會封上以保證你的安全，在你想離開時打開。來吧。學習，探索，發覺並意識到，我們的計劃對雙方都有利。”

嗯……這看上去並不怎麼可靠。你猶豫地往前走了一步，準備好應對一個陷阱，並準備好立即轉頭溜走————

你腳下的地板消失了，雖然僅僅落下了一英寸，你突然感到失重了。你回頭；那個剛形成的靈晶，已經開始碎裂了，發出着強烈的光。“我們知道自己並不怎麼可靠。我們不在乎你之前覺得會有陷阱，而且我們如果真想殺你，即使頃刻間溜走也不夠快。事實上，殺你很簡單。”你突然被心靈制動能力扔往坑底，到了一塊尖刺上方，停了下來，懸在尖刺上方几英寸。“顯然，我們不想讓你死，甚至不想讓你傷到一點皮毛，”頭腦裏的聲音說道，同時尖刺收縮起來，你被緩緩擡升到被點亮的大堂裏。“現在我們的關係確立了……讓我們來幫你吧。”你浮到頂，地板重新物質化，心靈制動力消失，你發現自己又站在堅實的地面上，片刻，靈晶破碎了。

儘管如此，你覺得自己不該在這裏。這個地方存在的事實總覺得是……錯誤的。
]], "tformat")
t("telepathic message (2)", "心靈傳訊 (2)", "_t")
t([[Did you know the Sher'Tul had brothers?  Long before their creation, when the gods were still young and gleeful, Quekjora convinced them they could work together to bring life to Eyal. Perhaps they could have, were they more mature at the time...  Eager cooperation withered under exposure to personal tastes and creative differences, the friendships of our creators turned to animosity, and yet we were still made.
 
We had no overt flaws.  The gods were mercilessly vigilant, eager to use any imperfections as an excuse to berate their perpetrator and claim superiority, and thus we were only allowed to live when they were out of ammunition to use.  We seemed perfect, even to a deep inspection...
 
I doubt any of them deliberately cursed us - no one of them could've done something so powerful.  Subconscious touches, psychic leakage, and other such imperceptible forces added up over time to indicate one inescapable truth: we were not wanted.  We had been forged in a bitter compromise, one desired by nobody involved; their hatred, their neglect, their frustration is the foundation of everything we are, and we carry it deep within ourselves.  Perhaps such a creature naturally attracts the ire of the universe, of fate itself. 

Or maybe we just angered someone powerful enough to put a retroactive temporal curse on us, or it was Amakthel personally ensuring his pet project would have no equals. We may never be certain.  All we know is, something - be it probability, or the universe's combined will, or simply our own bad luck - will not tolerate our existence, nor that of anything like us.
]], [[你知道夏·圖爾人有兄弟嗎？在他們被創造出來之前，當衆神還青春年少又無憂無慮，奎克久拉說服大家來一起合作爲埃亞爾帶來生命。也許他們真的能夠實現這樣的合作，如果他們當時更爲成熟的話……熱忱的合作在個人品味和創意的差異面前衰退了，我們的創造者的友誼變成了敵意，然而我們還是被這樣創造出來了。

我們的身上沒有明顯的缺陷。衆神們無情地警惕着對方，熱心地用造物身上任何的不完美之處來指責其創造者，以顯示自己的優越，直到他們彈盡糧絕，我們才被創造了出來。我們看上去很完美，細細檢查也如此，然而……
 
我們不認爲衆神中有人故意來詛咒我們————沒人能做出如此威力無窮的舉動。潛意識中的觸動，靈能的泄漏，還有其他的無法察覺的力量日積月累，表明了一個無可辯駁的事實：我們是不被需要的存在。我們在一個苦澀的妥協中鑄就，來源於一位神祇的一廂情願；衆神的憎恨，他們的忽略，他們的懊喪是我們存在的基石，我們在自身的存在中也一直傳承下來。也許我們這種生物，命中註定天怒人怨，被命運所詛咒。

或者我們只是激怒了另一位強大的存在，給我們施加了一個有追溯能力的時空詛咒，或者是因爲阿馬克泰爾本人想讓他的寵物工程無可比擬。我們可能永遠都不能確定這件事的原因。我們知道的是，有一種東西————不管是概率，或是宇宙的集體意志，或者僅僅只是我們自己的厄運————永遠不會容許我們，或與我們相似的任何事物存在。
]], "_t")
t("telepathic message (3)", "心靈傳訊 (3)", "_t")
t([[Did you know you killed us? You did, in one potential future, ordering our genocide from atop a steel drake.  In others, it was the Dominion, the Allied Kingdoms, Flamewright Industries, the Zigur-Thaloren Pact, or countless other transient mortal city-states.  We've been torn apart by Gerlyk, and dissected by Angolwen at the direction of Headmistress Argoniel or Chief Genius Tannen (yes, the smug git actually called himself that).  We've been devoured (literally and metaphorically) by the New Conclave under Mother Astelrid, wiped out by a plague engineered by the Grand Corruptor, drowned as the world was flooded by the Naloren, and reduced to ash by the reborn Crimson Dragonbrood.  We've been captured as torture-toys by the Demons and The Master's undead servitors, hunted for magical reagents by the Reknor Confederacy, and kept as adding machines by the Greater Republic of Steam.

You know, you should thank the Scourge from the West.  We certainly do.

In most, it was the Sher'Tul, eliminating their closest competitor, or the Mal'Rokka, taking Eyal for themselves.  In the few where we won every war, a meteor destroyed Eyal instead - a meteor that has now been intercepted by debris, from what you call the Spellblaze.  You're welcome - a contingent of our people kept the Mal'Rokka suppressed for long enough to allow that to happen.  If you want to see an example of how thoroughly existence wants to erase us, just ask them what they know about the "Dust Mages."

We don't advise learning psychic prognostication with such commitment as we did.  To see this many possibilities, to gaze into infinity with such detail without infinity gazing back...  you have to feel it.  Every spear through our hearts, every limb burned off...  and we all did it together, linking our minds to accomplish this, so all of us have suffered through this.  And after all that, we still can't be 100% sure it's accurate, although we've gotten to more 9s after 99.9% than we can actually count.]], [[你知道你曾殺過我們嗎？是的，在某個潛在的未來，你騎在一隻高聳的鋼化巨龍之上，下達滅亡我們的種族的命令。在其它的未來中，是巨魔帝國，是聯合王國，火築工業，伊格-自然精靈聯盟，或者是其他轉瞬即逝的凡間城邦。我們被蓋裏克撕成兩半，在阿格尼爾校長或者是大天才泰恩（是的，那個自鳴得意的蠢貨是這麼叫自己的）的命令下被安格洛文解剖。我們被聖母亞斯特莉的“新孔克雷夫”吞食（既是字面也是比喻意義上的），死於大腐化 者設計的一場瘟疫，當世界被納魯精靈淹沒時溺斃，被重生的赤紅龍族燒成灰燼。我們被惡魔或是大師的死靈僕從們捉來做被折磨的玩具，被瑞庫納聯邦狩獵以獲得魔法原料，並被大蒸汽共和國作爲零件的一部分。

你明白的，你應該感謝西方的災星。我們確實感謝。

在大多數情況下，是夏·圖爾人，消滅了最接近他們的競爭對手，或者是瑪·洛克人，他們把埃亞爾據爲己有。在少數幾個我們贏得每場戰爭的世界線中，一個隕石毀滅了埃亞爾————這個隕石現在被一個碎片攔截，碎片的來源是你們所說的魔法大爆炸。不用感謝我們————我們的一羣族人鎮壓了瑪·洛克人很長時間來防止這件事情發生。如果你想看看現存的一切是如何徹底地想抹除我們，就去問問那些惡魔有關“塵埃法師”的事情吧。

我們不建議像我們這種程度地努力學習心靈預測。要看到如此多的可能性，以如此細緻的目光注視無限，而無限永遠不會回望我們……請你體會一下這一切的感受。每一根刺向我們心臟的長槍，每一條燒掉的肢體……並且，因爲是我們的人把心靈連接到一起來實現這一預測的目標，因此，我們的每個人都親身感受到這極致的痛苦。並且，儘管如此，我們還是沒法100%確定這是準確的，即使在99.9%的小數點之後9的數量已經遠遠超出了我們願意數的範圍。]], "_t")
t("telepathic message (4)", "心靈傳訊 (4)", "_t")
t([[Do you know what would've happened if you hadn't stepped up to defend Kruk Pride?  The Allied Kingdoms could've gone on to keep the entire world under its thumb.  One unified army, marching under one banner, ready to eliminate us when we're reborn...  and that's assuming that a certain greater threat didn't step in first.  We don't want that, and neither do you.

Deception is beneath us; if there's one thing our creation taught us, it's that respect and alliance are unnecessary for cooperation, if there's an immediate common need to be fulfilled.  We've prepared some of this machinery to enhance your abilities, and grant you new knowledge...  it will serve you well in preserving Eyal's immediate existence, and granting the Orcs a land of their own.  A land that'll have to fight to survive, fending off the Dominion, the Allied Kingdoms, the warped Mal'Rokka calling themselves demons, the Naloren remnants...  and I wouldn't want to spoil the fun by saying what other sorts of special guests are arriving.  Don't worry, we won't be giving anyone an unfair advantage; you, and they, would just stab us in the back anyway.

The storm is coming.  It's going to be a bloodbath.  We see no need to be present for it, not until the last man is standing, wounded and exhausted, atop a pile of corpses.  He'll be an easy target.

You could always give up.  Stop fighting.  Let the Allied Kingdoms have Eyal, and be the latest in a long line of factors conspiring to prevent our rebirth.  Sacrifice your people to "save Eyal" from having us on it.  You won't, though, because you have something we'll never have: hope.  Hope that we can be fought off, that our return won't come in your lifetime.  Our predictions aren't 100% accurate anyway; who are we to take that hope from you?
]], [[你知道如果你不加緊保衛克魯克部落會發生什麼嗎？聯合王國會繼續進軍，把整個世界置於它掌中。一個聯合的軍隊，在一面旗幟下前進，隨時準備好在我們重生時消滅我們……這還是在保證一個更大的威脅不先發生的情況下。我們不想那樣，你也不想。

我們確實有所欺騙和隱瞞；如果創造我們的過程教會了我們什麼，那就是隻要有一個迫在眉睫的共同需求，尊重和聯合對於合作來說就是不必要的。我們準備了這個機器的一部分功能來強化你的能力，給你新的知識……它會在你保證埃亞爾的存在，給獸人一片自己的土地中的旅程中充分協助你。需要鬥爭才能在這片土地上生存，在土地上擋開巨魔帝國、聯合王國、管自己叫惡魔的，扭曲的馬·洛克人、納魯精靈的遺族……我也不想掃興地告訴你，將來還會有什麼其他貴賓來拜訪我們。不用擔心，我們不會給任何人不公正的優勢；你，和他們，只會到最後在背後捅我們一刀。

風暴將至。這將會是一場腥風血雨。而我們不需要出現在現場，直到最後一個人屹立在屍山上，傷痕累累、疲倦不堪。到那時，他會是我們的活靶子。

你可以隨時放棄。不用再戰鬥了。讓聯合王國統一埃亞爾，成爲一連串阻礙我們重生的因素上最近的一環。爲了從我們的手裏“拯救埃亞爾”而犧牲你的人民吧。你當然不會這麼做，因爲你有我們永遠不會有的東西：希望。希望我們能被打敗，希望我們的迴歸不會發生在你有生之年。畢竟我們的預測不是100%準確的；我們又怎麼會把你的這份希望拿走呢？
]], "_t")
t("telepathic message (5)", "心靈傳訊 (5)", "_t")
t([[Did you wonder what happened to us?  We wouldn't give fate the satisfaction of killing us through some unlikely coincidence.  We killed ourselves - but not before planting our seeds.

We accomplished a lot before we did, and we wouldn't want to have to accomplish that all over again.  Of course, if we kept that all in one place, our curse would notice it and eradicate it - so we split ourselves and our accomplishments into pieces, and obfuscated them through millenia of evolution and subtle manipulation.  You've probably met one piece of these - the body.  Strong.  Resilient.  Capable of living in any environment.  Rapidly healing.  Eternally youthful.  And very, very easy to assume control of, via psychic transfer, once we decide the time is right...  You're probably considering ordering your Pride to exterminate all the yetis you can.  Go ahead, eliminate all that free labor and see how you fare when the Dominion's using slaves and the Allied Kingdoms have ogres and dwarves.  Once again, it doesn't matter whether or not it's helping us, because it's something you need to survive.

That's only a third of what we could preserve, though.  The next is our mental processing ability, our psionically adept minds, our ability to assess information rapidly and logically analyze it.  You'll never be able to eradicate the Yeeks - believe us, we checked.  They seem to be as blessed as we are cursed, except that we're still doomed if we simply try to hide in them.  Pity, that.  Regardless, their brains and the system they are carrying will continue to exist; they will maintain our Way in our absence.

Lastly, there's our culture.  Our discoveries.  Everything we learned and didn't put into our bodies or brains, we stored with...  another group.  One that expands beyond the stars, one who we've disseminated countless subtly-encoded bits of information to, one with backups in so many places across the universe...  They'll deliver enough of it back home.  The Yeeks will absorb it, and we will be reborn in their minds until they can put us in our superior bodies.

Once the storm comes to Eyal, once the conflict is resolved...  perhaps the tide of hate and malice brought by such a massive war will distract the universe enough to let us combine our pieces and be reborn.  Or perhaps we will be able to do so once the gods are all dead or mad, their anger forgotten or nullified, the curse in turn having no fuel to keep going.  Perhaps the curse is already dying, only perpetuated by the Sher'Tul planetary shield - one that's gradually beginning to fail, cracks forming on it and the Mal'Rokka eagerly prying them wider.

And if not?  Our culture is everywhere.  We can't be completely removed without destroying it all.  Fate has decided we are a tumor to be excised; if we're going to be a tumor, we're now an invasive one.  Now fate can decide if we're a benign growth, or terminally malignant.  

Would you expect anything less from the physical incarnations of spiteful determination?
]], [[你知道我們的結局是什麼嗎？我們不會屈服於命運，讓它在某個偶然的巧合殺死我們中得到滿足。我們殺死了自己————但我們播下了我們的種子。
  
在這之前，我們取得了不少成就，並且我們也不希望這一切都付諸東流。當然，如果我們把那些成就放在一處，我們身上的詛咒會注意到然後消滅掉————所以我們把自己和取得的成就分成幾片，在千年的進化和微妙的操縱中把它們混入這個世界。你也許已經遇到我們的一個碎片了————身體。強壯。適應力強。可在任何環境中生存。有着迅速的恢復力。具有永恆的青春。並且，非常、非常地容易以心靈奪舍的方式來取得控制，當我們認爲時機對的時候，我們就會這麼做……你也許在考慮讓部落去儘可能消滅所有的雪人。去做吧，把所有那些免費勞動力消滅，當巨魔帝國能使用奴隸，而聯合王國有食人魔和矮人的時候，看看你們自己的命運會怎樣。再一次申明，這一切對我們是否有幫助並不重要，這是你們要生存下來必須做的事情。

這只是我們保存下來的東西的三分之一。下一個是我們的心靈處理能力，我們善於使用靈能的心靈，我們快速獲取並邏輯性分析信息的能力。你們永遠不能完全消滅奪心魔————相信我們，我們確認過了。他們看上去像是被這個世界祝福的一樣，就像我們是被這個世界詛咒一般。然而，我們如果只是想躲藏在他們身體裏面，我們失敗的命運仍然是註定的。真實可信。儘管如此，他們的大腦中所承載的系統還會長存；在我們不在的時候，他們還會把我們的維網繼續維持下去。

最後，還有我們的文化。我們的發現。任何我們曾經學習到，而又沒放到身體或大腦裏的只是，我們把它存儲在……另一個羣體中。一個擴張到羣星之間的羣體，一個我們植入了無數比特仔細編碼好的信息的羣體，一個在宇宙間有無數備份的羣體……他們會把當中足夠的信息帶回來的。奪心魔們會吸收這些，我們會重生到他們的心靈中，直到他們能把我們放在那優越的軀體裏。

一旦風暴降臨埃亞爾，一旦所有的衝突被解決……或許這場大戰帶來的憎恨與惡意之潮會充分地吸引宇宙的注意力，讓我們有機會組合好碎片，進行重生。或者我們可以在衆神們都死了或者發瘋了之後做到這一切，他們的怒火被遺忘或者消弭，這些詛咒也失去了繼續存活下去的燃料。或許那個詛咒已經瀕死，只是被夏·圖爾的星球之盾勉強延續下去————那個正在逐漸失效的護盾，上面佈滿裂痕，瑪·洛克人正急切地想要把它敲開。

那如果做不到呢？我們的文化無處不在。只要不把它們全部消滅，就不可能把我們徹底清除。命運已經決定了，我們是要被這個世界割除的腫瘤；既然我們命中註定要成爲腫瘤的話，我們也決心成爲一顆侵入性的腫瘤。現在輪到命運決定，我們是一個成長中的良性腫瘤還是末期的惡性腫瘤了。

畢竟，我們就是純粹惡意的決心在這個世界上的化身，你還能期望在我們的身上看到什麼呢？
]], "_t")
t("telepathic message (6)", "心靈傳訊 (6)", "_t")
t([[If you would indulge us...  Next to you is a tablet that was just carved by our machines, moments before you arrived.  If our curse holds, it will be completely illegible, but if it has been lifted, it will bear our name.  A blatant, distinct word that is an undeniable mark of our existence, a sign that no matter how it may have wanted to, the universe could not forget us.  Look to your right, and learn the name of those who have far more right to exist than you do, who have fought far harder for it, and will sink their hooks so deep into reality that it must either lift them up or be dragged into the depths with them.  Learn the name feared by existence itself!

#{italic}#(You look to your right, and see a tablet which has been broken into fragments.  The fragments are still arranged roughly in the right shape, and you can read a single word; another, larger fragment bears a sentence.)#{normal}#

]], [[如果你還願意繼續聽下去的話……在你身邊，是一塊石板，是在你過來時前剛剛由我們的機器雕刻完成的。如果我們的詛咒還在持續下去，上面的字將會是完全無法辨認的，而如果詛咒被解除，這上面會刻着我們的名字。那是一個顯眼、獨特的名字，是我們存在的無可否認的標誌。一個表明，宇宙也忘不了我們。往你右邊看，看看我們這個羣體的名字，這一羣體比你們遠遠更有權利存在，卻不得不爲了那權利比你們都努力地鬥爭，他們奮力將鉤子扎入最深的現實，讓現實不得不要麼將他們連根拔起，要不被他們一道拖進深淵。看吧，這個被存在本身畏懼的名字！
    
#{italic}#（你往右看，看到一塊破裂成碎片的石板。石板仍然按照正確的形狀排列，你可以讀到一個詞；另一個大一些的碎片上有個句子。）#{normal}#

]], "_t")
t([[#{bold}#WEISSI

DO YOU KNOW OUR NAME?#{normal}#]], [[#{bold}#維西

你知道我們的名字嗎？#{normal}#]], "_t")
t([[#{italic}#(Somehow the name seems to have faded from your memory!)#{normal}#

DO YOU KNOW OUR NAME?#{normal}#]], [[#{italic}#（不知爲何，這個名字從你的記憶中消失了！）#{normal}#

你知道我們的名字嗎？#{normal}#]], "_t")

------------------------------------------------
section "tome-orcs/data/lore/yeti.lua"

t("yeti's cave", "雪人洞穴", "newLore category")
t("crude cave painting (1)", "粗糙的壁畫 (1)", "_t")
t("You see here a crude cave painting, depicting a drake attacking a group of yetis, as an indistinct figure watches over them.  To the right, you see a drawing of the figure attacking the drake, and the yetis cheering.", "你看到一幅粗糙的壁畫，上面描繪着一條龍，正在攻擊一羣雪人，有一個粗糙的人頭正觀察着他們。在右邊，你看到那個人頭擊敗了那條龍，而雪人們發出了歡呼。", "_t")
t("crude cave painting (2)", "粗糙的壁畫 (2)", "_t")
t("You see here a cave painting, depicting a giant attempting to lead some yetis away in chains, but being pulled down and mauled by other yetis.", "你看到一幅壁畫，上面畫着一個巨人用鎖鏈拷着雪人，其他的雪人正奮力攻擊着他。", "_t")
t("crude cave painting (3)", "粗糙的壁畫 (3)", "_t")
t("You see here a cave painting, depicting a giant holding an object, which is projecting some sort of beam at a yeti.  The affected yeti is walking toward the giant, while other yetis are looking on in horror.", "你看到一幅壁畫，上面畫着一個巨人，他手中拿着的東西朝着雪人發出一道亮光。被亮光照射的雪人朝着巨人走去，其他的雪人驚恐地看着這一切。", "_t")

------------------------------------------------
section "tome-orcs/data/maps/zones/worldmap.lua"

t("Far East", "遠東", "_t")
t("Var'Eyal", "瓦·埃亞爾", "_t")
t("WARNING", "警告", "_t")
t("Danger!", "危險！", "_t")
t("Warning, to the west is #CRIMSON##{bold}#Atmos Tribe#{normal}##LAST# territory. Likely far too dangerous for you!", "警告，西邊是#CRIMSON##{bold}#氣之部落#{normal}##LAST#的領地。似乎對你來說太危險了！", "_t")
t("Clork Peninsula", "克拉克半島", "_t")

------------------------------------------------
section "tome-orcs/data/quests/amakthel.lua"

t("The Dead God Awaits", "已死之神的復甦", "_t")
t("Deep within Eyal you found a huge cavern containing some of the remains of the great dead god Amakthel...", "在埃亞爾的深處，你找到了一個巨大的山洞，那裏面深埋着已死的巨神阿馬克泰爾的遺骸。", "_t")
t("Along with what appears to be a living Sher'tul that seems to be trying to resurrect him.", "在那裏，還有一個活生生的夏·圖爾人，它試圖復活這尊古神。", "_t")
t("It must be stopped at all cost, the Prides only just got their freedom back, you can not allow anything to take it away again!", "必須不惜一切代價阻止他的可怕行徑，部落的自由來之不易，任何人都無法再次奪走它！", "_t")
t("The Sher'tul Priest has been taken care of, Amakthel will keep on sleeping forever now. The Prides and the world are safe.", "夏·圖爾祭司已經被妥善處置，阿馬克泰爾將永久繼續沉睡。部落和世界的和平得到了確保。", "_t")
t("#LIGHT_GREEN#You have won the game!.#WHITE#", "#LIGHT_GREEN#你通關了！#WHITE#", "_t")
t("#CRIMSON#You feel as if your Rod of Recall is working again in this area.", "#CRIMSON#你感覺到你的召回之杖可以繼續在這個區域運作了。", "log")
t("Orc Warrior", "獸人戰士", "_t")
t("Winner", "遊戲勝利", "_t")
t("#GOLD#Well done! You have won the Tales of Maj'Eyal: Embers of Rage!#WHITE#", "#GOLD#幹得不錯！你通關了馬基·埃亞爾的傳說：餘燼怒火#WHITE#", "_t")
t("You have thwarted the Steam Giants' genocidal plans, and avenged those killed in the attack on Kruk Pride.  Their desperate pact with the High Priest did nothing to stop you; the priest and his god lay dead at your feet, and you have ensured they will #{italic}#stay#{normal}# dead for the foreseeable future.", "你挫敗了蒸汽巨人滅絕你們的邪惡計劃，併爲那些在他們殘忍襲擊中喪生的部落同胞復仇。他們絕望中與夏·圖爾祭祀的邪惡契約也未能阻止你，祭祀和他的神在地底逝去，你相信他們將會#{italic}#永遠#{normal}#長眠在那裏。", "_t")
t("The humans, elves, and halflings will not be able to hurt your people again.  By destroying the farportal and denying King Tolak's army its glorious battle, you have ensured the safety of your people from the Allied Kingdoms, and by storming the Gates of Morning you have eliminated the last bearers of the West's hateful aggression in Var'Eyal.", "無論是人類、精靈還是半身人再也無法傷害你的族人。你拒絕了國王托拉克的軍隊和輝煌的戰鬥，選擇摧毀了遠古傳送門，確保你的人民將不會受到聯合王國的侵害。你對晨曦之門的襲擊也摧毀了西方在瓦·埃亞爾可惡侵略的最後爪牙。", "_t")
t("For now, peace reigns.  You know that this will not last forever.  You may have repelled its vanguard, but the Kar'Haïb Dominion bides its time waiting for a weakness it can exploit; the smugglers' portals from Maj'Eyal remain undiscovered, and while neither you nor King Tolak has any remaining desire to take the other's continent, the fear of invasion will linger in the backs of your minds.", "終於，和平降臨了。你知道這和平來之不易。雖然你驅散了他們的先鋒隊，但卡爾·亥巴帝國的巨魔絕不會放棄任何他們可以利用的弱點；走私者在馬基·埃亞爾使用的傳送門還沒有被發現；此外，即使你或托拉克國王放棄了侵入對方領土的念頭，對入侵的恐懼仍然在你們的頭腦中環繞。", "_t")
t("  The messages of the Lost City give you cause to remain ever vigilant for the threats they warned of, including their authors, and you wonder what your people will do now that their struggle to escape eradication, one that has defined them for their entire recorded history, has ceased to be a concern.", "  來自失落之城的消息讓你充滿警醒，無論是那些他們警告的恐怖威脅，還是他們本身。你想知道，當你的人民所極力擺脫的滅亡威脅：那個鐫刻在你們整個歷史中的威脅，現在已經不復存在的時候，你們的人民又將何去何從？", "_t")
t("Regardless...  You just killed a god and gave your people the first chance to relax in thousands of years.  It's been a pretty good day.", "不管怎樣…你殺死了一個神，而你的人民在數千年的征戰中終於有了放鬆的機會。多麼愉快的一天。", "_t")
t("You may continue playing and enjoy the rest of the world.  Your soldiers may want to speak with you outside...", "你可以繼續遊戲，享受這個世界。你的士兵在外面，有些話要說……", "_t")
-- untranslated text
--[==[
t("", "", "_t")
--]==]


------------------------------------------------
section "tome-orcs/data/quests/annihilator.lua"

t("Research. Tinker. Annihilate.", "研究。製造。殲滅。", "_t")
t("Inside some of your foes you have found some intact pieces that give you new ideas.", "在你的一些敵人身上，你發現了一些完整的碎片，這給你帶來了新的想法。", "_t")
t("Keep on killing mechanical contraptions or steam-related foes...", "請繼續殺死機械裝置，或和蒸汽有關的敵人……", "_t")
t("#LIGHT_GREEN#* You destroyed a mecharachnid equiped with a flamethrower. Both those things could prove very useful.#WHITE#", "#LIGHT_GREEN#* 你摧毀了一個裝備火焰噴射器的機械蜘蛛。這兩樣東西將來都會很有用。#WHITE#", "_t")
t("#LIGHT_GREEN#* You have studied the 'remains' of an greater or ultimate hethugoroth, providing new ideas for ways to annihilate with heat.#WHITE#", "#LIGHT_GREEN#* 你研究了一個大型或終極赫斯格魯斯的“遺骸”。這爲你如何用熱殲滅敵人提供了新的思路。#WHITE#", "_t")
t("#LIGHT_GREEN#* The impressive Automated Defense System remains will prove very useful to create automated and self-deploying constructs.#WHITE#", "#LIGHT_GREEN#* 這種令人印象深刻的自動防禦系統的殘骸，對製造可以自動部署的自動化機械十分有用。#WHITE#", "_t")

------------------------------------------------
section "tome-orcs/data/quests/destroy-sunwall.lua"

t("The Deconstruction of Falling Stars", "羣星的隕落", "_t")
t([[The people of the sunwall have lingered on this land for too long and now they are spreading their control to all the mainland. This must not be allowed!
With the help of their newfound allies in the west they keep a permanent guard over the farportal. The portal must be permanently destroyed to prevent reinforcements.
The leader of the Sunwall, High Sun Paladin Aeryn must be punished for her crimes against the Prides.]], [[太陽堡壘的敵人已經在這片土地上橫行了太久，他們妄圖掌控整個大陸。他們絕不會得逞！
在他們來自西方的新盟友的幫助下，他們永久守護着遠古傳送門。摧毀遠古傳送門，防止援軍前來！
太陽堡壘的領袖，高階太陽騎士艾琳，將會爲她對部落犯下的惡行付出代價！]], "_t")
t("#LIGHT_GREEN#* You have killed Aeryn, making sure no more troops will come from the west.#WHITE#", "#LIGHT_GREEN#* 你殺死了艾琳，西方的援軍再也不會前來了。#WHITE#", "_t")

------------------------------------------------
section "tome-orcs/data/quests/free-prides.lua"

t("Children of Garkul, Unite!", "加庫爾的子民們，聯合起來！", "_t")
t("All the few remaining orcs of the mainland have been captured by Sunwall and their western allies.", "大陸上剩餘少數的獸人都被太陽堡壘和他來自西方的盟友抓了起來。", "_t")
t("To ensure a future, any future, for our race they must be freed.", "爲了我們種族的未來，他們必須被解放。", "_t")
t("The internment camp is located somewhere to the north. The orcs are subdued into obedience by a powerful #{halfling}# psionic, Mindwall, and guarded by elite Sunwall troops.", "T他們的拘留營在北部的某處。獸人們的心靈被一個強大的半身人靈能力者，意志之牆所控制，並被太陽堡壘的精英部隊重重把守。", "_t")
t("Mindwall must be taken care of and the prides set free.", "必須幹掉意志之牆，我們的部落才能迎來自由", "_t")
t("But #{bold}#BEFORE#{normal}# that you should go and destroy the Sunwall Observatory to the east, as our spies have found a way to resist Mindwall's psionic powers which requries #{italic}#ingredients#{normal}# from there.", "但是#{bold}#之前#{normal}#你最好去一趟東部的太陽堡壘觀星臺。我們的間諜收到線報稱，那裏獲得到的#{italic}#材料#{normal}#有助於找出抵禦意志之牆的精神能力的方法。", "_t")
t("#LIGHT_GREEN#* You have destroyed Mindwall body but he managed to split his mind into many pieces and taken direct control of the subdued orcs. Destroy the pillars in each level four other levels.#WHITE#", "#LIGHT_GREEN#* 你摧毀了意志之牆的身軀，但他找到了一種辦法把自己的靈魂分成許多塊，分別控制那些被關押的獸人。摧毀其他四個關卡的水晶柱。#WHITE#", "_t")
t("#LIGHT_GREEN#* You have freed all the Vor Pride orcs.#WHITE#", "#LIGHT_GREEN#* 你解放了沃爾部落的獸人。#WHITE#", "_t")
t("#GREY#* You need to have free the Vor Pride orcs.#WHITE#", "#GREY#* 你必須解放沃爾部落的獸人。#WHITE#", "_t")
t("#LIGHT_GREEN#* You have freed all the Rak'Shor Pride orcs.#WHITE#", "#LIGHT_GREEN#* 你解放了拉克·肖部落的獸人。#WHITE#", "_t")
t("#GREY#* You need to have free the Rak'Shor Pride orcs.#WHITE#", "#GREY#* 你必須解放拉克·肖部落的獸人。#WHITE#", "_t")
t("#LIGHT_GREEN#* You have freed all the Gorbat Pride orcs.#WHITE#", "#LIGHT_GREEN#* 你解放了加伯特部落的獸人。#WHITE#", "_t")
t("#GREY#* You need to have free the Gorbat Pride orcs.#WHITE#", "#GREY#* 你必須解放加伯特部落的獸人。#WHITE#", "_t")
t("#LIGHT_GREEN#* You have freed all the Grushnak Pride orcs.#WHITE#", "#LIGHT_GREEN#* 你解放了格魯希納克部落的獸人。#WHITE#", "_t")
t("#GREY#* You need to have free the Grushnak Pride orcs.#WHITE#", "#GREY#* 你必須解放格魯希納克部落的獸人。#WHITE#", "_t")
t("#LIGHT_GREEN#* The Pride is once again free and united.#WHITE#", "#LIGHT_GREEN#* 部落重獲自由，更加團結。#WHITE#", "_t")
-- untranslated text
--[==[
t("", "", "_t")
--]==]


------------------------------------------------
section "tome-orcs/data/quests/gem.lua"

t("Mole Down, Two To Go", "再一次，鑽下地", "_t")
t("As you left the Gates of Morning in ruins you noticed a strange powerful tremor that seems to come from nearby.", "當你離開晨曦之門的廢墟，你注意到周圍有一股強大的震感。", "_t")
t("Investigating you have found a huge mechanical mole of obvious steam giant origin.", "一番調查後，你找到了一個巨大的機械鼴鼠，一定是蒸汽巨人們造的。", "_t")
t("#LIGHT_GREEN#* You have crushed both the horrors and the giants, making sure no precious information will come back to the Palace of Fumes.#WHITE#", "#LIGHT_GREEN#* 你擊敗了巨人和恐魔們，他們無法把珍貴的信息帶回煙霧宮殿了。#WHITE#", "_t")
-- untranslated text
--[==[
t("", "", "_t")
--]==]


------------------------------------------------
section "tome-orcs/data/quests/kaltor-shop.lua"

t("The Grumpy Shopowner", "脾氣暴躁的店主", "_t")
t("Kaltor's shop seems to be nearby in the mountain. Maybe it could be interesting to pay him a visit?", "卡托爾的店鋪似乎就在附近的山中。或許你有興趣到此一遊？", "_t")
t("He does sound well armed, though, so be prepared as it is likely very dangerous.", "不過，聽說他全副武裝，所以請做好準備。", "_t")
t("So maybe take some time to plan the raid.", "如果你想要幹掉他，請擇時計劃一下。", "_t")
t("#LIGHT_GREEN#* You have disposed of Kaltor, the loot is yours!#WHITE#", "#LIGHT_GREEN#* 你做掉了卡托爾，他的寶藏歸你了！#WHITE#", "_t")
t("#PURPLE#You heard a loud noise!", "#PURPLE#你聽到了巨大的噪音！", "saySimple")

------------------------------------------------
section "tome-orcs/data/quests/kill-dominion.lua"

t("This is our land!", "這是我們的土地！", "_t")
t("A group of trolls from the Kar'Haïb Dominion is trying to take foot on the mainland.", "一羣來自卡爾·亥巴巨魔帝國的巨魔試圖染指這片土地。", "_t")
t("With the Sunwall at full force we can not have the luxury of having to fight on both fronts, the Dominion port of the south must be destroyed.", "由於太陽堡壘已經全軍戒備，我們決不能兩面受敵。巨魔帝國的港口必須被摧毀。", "_t")
t("A potent bomb was given to you, you must place it at a weak spot of the tower where it will detonate and destroy the port.", "我們給了你一個強力的炸彈，你必須把它放在塔樓的脆弱處，它會爆炸並摧毀港口。", "_t")
t("It would be a good idea for you to not be there anymore when the bomb explodes however.", "在炸彈爆炸前，你最好提前逃走", "_t")
t("#LIGHT_GREEN#* You have destroyed the Dominion port, the trolls will not be a problem in the near future.#WHITE#", "#LIGHT_GREEN#* 你已經摧毀了巨魔帝國的港口，巨魔侵襲的危險短期內不會再出現了。#WHITE#", "_t")
t("Tower Detonator", "塔樓炸彈", "_t")
t("This bomb was tailored to weaken the structure of the Dominion's port tower. If placed at the right spot it will explode after 100 turns and destroy the whole port.", "這枚炸彈是爲削弱帝國港口塔樓的結構而特製的。如果放在正確的位置，它會在100回合後爆炸並摧毀整個港口。", "_t")
t("place the bomb on the structural weakness.", "將炸彈放在建築的弱點處。", "_t")
t("Sewer Detonator", "下水道炸彈", "_t")
t("You must first locate the structural weakness in the Dominion's port tower.", "你需要先找到塔樓的結構弱點。", "_t")
t([[You place the detonator, you have 100 turns to get out or be destroyed by the explosion.
Use your #{bold}##GOLD#Rod of Recall#LAST##{normal}#!]], [[你安置了炸彈，將在100回合後爆炸。
使用#{bold}##GOLD#迴歸之杖#LAST##{normal}#！]], "_t")
-- untranslated text
--[==[
t("", "", "_t")
--]==]


------------------------------------------------
section "tome-orcs/data/quests/krimbul.lua"

t("Clan of the Unicorn", "獨角獸部族", "_t")
t("Metash has asked you to investigate the Krimbul Clan, south of the peninsula.", "梅塔什希望你調查半島南部的克里布爾部落。", "_t")
t("A whitehoof turned mad with power is trying to lead them in a war against Kruk Pride.", "一羣獲得了力量的白蹄變得瘋狂，他們想要用戰爭對抗克魯克部族。", "_t")
t("#LIGHT_GREEN#* You have stopped the pitiful Nektosh, ensuring one less threat for the Pride and a future for the Whitehooves.#WHITE#", "#LIGHT_GREEN#* 你阻止了可憐的納克託什，部落少了一個敵人，多了一個朋友，白蹄族也迎來了更光輝的命運。#WHITE#", "_t")
-- untranslated text
--[==[
t("", "", "_t")
--]==]


------------------------------------------------
section "tome-orcs/data/quests/kruk-invasion.lua"

t("Homeland", "家園", "_t")
t("The giants have breached the mountain-side of Kruk pride!", "巨人們已經進犯了克魯克部族的靠山側！", "_t")
t("They are invading the town just when most of our forces are outside.", "他們進攻了城鎮，而我們的部隊卻還在外面。", "_t")
t([[Only you and few others are left to close the breach by collapsing the tunnel from the inside.
]], [[只有你和少量同伴還留在這裏，必須炸燬他們的隧道，封鎖突破口。
]], "_t")
t("#LIGHT_GREEN#* You have collapsed the tunnel, saving the Pride. For now.#WHITE#", "#LIGHT_GREEN#* 你成功炸燬了隧道，挽救了部落的燃眉之急。#WHITE#", "_t")
t("#LIGHT_GREY#* You must place the bomb at the end of the tunnel to destroy it.#WHITE#", "#LIGHT_GREY#* 你必須在隧道盡頭安裝炸彈來炸燬它。#WHITE#", "_t")
t("Cave Detonator", "洞穴炸彈", "_t")
t("This bomb was tailored to crumble the tunnel used by the Steam Giants to invade Kruk Pride.", "這枚炸彈是爲粉碎蒸汽巨人用來入侵克魯克部落的隧道而特製的。", "_t")
t([[You place the detonator, you have 220 turns to get out or be destroyed by the explosion.
Use your #{bold}##GOLD#Rod of Recall#LAST##{normal}#!]], [[你成功安裝了炸彈，將於220回合後爆炸。你需要在爆炸前離開。
使用 #{bold}##GOLD#迴歸之杖#LAST##{normal}#!]], "_t")
t("#LIGHT_GREEN#Kruk Pride is safe for now. Now is time for revenge!", "#LIGHT_GREEN#克魯克部落安全了。現在是復仇的時刻！", "saySimple")

------------------------------------------------
section "tome-orcs/data/quests/palace.lua"

t("No Fumes Without Fire", "無火不起煙", "_t")
t("The time for revenge is at hand! The Tribe stands crippled under your assaults.", "復仇的時刻終於到了！氣之部族在你的攻擊下瀕臨癱瘓！", "_t")
t("Enter the Palace of Fumes and crush their leaders once and for all!", "攻入煙霧宮殿，徹底粉碎他們的領袖！", "_t")
t("For Kruk!", "爲了克魯克！", "_t")
t("For the Prides!", "爲了部落！", "_t")
t("For the Garkul!", "爲了加庫爾！", "_t")
t("#LIGHT_GREEN#* Council Member Nashal is dead.#WHITE#", "#LIGHT_GREEN#* 議會成員納沙爾死了。#WHITE#", "_t")
t("#LIGHT_GREEN#* Council Member Tormak is dead.#WHITE#", "#LIGHT_GREEN#* 議會成員托馬剋死了。#WHITE#", "_t")
t("#LIGHT_GREEN#* Council Member Pendor is dead.#WHITE#", "#LIGHT_GREEN#* 議會成員潘多爾死了。#WHITE#", "_t")
t("#LIGHT_GREEN#* Council Member Palaquie is dead.#WHITE#", "#LIGHT_GREEN#* 議會成員帕拉奎死了。#WHITE#", "_t")
t("#LIGHT_GREEN#* Council Member Tantalos is dead.#WHITE#", "#LIGHT_GREEN#* 議會成員坦塔洛斯死了。#WHITE#", "_t")
t("#LIGHT_GREEN#* You have destroyed the Council and shattered the Tribe.#WHITE#", "#LIGHT_GREEN#* 你摧毀了他們的議會，氣之部族分崩離析！#WHITE#", "_t")
t("What is all this noise about!", "這是什麼聲音！", "_t")
t("Tantalos! What have you done!", "坦塔洛斯！你都幹了些什麼！", "_t")
-- untranslated text
--[==[
t("", "", "_t")
--]==]


------------------------------------------------
section "tome-orcs/data/quests/quarry.lua"

t("Hunter, Quarry", "石匠與獵人", "_t")
t("The Steam Quarry is a strategic zone for the Atmos tribe, it provides them with much of their energy needs.", "蒸汽採石場是氣之部族的重要戰略設施，爲他們供應能量。", "_t")
t("If you are to assault the Palace of Fumes you need to cut that supply off. Destroy the three giant steam valves to make the Palace vulnerable.", "如果你想要進攻煙霧宮殿你必須切斷他們的供應。摧毀三個巨大的蒸汽閥來破壞宮殿的防禦。", "_t")
t("#LIGHT_GREEN#* The first valve has been destroyed.#WHITE#", "#LIGHT_GREEN#* 第一個蒸汽閥已被摧毀。#WHITE#", "_t")
t("#LIGHT_GREEN#* The second valve has been destroyed.#WHITE#", "#LIGHT_GREEN#* 第二個蒸汽閥已被摧毀。#WHITE#", "_t")
t("#LIGHT_GREEN#* The third valve has been destroyed.#WHITE#", "#LIGHT_GREEN#* 第三個蒸汽閥已被摧毀。#WHITE#", "_t")

------------------------------------------------
section "tome-orcs/data/quests/ritch-hive.lua"

t("A Ritch Party", "裏奇派對", "_t")
t("Our ultimate goal on the mainland is to get rid of the Sunwall once and for all.", "我們在大陸上的最終目的是一勞永逸地清除太陽堡壘的威脅。", "_t")
t("To do that we will prepare a special surprise to help our final attack.", "爲此，我們必須爲最終的突襲做好準備，給他們一個“驚喜”。", "_t")
t("Go to the Ritch Hive in the mountains north of the Erúan desert and collect a big pile of ritch eggs.  About 30 viable eggs should be sufficient.", "前去艾露安沙漠北部丘陵中的裏奇蟲巢，收集大量的裏奇蟲卵。至少要30個纔夠。", "_t")
t("When you have enough, find a tunnel leading north and use the special sand shredder gloves tinker to open a path under the Gates of Morning.", "當你有了足夠的裏奇蟲卵，找到一條向北的隧道，使用特殊的挖沙手套插件來挖出一條通向晨曦之門的道路。", "_t")
t("Finally, place the eggs in a protected spot to hatch.  With luck, they will provide a distraction while you later assault the city.", "最後，在合適的地方放置這些蟲卵來腐化它們。運氣好的話，當你之後襲擊城市的時候，它們可以大大擾亂敵軍。", "_t")
t("#LIGHT_GREEN#* You have collected enough eggs.#WHITE#", "#LIGHT_GREEN#* 你收集了足夠多的蟲卵#WHITE#", "_t")
t("#LIGHT_GREEN#* You have tunnelled close enough to the Gates of Morning.#WHITE#", "#LIGHT_GREEN#* 你已經向北挖到晨曦之門的地方。#WHITE#", "_t")
t("#LIGHT_GREEN#* You have placed the little surprise.#WHITE#", "#LIGHT_GREEN#* 你安排好了了這些小小的“驚喜”。#WHITE#", "_t")
t("Stralite Sand Shredder", "藍鋯石掘沙者", "_t")
t("Automatically deploy a huge rotating drill when you hit a sandwall, carving out a big part of it quickly.", "當你碰到沙牆時，會自動部署一個巨大的旋轉鑽頭，很快就鑽出一個大洞。", "_t")
t("You cannot bring yourself to drop the %s", "你無法丟棄 %s", "logPlayer")
-- untranslated text
--[==[
t("", "", "_t")
--]==]


------------------------------------------------
section "tome-orcs/data/quests/start-orc.lua"

t("Of Steamwork and Pain", "苦痛和蒸汽", "_t")
t([[To win the war you must help the Pride by striking a blow to the giant's morale and supply lines.
]], [[爲了讓部落贏得和蒸汽巨人的戰爭，你必須打擊敵人的士氣和補給線。
]], "_t")
t("#LIGHT_GREEN#* You have assaulted the Vaporous Emporium, crushing the morale of the Atmos tribe.#WHITE#", "#LIGHT_GREEN#* 你已經襲擊了蒸汽商場，摧垮了氣之部落的士氣。#WHITE#", "_t")
t("#SLATE#* You must assault the Vaporous Emporium to crush the morale of the Atmos tribe!#WHITE#", "#SLATE#* 你必須襲擊了蒸汽商場來摧垮了氣之部落的士氣！#WHITE#", "_t")
t("#LIGHT_GREEN#* You have explored the yeti cave and vanquished the Yeti Patriarch.#WHITE#", "#LIGHT_GREEN#* 你已經探索了雪人洞穴，打敗了雪人族長。#WHITE#", "_t")
t("#SLATE#* You must explore the Yeti Cave and destroy the patriarch!#WHITE#", "#SLATE#* 你必須探索雪人洞穴並擊敗他們的族長！#WHITE#", "_t")

------------------------------------------------
section "tome-orcs/data/quests/sunwall-observatory.lua"

t("Stargazers", "觀星者", "_t")
t("Our ultimate goal on the mainland is to get rid of the Sunwall once and for all.", "我們在大陸上的最終目的是一勞永逸地清除太陽堡壘的威脅。", "_t")
t("Our scouts have noticed the Gates of Morning is being reinforced with sun and moon orbs.", "我們的哨兵注意到晨曦之門使用太陽球和月亮球來進行防護。", "_t")
t("Go to the Sunwall Observatory and destroy everything there to reduce their supplies.", "前往太陽堡壘觀星臺，摧毀它來中斷他們的供應。", "_t")
t("#LIGHT_GREEN#* You have destroyed the Observatory, the Gates of Morning defenses will be weakened.#WHITE#", "#LIGHT_GREEN#* 你摧毀了觀星臺，晨曦之門的防禦被削弱了。#WHITE#", "_t")
-- untranslated text
--[==[
t("", "", "_t")
--]==]


------------------------------------------------
section "tome-orcs/data/quests/to-mainland.lua"

t("You Shall Pass!", "你必須通過！", "_t")
t("The Atmos tribe is not our sole problem. The Sunwall as grown in strength since the Scourge from the West came and murdered the other Prides leaders.", "氣之部族不是我們唯一的問題。自從那個西部來的災星來到這裏並屠殺了我們的部落領袖，太陽堡壘的實力與日俱增。", "_t")
t("Our brothers on the mainland lay enslaved, but before we free them you must secure a way to the mainland.", "我們在大陸上的兄弟慘遭奴役，爲了解放他們我們必須找到一條到達大陸的安全的路。", "_t")
t([[Go to the sunwall outpost. Show them the wrath of Garkul, show no mercy for they have none for us.
]], [[前去太陽堡壘前哨站。讓他們領教加庫爾的怒火，絕不仁慈，因爲他們對我們也不曾仁慈。
]], "_t")
t("#LIGHT_GREEN#* You have destroyed the sunwall outpost, and secured a way to the mainland.#WHITE#", "#LIGHT_GREEN#* 你已經摧毀了太陽堡壘前哨站，確保了通向大陸的安全通路。#WHITE#", "_t")
t("To the mainland!", "前往大陸！", "_t")
t([[The way to the mainland is now clear.
Travel there using the bridge on the worldmap.]], [[前往大陸的障礙已經被清除了。
使用大地圖上的橋來前往大陸。]], "_t")

------------------------------------------------
section "tome-orcs/data/quests/voyage.lua"

t("Voyage to the Center of Eyal", "直探地心！", "_t")
t("In the Palace of Fumes you found a geothermal vent that digs deep into the planet's core.", "在煙霧宮殿中，你找到了一個冒出地熱的排風口，直探這顆星球的地心。", "_t")
t("Strange mutated giants came out. You must find the source of those titans!", "奇怪的變異巨人從裏面走了出來。你必須找出泰坦的來源！", "_t")
t("#LIGHT_GREEN#* Travelling deep within Eyal you found the source of all corruptions: the dead god #{bold}##CRIMSON#Amakthel#LAST##{normal}#.#WHITE#", "#LIGHT_GREEN#* 在埃亞爾的深核中尋找，你終於找到了一切污染的盡頭：已死之神#{bold}##CRIMSON#阿馬克泰爾#LAST##{normal}#。#WHITE#", "_t")

------------------------------------------------
section "tome-orcs/data/quests/weissi.lua"

t("Mystery of the Yetis", "雪人之謎", "_t")
t("You have found a bit of preserved yeti muscle, probably somebody somewhere will be interested.", "你找到了一些保存好的雪人肌肉，或許哪裏有誰會有什麼興趣吧…", "_t")
t("For each yeti muscle you return to the psy-machines in the ruins of a lost city you will gain a great reward.", "你每找到一份雪人肌肉並交給在失落之城廢墟的靈能機器，你就會獲得一份獎勵。", "_t")
t("#LIGHT_GREEN#* You have helped the strange psionic machines and got rewards out of them. You still feel like somehow you did wrong...", "#LIGHT_GREEN#* 你幫助了那個奇怪的機器並從那裏得到了回報。可是，你總覺得你好像做錯了什麼…", "_t")
-- untranslated text
--[==[
t("", "", "_t")
--]==]


------------------------------------------------
section "tome-orcs/data/quests/yeti-abduction.lua"

t("Yeti Reinforcements", "雪人援軍", "_t")
t("You found a yeti mind control tinker. If you can tame 8 wild yetis and send them back to Kruk Pride they can be trained and sent back to you at your request using a psychoportation beacon.", "你找到了一個雪人心靈控制器配件。如果你馴服八個野生的雪人並把它們帶回克魯克部落，你可以使用一個心靈傳動裝置來召喚他們爲你而戰。", "_t")
t("Wild yetis are mostly found in yeti's caves.", "野生雪人主要出現在雪人洞穴。", "_t")
t("#LIGHT_GREEN#* Captured eight yetis (will be available to summon at level 20).#WHITE#", "#LIGHT_GREEN#* 抓住了八隻雪人（你至少需要20級才能召喚他們）#WHITE#", "_t")
t("#LIGHT_GREY#* Captured %d/8 yetis.#WHITE#", "#LIGHT_GREY#* 捕獲了 %d/8 個雪人。#WHITE#", "tformat")
t("Yeti's Psychoportation Beacon", "雪人精神傳送信標", "_t")
t("Call a trained yeti to your side.", "召喚雪人來協助你", "_t")
t("Yetis left to call: %d", "剩餘可召喚的雪人: %d", "tformat")
t("call a trained yeti for help", "召喚受訓練的雪人來幫助你", "_t")
t("The yetis are not ready yet.", "雪人還沒有準備好。", "log")
t("Yeti", "雪人", "_t")
t("You extract the psychoportation beacon from the mind controller. Yetis will require some time to train before being usable.", "你從精神控制器上提取精神傳送信標。雪人需要一些時間來訓練才能使用。", "log")
-- untranslated text
--[==[
t("", "", "_t")
--]==]


