section "tome-orcs/data/resolvers.lua"

t("Using medical injector with %d%% efficiency and %d%% cooldown modifier.", "使用藥物注射器，注射%d%%效率和%d%%冷卻時間修正的藥劑。", "tformat")
t("No medical injector available, values are indicative only.", "沒有可用的藥物注射器，數值僅供參考。", "_t")

