section "tome-orcs/data/talents/celestial/celestial-empyreal.lua"

t("celestial", "天空", "talent category")
t("Sol", "太陽", "talent type")
t("Cosmic", "宇宙", "talent type")
t("Energies", "能量", "talent type")
t("Reflection", "反射", "talent type")
t("Void", "虛空", "talent type")
-- untranslated text
--[==[
t("", "", "_t")
--]==]


------------------------------------------------
section "tome-orcs/data/talents/celestial/cosmic.lua"

t("Lunar Orb", "月光之球", "talent name")
t("Fires out a bolt of cosmic energy in the target direction. The projectile continues until it hits a wall or the edge of the map, dealing %0.2f dark damage to enemies hit and restoring %d negative energy. The negative energy gained is reduced by 25%% per enemy hit, restoring a maximum of %d. Enemies hit will become aware of you.", "向目標方向射出一道宇宙能量. 直到碰到牆或者到達地圖邊緣, 對敵人造成 %0.2f 的暗影傷害並回復 %d 負能量. 負能量回復量最大爲 %d , 每擊中一個敵人將少回覆 25%% 的負能量, 被擊中的敵人將注意到你.", "tformat")
t("Astral Path", "星光大道", "talent name")
t("The spell fizzles: there are no available spots to teleport to.", "法術失敗了：周圍沒有可供傳送到的區域。", "logSeen")
t([[Fire an orb of negative energy towards a spot within range %d.
		When the orb reaches its destination, it will teleport you to its location.
		The speed of the projectile (%d%%) increases with your movement speed]], [[在 %d 碼內發射一個負能量球.
		當負能量球到達目的地時, 會將你傳送到其位置.
		其飛行速度 (%d%%) 受你的移動速度加成。]], "tformat")
t("Galactic Pulse", "銀河脈衝", "talent name")
t([[Sends out a slow-moving spiral of cosmic energy towards a target location within range 8.
		As the cosmic energy moves, it pulls in targets adjacent to it, dealing %0.2f darkness damage and granting you 1 negative energy per hit.]], [[在 8 碼內發出一個緩慢移動的螺旋宇宙能量.
		當它移動時, 會把相鄰的目標拉向它, 造成 %0.2f 暗影傷害並每擊中一次回覆 1 點負能量.]], "tformat")
t("Supernova", "超新星", "talent name")
t([[Expend all of your negative energy to create a massive burst of dark energy (radius %d) at a target location within range %d.
		This deals %0.2f darkness damage and pins targets hit for %d turns.
		The damage and pin chance increase with your spellpower, and the damage, radius and pin duration all increase with negative energy and talent level]], [[釋放你所有的負能量在 %d 碼範圍內造成 (範圍 %d ) 的大規模暗能量爆發.
		造成 %0.2f 的暗影傷害並定身被擊中的敵人 %d 回合.
		傷害及定身機率受法術強度加成, 傷害、範圍、和定身持續時間全部受負能量和技能等級加成。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/celestial/crepescula.lua"

t("Twilit Echoes", "微光迴響", "talent name")
t([[The target feels the echoes of all your light and dark damage for %d turns. 

Light damage slows the target by %0.2f%% per point of damage dealt for %d turns, up to a maximum of %d%% at %d damage.
Dark damage creates an effect at the tile for %d turns which deals %d%% of the damage dealt each turn. It will be refreshed as long as the target continues taking damage from it or another source while Twilit Echoes is active, dealing its remaining damage over the new duration as well as the new damage.]], [[目標會受到你所有光暗傷害的迴響, 持續 %d 回合. 

每點光傷害減速敵人 %0.2f%% 持續 %d 回合, 在 %d 傷害時達到最大值, 爲 %d%% .
暗系傷害創造一個持續 %d 回合的地塊, 每回合造成傷害的 %d%%. 當有另一個微光迴響激活或目標持續承受此傷害時, 將刷新持續時間, 剩餘傷害和新承受的傷害將平分至新持續時間內.]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/celestial/energies.lua"

t("Celestial Acceleration", "天體加速", "talent name")
t("Increases your movement speed by %0.2f%% per percent of positive energy and your casting speed by %0.2f%% per percent of negative energy, up to a maximum of %0.2f%% at 80%%. Sustained energy still counts toward the maximum.", "每 1%% 的正能量增加 %0.2f%% 的移動速度, 每 1%% 的負能量增加 %0.2f%% 施法速度, 在 80%% 時達到最大值, 爲 %0.2f%%. 持續能量仍然算向最大值.", "tformat")
t("Polarization", "偏振", "talent name")
t("Whichever of your positive and negative energies is a higher percentage regenerates towards its max instead of its normal resting value (%d positive, %d negative). Your negative and positive regeneration/degeneration rates are increased to %0.2f.", "無論是你的正能量還是負能量都將用更高百分比的恢復替代正常的休息值 (%d 正能量, %d 負能量). 你的正能量和負能量恢復/ 消退速度增加至 %0.2f.", "tformat")
t("Magnetic Inversion", "磁反轉", "talent name")
t("Swap your current positive and negative energy levels. This spell takes no time to cast.", "交換當前正和負能量水平，這個法術是瞬發法術。", "_t")
t("Plasma Bolt", "等離子球", "talent name")
t("Fires out a bolt of pure energy, dealing %0.2f light and %0.2f darkness damage in a radius of %d, and slowing targets hit. Their movement is reduced by %d%% and attacking, casting and mind attacks by %d%%. The bolt will attune to your current positive and negative energy amounts.", "發射一道純粹的能量, 在 %d 範圍內造成 %0.2f 的光傷害和 %0.2f 的暗影傷害 , 並減速. 他們的移動速度減少 %d%% 並減少 %d%% 的攻擊力、法術和精神攻擊. 此能量將協調你當前的正負能量數值。", "tformat", {3,1,2,4,5})

------------------------------------------------
section "tome-orcs/data/talents/celestial/reflection.lua"

t("Diffraction Pulse", "衍射脈衝", "talent name")
t("Create a distortion at the target tile, knocking back all projectiles and changing their direction to face away if possible.", "在目標所在地創造一個地塊, 擊退所有的飛行物如果可能的話還會改變他們的方向。", "_t")
t("Mirror Wall", "反射鏡牆", "talent name")
t("mirror wall", "鏡像之牆", "_t")
t("Creates a wall %d units long for %d turns, reflecting all projectiles that hit it and blocking sight.", "創造一堵牆長 %d 持續 %d 回合, 反射所有擊中此牆的飛行物並且阻擋視線.", "tformat")
t("Spatial Prism", "空間棱鏡", "talent name")
t("Target a projectile in mid-flight to clone it and target that projectile independently. You gain ownership over the new projectile.", "選擇一個飛行中的拋射物，複製它，並指定新拋射物的目標。你獲得新的拋射物所有權。", "_t")
t("Mirror Self", "自我鏡像", "talent name")
t("Mirror Image (%s)", "鏡像 (%s)", "tformat")
t("A cloned image of you.", "你的克隆影像。", "_t")
t("Mirror Self", "自我鏡像", "_t")
t("Summons a clone for %d turns which casts all the spells you cast, dealing %d%% damage and having %d%% health. Additionally, all light damage the clone deals becomes darkness damage and all darkness damage becomes light damage.", "召喚一個持續 %d 回合能施放你所有法術的鏡像, 造成 %d%% 的傷害和擁有 %d%% 生命值. 此外, 鏡像造成的所有光傷害轉換爲暗影傷害，所有暗影傷害轉換爲光傷害.", "tformat")

------------------------------------------------
section "tome-orcs/data/talents/celestial/sol.lua"

t("Solar Orb", "日光球", "talent name")
t("Solar Orb", "日光球", "_t")
t("Fire out an orb of light that deals %0.2f light damage and then returns, dealing the same amount of damage again and reducing the cooldown by half (%d) when it reaches you. The damage will increase with your spellpower. The ball will travel at most %d distance to return to you.", "發射一個光球造成 %0.2f 的光傷害然後折返, 再次造成相同的傷害並且當回到你身上的時候減少一半 ( %d ) 的冷卻時間. 傷害受法術強度加成。球體最多飛行 %d 然後折回你.", "tformat")
t("Solar Wind", "太陽風", "talent name")
t("While sustained, this ability speeds up outgoing projectiles by %d%% while slowing incoming projectiles by %d%%. The increase and decrease improve with your spellpower", "開啓時, 增加發射出去的拋射物 %d%% 速度, 減少射向你的拋射物 %d%% 速度. 增加和減少隨着你的法術強度提高.", "tformat")
t("Lucent Wrath", "光之憤怒", "talent name")
t("After %d turns, the target area in (radius %d) is blasted with a beam of light, dealing %0.2f damage and lighting the area", "%d 回合後, 在 (範圍 %d ) 的目標區域發出一束激光, 造成 %0.2f 傷害並照明區域.", "tformat")
t("Lightspeed", "光速", "talent name")
t("%s moves at light speed!", "%s光速移動！", "logSeen")
t("Instantly gain %d%% percent of a turn.", "立刻獲得 %d%% 額外回合.", "tformat")

------------------------------------------------
section "tome-orcs/data/talents/celestial/void.lua"

t("Nebula Spear", "星雲之矛", "talent name")
t("Fire out a spear of cosmic energies. If it hits an enemy it deals %0.2f damage, otherwise it explodes in a thin cone of radius %d at the end of its range, blocked by enemies, which deals %0.2f to %0.2f damage depending on how much the enemies block.", "射出一個帶有宇宙能量的矛. 如果擊中敵人將造成 %0.2f 傷害, 否則它在到達最大射程時爆炸並造成一個範圍 %d 的錐形傷害, 能被敵人阻擋, 造成 %0.2f 至 %0.2f 傷害取決於有多少個敵人阻擋.", "tformat")
t("Crescent Wave", "新月波動", "talent name")
t("Fires out a projectile in a clockwise arc. If it hits an enemy it deals %0.2f damage and roots them for one turn. If another projectile damages them within %d turns, they take half that damage and are rooted again.", "向順時針方向發射一個拋射物. 如果擊中敵人將造成 %0.2f 傷害並定身 1 回合. 如果另一個拋射物在 %d 回合裏擊中他們, 他們將只收到一半的傷害並再次定身。", "_t")
t("Twilit Echoes", "微光迴響", "talent name")
t([[The target feels the echoes of all your light and dark damage for %d turns. 

Light damage slows the target by %0.2f%% per point of damage dealt for %d turns, up to a maximum of %d%% at %d damage.
Dark damage creates an effect at the tile for %d turns which deals %d%% of the damage dealt each turn. It will be refreshed as long as the target continues taking damage from it or another source while Twilit Echoes is active, dealing its remaining damage over the new duration as well as the new damage.]], [[目標會受到你所有光暗傷害的迴響, 持續 %d 回合. 

每點光傷害減速敵人 %0.2f%% 持續 %d 回合, 在 %d 傷害時達到最大值, 爲 %d%% .
暗系傷害創造一個持續 %d 回合的地塊, 每回合造成傷害的 %d%%. 當有另一個微光迴響激活或目標持續承受此傷害時, 將刷新持續時間, 剩餘傷害和新承受的傷害將平分至新持續時間內.]], "tformat")
t("Starscape", "星界領域", "talent name")
t("This spell cannot be cast here.", "該技能不能在這裏使用。", "logPlayer")
t("Summons the starscape in the surrounding area in a radius of %d. For %d turns, this area exists outside normal time, and in zero gravity. In addition to the effects of zero gravity, Movement of projectiles and other creatures is three times as slow. Spells and attacks cannot escape the radius until the effect ends.", "在 %d 範圍內召喚一片星界領域 . %d 回合內, 這個區域存在於正常時間之外, 且重力爲零. 除了零重力之外, 拋射物和生物的活動比平時慢 3 倍. 法術和攻擊不能逃脫範圍, 直到效果結束.", "tformat")

------------------------------------------------
section "tome-orcs/data/talents/misc/npcs.lua"

t("Petrifying Gaze", "石化凝視", "talent name")
t([[Gaze at your foes and turn them to stone for %d turns.
		Stoned creatures are unable to act or regen life, and are very brittle.
		If a stoned creature is hit by an attack that deals more than 30%% of its life, it will shatter and be destroyed.
		Stoned creatures are highly resistant to fire and lightning, and somewhat resistant to physical attacks.
		This spell may fail against creatures resistant to being stunned, that are specifically immune to stoning, or certain bosses.]], [[凝視你的敵人並把他石化 %d 回合。
		被石化的生物不能行動，回血，並且非常脆弱。
		如果被石化的生物一次性受到了超過總生命值 30%% 的傷害，那麼他會破碎並死去。
		被石化的生物對火焰和閃電有着很高的抗性，並對物理攻擊有着一定的抗性。]], "tformat")
t("Gnashing Maw", "撕咬", "talent name")
t([[Hits the target with your weapon, doing %d%% damage. If the attack hits, the target's Accuracy is reduced by %d for %d turns.
		Accuracy reduction chance increases with your Physical Power.]], [[用你的武器攻擊目標並造成 %d%% 傷害。如果此次攻擊命中，則目標命中會減少 %d 持續 %d 回合。 
		命中減值受物理強度加成。]], "tformat")
t("Sandrush", "潛沙突襲", "talent name")
t("@Source@ dives in the sand!", "@Source@潛入沙中！", "_t")
t("You are too close to build up momentum!", "離開目標太近無法施展！", "logPlayer")
t([[Dive into the sand and rush towards your target at up to range %d, gaining a free attack if you reach it.
		At the exit point, up to 9 sand pits will appear that last for %d turns (based on your Strength).
		You must rush from at least 2 tiles away.]], [[潛入沙中向距離你 %d 碼的目標發起突襲攻擊。
		在你的躍出點會出現最多 9 個持續 %d 回合（基於你的力量）的沙坑。
		你必須突襲至少 2 碼。]], "tformat")
t("Ritch Larva Infect", "裏奇幼蟲寄生", "talent name")
t("@Source@ stings with her ovipositor!", "@Source@使用產卵器刺入敵人！", "_t")
t([[Sting the target with your ovipositor, injecting %d larvae into it to finish their hatching process.
		Over a 5 turn gestation period, the larvae will feed on the victim internally, dealing %0.2f to %0.2f physical damage each turn (increasing as they grow).
		After the gestation period is complete, each larva will rip itself free of its host, dealing %0.2f physical and %0.2f fire damage.
		]], [[用你的產卵器蜇目標一下，將 %d 個幼蟲注入目標體內以完成他們的孵化流程。
		在一個 5 回合的發育週期內，幼蟲們會以受害者的血肉爲食，每回合造成 %0.2f 到 %0.2f 的物理傷害（隨着他們的成長增多）。
		在發育期結束後，幼蟲會從寄主體內鑽出，每個幼蟲造成 %0.2f 物理和 %0.2f 火焰傷害。
		]], "tformat")
t("Slumbering...", "沉睡中...", "talent name")
t("@Source@ enters a deep slumber.", "@Source@進入深睡眠。", "_t")
t("#STEEL_BLUE#%s slumbers...", "#STEEL_BLUE#%s睡着了……", "saySimple")
t("#CRIMSON#%s awakens!", "#CRIMSON#%s醒來了！", "saySimple")
t("The Dead God slumbers. For now.", "已死之神正在沉睡。起碼現在是這樣。", "_t")
t("Tentacle Spawn", "衍生觸手", "talent name")
t("@Source@ spawns a tentacle near @target@.", "@Source@在@target@身旁召喚了觸手。", "_t")
t("You cannot summon; you are suppressed!", "你不能召喚，你被壓制了！", "logPlayer")
t("Not enough space to summon!", "沒有足夠的空間召喚。", "logPlayer")
t("#ORCHID#%s summons a %s...", "#ORCHID#%s召喚了一個%s...", "logCombat")
t("#ORCHID#%s summons a %s...", "#ORCHID#%s召喚了一個%s...", "saySimple")
t("The Dead God wishes to tickle you...", "已死之神想要逗逗你……", "_t")
t("Curse of Amakthel", "阿馬克泰爾的詛咒", "talent name")
t([[Create a circle of cursed ground (radius %d) for %d turns. Any foes inside will be cursed, all new negative effects on them will have their duration doubled.
		]], [[創造一片詛咒之地（半徑 %d 碼） %d 回合。任何陷入其中的敵人都會被詛咒，任何他們新得到的負面狀態的持續時間都會翻倍。
		]], "tformat")
t("Temporal Ripples", "時空漣漪", "talent name")
t([[Creates a circle of radius %d of altered time for %d turns. Any damage your foes take while standing in it will heal the attacker for 200%% of the damage dealt.
		]], [[創造一片半徑 %d 碼的時間錯亂之地 %d 回合。任何站在其中的敵人受到的傷害都會治療攻擊者 200%% 傷害數額的生命。
		]], "tformat")
t("Saw Storm", "鋸刃風暴", "talent name")
t([[Summon a storm of swirling sawblades to slice your foes, inflicting %d physical damage and bleeding to anyone who approaches for %d turns.
		The damage and duration will increase with your Mindpower.]], [[召喚由旋轉的鋸刃組成的風暴來撕裂你的敵人，對每個接近者造成 %d 物理傷害並使其流血，持續 %d 回合。
]], "tformat")
t("Razor Saw", "剃刀飛鋸", "talent name")
t([[Launches a sawblade with intense power doing %0.2f physical damage to all targets in line.
		The damage will increase with Mindpower]], [[發射一個動能十足的鋸刃，對一條線內的所有目標造成 %0.2f 物理傷害。
		傷害會隨着你的精神強度增長。]], "tformat")
t("Rocket Dash", "火箭突進", "talent name")
t("@Source@ rockets forward!", "@Source@使用火箭突進向前！", "_t")
t([[Dash forward using rockets.
		If the spot is reached and occupied, you will perform a free melee attack against the target there.
		This attack does 130% weapon damage.
		You must dash from at least 2 tiles away.]], [[使用火箭向前突進。
		如果目標地點已被佔據，那麼你對那裏的目標進行一次近戰攻擊。
		攻擊會造成 130% 武器傷害。
		你必須至少突進 2 碼。]], "_t")
t("Mind Controlled Yeti", "精神控制的雪人", "talent name")

------------------------------------------------
section "tome-orcs/data/talents/misc/objects.lua"

t("steam", "蒸汽", "talent category")
t("object techniques", "物品戰技", "talent type")
t("Steam powers of the various objects of the world.", "世界上各種物品的蒸汽能力。", "_t")
t("Overgrowth", "過度生長", "talent name")
t([[Instantly grow a moss circle of radius %d at target area.
		Each turn the moss deals %0.2f nature damage to each foe within its radius.
		This moss is very thick and sticky causing all foes passing through it have their movement speed reduced by %d%% and have a %d%% chance to be pinned to the ground for 4 turns.
		The moss lasts %d turns.
		Moss talents are instant but place all other moss talents on cooldown for 3 turns.
		The damage will increase with your Mindpower.]], [[瞬間在半徑 %d 碼的區域內長出苔蘚圈。
		每回合苔蘚會對其中的敵人造成 %0.2f 的自然傷害。
		這些又厚又粘的苔蘚會讓途經他們的敵人移動速度下降 %d%% 並且有 %d%% 的機率被定身 4 回合。
		苔蘚能持續 %d 回合。
		苔蘚技能都是瞬發的，但是會讓其他的苔蘚技能進入冷卻 3 回合。
		傷害受精神強度加成。]], "tformat")
t("Ceasefire", "停火", "talent name")
t("You require at least a steamgun for this talent.", "你需要至少一把蒸汽槍才能使用這一技能。", "logPlayer")
t("%s resists!", "%s抵抗了效果！", "logSeen")
t([[You fire an incredibly potent shot at an enemy, doing %d%% damage and dazing them for %d turns.
		The daze chance increases with your Steampower.]], [[你向一個敵人射出一發威力無窮的子彈，造成 %d%% 傷害並眩暈他們 %d 回合。
		眩暈機率受蒸汽強度加成。]], "tformat")
t("Surekill", "一擊必殺", "talent name")
t([[You fire an exceptionally lethal shot at an enemy, doing %d%% damage.
Damage dealt by this talent is increased by half your critical multiplier, if doing so would kill the target.]], [[你向一個敵人射出一發無比致命的子彈，造成 %d%% 傷害。
		如果能殺死敵人，那麼傷害會提升你暴擊傷害係數的一半。]], "tformat")
t("Rocket Smash", "火箭重擊", "talent name")
t("@Source@ rockets forward!", "@Source@使用火箭突進向前！", "_t")
t("You are too close to build up momentum!", "離開目標太近無法施展！", "logPlayer")
t([[Dash forward using rockets.
		If the spot is reached and occupied, you will perform a free melee attack against the target there and knock them back 4 spaces as well as anyone else they collide with.
		This attack does 180% weapon damage.
		You must dash from at least 2 tiles away.]], [[藉助火箭向前突擊。
		如果目標地點已被佔據，那麼你到達的時候會對目標進行一次近戰攻擊並擊退他和任何被他撞到的目標 4 碼。
		這個攻擊會造成 180% 武器傷害。
		你必須突擊至少 2 格。]], "_t")
t("Laser Powered Smash", "激光重擊", "talent name")
t("@Source@ unleashes the power of the Gloryhammer!", "@Source@釋放了光榮之錘的終極力量！", "_t")
t([[Unleash the ultimate power of the Gloryhammer to all foes around in radius 1.
		This attack creates an explosion of radius 1 around every affected target, dealing 50% weapon damage and blinding them for 4 turns.]], [[釋放光榮之錘的終極力量，攻擊半徑 1 碼範圍內的所有敵人。
		這一攻擊會在每個受影響的目標身上引發半徑爲 1 的爆炸，造成 50% 武器傷害，並致盲他們 4 回合。]], "_t")

------------------------------------------------
section "tome-orcs/data/talents/misc/races.lua"

t("race", "種族技能", "talent category")
t("yeti", "雪人", "talent type")
t("The various racial bonuses a character can have.", " 多種多樣的種族天賦。", "_t")
t("Algid Rage", "寒冰之怒", "talent name")
t([[Your yeti is attuned to the cold climates.
		For 5 turns all damage you deal has %d%% chance to encase the target in an iceblock for 3 turns.
		While Algid Rage is up you easily pierce through iceblocks, reducing the damage they absorb by 50%%.
		The bonus will increase with your Willpower.]], [[你的雪人早已適應寒冷的環境。
		在 5 回合中你造成的所有傷害都有 %d%% 機率把目標凍在冰塊中 3 回合。
		在寒冰之怒生效中你可以輕鬆地穿透冰塊，減少 50%% 他們所吸收的傷害。
		數值會隨着你的意志提升。]], "tformat")
t("Thick Fur", "厚實毛皮", "talent name")
t("Your yeti's fur acts like a shield, providing %d%% cold resistance, %d%% physical resistance and %d magical save.", "你厚實的雪人毛皮能像盾牌一樣保護你，爲你提供 %d%% 寒冷抗性， %d%% 物理抗性和 %d 魔法豁免。", "tformat")
t("Resilient Body", "堅韌身軀", "talent name")
t([[Your yeti's body is very resilient to detrimental effects.
		Each time you are hit by a physical, magical, or mental detrimental effect your body reacts with a burst of healing.
		This effect heals for %d and can only occur up to 3 times per turn.
		It increases with your Constitution stat.]], [[你的雪人身軀面對負面狀態十分堅韌。
		每當你被一個負面的物理，魔法或精神狀態擊中時，你的身體會反射性地觸發恢復之力。
		這個效果會治療你 %d 生命值，且每回合最多觸發 3 次。
		治療值會受體質值加成。]], "tformat")
t("Mindwave", "腦波衝擊", "talent name")
t([[You willingly fry a few parts of your yeti's brain to trigger a huge psionic blast in cone of radius %d.
		Any foes caught in the blast will suffer %0.2f mind damage and be confused (35%% power) for %d turns.
		The damage will increase with your Constitution and the apply power will be the highest of your mind, spell, or physical power.]], [[你自主地將你的雪人大腦的一小部分燒熟，以此來在半徑 %d 碼的錐形裏釋放一發強大的精神衝擊。		
		任何陷入精神衝擊的敵人都會受到 %0.2f 精神傷害並被混亂（35%% 強度） %d 回合。
		傷害會受體質值加成，混亂效果應用強度則爲你物理，法術，精神強度中的最高者。]], "tformat")
t("whitehooves", "白蹄", "talent type")
t("Whitehooves", "白蹄", "talent name")
t([[Improves your undead body, increasing Strength and Magic by %d.
		Each time you move you gain a charge (up to %d) of death momentum, increasing your movement speed by 20%%.
		Each turn spent not moving you lose a charge.]], [[強化你的死靈身軀，增加 %d 的力量和魔力。
		每次你移動時都會獲得 1 層（最多 %d 層）死亡波紋，提升 20%% 你的移動速度。
		如果回合內你沒有移動，那麼你會失去一層死亡波紋。]], "tformat")
t("Dead Hide", "亡者之皮", "talent name")
t("Your undead skin hardens under stress. Each charge of death momentum also increases all flat damage resistance by %d.", "你的死靈皮膚在重壓之下會變得更加堅硬。每層死亡波紋都會提供 %d 的傷害減免。", "tformat")
t("Lifeless Rush", "無生突襲", "talent name")
t([[You summon your undead energies to instantly build up death momentum to its maximum possible charges.
		The effect will only start to decrease after %d turns.
		In addition, the death momentum effect also grants +%d%% to all damage per charge.]], [[你喚起你的死靈之力，瞬間獲得最大層數的死亡波紋。
		死亡波紋只會在 %d 回合後開始衰減。
		除此之外，每層死亡波紋還會提供 +%d%% 的全部傷害。]], "tformat")
t("Essence Drain", "吸取精華", "talent name")
t([[You send a wave of darkness at your foe, dealing %0.2f darkness damage.
		The darkness will drain a part of its life essence (only works on living targets) to increase the duration before the next charge of death momentum is used by %d.
		Only usable when you have the death momentum effect.
		The damage scales with your Magic stat.]], [[你對你的敵人釋放出一波黑暗能量，造成 %0.2f 暗影傷害。
		黑暗會吸取他的一部分生命精華（只對活着的目標有效）來延長死亡波紋在消耗下一層前的持續時間 %d 回合。
		只能在你有死亡波紋的時候使用。
		傷害會隨着你的魔力增長。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/psionic/action-at-a-distance.lua"

t("Condensate", "冷凝", "talent name")
t([[Condensate hot steam around your foes in radius %d, burning them for %0.2f fire damage and applying the wet effect for 4 turns, halving their stun resistances.
		The damage will increase with your Mindpower.]], [[在你敵人身邊的 %d 碼內冷凝熱蒸汽。對他們造成 %0.2f 火焰傷害並浸溼他們 4 回合。被浸溼的敵人的震撼抗性會減半。
		傷害受精神強度加成。]], "tformat")
t("Solidify Air", "固化空氣", "talent name")
t("solid air", "固化空氣", "_t")
t("a piece of solidified air", "一塊固化的空氣", "_t")
t([[You concentrate your will in a cone in front of you, condensing the air into a tangible, solid form.
		Any creatures caught inside take %0.2f physical damage.
		Any places with no creatures will be filled with solid air, blocking the way for %d turns.
		The damage will increase with your Mindpower.]], [[你集中精神力把你前方的錐形空間內的空氣凝聚成固態。
		任何陷入其中的生物都會受到 %0.2f 的物理傷害。
		任何沒被生物佔據的地方會被固化空氣佔滿，阻路 %d 回合。
		傷害受精神強度加成。]], "tformat")
t("Superconduction", "超導", "talent name")
t([[Call a streak of lightning on your target, dealing %0.2f to %0.2f lightning damage.
		If it is wet the lightning propagates to all foes in radius %d, doing the same damage to each.
		All affected foes are seared for 4 turns, reducing their fire resistance by %d%% and and mind save by %d.
		The damage will increase with your Mindpower.]], [[召喚一道閃電劈向你的目標，造成 %0.2f 到 %0.2f 閃電傷害。
		如果目標被浸溼了，那麼閃電擴散，對半徑 %d 碼內的所有單位造成同樣的傷害。
		所有被劈中的單位都會被燒焦 4 回合，降低他們的火焰抗性 %d%% 和精神豁免 %d 。
		傷害受精神強度加成。]], "tformat")
t("Negative Biofeedback", "負反饋", "talent name")
t([[Any time you deal damage with a psionic ability you incur a negative biofeedback in your foes, stacking up to %d times for 5 turns.
		Each stack reduces their physical save by %d, defense and armour by %d.
		This effect may only occur once per turn.]], [[每當你使用精神技能造成傷害時，你對你的敵人施加一個負反饋，能疊加至 %d 層並持續 5 回合。
		每層都會降低他們 %d 的物理豁免和 %d 的防禦與護甲。
		這個效果每回合只能觸發一次。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/psionic/gestalt.lua"

t("Gestalt", "格式塔", "talent name")
t([[You let your mind tap into your steam generators for energy, increasing your Mindpower in proportion to your steam level: %d when at full steam and 0 when at 0 steam.
		Using a psionic talent will feedback into your generators, increasing your Steam power by %d for your next steamtech talent.
		Using a steamtech talent will feedback into psionic focus, increasing your psi level by %d.
		The effects increase with your Willpower.]], [[你讓你的心靈從你的蒸汽發動機中汲取能量，按照你蒸汽的比例增加你的精神強度：滿蒸汽時 %d 點， 0 蒸汽時 0 點。
		使用精神技能會反饋你的發動機，爲你的下一個蒸汽技能增加 %d 點蒸汽強度。
		使用蒸汽技能會反饋你的精神，增加你的 %d 點你的靈能。
		效果受精神強度加成。]], "tformat")
t("Improved Gestalt", "強化格式塔", "talent name")
t([[When you use a steamtech talent while Gestalt is active you drain some residual power to form a psionic shield.
		The shield forms for 3 turns and absorbs %d damage.
		The effects increase with your Mindpower.]], [[每當你在格式塔激活狀態中使用蒸汽技能時，你會吸取一些殘留的力量來形成一個精神護盾。
		這個護盾持續 3 回合，並能吸收 %d 傷害。
		效果受精神強度加成。]], "tformat")
t("Instant Channeling", "瞬間引導", "talent name")
t("You must have either a psionic damage shield active or Improved Gestalt available to use this talent.", "你必須在格式塔在激活狀態且有一個精神護盾或者強化格式塔不在冷卻中的情況下使用這一技能。", "logPlayer")
t([[Instantly channel all of your remaining steam to replenish your psi energies and either enhance your active psionic damage shield or trigger a new one.
		The (new or existing) shield duration is increased by 3 turns and its power is boosted by %d%% of the steam used.
		You restore psi equal to %d%% of the steam used.
		This talent requires Gestalt to be active and either an active psionic damage shield or Improved Gestalt off cooldown.]], [[瞬間引導你剩餘的所有蒸汽來補充你的靈能並充能或製造一個新的精神護盾。
		護盾的持續時間會增加 3 回合，並能多吸收 %d%% 消耗的蒸汽數額的傷害。
		你回覆等同於 %d%% 所消耗的蒸汽數額的靈能。
		此技能需要格式塔在激活狀態且有一個精神護盾或者強化格式塔不在冷卻中。]], "tformat")
t("Forced Gestalt", "強力格式塔", "talent name")
t([[Temporarily expand your mind to force your Gestalt upon your foes in a radius of 5. Up to %d foe(s) will be affected.
		The Gestalt will drain each affected foe's powers (physical power, mind power, spell power and steam power) by %d for 5 turns.
		Your own powers will be increased in return by the drained amount (reduced for each additional foe).
		In addition for 5 turns you can sense creatures beyond your sight, even through walls in radius %d.
		The effects improve with your Mindpower.]], [[暫時延伸你的心靈以使你的格式塔籠罩你周圍半徑 5 碼內的敵人，最多可影響 %d 個敵人。
		格式塔會吸收每個被影響敵人的力量（物理強度，精神強度，法術強度，蒸汽強度） %d 點，持續 5 回合。
		你自身的力量會增加所吸取的數額（每多吸收一個額外的敵人，效果都會衰減）。
		除此之外，在 5 回合內你可以超脫視線的感知半徑 %d 碼內的生物。
		效果受精神強度加成。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/psionic/psionic-fog.lua"

t("Vaporous Step", "蒸汽步", "talent name")
t([[You concentrate your will to psychoport some of the steam of your generator to a remote location. Each turn steam accumulates there, up to %d charges.
		When you deactivate the effect you release the accumulated psionic and steam energies, instantly switching places with the target location and releasing the charges in a fiery explosion of hot wet steam in radius 4.
		The explosion will do %0.2f fire damage, multiplied by 33%% (diminutive) for each charge and apply the wet effect.
		The effect will fizzle if the charged grid is currently occupied by a creature or not in sight.
		The damage will increase with your Steampower.]], [[你集中精神來將一些你發動機中的蒸汽意念移動到遠方。 
		每回合蒸汽都會在那裏累積，最多 %d 層。
		當你解除狀態時，你會釋放累積的精神力和蒸汽，瞬間移動到該地點並製造一個半徑 4 碼的炙熱的蒸汽爆炸。
		爆炸將造成 %0.2f 乘以每層 33%% 的火焰傷害並附加浸溼狀態。
		如果目標地點已經被佔據或不在視線之內，則技能將失敗。
		傷害會受蒸汽值加成。]], "tformat")
t("Inhale Vapours", "吸入蒸汽", "talent name")
t([[When you deactivate Vaporous Step, if the psychoport succeeds you inhale some of the vapours, regenerating %d steam and %d life.
		The effects will be multiplied by 33%% (diminutive) for each charge of Vaporous Step.
		The healing done will increase with your Mindpower.]], [[當你解除蒸汽步時，如果意念移動成功了，你會吸入一些蒸汽，回覆 %d 蒸汽和 %d 生命。
		效果會乘以蒸汽步的層數乘以 33%% 。
		治療量受精神強度加成。]], "tformat")
t("Psionic Fog", "心靈迷霧", "talent name")
t([[Using the steam of your generators you shape it into a psionic fog that lasts %d turns. Any foes caught inside will take %0.2f damage per turn and be seared, reducing their fire resistance by %d%% and and mind save by %d.
		The damage will increase with your Mindpower.]], [[你將你發動機裏的蒸汽塑形爲持續 %d 回合的心靈迷霧。
		任何陷入其中的敵人每回合都會受到 %0.2f 的傷害，並被燒焦，降低他們 %d%% 火焰抗性和 %d 精神豁免。
		傷害受精神強度加成。]], "tformat")
t("Uncertainty Principle", "測不準原理", "talent name")
t("#STEEL_BLUE#(%d quantum shifted)#LAST#", "#STEEL_BLUE#(%d 量子轉移)#LAST#", "tformat")
t([[While inside a psionic fog the quantum state of space is warped by your powerful tech-augmented psionic powers.
		When you would get hit you instead find yourself in an adjacent location.
		This effect has a cooldown.]], [[你能在心靈迷霧中使用你被技術強化過的心靈力量來掌握空間的量子態本質。
		當你將被擊中時，你會閃現到一個臨近的位置。
		這個效果有冷卻時間。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/psionic/psionic.lua"

t("psionic", "靈能", "talent category")
t("gestalt", "格式塔", "talent type")
t("Harness steam energies to power your own mind.", "利用蒸汽能量來驅動你自己的思想。", "_t")
t("action at a distance", "遠程動作", "talent type")
t("Focus your mental energies to make things happen. Or combust.", "集中精神使事情發生。或者燃燒。", "_t")
t("psionic fog", "靈能之霧", "talent type")
t("Psionically manipulate steam to harass your foes and protect yourself.", "靈能操控蒸汽騷擾敵人並保護自己。", "_t")

------------------------------------------------
section "tome-orcs/data/talents/spells/galvanic-technomancy.lua"

t("Galvanic Rod", "放電柱", "talent name")
t("You need an arcane dynamo to cast this spell.", "你需要奧術發電機才能釋放這一法術。", "logPlayer")
t([[You summon a galvanic rod at a location. Upon arrival the rod releases a shock in radius %d dealing %0.2f galvanic damage (fire and lightning) to all creatures.
		You have 3 rods each with their own %d turns cooldown.
		This spell works with Burning Wake.
		This spell has 25%% chance to try to activate Hurricane, if used.
		The damage will increase with your Spellpower.]], [[你在指定位置召喚放電柱。放電柱會在 %d 碼半徑範圍內釋放電擊，對所有生物造成 %0.2f 放電（火焰和閃電）傷害。
		你有 3 枚放電柱，它們各自有 %d 回合的冷卻時間。
		這一技能可以觸發無盡之炎效果。
		這一法術有 25%% 的機率觸發風暴之怒。
		技能傷害受法術強度加成。]], "tformat")
t("Galvanic Arcing", "電弧放射", "talent name")
t([[Using your arcane power you force galvanic rods to linger for %d turns. While lingering they are inert, but can link up to other rods.
		When two rods are present in range %d of one another they link with a galvanic beam.
		When three rods are present in range %d of one another they link with a triangular galvanic zone.
		Any creature caught in a galvanic beam or zone take %0.2f galvanic damage per turn.
		You can maintain at most 3 rods.
		At level 3 all affected creatures are shocked, reducing their stun and pin resistances by half.
		At level 5 your weapon (if metallic, or embedded with a metallic tinker) acts as a rod that does not count towards your maximum.
		This spell has 15%% chance to try to activate Hurricane, if used.
		The damage will increase with your Spellpower.]], [[你使用奧術能量來讓放電柱額外停留 %d 回合。停留的放電柱不會活動，但是可以和其他放電柱建立鏈接。
		如果在 %d 碼範圍內有兩枚放電柱，它們會鏈接起來，形成一條放電射線。
		如果在 %d 碼範圍內有三枚放電柱，它們會鏈接起來，形成一個三角形的放電領域。
		任何被放電射線或放電領域擊中的生物都會每回合受到 %0.2f 放電傷害。
		你最多同時釋放三枚放電柱。
		技能等級 3 時，所有被影響的生物會被震撼，使他們的震懾和定身抗性減半。
		技能等級 5 時，你的金屬武器，或是裝載了金屬插件的武器，可以作爲一個放電柱使用，該放電柱不計入你的放電柱總量。
		這一法術有 15%% 的機率觸發風暴之怒。
		技能傷害受法術強度加成。]], "tformat")
t("Unstable Blast", "不穩定爆破", "talent name")
t("You need Galvanic Arcing active and at least one rod to cast this spell.", "你需要開啓電弧放射並至少有一個放電柱才能釋放這一法術。", "logPlayer")
t([[Reaching through the aether you temporarily destabilize a galvanic rod's control systems. (Using your weapon as a rod does not count as a valid target)
		This creates a blast in radius 1 around it, or through all connected rods if they are linked dealing %0.2f galvanic damage to all creatures and stunning them for %d turns.
		This spell works with Burning Wake.
		The damage will increase with your Spellpower.]], [[你召喚以太的能量，暫時使一枚放電柱的控制系統不穩定化。（你不能把自己武器作爲的放電柱當做該技能的釋放目標）
		這將會在 1 碼半徑內，或是在鏈接到的所有放電柱的領域內，產生一股衝擊波。對所有生物造成 %0.2f 放電傷害，並震懾它們 %d 回合。
		這一法術可以觸發無盡之炎效果。
		技能傷害受法術強度加成。]], "tformat")
t("Energy Mass Conversion", "質能轉換", "talent name")
t("You need Galvanic Arcing active and three rods to cast this spell.", "你需要開啓電弧放射並至少有三個放電柱才能釋放這一法術。", "logPlayer")
t([[Using large amounts of arcane power you create a supercharged Unstable Blast in your rods.
		The extra energy is briefly converted to a huge mass, pulling in all creatures (but you) in range %d of any rod towards the center of the galvanic field.
		Can only be used with a triangular field is setup.]], [[你使用大量的奧術能量，在你的放電柱中造成一股超載的不穩定爆破。
		額外的能量將會被轉化成巨大的質量，將在任何放電柱 %d 碼範圍內所有的生物（不包括你）拖向放電領域的中央。
		只能在激活了一個三角放電領域的時候纔可以使用。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/spells/occult-technomancy.lua"

t("Metaphasic Spin", "相位旋轉", "talent name")
t("You need an arcane dynamo to cast this spell.", "你需要奧術發電機才能釋放這一法術。", "logPlayer")
t("Select the steamsaw to use?", "使用哪把蒸汽鏈鋸？", "_t")
t([[You imbue a steamsaw with arcane and temporal forces, making it spin very fast around your waist (ignoring requirements).
		The saw spins so fast it it disturbs spacetime around you, increasing your spellpower by up to %d, your spell critical chance by up to %d and your mana regen by up to %0.1f (depending on steamsaw tier).
		Any successful melee attack against you also triggers an automatic steamsaw attack that cannot miss dealing %d%% weapon damage as occult damage (arcane and temporal).
		The steamsaw used will provide its bonus as if it was worn, but you can not Block with it.
		Increases steamsaws weapon damage by %d%% and uses Magic instead of Strength to determine their damage.
		If using Aether Avatar, all Occult Technomancy spells become usable for its duration and all occult damage becomes pure arcane.

		#{italic}#When you first learn this talent you also learn the Steamsaw tinker creation if you didn't already know it.#{normal}#
		]], [[你把奧術和時空能量注入一把蒸汽鏈鋸，讓他在你的手中飛速旋轉。（無視裝備需求）
		這把鏈鋸旋轉的速度是那麼快，它擾亂了你周圍的時空。最多增加你 %d 的法術強度， %d 的法術暴擊率，和 %0.1f 的法力值恢復（基於蒸汽鏈鋸的材質等級）
		任何對你的成功的近戰攻擊都會觸發一次必定命中的自動的蒸汽鏈鋸反擊，造成 %d%% 玄機（奧術和時空）武器傷害。
		使用這種方法裝備的蒸汽鏈鋸會提供裝備它所提供的屬性加成，但你不能使用它來格擋。
		增加蒸汽鏈鋸的武器傷害 %d%% ，並在使用蒸汽鏈鋸時用魔力值代替力量值計算傷害。
		如果你激活了以太之體，所有科技法術：玄機系的技能都可以在以太之體狀況下使用，並且它們所造成的傷害會被轉換成純淨的以太傷害。

		#{italic}#當你第一次學會這一技能的時候，如果你還沒有掌握蒸汽鏈鋸的配方，你還會同時學會這一配方。#{normal}#
		]], "tformat")
t("Reality Breach", "現實割裂", "talent name")
t("You need to activate Metatemporal Spinner to cast this spell.", "你需要開啓相位旋轉才能釋放這一法術。", "logPlayer")
t("#Source# annihilates '#Target#'!", "#Source#毀滅了'#Target#'!", "logCombat")
t([[Spin your saw at incredible speeds for an instant, fully breaking reality in a 3-wide beam in front of you.
		Any creatures caught by the beam take %0.2f occult damage and are untethered from reality, reducing their global speed by %d%% and the speed of any projectiles they fire by %d%% for 4 turns.
		At level 3 any projectiles caught in the beam are instantly annihilated.
		At level 5 the beam is so strong that all creatures caught inside are knocked back 3 tiles.
		The breach is so deep that the beam will always have the maximum possible length it can.
		The damage will increase with your Spellpower.]], [[讓你的鏈鋸以難以置信的速度飛速旋轉，撕裂周圍的現實，在你面前產生一條寬度爲 3 的射線。
		所有被射線擊中的生物將會受到 %0.2f 玄機傷害，並且進入脫離現實的狀態。它們的整體速度降低 %d%% ，發射的一切拋射物也會被減速 %d%% ，持續 4 回合。
		技能等級 3 時，射線範圍內的所有拋射物也會被立刻摧毀。
		技能等級 5 時，這一射線的力量是如此強大，所有被擊中的生物都會被擊退 3 碼。
		這一切裂是如此強大，射線必定會達到可能的最大射程纔會停止。
		傷害受法術強度加成。]], "tformat")
t("Ethereal Steam", "虛幻蒸汽", "talent name")
t([[You reach out through the aether to all creatures in sight that were slowed by Reality Breach or Congeal Time.
		For each target you create a link of arcane infused steam to it that lasts %d turns.
		Any time the target uses a talent one of your cooling down spells is reduced by 1 (prioritizing Technomancy spells).
		Each turn the link is up the target and any creature inside the link takes %0.2f occult damage.
		As long as at least one link is up, the cooldown of your Metaphasic Spin spell is set to 6 turns instead of 30.
		The damage will increase with your Spellpower.]], [[你通過以太，接觸視野內所有被現實割裂和時間凝固技能減速的生物。
		對於每一個目標，你會和它之間建立一條注入奧術能量的蒸汽組成的連接，持續 %d 回合。
		每當目標使用一個技能，你的一個法術的冷卻時間都會減少 1 回合。（優先降低科技法術的冷卻時間）
		在每一個回合，被連接的生物以及所有連接線上的生物，都會受到 %0.2f 玄機傷害。
		當至少有一個連接存在的時候，你相位旋轉技能的冷卻時間從30回合降低爲6回合。
		傷害受法術強度加成。]], "tformat")
t("Metaphasic Echoes", "相位迴響", "talent name")
t("You can only cast this spell on the turn after Reality Breach.", "你只有在使用現實切裂之後立刻釋放這一法術。", "logPlayer")
t([[Using your sheer arcane power you keep breaches in spacetime open for %d turns.
		Each turn they are open you project an occult clone of your saw along each breach, damaging any creature caught for %d%% occult weapon damage.
		The saw cuts both in a physical and arcane way, reducing the duration of a random beneficial effect on each target by %d each time.
		Each target can only be affected once per turn.
		This spell is only usable for one turn after casting Reality Breach but any Reality Breach cast during its duration is also recorded inside.]], [[你調動強大的奧術力量，在時空中切開的裂縫會保持開放，持續 %d 回合。
		在這一裂縫打開的每一回合裏，從裂縫中會投射一個你鏈鋸的玄機克隆，對所有擊中的生物造成 %d%% 玄機武器傷害。
		這一鏈鋸會在物理和奧術的意義上切裂敵人，每次擊中會降低目標身上一個隨機增益效果的持續時間 %d 回合。
		每個目標每回合只會被這一效果影響一次。
		這一技能只有在你使用現實切裂一回合後可以使用，但你在這一技能持續時間能釋放的其他現實切裂技能都會被記錄下來。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/spells/other-technomancy.lua"

t("Electron Incantation", "電子充能", "talent name")
t("You need an arcane dynamo to cast this spell.", "你需要奧術發電機才能釋放這一法術。", "logPlayer")
t("You can only cast this spell after casting an other technomancy spell.", "你只能在使用一個科技法術之後立刻釋放這一法術。", "logPlayer")
t([[After casting a technomancy spell you store some of its energies that you can then use to overload your arcane dynamo, increasing the steam it generates per 10 mana spent by 4 for 4 turns.
		In addition the energies spills outward in radius 3, dealing %0.2f damage (damage type based on the type of technomancy spell used).
		This spell is only usable after casting a technomancy spell and until you use any other spell or talent.
		The damage will increase with your Spellpower.]], [[每當你釋放一個科技法術，你都會儲存它一部分的能量，用來超載你的奧術發電機。每消耗 10 點法力值就會增加它產生的 4 點蒸汽值，持續 4 回合。
		此外，這些能量會在你周圍 3 碼半徑內溢出，造成 %0.2f 傷害。（傷害類型基於你使用的科技法術的類型）
		這個法術只可以在你剛剛施放了一個科技法術，且中途沒有釋放過其他法術的時候使用。
		技能傷害受法術強度提升。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/spells/spells.lua"

t("spell", "法術", "talent category")
t("undead drake", "亡靈飛龍", "talent type")
t("Take on the defining aspects of an Undead Drake.", "化身成爲亡靈龍形態使你能使用亡靈龍技能。", "_t")
t("galvanic technomancy", "科技法術: 放電", "talent type")
t("Combine the power of steamtech and arcane forces to destroy your foes with fire and lightning.", "結合蒸汽科技和奧術能量的力量，用火焰和閃電元素摧毀你的敵人。", "_t")
t("terrene technomancy", "科技法術：寒巖", "talent type")
t("Combine the power of steamtech and arcane forces to destroy your foes with earth and water.", "結合蒸汽科技和奧術能量的力量，用水和土元素摧毀你的敵人。", "_t")
t("occult technomancy", "科技法術: 玄機", "talent type")
t("Combine the power of steamtech and arcane forces to destroy your foes with arcane and time.", "結合蒸汽科技和奧術能量的力量，用奧術和時間元素摧毀你的敵人。", "_t")
t("other technomancy", "科技法術: 其他", "talent type")
t("Combine the power of steamtech and arcane forces to destroy your foes.", "結合蒸汽科技和奧術能量的力量，摧毀你的敵人。", "_t")

------------------------------------------------
section "tome-orcs/data/talents/spells/terrene-technomancy.lua"

t("Micro Spiderbot", "迷你蜘蛛機器人", "talent name")
t("You need an arcane dynamo to cast this spell.", "你需要奧術發電機才能釋放這一法術。", "logPlayer")
t([[You build %d micro spiderbot(s) from the earthly elements around you. Spiderbots are powered by an arcane cryogenic power unit directly linked to your own power.
		Spiderbots will deal %0.2f terrene damage (physical and cold) each turn to their targets. The deep cold of the attack has 25%% chance to freeze the feet of the target, pinning it to the ground for 5 turns.
		If a target dies, the spiderbot will jump onto a new target in range %d around you.
		If there are multiple spiderbots on a single target and more free targets are in range they will dispatch on as many as possible.
		If there are multiple spiderbots on a single target they attack as one, stacking their damage (with disminishing returns) and trying to freeze once.
		You can maintain up to %d spiderbots at once and each can last up to %d turns, but spiderbots need to be in sight to be able to act.
		The cooldown of this spell is affected by Body of Stone.
		The damage will increase with your Spellpower.

		You have currently %d spiderbot(s) up.]], [[你使用周圍的土元素製造 %d 個迷你蜘蛛機器人。蜘蛛機器人是由和你的力量相連的奧術致冷單元驅動的。
		蜘蛛機器人每個回合會對它們的目標造成 %0.2f 寒巖（物理和寒冷）傷害。極寒的攻擊有 25%% 的機率凍結目標的雙腳，將他們定身 5 回合。
		如果目標被擊殺了，蜘蛛機器人將會跳躍到你半徑 %d 碼範圍內的另一個敵人身上。如果這個目標上有多個機器人，並且在範圍內有足夠多的可選目標，他們會盡可能分散地跳到每個敵人身上。
		如果一個目標的身上附身了多個蜘蛛機器人，他們會一起攻擊，傷害會疊加（但收益遞減），並且會一起試圖凍結目標。
		你可以維持最多 %d 個蜘蛛機器人，他們最多存活 %d 回合。但是，只有在你視野範圍內的蜘蛛機器人才會行動。
		這一技能的冷卻時間受岩石身軀的影響。
		技能傷害受法術強度加成。

		你現在有 %d 個蜘蛛機器人。]], "tformat")
t("Cryogenic Digs", "低溫掘進", "talent name")
t([[Each time a spiderbot expires it digs around, producing either a Glacial Vapour (%0.2f cold damage and doing 30%% more damage to wet targets) or Earthquake (%0.2f physical damage and 25%% chances to stun for 2 turns) of radius 1 that last for %d turns.
		Those special kinds of Glacial Vapour and Earthquake do not affect the caster.
		The damage will increase with your Spellpower.]], [[每當一個蜘蛛機器人到持續時間時，它會鑽入地下，在 1 碼範圍內產生寒霜冰霧 （ %0.2f 寒冷傷害，對溼潤目標造成 30%% 額外的傷害）或地震（ %0.2f 物理傷害，有 25%% 機率震懾目標 2 回合）， 持續 %d 回合。
		這種寒霜冰霧或地震不會影響技能施放者。
		傷害受法術強度提升。]], "tformat")
t("Ramming Bot", "機器人衝撞", "talent name")
t("You need an arcane dynamo and an active spiderbot to cast this spell.", "你需要奧術發電機和一個活躍的蜘蛛機器人才能釋放這一法術。", "logPlayer")
t([[Command a random spiderbot to jump onto your target at ramming speed. The impact destroys the bot (possibly triggering Cryogenic Digs).
		This creates a radius %d explosion dealing %0.2f terrene damage to all creatures while also freezing them for %d turns and rendering them wet for %d turns.
		The cooldown of this spell is affected by Body of Stone.
		The damage will increase with your Spellpower.]], [[指揮一個隨機的蜘蛛機器人，跳起高速撞向你的目標。這一撞擊會立刻摧毀這個機器人。（可以觸發低溫掘進效果）
		這回造成一個半徑 %d 碼的爆炸，對所有生物造成 %0.2f 寒巖傷害，並凍結他們 %d 回合，使他們溼潤 %d 回合。
		這一技能的冷卻時間受岩石身軀的影響。
		傷害受法術強度提升。]], "tformat")
t("Spiderbot Shield", "機器人護盾", "talent name")
t([[You call back up to %d spiderbots to you to create protective barrier for %d turns.
		Spiderbots have %d life and they take damage in order, always fully absorbing the blow that destroyed them.
		If Cryogenic Digs is active when a spiderbot is destroyed it jumps to the attacker and triggers the dig there.
		The cooldown of this spell is affected by Body of Stone.
		]], [[你召回最多 %d 個蜘蛛機器人，在你的身邊形成一個保護屏障，持續 %d 回合。
		蜘蛛機器人有 %d 點生命值，會依次承受傷害。如果被摧毀，他們會完全承受摧毀他們的那一擊傷害。
		如果你激活了低溫掘進，被摧毀的機器人會跳向攻擊你的敵人，然後在那裏向下掘進。
		這一技能的冷卻時間受岩石身軀的影響。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/spells/undead-drake.lua"

t("Raze", "夷爲平地", "talent name")
t([[You revel in death, devouring the souls of your victims. Whenever you inflict damage to a target, you deal an additional %0.2f darkness damage.
		Additionally, you gain %d souls whenever you score a kill.
		The damage will scale with the highest of your spell or mind power and can only occur up to 25 times per turn.]], [[你在死亡中狂歡，吞噬你受害者們的靈魂。每當你對一個目標造成傷害時，你造成 %0.2f 額外暗影傷害。
		除此之外，每當你殺死敵人時你獲得 %d 個靈魂。
		傷害將會隨你法術強度和精神強度中較高者變化，且每回合最多觸發 25 次。]], "tformat")
t("Infectious Miasma", "疫毒瘴氣", "talent name")
t([[Release a cloud of deadly miasma over a targeted area, dealing %0.2f darkness damage to all units inside it with a 20%% chance of inflicting a disease that will do blight damage and weaken either Constitution, Strength or Dexterity for %d turns.
		The damage will scale with the highest of your spell or mind power.]], [[在目標區域釋放一個致命的瘴氣雲團，對其中所有的目標造成 %0.2f 暗影傷害並有 20%% 機率使其感染一個持續 %d 回合的疾病。疾病將造成枯萎傷害並降低體質，力量，或敏捷。
		傷害將會隨你法術強度和精神強度中較高者變化。]], "tformat")
t("Vampiric Surge", "吸血狂潮", "talent name")
t([[You surge with a life draining energy for %d turns.
		While the effect lasts, you heal yourself for %d%% of all damage you deal.]], [[你激發一波吸血能量，持續 %d 回合。
		在狀態持續中你造成的所有傷害的 %d%% 都將轉換爲你的生命。]], "tformat")
t("Necrotic Breath", "死靈吐息", "talent name")
t("@Source@ breathes a wave of darkness!", "@Source@吐出一波黑暗！", "_t")
t([[You breathe a wave of deathly miasma in a cone of radius %d. Any target caught in the area will take %0.2f darkness damage over 4 turns and receive either a bane of confusion or a bane of blindness for 4 turns.
		The damage will increase with your Magic, and the critical chance is based on your Spell crit rate.]], [[你向半徑 %d 的錐形內噴出致死瘴氣。任何被噴到的目標將在 4 回合內受到 %0.2f 暗影傷害並被混亂災禍或致盲災禍影響。
		傷害將會隨着你的魔力增長，並且暴擊率基於你的魔法暴擊率。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/artillery.lua"

t("Rocket Pod", "火箭發射器", "talent name")
t([[You equip an automated, shoulder mounted rocket launcher. Each turn it will launch rockets at up to %d enemies in weapon range, dealing %d%% steamgun damage as fire.
		The rockets will pass harmlessly through allies, but on-hit effects triggered by them only deal 50%% of their usual damage.]], [[你裝備着一款全自動的，肩抗式的火箭發射器。每個回合，他會自動向武器範圍內的 %d 個敵人發射火箭，造成 %d%% 的火焰蒸汽槍傷害。
		火箭可以安全地穿過盟友。火箭觸發的武器命中效果只造成50%%的傷害。]], "tformat")
t("Incendiary Powder", "燃燒粉末", "talent name")
t([[Augment your rockets with highly flammable materials, causing them to burn targets for %0.2f fire damage over 3 turns. Subsequent shots against burning targets refresh the effect of the duration (but do not stack) and inflict %0.2f additional fire damage.
Targets affected by this burning that fall below 25%% life enter a state of panic, giving them a %d%% chance each turn to flee in terror from you.
The fire damage will increase with your Steampower.]], [[用高度易燃的物質強化你的火箭，讓它們可以引燃目標，在 3 回合內造成 %0.2f 火焰傷害。繼續擊中被引燃的目標會刷新效果的持續時間（但不能疊加），並造成 %0.2f 額外火焰傷害。
被這一燃燒效果影響的目標若生命值降低到 25%% 以下，將會陷入恐慌的狀態，他們每回合有 %d%% 的機率在恐慌中逃離你。
火焰傷害受蒸汽強度加成。]], "tformat")
t("Lock On", "目標鎖定", "talent name")
t("You require a steamgun for this talent.", "你需要一把蒸汽槍才能使用這一技能。", "logPlayer")
t([[Lock on to your target with your rocket pod for 5 turns.
While locked on your regular rocket pod attacks are disabled. However, each turn you automatically fire a rocket barrage dealing %d%% increased damage at your target.
Marked targets also lose %d defense and cannot benefit from concealment or evasion.
The defense loss will increase with your Steampower.]], [[讓你的火箭發射器鎖定目標 5 回合。
當你鎖定目標的時候，自動火箭發射將會被暫停。然而，每回合你會朝目標發射火箭彈幕，造成額外 %d%% 的傷害。
被鎖定的目標也會失去 %d 閃避值，且躲閃效果和不可見帶來的閃避效果會被取消。
閃避值降低效果受蒸汽強度加成。]], "tformat")
t("Death From Above", "死亡天降", "talent name")
t([[You use your rocket pods to launch yourself into the air for 3 turns, firing a radius 2 barrage of rockets that deal %d%% steamgun damage as fire in radius 2. 
		While flying you gain %d%% movement speed, %d%% chance to evade melee and ranged attacks, and can reactivate this talent at will to repeat the rocket barrage.
		Using any talent other than Rocket Barrage will end this effect immediately.]], [[你啓動火箭發射器，將自己發射到天空中，持續 3 回合，同時發射範圍爲 2 的火箭彈幕，在 2 碼半徑內造成 %d%% 火焰蒸汽槍傷害。
		當處在飛行狀態的時候，你獲得 %d%% 移動速度， %d%% 機率躲閃近戰和遠程攻擊，並且可以重新激活這個技能，再次發射火箭彈幕。使用任何火箭彈幕之外的技能都會提前終止這一效果。]], "tformat")
t("Rocket Barrage", "火箭彈幕", "talent name")
t("Fires a barrage of rockets in radius 2, dealing %d%% steamgun damage as fire.", "發射火箭彈幕，在 2 碼半徑內造成 %d%% 火焰蒸汽槍傷害。", "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/automated-butchery.lua"

t("Continuous Butchery", "無盡屠戮", "talent name")
t("You require a steamsaw for this talent.", "你需要一把蒸汽鏈鋸才能使用這以技能。", "logPlayer")
t([[You attune your saws to a specific target for 5 turns.
		Each time you strike this target all damage done with steamsaws (including by other talents) is increased by +%d%%.
		If you strike any other foe the bonus ends.
		#{italic}#Metal your foes to death!#{normal}#]], [[用鏈鋸纏繞指定目標 5 回合。
		使用鏈鋸對此目標造成傷害時，傷害增加 %d%% （其他鏈鋸技能也可以加成）。
		當攻擊其他目標時，傷害加成效果結束。
		#{italic}#切碎他們！！#{normal}#
		]], "tformat")
t("Explosive Saw", "爆炸飛鋸", "talent name")
t([[You send a saw mounted on an automated steam propulsor to assault a foe, dealing %0.2f physical damage each turn for 4 turns and silencing it.
		At the end of the duration, the saw explodes for %0.2f fire damage and flies back, pulling the target up to %d tiles towards you.
		The damage will increase with your Steampower.]], [[你用自動蒸汽彈射器向敵人發射一把鏈鋸，造成 %0.2f 物理傷害並沉默敵人，持續 4 回合。
		持續時間結束後，鏈鋸爆炸，造成 %0.2f 的火焰傷害並飛回，將目標向你的位置拉扯 %d 格。 
		傷害受蒸汽強度加成。]], "tformat")
t("Mow Down", "肢解", "talent name")
t([[When you kill a foe with a melee strike you quickly throw some of their remains in your steam engine, instantly regenerating %d steam.
		When you deal a critical melee strike you also have a %d%% chance to cut a part of your foe and use it in your steam engine.
		When either of those happens this strikes fear in all foes in radius 4 of the victim, brainlocking them for %d turns.
		#{italic}#To the meat grinder!#{normal}#]], [[殺死敵人時，迅速將部分殘軀扔進蒸汽引擎，恢復 %d 蒸汽值。
		造成暴擊時也有 %d%% 概率切下敵人的軀體扔進引擎。
		任意一種行爲都會恐懼 4 格內的敵人，造成 %d 回合的思維封鎖效果。
		#{italic}#變成肉醬吧！！#{normal}#]], "tformat")
t("Tech Overload", "系統過載", "talent name")
t([[You override all security measures of your tinkers, allowing you to reset the cooldown of %d of most of your steamtech talents of tier %d or less and instantly increases your steam level by %d%% of the maximum.
		In addition for 6 turns your maximum steam capacity is doubled, but steam regeneration is halved.
		#{italic}#Master of Tech, Master of Death!#{normal}#]], [[你開啓全部插件的超頻模式，重置最多 %d 個蒸汽科技技能（ %d 層級或以下）的冷卻時間 ，直接恢復 %d%% 蒸汽值。
		在 6 回合內，蒸汽值最大值翻倍，但是恢復值減半。
		#{italic}#科技至尊、死亡之主！！#{normal}#]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/automation.lua"

t("Pulse Detonator", "脈衝爆彈", "talent name")
t([[Sends a pulse detonator to the target. Upon arrival it explodes in radius 4 cone, dealing %0.2f physical damage, knocking back foes by 3 and dazing them for %d turns.
		Damage increases with your steampower.]], [[向目標位置發射一發脈衝爆彈，當到達後爆炸形成範圍 4 的錐形衝擊波，對範圍內敵人造成 %0.2f 物理傷害，擊退 3 碼並造成 %d 回合的眩暈。
		]], "tformat")
t("Flying Grapple", "飛爪擒拿", "talent name")
t("Flying Grapple", "飛爪擒拿", "_t")
t("A flying grapple pull %s into %s!", "彈簧飛爪將%s拉向%s！", "logSeen")
t([[You send a small steam-powered flying grapple to a target. The drone is homing so if the target moves it will follow.
		When it reaches its target it deploys grapples in all directions around it in radius 4.
		The grapples latch onto any foes and pull them toward the target. If they are stopped by a creature (or the target) both them and the creature take %0.2f physical damage.
		]], [[向目標發射一枚自動制導的蒸汽動力無人機。
		命中目標後，無人機向 4 碼內的所有方向發射金屬飛爪。
		飛爪會抓住範圍內任何敵人，並將它們向目標拉扯。
		如果拉扯過程中被其他生物阻擋，兩者均受到 %0.2f 物理傷害。
		]], "tformat")
t("Net Projector", "束網彈射器", "talent name")
t("%s resists the net.", "%s抵抗了束網。", "logSeen")
t([[Sends a lightly electrified net of radius 2 toward a target, all creatures caught inside will be pinned in place for 5 turns.
		While the electricity is not enough to do damage it does shock their body, reducing all resistances by %d%%.]], [[向目標發射一張範圍 2 碼的輕質電場束網，範圍內的所有生物會被定身在原地，持續 5 回合。
		雖然電力不足以造成傷害，但是持續電擊會導致肢體麻痹，全體抗性性降低 %d%% 。]], "tformat")
t("Sawfield", "飛鋸領域", "talent name")
t([[For 4 turns many small saws circle around the target in radius %d, making any creature caught inside bleed for %0.2f physical damage.
		Damage increases with your steampower.]], [[發射出大量的小型飛鋸環繞目標飛行，範圍 %d 碼。 
		範圍內的所有生物受到 %0.2f 物理流血傷害。
		技能持續 4 回合。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/avoidance.lua"

t("Automated Cloak Tessellation", "披風護甲", "talent name")
t("@Source@ tessellates @hisher@ cloak!", "@Source@在@hisher@披風上佈滿金屬！", "_t")
t("You require a cloak to use this talent.", "你需要有披風才能使用這一技能。", "logPlayer")
t([[You tessellate your cloak with small pieces of metal, providing %d damage reduction against all attacks.
		The myriad metal scraps also help against incoming projectiles, providing a %d%% chance of deflecting them to a nearby spot.]], [[在披風上佈滿小塊金屬，對所有攻擊提供 %d 的傷害減免。
	大量的金屬碎片同時對遠程打擊提供偏移抵抗，有 %d%% 的概率將投射物反射至附近的其他位置。]], "tformat")
t("Cloak Gesture", "披風花招", "talent name")
t("@Source@ weaves @hisher@ cloak!", "@Source@揮舞@hisher@披風！", "_t")
t([[With a gesture of your cloak, you drop a small incendiary device in front of you, creating a wall of thick steam of %d length that burns creatures passing it for %0.2f fire damage and blocks sight for 5 turns.
		At level 5 the action is so perfect that your foes even lose track of you entirely.
		Damage increases with your steampower.]], [[在抖動披風的同時，在面前扔下一個小型的爆燃設備，產生一堵長度爲 %d 的濃密蒸汽牆。對穿越的生物造成 %0.2f 的火焰傷害，並且阻擋生物視線。效果持續 5 回合。
	技能等級 5 時，敵人會完全喪失你的行蹤，仇恨丟失。
	傷害受蒸汽強度加成。]], "tformat")
t("Embedded Restoration Systems", "嵌入式回覆系統", "talent name")
t("#LIGHT_BLUE#%s's embedded restoration system activate.", "#LIGHT_BLUE#%s的內置恢復系統啓動了。", "logSeen")
t("%s activates %s cloak's restoration systems!", "%s激活了%s披風的恢復系統!", "logSeen")
t("%s deactivates %s cloak's restoration systems.", "%s關閉了%s披風的恢復系統。", "logSeen")
t([[Your cloak is lined with an automated health system that activate when no enemies are visible.
		When it triggers, you will be healed for %d life.
		At talent level 3, it will also remove one detrimental physical effect.
		The system can only trigger once every %d turns.]], [[爲披風加裝嵌入式回覆系統，周圍沒有可見敵人時自動觸發，回覆 %d 生命值。
	技能等級 3 時，同時會消除一個物理負面效果。
	該系統每 %d 回合自動觸發一次。]], "tformat")
t("Cloaking Device", "屏蔽設備", "talent name")
t([[Trigger an array of small mirrors to appear all over your cloak.
		The mirrors are positioned to reflect all light shining on you, granting %d stealth power for 10 turns.
		Stealth power increases with your steampower.]], [[在披風上佈滿細小的反射鏡陣列，反射照射到你身上的所有光線，讓你直接潛形。
		獲得 %d 潛行強度，持續 10 回合。
		潛行強度受蒸汽強度加成。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/battle-machinery.lua"

t("Explosive Steam Engine", "引擎轟炸", "talent name")
t("critical steam engine", "不穩定蒸汽引擎", "_t")
t("trap", "陷阱", "_t")
t([[Throw a small, unstable steam engine on the battlefield that will go critical after 2 turns.
		It will then create an explosion of hot vapour in radius %d, burning all foes for %0.2f fire damage.
		Any bleeding foe caught in the flames will take 40%% more damage.
		Damage scales with your Steampower.
		#{italic}#Tick Tock Tick BOOM!#{normal}#]], [[在戰場上投擲一枚兩回合後爆炸的微型不穩定蒸汽引擎。
		爆炸後在 %d 碼範圍內產生灼熱的蒸汽雲霧，對範圍內敵人造成 %0.2f 的火焰傷害。
		流血狀態的敵人會受到 40%% 的額外火焰傷害。
		傷害受蒸汽強度加成。
		#{italic}#嘀嗒嘀嗒嘀嗒轟！！#{normal}#]], "tformat")
t("Lingering Cloud", "厚重雲霧", "talent name")
t([[Explosive Steam Engine vapour now lingers for 5 turns.
		Each turn, bleeding foes inside the cloud will take %0.2f fire damage.
		Any steamtech-using creature will also regenerate %d additional steam per turn while inside the cloud.
		Damage scales with your Steampower.
		#{italic}#Modern technology at the service of burnination!#{normal}#]], [[引擎轟炸產生的蒸汽雲霧現在會持續 5 回合。
		每回合雲霧範圍內的流血敵人會受到 %0.2f 火焰傷害。
		任何使用蒸汽科技的生物在雲霧中每回合額外回覆 %d 蒸汽值。
		傷害受蒸汽強度加成。
		#{italic}#嚐嚐最新科技帶來的燃燒服務吧！#{normal}#]], "tformat")
t("Tremor Engine", "巨震引擎", "talent name")
t("tremor engine", "巨震引擎", "_t")
t([[Throw a tremor engine on the battlefield that will trigger after 2 turns.
		For 5 turns after triggering, it will constantly shake the ground and stun, pin, or disarm any creature in radius %d for %d turns.
		#{italic}#The ground is mere paper to you!#{normal}#]], [[在戰場上投擲一枚兩回合後觸發的巨震引擎。
		觸發後 5 回合內，他會持續的造成地面的小範圍震動，震懾、定身或者繳械範圍 %d 內任何生物 %d 回合。
		#{italic}#你腳下是紙, 不是大地。顫抖吧！#{normal}#]], "tformat")
t("Seismic Activity", "地震爆發", "talent name")
t("raging volcano", "活火山", "_t")
t([[On its last pulse, your Tremor Engine shakes violently, raising a volcano for %d turns.
		Each turn, the volcano will send out fiery boulders that deal %0.2f fire and %0.2f physical damage.
		Damage scales with your Steampower.
		#{italic}#All the fury of fire at your disposal!#{normal}#]], [[巨震引擎的最後一次爆發輸出撕裂地面，引出岩漿，形成一座火山，持續 %d 回合。
		每回合，火山會噴出熔岩球，造成 %0.2f 火焰傷害 %0.2f 物理傷害。
		傷害受蒸汽強度加成。
		#{italic}#品嚐火焰之怒吧！#{normal}#]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/battlefield-management.lua"

t("Saw Wheels", "鏈鋸輪滑", "talent name")
t("You require a steamsaw for this talent.", "你需要一把蒸汽鏈鋸才能使用這以技能。", "logPlayer")
t([[Firmly plant your steamsaws in the ground, using them to propel yourself very quickly (+%d%% movement speed).
		Any foes on either side of your movement get wrecked by the saws, knocking them 3 tiles away from you.
		Attacking or using any talent will break this effect.
		When this effect is broken or cancelled the sudden change in motion deals %d%% weapon damage to all foes around you. To do full damage you need to have moved at least 5 times, otherwise damage is lower (or null for no movement).
		#{italic}#The wheels of death! Amazing!#{normal}#]], [[把鏈鋸深深插入地面，作爲履帶，增強自己的行動能力（移動速度增加 %d%% ）。
		在你移動路線兩側的敵人被鏈鋸割斷，被擊退 3 碼。
		攻擊或者使用其他技能的動作都會中斷效果 , 同時衝擊力對周圍的敵人造成 %d%% 武器傷害。你需要至少移動五次來達到最高傷害，否則傷害會降低。若不移動則沒有傷害。 
		#{italic}#衝鋒！死亡之輪！！#{normal}#]], "tformat")
t("Grinding Shield", "利齒護盾", "talent name")
t([[Spin your saws wildly around you to create a wall of steamy sawteeth.
		All melee damage against you is reduced by %d%%, you have %d%% chance to evade projectiles and you can never take a blow that deals more than %d%% of your max life.
		#{italic}#Split their bones on the saws of death!#{normal}#]], [[圍繞自身快速旋轉鏈鋸，形成一堵鏈鋸齒形成的牆壁。
		所有近戰傷害降低 %d%% ，有 %d%% 的概率迴避投射物，並且受到的一擊傷害不會超過最大生命值的 %d%% 。
		#{italic}#用死亡鏈鋸拆了他們的骨頭！！#{normal}#]], "tformat")
t("Punishment", "懲戒", "talent name")
t("#CRIMSON#%s unleashes a punishing strike for %d%% bonus damage!", "#CRIMSON#%s釋放一次懲罰打擊，造成%d%%額外傷害！", "logSeen")
t([[Slam your saws into your target, dealing 100%% weapon damage + %d%% per physical, magical, or mental effect on them (up to 7 effects).
			Sustains are not effects.
		#{italic}#The Metal Punisher!#{normal}#]], [[用鏈鋸猛力拍擊目標，造成 100%% + 每個物理、魔法或者精神狀態 %d%% 加成的傷害（最多 7 個）。
		持續技能不視作狀態。
		#{italic}# 鋼鐵懲戒！！#{normal}#]], "tformat")
t("Battlefield Veteran", "戰場老兵", "talent name")
t([[You have lived through many battles, and your experience makes you a gritty veteran.
		Saw Wheels end of effect attack increased by %d%%.
		Grinding Shield lets you live below your normal limits, up to -%d life.
		Punishment has a %d%% chance to have its cooldown reduced by 1 for each effect.
		#{italic}#Domination for all!#{normal}#]], [[你是一名堅毅的老兵，經歷了大量戰爭仍然能夠倖存，有着豐富的戰鬥經驗。
		鏈鋸輪滑的傷害增加 %d%% 。
		利齒護盾讓你超越生存下限，在 -%d 的生命下仍然生存。
		懲戒有 %d%% 的概率觸發：對象每具備一個效果，就降低懲戒 1 回合冷卻時間。
		#{italic}#一切盡在掌控！！#{normal}#]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/blacksmith.lua"

t("Massive Physique", "強壯體魄", "talent name")
t([[Working iron has honed your body into an amazing shape, granting %d strength and constitution.
		At talent level 5, you are so incredibly built that you gain one size category.]], [[長期打鐵，讓你的身體格外強壯，增加 %d 力量和體質。
		技能等級 5 時，你的肌肉是如此巨大，體型增大一個等級。]], "tformat")
t("Endless Endurance", "永不疲倦", "talent name")
t([[Working long hours at a forge has made you incredibly slow to tire and given you endless vitality.
		Your healing factor is increased by %d%% and your life regeneration by %0.2f.
		Stopping you is nearly impossible; your pinning resistance is increased by %d%%.]], [[長時間的鍛造工作讓你擁有不可思議的持久力和無盡的活力。
		你的治療係數增加 %d%% ，生命恢復增加 %0.2f 。
		你力大無窮，很難被阻止，定身抗性增加 %d%% 。]], "tformat")
t("Life in the Flames", "浴火而生", "talent name")
t([[Slaving for many years at the forge has made you more resilient to physical pain and fire burns.
		Your fire resistance is increased by %d%% and your physical resistance by %d%%.
		At talent level 5, you are so accustomed to the flames that you become immune to the fireburn effect.]], [[長時間的鍛造工作讓你對疼痛和火焰的忍耐力提高。
		火焰抗性增加 %d%% ，物理抗性增加 %d%% 。
		技能等級 5 時，你對火焰抗性極高，從而免疫燃燒狀態。]], "tformat")
t("Craftsman's Eye", "匠師之眼", "talent name")
t([[You can easily see the weak points in your enemy's defenses. After all, you know to look for the same flaws in your own work.
		This grants %d armour penetration and %d%% critical strike multiplier.
		At talent level 5, you can also fight stealthed and invisible creatures without penalty.]], [[你能夠像找到自己工作的錯誤一樣輕易發現敵人防禦的弱點。
		獲得 %d 的護甲穿透和 %d%% 的暴擊傷害加成。
		技能等級 5 時，能夠自如的與潛行和隱形生物戰鬥，無視減免。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/bullets-mastery.lua"

t("Overheat Bullets", "過熱子彈", "talent name")
t("You must dual wield steamguns for this talent.", "你需要雙持蒸汽槍才能使用這一技能。", "logPlayer")
t([[By sending a stream of hot steam over your bullets you overheat them. For the next %d turns, each bullet will set the target ablaze, making it burn for %0.2f fire damage over 5 turns (most of your shooting talents fire two bullets at once).
		Damage will increase with Steampower.
		Only one bullet enhancement can be used at once.]], [[使用蒸汽進行子彈的過熱處理。
		接下來的 %d 回合內，你的子彈會點燃目標，在 5 回合內造成 %0.2f 火焰傷害（大多數射擊技能一次發射兩枚彈藥）。
		一次只能使用一種彈藥強化能力。]], "tformat")
t("Supercharge Bullets", "超速子彈", "talent name")
t([[You are able to polish your bullets so well they can go through multiple targets for %d turns.
		This also improves their armour penetration by %d.
		Only one bullet enhancement can be used at once.]], [[精心打磨子彈，接下來的 %d 回合內，你的子彈能夠穿透多個目標。
		同時提高護甲穿透 %d 點。
		一次只能使用一種彈藥強化能力。]], "tformat")
t("Percussive Bullets", "衝擊子彈", "talent name")
t([[You swap your bullets for more massive ones for %d turns.
		When striking a creature, these bullets have a %d%% chance of knocking it back 3 tiles and a %d%% chance of stunning it for 3 turns.
		The chances to knockback and stun increase with your Steampower.
		Only one bullet enhancement can be used at once.]], [[爲了提高子彈的衝擊力，換用了巨型子彈。
		接下來的 %d 回合內，你的子彈擊中時有 %d%% 概率擊退目標 3 碼，同時有 %d%% 概率震懾目標 3 回合。
		擊退和震懾概率受蒸汽強度影響。
		一次只能使用一種彈藥強化能力。]], "tformat")
t("Combustive Bullets", "爆炸子彈", "talent name")
t([[You coat your bullets with flammable materials, for the next %d turns each bullet will explode when it hits its target, dealing %0.2f fire damage to all foes within radius 2 (most of your shooting talents fire two bullets at once).
		Damage will increase with Steampower.
		Only one bullet enhancement can be used at once.]], [[在子彈上覆蓋了可燃材料。在接下來的 %d 回合，子彈在擊中目標後都會爆炸，對 2 碼範圍內的敵人造成 %0.2f 火焰傷害（大多數射擊技能一次發射兩枚彈藥）。
		傷害隨蒸汽強度提高。
		一次只能使用一種彈藥強化能力。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/butchery.lua"

t("Steamsaw Mastery", "鏈鋸掌握", "talent name")
t("Increases weapon damage by %d%% and Physical Power by 30 when using steamsaws.", "使用鏈鋸時，提高 %d%% 武器傷害和 30 物理強度。", "tformat")
t("Overheat Saws", "過熱鏈鋸", "talent name")
t("You require two steamsaws for this talent.", "你需要兩把蒸汽鏈鋸才能使用這一技能。", "logPlayer")
t([[Channel hot steam around your saws, burning foes you strike in melee for %0.2f fire damage over 3 turns (which can stack)!
		#{italic}#Hot, steamy maiming!#{normal}#]], [[用蒸汽包裹鏈鋸，對近戰攻擊命中的目標在 3 回合內造成 %0.2f 點火焰傷害（可以疊加）。
		#{italic}#滾燙的蒸汽，死吧！#{normal}#]], "tformat")
t("Tempest of Metal", "金屬狂怒", "talent name")
t([[Continuously swing your steamsaws around you, dealing %d%% weapon damage to adjacent foes each time you attack.
		Your chaotic motions make it difficult for anything to hit you, granting %d%% chance to completely negate all damage.
		Damage avoidance chance increases with Steampower.
		#{italic}#Make the metal talk!#{normal}#]], [[持續揮舞你的鏈鋸，每次你攻擊時對周圍敵人造成 %d%% 武器傷害。
		你狂亂的動作使你很難被命中， %d%% 機率無視傷害。
		傷害無效概率隨蒸汽強度提高。
		#{italic}#感受金屬之怒吧！！#{normal}#]], "tformat")
t("Overcharge Saws", "鏈鋸過載", "talent name")
t([[You temporarily overcharge the saw motors, increasing the effective talent level of all saw talents by %d%% for %d turns.
		#{italic}#The pain shall never stop!#{normal}#]], [[鏈鋸引擎臨時進入過載模式，增加 %d%% 的鏈鋸相關技能有效等級 , 持續 %d 回合。
		#{italic}#無盡地痛苦#{normal}#]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/chemical-warfare.lua"

t("Miasma Engine", "瘴氣引擎", "talent name")
t([[You repurpose your steam engine to emit a cloud of toxic, corrosive chemicals around you.
		Each time you use a non-instant steamtech talent, you create a radius 3 cloud of miasma for 5 turns. All enemies within the miasma have %d%% reduced healing and %d%% chance to fail talent usage.
		Each time miasma is reapplied the failure chance increases, up to %d%% after 5 reapplications.
		The first time each turn a target affected by miasma is hit by a melee or ranged attack the miasma seeps into their wounds, dealing an additional %0.2f acid damage.
		Miasma duration does not increase on re-apply.
		When a creature survives the miasma it becomes immune to it for 9 turns.]], [[你使用你的蒸汽機，在你的周圍產生一股有毒且有腐蝕性的化學物質形成的雲霧。
		每當你使用一個非瞬發的蒸汽科技技能的時候，你會在周圍產生半徑爲 3 碼的瘴氣，持續 5 回合。所有被包裹入瘴氣的敵人治療效果減少 %d%% ，且會有 %d%% 的機率使用技能失敗。
		瘴氣效果疊加的時候，這一技能使用失敗的機率也會上升，最多疊加五次，達到 %d%% 。
		當被瘴氣影響的目標每回合第一次被近戰或遠程攻擊擊中的時候，瘴氣會滲入他們的傷害，造成 %0.2f 額外的酸性傷害。
		瘴氣效果疊加的時候，持續時間不會疊加。
		當一個生物在瘴氣效果中存活下來後，它會免疫瘴氣效果 9 回合。]], "tformat")
t("Caustic Dispersal", "腐蝕擴散", "talent name")
t("You require a steamgun for this talent.", "你需要一把蒸汽槍才能使用這一技能。", "logPlayer")
t("You fire a toxic shell that explodes in radius %d, dealing %d%% weapon damage as acid and leaving behind a cloud of miasma for %d turns that inherits all effects from your Miasma Engine.", "你發射一枚毒氣彈，在半徑 %d 碼範圍內爆炸，造成 %d%% 酸性武器傷害，並留下一團瘴氣，持續 %d 回合。瘴氣效果繼承你瘴氣引擎技能的一切效果。", "tformat")
t("Smogscreen", "蔽目毒雲", "talent name")
t("You become difficult to target through the thick smog generated by your Miasma Engine. While surrounded by miasma you have a %d%% chance to entirely avoid damage, increased by %d%% per stack.", "在你的瘴氣引擎造成的濃霧中，敵人更難擊中你了。當你被瘴氣包裹的時候，你有 %d%% 的機率完全閃避傷害。瘴氣的半徑每疊加一層，則效果增加 %d%% 。", "tformat")
t("Fumigate", "毒氣薰殺", "talent name")
t("You require a steamgun and an active miasma cloud for this talent.", "你需要一把蒸汽槍和一個活躍的瘴氣雲霧才能使用這一技能。", "logPlayer")
t([[You consume all Miasma Engine stacks you have to fire a blast of corrosive death through your steamgun, dealing %d%% weapon damage as acid in a radius %d cone with a %d%% chance to remove a random beneficial physical or mental effect. For every stack beyond the first the damage dealt is increased by 50%% and there is a %d%% chance to remove an additional effect.
		This attack ignores all enemy armour, and you must have at least 1 stack of Miasma Engine to use this talent.]], [[你消耗所有瘴氣引擎的疊加效果，並用你的蒸汽槍發射出毀滅性的腐蝕爆炸，在 %d 碼範圍的扇形區域內造成 %d%% 酸性武器傷害，並有 %d%% 的機率移除一個隨機物理或精神效果。你瘴氣引擎疊加的層數每超過一層，則增加 50%% 傷害，並有 %d%% 機率額外移除一個效果。
		這一攻擊無視敵人護甲，你至少需要有一層瘴氣引擎效果才能使用這個技能。]], "tformat", {2,1,3,4})

------------------------------------------------
section "tome-orcs/data/talents/steam/chemistry.lua"

t("Therapeutics", "治療學", "talent name")
t([[Allows you to create therapeutic tinkers of level %d.
		You will learn a new schematic at level 1.
		Each other talent level, you have a 20%% chance to learn one more random schematic, if you have not gained it by level 5 you are guaranteed it (unless all are known).
		%s]], [[允許你製造 %d 等級的治療學道具。
	1 級時必定獲得一個配方。之後每一級有 20%% 的概率獲得一個新配方。如果到 5 級還沒有獲得第二個新配方，就必定再獲得一個新配方。
		%s]], "tformat")
t("Chemistry", "化學", "talent name")
t([[Allows you to create chemical tinkers of level %d.
		You will learn a new schematic at level 1.
		Each other talent level, you have a 20%% chance to learn one more random schematic, if you have not gained it by level 5 you are guaranteed it (unless all are known).
		%s]], [[允許你製造 %d 等級的化學道具。
	1 級時必定獲得一個配方。之後每一級有 20%% 的概率獲得一個新配方。如果到 5 級還沒有獲得第二個新配方，就必定再獲得一個新配方。
		%s]], "tformat")
t("Explosives", "爆炸學", "talent name")
t([[Allows you to create explosive tinkers of level %d.
		You will learn a new schematic at level 1.
		Each other talent level, you have a 20%% chance to learn one more random schematic, if you have not gained it by level 5 you are guaranteed it (unless all are known).
		%s]], [[允許你製造 %d 等級的爆炸學道具。
	1 級時必定獲得一個配方。之後每一級有 20%% 的概率獲得一個新配方。如果到 5 級還沒有獲得第二個新配方，就必定再獲得一個新配方。
		%s]], "tformat")
t("Steam Power", "蒸汽動力", "talent name")
t("Increases the efficiency of all steamtech you operate, granting %d steampower.", "提高所有蒸汽設備的效果，獲得 %d 點蒸汽強度。", "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/demolition.lua"

t("Grenade Launcher", "榴彈發射器", "talent name")
t([[You mount a grenade launcher on your steamgun that launches high explosive rounds. Each time you make a basic attack with your steamgun or a heavy weapon, you fire a grenade at the target that explodes for %d%% steamgun damage in radius %d.
		This talent also reinforces the armor of you and your minions to give you immunity to your own grenades.
		You can only fire a single grenade once every 9 turns.]], [[你在蒸汽槍上裝在一個榴彈發射器，它可以發射高度爆炸性的彈藥。每當你使用蒸汽槍或重裝武器射擊的時候，你會朝目標發射一枚手榴彈，爆炸在 %d 碼範圍內造成 %d%% 蒸汽槍傷害。
		這一技能也會強化你的護甲，你的隨從免疫你的手榴彈效果。
		你每 9 回合內最多發射一枚榴彈。]], "tformat", {2,1})
t("Reactive Armor", "反應式裝甲", "talent name")
t([[You line your armor with explosive plating that detonates when struck. On taking a melee or ranged hit that deals more than 8%% of your maximum life a plate detonates, reducing the damage taken by %d%% and triggering a basic grenade attack in a radius %d cone projected at the target dealing %d%% of its usual damage.
		This cannot trigger more than once per turn.
		Blocking an attack with your shield will also trigger the retaliation damage, if it has not already triggered this turn.
		You have up to 3 plates at a time, and regain one every %d turns.]], [[你在你的護甲上嵌入爆炸物裝甲層，在被攻擊的時候會發生爆炸。在近戰或遠程攻擊對你造成超過最大生命值 8%% 的傷害的時候，裝甲層會發生爆炸，降低所受到的傷害 %d%% 並在目標方向 %d 碼範圍的扇形區域內觸發一次手榴彈攻擊，造成平常的手榴彈 %d%% 的傷害。
		每回合最多觸發一次該效果。
		如果該回合內沒有觸發過這一效果，使用盾牌格擋攻擊也可以觸發這樣的反擊傷害。
		你最多同時能有 3 層護甲層，每 %d 回合會補充一層。]], "tformat")
t("Sapper", "爆破工兵", "talent name")
t([[You load advanced grenades into your launcher.
	Incendiary Grenade: Deals fire damage over 3 turns, increasing damage taken by %d%%.
	Chemical Grenade: Deals acid damage and slows targets by %d%% for 3 turns.
	Shock Grenade: Deals lightning damage and shocks targets for %d turns, reducing stun and pin resistance by 50%%.
	In addition, your turrets now explode when destroyed, dealing %0.2f physical damage to enemies in radius 3.
	You can only choose a single type of grenade at a time.]], [[你往你的發射器內裝入高級榴彈。
		燃燒榴彈：在 3 回合內造成火焰傷害，增加所受到的傷害 %d%% 。
		化學榴彈：造成酸性傷害，減速目標 %d%% ，持續 3 回合。
		震盪榴彈：造成閃電傷害，震撼目標 %d 回合，使目標震懾和定身抗性減少50%% 。
		另外，你的炮臺被摧毀的時候會引發爆炸，對半徑 3 碼內的敵人造成 %0.2f 物理傷害。
		你只能同時激活一種榴彈類型。]], "tformat")
t("Barrage", "榴彈轟炸", "talent name")
t("You require a steamgun and an empty grenade launcher for this talent.", "你需要一把蒸汽槍和一個空的榴彈發射器才能使用這一技能。", "logPlayer")
t([[You load a magazine of %d grenades into your launcher, causing your next %d shots to fire a random grenade type in place of your usual Grenade Launcher, dealing 50%% of the usual grenade damage.
		While the magazine is loaded your attack speed is increased by %d%%.
		Your Grenade Launcher talent must be on cooldown to use this talent, and the magazine will only last for 6 turns.]], [[你往發射器中裝入一組 %d 發榴彈，讓你接下來的 %d 次射擊時會從榴彈發射器中發射一枚隨機類型的榴彈，造成 50%% 榴彈傷害。
		當你裝入榴彈後，你的攻擊速度提高 %d%% 。
		你的榴彈發射器技能必須處於冷卻狀態才能使用該技能。裝入的榴彈最多持續 6 回合。]], "tformat")
t("Incendiary Grenade", "燃燒榴彈", "talent name")
t("Enhance your grenade with an incendiary agent that burns through armor, dealing fire damage over 3 turns and increasing damage taken while burning by %d%%.", "用高度易燃物質強化榴彈，燒蝕敵人護甲，3回合內造成火焰傷害，在目標燃燒時增加所受到的傷害 %d%% 。", "tformat")
t("Chemical Grenade", "化學榴彈", "talent name")
t("Enhance your grenade with incapacitating chemicals that deal acid damage and reduce global speed by %d%% for 3 turns.", "用致殘化學物質強化榴彈，造成酸性傷害，降低目標整體速度 %d%% ，持續 3 回合。", "tformat")
t("Shock Grenade", "震盪榴彈", "talent name")
t("Enhance your grenade with an electrical charge, causing it to deal lightning damage and shock targets for %d turns, reducing stun and pin resistance by 50%%.", "用電力彈藥強化榴彈，造成閃電傷害，震撼敵人 %d 回合，震懾和定身抗性降低50%%。", "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/dread.lua"

t("Mechanical Arms", "機械巨臂", "talent name")
t([[Using psionic forces you maintain in place on your back two giant horrific mechanical arms.
		Each basic turn (as if you had 100%% speed) they can automatically attack up to 2 foes within range 3 with a mindstar attack doing %d%% weapon damage.
		Creatures harassed by the mechanical arms have their damage reduced by %d%% for 5 turns.]], [[你使用靈能操控背後的兩個恐怖的機械巨臂。
		每個基礎回合（如果你的整體速度爲100%%的話）機械巨臂能夠使用靈晶自動攻擊 3 碼內的最多兩個敵人，造成 %d%% 武器傷害。
		被機械巨臂攻擊的目標傷害降低 %d%% ，持續 5 回合。]], "tformat")
t("Lucid Shot", "醒神射擊", "talent name")
t("You require a steamgun for this talent.", "你需要一把蒸汽槍才能使用這一技能。", "logPlayer")
t([[Fire a powerful shot at a foe doing %d%% weapon damage.
		If the creature, or any creatures in radius 3, was affected by a fear or nightmare effect it violently wakes up, shaking it off only to find itself disoriented, unable to discern friends from foes for %d turns.]], [[對一個敵人進行一次強力射擊，造成 %d%% 的武器傷害。
		目標三碼範圍內被恐懼或者噩夢效果影響的生物將被突然驚醒而處於迷失狀態，無法分辨敵我，持續 %d 回合。]], "tformat")
t("Psy Worm", "靈能蠕蟲", "talent name")
t([[Fire a psionic-enhanced shot at a foe doing %d%% mind weapon damage and infecting it with a psy worm for 8 turns.
		Each turn the worm will do %0.2f mind damage and restore %d psi to you, double if stunned or feared.
		Also each turn the worm has 25%% chances to spread to a nearby foe in radius 3.
		When a creature infected by Psy Worm dies it spreads to all enemies in a radius of 3.]], [[對一個敵人進行一次靈能強化射擊，造成 %d%% 精神武器傷害，同時使目標感染持續 8 回合的靈能蠕蟲。
		蠕蟲每回合造成 %0.2f 精神傷害，併爲你回覆 %d 點靈能。
		如果目標處於震懾或者恐懼狀態，效果翻倍。
		另外，蠕蟲每回合有 25%% 的概率感染 3 碼內的所有其他敵人。]], "tformat")
t("No Hope", "無助深淵", "talent name")
t("Entering the mind of your foe you manipulate it to make it lose hope of defeating you, reducing all its damage by 40%% for %d turns.", [[操縱敵人的思維，讓敵人失去戰勝你的希望。
		降低敵人 40%% 的全部傷害，持續 %d 回合。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/elusiveness.lua"

t("Slip Away", "身如游魚", "talent name")
t([[Using small steam motors to enhance your movements, you are able to slip past up to %d foes in a line.
		After passing the targets, you will quickly run %d tiles away.]], [[用小型噴射引擎強化你的機動性，可以穿過直線上連續的 %d 個敵人。
	穿越後，會急速前進 %d 碼。]], "tformat")
t("Agile Gunner", "動若脫兔", "talent name")
t([[The thrill of the hunt invigorates you. For each foe in radius %d around you, you gain 20%% movement speed (up to %d%%).
		Current bonus: %d%%.]], [[被獵殺的危險令你激動不已。
		半徑 %d 內每有一個敵人，你獲得 20%% 移動速度（最多 %d%% ）。
		當前加成： %d%% 。]], "tformat")
t("Awesome Toss", "致命翻轉", "talent name")
t("You require two steamguns for this talent.", "你需要兩把蒸汽槍才能使用這一技能。", "logPlayer")
t([[In an awesome feat of agility and technological prowess, you toss both of your steamguns in the air, causing them to spin madly for 3 turns.
		Each turn, they will fire twice at random targets in range, dealing %d%% weapon damage.
		While the guns are airborne, you are disarmed and cannot attack.
		The spectacle is so distracting that your foes have a hard time concentrating on you, increasing all of your resistances by %d%%.]], [[在驚人的靈巧和科技力量下，你將你的蒸汽槍翻轉指向天空，持續旋轉 3 回合。
		每回合，蒸汽槍將隨機射擊 2 次，造成 %d%% 武器傷害。
		效果持續期間，你視爲被繳械，不能攻擊。
		這場表演如此引人注目，你的敵人都被吸引，使你的傷害抗性增加 %d%% 。]], "tformat")
t("Dazzling Jump", "炫目大跳", "talent name")
t("%s seems immune to the powerful kick.", "%s對強力的踢腿免疫。", "logSeen")
t([[While your foes are distracted by your Awesome Toss, you use powerful steam motors to jump into the air and kick a target %d tiles away.
		The impact is so great that it ripples outwards, slowing all creatures in radius 3 by %d%% for 4 turns while the reaction force propels you %d tiles backwards.]], [[當你的敵人被致命翻轉吸引時，你啓動強力的蒸汽引擎，跳向空中，將目標踢走 %d 碼。 
		這次攻擊衝擊力非常大，半徑 3 以內所有生物將被減速 %d%% ，持續 4 回合。
		反衝力也讓你後退 %d 碼。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/engineering.lua"

t("Emergency Steam Purge", "緊急蒸汽排出", "talent name")
t([[You open all steam valves at once, releasing a radius %d wave of superheated steam around yourself which deals %0.2f fire damage (but can not be a critical hit).
		If you had at least 35 steam, the vapours will be so hot that they can burn sensory organs, blinding affected creatures for %d turns.
		The effects scale with your current steam value; at 1 steam they are only 15%% as effective as at 50 or more (current factor %d%%).]], [[你打開所有蒸汽閥，釋放半徑 %d 的蒸汽衝擊波，造成 %0.2f 火焰傷害。（這一技能無法暴擊）
		若你有至少 35 點蒸汽，氣體的溫度將變得極高，能燒傷感知器官，令受影響的生物目盲 %d 回合。 
		效果受當前蒸汽值加成。 1 點蒸汽值時，強度僅爲 50 或更高點蒸汽值的 15%% 。
		當前強度係數 %d%% 。]], "tformat")
t("Innovation", "創新", "talent name")
t([[Your knowledge of physical laws allows you to use and improve equipment in ways their creators never dreamed.
		Increases all stats, saves, armour, and defense bonuses by %d%% on equipment that is crafted by a master or powered by steamtech.]], [[你對物理學的瞭解令你能以全新的方式改進裝備。
		增加大師製作或者蒸汽科技的裝備提供的屬性、豁免、護甲和閃避 %d%% 。]], "tformat")
t("Supercharge Tinkers", "插件超頻", "talent name")
t([[Using a huge amount of steam, you temporarily supercharge your tinkers and other steam-powered talents.
		For %d turns, you gain %d steampower and %d%% steamtech critical chance.]], [[消耗大量蒸汽，令所有配件和蒸汽技能超頻工作 %d 回合。
		超頻期間，你獲得 %d 蒸汽強度和 %d%% 蒸汽技能暴擊率。]], "tformat")
t("Last Engineer Standing", "背水一戰", "talent name")
t([[Sometimes, being a master tinker requires taking risks; yours are more calculated than others.
		Gain %d cunning, %d physical save, %d%% resistance to self-inflicted damage, and %d%% chance to avoid being critically hit.]], [[成爲大師意味着你經歷了更多危險，你的計算力也超越凡人。
		增加 %d 靈巧， %d 物理豁免， %d%% 自身傷害抗性， %d%% 機率避免暴擊。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/furnace.lua"

t("Furnace", "熔爐", "talent name")
t([[You add a portable furnace to your steam generators.
		While it is active your fire and physical damage increases by %d%% and your fire and physical resistance penetration by %d%%.
		#{italic}#Burninate all with awesome Steam power!#{normal}#
		]], [[你往蒸汽製造機中安裝一個便攜式熔爐。
		熔爐激活時，你的物理和火焰傷害增加 %d%% ，物理和火焰抗性穿透增加 %d%% 。
		#{italic}#用蒸汽燒盡一切！#{normal}#
		]], "tformat")
t("Molten Metal", "融化金屬", "talent name")
t([[While Furnace is on your armour is so hot from the furnace it dissipates parts of all energy based attacks against you.
		All non physical, non mind damage is reduced by %d (current %d).
		Each turn this happens you gain a molten point (up to 10), decreasing the efficiency of the reduction by 25%%.
		Molten points are removed upon running or resting.
		#{italic}#Hot liquid metal, the fun!#{normal}#
		]], [[你的護甲溫度極高，能驅散部分能量攻擊。
		所有非物理、非精神傷害降低 %d 點（當前 %d ）。
		每回合該效果觸發時，你獲得 1 點融化點數（最多 1 0 點），減少 25%% 減傷效率。
		奔跑和休息將取消融化點數。
		#{italic}#火熱的液態金屬，樂趣無窮！#{normal}#
		]], "tformat")
t("Furnace Vent", "通風孔", "talent name")
t([[Open the vents on your furnace, creating a conic blast dealing up to %0.2f fire damage at 10 molten points (currently %0.2f).
		All molten points are consumed.
		The damage will increase with your Steampower.
		#{italic}#By fire be purged!#{normal}#
		]], [[打開熔爐通風孔，製造錐形熱風，在 1 0 點融化點數時造成最多 %0.2f 火焰傷害（當前 %0.2f 點）。
		消耗所有融化點數。
		#{italic}#讓火焰淨化一切！#{normal}#
		]], "tformat")
t("Melting Point", "熔點", "talent name")
t([[When you reach 10 molten points your armour overheats, reaching temperatures so high that they cauterize up to %d detrimental physical effects on you.
		A special medical injector injects you with a fire immunity serum at that precise moment to make you immune to the burning effect.
		When this happens all molten points are consumed and trigger a Furnace Vent at the creature that triggered the last molten point.
		This effect drains 15 steam when triggered, and will not trigger if steam is too low.
		#{italic}#It's only a flesh burn!#{normal}#
		]], [[當你達到 1 0 點融化點數時，你的護甲過熱，溫度極高，以至於 %d 個負面物理狀態被高溫驅散。
		同時，一種特殊的藥物注射器將注射一種火焰免疫藥劑，令你免疫燒傷效果。
		該效果觸發時，消耗所有融化點數，並自動觸發一次通風孔效果，目標爲最後一次提供融化點數的生物。 
		該效果將消耗 1 5 點蒸汽。蒸汽不足時不能觸發。
		#{italic}#只是肉體在燃燒!#{normal}#
		]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/gadgets.lua"

t("Autoloader", "自動填彈器", "talent name")
t([[You link your weapons and shield to your steam generators, using them to load ammunition and improve the power of your weapons. 
		Each time you fire your Steamgun, you have a %d%% chance to reload 1 Heavy Weapon ammo.
		Each time you fire a Heavy Weapon you reload %d ammo.
		Each time you raise your shield to block, you reload 1 Heavy Weapon ammo.
		This also increases weapon damage by %d%% and Physical Power by 30 when using steamguns or heavy weapons.
		In addition, your steamgun and heavy weapon shots now bypass friendly targets harmlessly.]], [[你將武器和盾牌連接到蒸汽機，使用它們來爲你的武器填充彈藥，並強化武器的能力。
		每當你使用蒸汽槍射擊的時候，有 %d%% 的機率填充一枚重裝武器的彈藥。
		每當你使用重裝武器射擊的時候，會填充 %d 枚彈藥。
		每當你使用盾牌格擋的時候，會填充一枚重裝武器的彈藥。
		這一技能也會在你使用蒸汽槍或重裝武器的時候提升武器傷害 %d%% ，提升物理強度 30 。
		另外，你的蒸汽槍和重裝武器射擊可以安全地穿過友方目標。]], "tformat")
t("Exoskeleton", "機械外骨骼", "talent name")
t("#STEEL_BLUE#(%d exoskeleton)#LAST#", "#STEEL_BLUE#(%d外骨骼)#LAST#", "tformat")
t([[Current exoskeleton life: %d/%d
		You craft a set of steam powered armor that fits over your regular armor, enhancing your defense. The armor has %d life, and 50%% of all damage taken is redirected to it.
		Your powered armour repairs 5%% of it’s maximum life each turn, and each time you spend steam it will be repaired for %d%% of the steam cost.
		The armor's maximum life will increase with your Steampower.]], [[當前機械外骨骼生命值： %d / %d
		你製造一臺蒸汽驅動的機械外骨骼，可以裝載在你平常的護甲外面，增強你的防禦能力。機械外骨骼具有 %d 生命值，你受到的所有傷害的 50%% 會轉移到它身上。
		你的機械外骨骼每回合會修復 5%% 的最大生命值，每當你消耗蒸汽的時候，他也會修復相當於蒸汽值消耗 %d%% 的生命值。
		外骨骼的最大生命值受蒸汽強度加成。]], "tformat")
t("Hypervision Goggles", "強化視覺護目鏡", "talent name")
t([[Enhance your vision for %d turns, giving you vision of all targets in range %d, even through walls. While the goggles are active you also spot flaws in your opponent's defenses, increasing your resistance penetration by %d%%.
In addition, the goggles passively increase your stealth, invisibility and trap detection by %d.]], [[強化你的視覺，持續 %d 回合。你將能看到半徑 %d 碼範圍內的所有目標，該效果可以穿牆。當護目鏡激活的時候，你也能注意到敵人防禦上的弱點，增加你的抗性穿透 %d%% 。
此外，護目鏡會被動地增加你 %d 潛行、隱形和陷阱偵測能力。]], "tformat")
t("AED", "電擊除顫器", "talent name")
t([[Prepare a defensive device that stores an electrical charge for 8 turns.
If your life falls below 0 while the AED is active it will activate to shock you back into life, negating the triggering attack, restoring %d life and dealing %0.2f lightning damage in radius %d that dazes affected enemies for 3 turns.
If the AED does not activate, the cooldown is reduced by 15 turns.
The healing and damage will increase with your Steampower.]], [[準備好一個防禦性的設備，其電力可以持續 8 回合。
當你的生命值降到 0 點以下的時候，電擊除顫器會啓動，把你救活，取消這一致死的攻擊，恢復 %d 點生命值，並在半徑 %d 碼範圍內造成 %0.2f 閃電傷害，震懾目標 3 回合。
如果電擊除顫器沒有啓動，其冷卻時間會減少 15 回合。
生命值恢復量和傷害受蒸汽強度加成。]], "tformat", {1,3,2})

------------------------------------------------
section "tome-orcs/data/talents/steam/gunner-training.lua"

t("Steamgun Mastery", "蒸汽槍掌握", "talent name")
t([[Increases weapon damage by %d%% and Physical Power by 30 when using steamguns.
		Also, increases your reload rate by %d.]], [[當你使用蒸汽槍時，增加 30 物理強度和 %d%% 武器傷害。
		你的裝填彈藥速率增加 %d 。]], "tformat")
t("Double Shots", "雙重射擊", "talent name")
t("You require a steamgun for this talent.", "你需要一把蒸汽槍才能使用這一技能。", "logPlayer")
t("%s resists!", "%s抵抗了效果！", "logSeen")
t([[In an overpowering display of marksmanship, you fire your steamgun(s) twice in rapid succession.
Each shot (targeted separately) deals %d%% damage and stuns its target for %d turns.
		The stun chance increases with your Steampower.]], [[你快速地射擊兩次，每次射擊造成 %d%% 傷害，並震懾目標 %d 回合。
		震懾成功率受蒸汽強度加成。]], "tformat")
t("Uncanny Reload", "神祕裝填", "talent name")
t([[You focus on managing your steamgun ammo for %d turns.
		While the effect lasts your attacks do not consume shots.]], [[你集中精力於蒸汽槍彈藥 %d 回合。
		效果持續期間不消耗彈藥。]], "tformat")
t("Static Shot", "靜電射擊", "talent name")
t([[You fire a special, electrically charged shot with your steamgun(s) at a spot within range.
		When each shot reaches its target, it bursts into electrified shrapnel within radius %d, which shocks each target hit and deals %d%% weapon damage as lightning.
		Shocked targets lose up to %d non-magical effects (for the first shot that hits).
		This talent does not use ammo.]], [[你射出一發特製電擊子彈。
		子彈擊中目標時，將變形爲閃電榴彈，電擊 %d 範圍內所有目標，造成 %d%% 電擊武器傷害。
		被電擊的目標失去至多 %d 項非魔法效果（僅第一發有效）。
		該技能不消耗彈藥。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/gunslinging.lua"

t("Strafe", "掃射", "talent name")
t("@Source@ strafes with @hisher@ steamguns!", "@Source@使用@hisher@蒸汽槍掃射！", "_t")
t("You must dual wield steamguns for this talent.", "你需要雙持蒸汽槍才能使用這一技能。", "logPlayer")
t([[You have learned to fire while moving.
		In one motion, you fire your double steamguns (100%% weapon damage, 1 tile range penalty) and may then move to an adjacent tile (unless pinned to the ground or immobilized).
		This talent can be activated for up to %d consecutive turns before it goes on cooldown, and takes time according to your steamtech speed or movement speed (if you move), whichever is slower.
		When Strafe ends you may instantly reload between %d and %d ammo (based on the number of strafes you performed and your ammo capacity).]], [[你學會如何在移動中射擊。
		在射擊（100%% 武器傷害，射程 -1 ）的同時你能移動到相鄰的一格。
		該技能在冷卻前能激活連續 %d 個回合，消耗時間取決於蒸汽速度和移動速度較慢者。
		掃射結束後，你立刻獲得 %d 到 %d 彈藥（取決於掃射期間你消耗的彈藥與你的彈藥容量）。]], "tformat")
t("Startling Shot", "驚豔射擊", "talent name")
t("Something", "某物", "_t")
t("%s misses %s shot.", "%s躲開了%s攻擊", "logSeen")
t([[You deliberately fire a missing shot at a target, startling it for 3 turns.
		If the target fails a mental save it instinctively recoils two steps back.
		The next shot that hits the startled creature will deal %d%% more damage.]], [[你故意朝目標射出偏離的子彈，令其驚訝 3 回合。
		若目標未通過精神豁免檢定，將後退 2 步。
		驚訝狀態下的目標在下一次攻擊中將受到額外 %d%% 傷害。]], "tformat")
t("#Source# fires a retaliatory shot at #Target#!", "#Source#朝#Target#發射反擊射擊！", "logCombat")
t("Evasive Shots", "反擊射擊", "talent name")
t([[Using small engines to augment your reflexes you are able to automatically fire retaliatory shots at your foes doing %d%% weapon damage.
		Retaliation shots are fired when you evade/are missed by a melee or ranged attack.
		This can only happen once per turn and uses shots as normal.]], [[開啓引擎強化反射神經，你能進行反擊射擊 , 造成 %d%% 武器傷害。
		反擊射擊是當你閃避或躲閃近戰、遠程攻擊時觸發的自動射擊。
		反擊射擊一回合只能觸發一次，且照常消耗彈藥。]], "tformat")
t("Trick Shot", "魔術射擊", "talent name")
t([[Your cunning and dexterity allow you to fire incredible trick shots that can hit multiple targets.
		You precisely aim your trick shot to ricochet amongst foes you can see so that whenever it hits something solid (creature or solid wall), it will bounce towards the next closest foe.
		It may ricochet up to %d times (or until it misses) within range 5 of your first target and will not target the same foe twice.
		Your shot deals %d%% weapon damage on its first strike, but loses %d%% damage and %d(%d%%) accuracy with each bounce.]], [[你的靈敏讓你能射出同時擊中多個敵人的子彈。
		你精確地瞄準敵人，子彈命中後將彈射至其他目標上。
		子彈最多彈射 %d 次，只能在第一個目標周圍 5 碼範圍內彈射，不會命中同一個目標兩次。
		第一次命中將造成 %d%% 武器傷害，之後每次彈射下降 %d%% 傷害和 %d （ %d%% ）命中。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/heavy-weapons.lua"

t("Heavy Weapons", "重裝武器", "talent name")
t([[You gain the ability to equip one of 3 heavy weapons listed below, temporarily granting you a special attack. Heavy weapons are significantly more powerful than a steamgun, but require heavy ammunition to fire. You can store up to %d ammunition at a time, and regenerate 1 every 3 turns while a heavy weapon is not equipped.
		
		#AQUAMARINE#Flamethrower#LAST#: An incendiary device which projects streams of liquid flame at your foes. Deals %d%% steamgun fire damage over 3 turns to those in radius 5. The flamethrower ignores armor, always hits, and counts as a steamgun shot for the purpose of on-hits.
		#AQUAMARINE#Shockstaff#LAST#: An electrically charged baton wielded in close combat. Deals %d%% lightning damage to enemies in a frontal arc, as well as reducing the damage they deal by %d%% for 3 turns. This counts as a melee attack but triggers ammunition on-hit effects. All shockstaff attacks will also make a shield attack for the same damage as lightning. You can charge up to your steamgun's range to make shockstaff attacks.
		#AQUAMARINE#Boltgun#LAST#: A multi-barreled steamgun that launches efficient, chemical infused bolts. Fires twice for %d%% steamgun acid damage and generates %d steam per hit.
		
		The damage dealt by your Heavy Weapons is based off your currently equipped ammunition, and are treated as Steamguns for the purposes of weapon mastery talents and other effects.
		Firing your Steamgun will immediately unequip your heavy weapon.		
		]], [[你可以裝備以下所示的三種重裝武器，讓你獲得特殊的攻擊能力。重裝武器比普通蒸汽槍要強大得多，但需要重裝武器彈藥才能發射。你可以最多存儲 %d 枚重裝武器彈藥，在沒有裝備重裝武器的時候，每 3 回合裝填 1 點彈藥。
		#AQUAMARINE#噴火器#LAST#:向敵人發射液體火焰的燃燒裝置。對半徑 5 碼範圍內的目標，在 3 回合內造成 %d%% 火焰蒸汽槍傷害。噴火器忽略護甲，必定命中目標，且會觸發蒸汽槍的命中特效。
		#AQUAMARINE#電擊棒#LAST#:在近距離戰鬥中使用的帶電的電棍。對正面所有敵人造成 %d%% 閃電武器傷害，同時在 2 回合內減少他們造成的傷害 %d%% 。這一攻擊被視爲近戰傷害，但可以觸發彈藥的命中效果。所有電擊棒攻擊也會附加同樣閃電傷害的盾牌攻擊。使用電擊棒的時候，你可以衝刺攻擊，衝刺的範圍相當於你的蒸汽槍射程。
		#AQUAMARINE#爆矢槍#LAST#:一種高速多管蒸汽槍，裝載灌注了化學物質的子彈。射擊兩次造成 %d%% 酸性傷害，每次命中獲得 %d 蒸汽。
		你使用重裝武器造成的傷害受靈巧值加成，他們受武器精通類技能加成的時候被視爲蒸汽槍。
		使用蒸汽槍射擊的時候，將會立刻解除裝備你的重裝武器。]], "tformat")
t("Flamethrower", "火焰噴射器", "talent name")
t("You require a steamgun for this talent.", "你需要一把蒸汽槍才能使用這一技能。", "logPlayer")
t("You require heavy ammunition to use this talent.", "你需要重裝武器彈藥才能使用這一技能。", "logPlayer")
t([[You replace your steamgun and attack with an incendiary device that projects streams of liquid flame at your foes.
		
		Deals %d%% steamgun damage as fire over 3 turns to enemies in radius 5.

		These attacks cannot miss and ignore armor.]], [[你將你的蒸汽槍替換成一把強大的蒸汽動力的噴火器，將你的敵人化爲灰燼。
		
		在 5 碼範圍內，在 3 回合內造成 %d%% 火焰蒸汽槍傷害。

		這一攻擊必定命中目標，無視護甲。]], "tformat")
t("Flame Jet", "火焰噴射", "talent name")
t("You are disarmed.", "你被繳械了。", "logPlayer")
t("You require heavy ammunition to fire your flamethrower.", "你需要重裝武器彈藥才能使用火焰噴射器。", "logPlayer")
t("Fire a jet of flame, dealing %d%% weapon damage as fire over 3 turns.", "發射一團火焰，在 3 回合內造成 %d%% 火焰武器傷害。", "tformat")
t("Shockstaff", "電擊棒", "talent name")
t("You require heavy ammunition to power your shockstaff.", "你需要重裝武器彈藥才能使用電擊棒。", "logPlayer")
t([[You replace your steamgun and attack with a lightning-charged staff to engage in close combat.
		
		Deals %d%% steamgun damage as lightning to enemies in a frontal arc, as well as reducing the damage they deal by %d%% for 3 turns. This counts as a melee attack but triggers ammunition on-hit effects. All shockstaff attacks will also make a shield slam for the same damage as lightning. 

		You can charge up to your steamgun's range to make shockstaff attacks.]], [[你將你的蒸汽槍替換成一根通了強電的電棍，用於進行近戰格鬥。
		
		在前方造成 %d%% 閃電蒸汽槍傷害，並降低他們所造成的傷害 %d%% ，持續 3 回合。這一效果視作近戰攻擊，但可以觸發彈藥的命中效果。所有電擊棒傷害也會附加一次盾牌攻擊，造成同樣的閃電傷害。
		
		你可以衝刺進行電擊棒攻擊，衝刺範圍等於蒸汽槍射程。]], "tformat")
t("Stormstrike", "暴風打擊", "talent name")
t([[Sweep your shockstaff, striking all enemies in a frontal arc for %d%% weapon damage as lightning and reducing their damage dealt by %d%% for 3 turns.
		If you have a shield, you will also strike them.
		While active this replaces your normal melee attack.]], [[揮舞電擊棒，攻擊正面所有敵人，造成 %d%% 閃電武器傷害，降低他們所造成的傷害 %d%% ，持續 3 回合。
		如果你裝備了盾牌，你還會附加一次盾擊。
		這一技能可以取代你的普通攻擊]], "tformat")
t("Boltgun", "爆矢槍", "talent name")
t("You require heavy ammunition to fire your boltgun.", "你需要重裝武器彈藥才能使用爆矢槍。", "logPlayer")
t([[You replace your steamgun and attack with a multi-barreled bolt launcher, firing deadly chemical-infused flechettes.
		
		Each attack fires twice for %d%% weapon damage as acid and generates %d steam per hit.]], [[你把你的蒸汽槍替換成一把多管重型槍械，發射注入了致命的化學物質的子彈。
		
		每次攻擊造成兩次 %d%% 酸性武器傷害，擊中恢復 %d 蒸汽]], "tformat")
t("Flechette Burst", "毒彈爆射", "talent name")
t("%s resists the disarm!", "%s抵抗了繳械!", "logSeen")
t("Fire two chemical flechettes, dealing %d%% weapon damage as acid and generating %d steam per hit.", "發射兩枚化學毒彈，造成 %d%% 酸性武器傷害，每次擊中恢復 %d 蒸汽。", "tformat")
t("Heavy Weapon Expertise", "重裝武器精通", "talent name")
t("You require heavy ammunition and a heavy weapon to use this talent.", "你需要重裝武器彈藥和重裝武器才能使用這一技能。", "logPlayer")
t("%s resists the stunning blow!", "%s抵抗了震懾打擊。", "logSeen")
t("%s resists the stunning shock!", "%s抵抗了震懾打擊!", "logSeen")
t([[Your advanced training unlocks specialised techniques, triggering an effect based on your current heavy weapon at the cost of 1 heavy weapon ammunition.
#AQUAMARINE#Flamethrower#LAST#: Sweep your flamethrower across the ground, dealing %d%% steamgun damage as fire and raising a length 7 wall of fire for 5 turns. Those inside the wall take %0.2f fire damage and have their fire resistance reduced by %d%% for 2 turns.
#AQUAMARINE#Shockstaff#LAST#: Slam your staff into the target, creating a radius 3 shockwave that deals %d%% shockstaff damage as lightning and stuns those within for %d turns.
#AQUAMARINE#Boltgun#LAST#: Fire %d boltgun shots dealing %d%% steamgun damage as acid and disarming the target for 5 turns.
The damage dealt by the fire wall and the chance to apply effects will increase with your Steampower.]], [[你通過特殊訓練解鎖了新的重裝武器戰技。你現在可以消耗 1 重裝武器彈藥，根據你現在裝備的重裝武器類型，觸發以下的效果。
#AQUAMARINE#噴火器#LAST#: 用噴火器掃射地面，造成 %d%% 火焰蒸汽槍傷害，併產生一道長度爲 7 的火牆，持續 5 回合。在火牆內的敵人會受到 %0.2f 的火焰傷害，且它們的火焰傷害抗性會降低 %d%% ，持續 2 回合。
#AQUAMARINE#電擊棒#LAST#: 用電棒猛擊目標，在 3 碼範圍內產生衝擊波，造成 %d%% 閃電電擊棒傷害，並震懾敵人 %d 回合。
#AQUAMARINE#爆矢槍#LAST#: 發射 %d 枚爆炸彈藥，造成 %d%% 酸性武器傷害，並繳械敵人 5 回合。
火牆造成的傷害，以及造成異常狀態的機率，受蒸汽強度加成。]], "tformat")
t("Automated Defenses", "自動防禦系統", "talent name")
t([[You augment your shield with your heavy weapon technology, causing an effect when you Block with a heavy weapon equipped.
#AQUAMARINE#Flamethrower#LAST#: Vent choking, burning smoke in an area of the same radius as your flamethrower. Enemies caught within take %d%% shield damage as fire and are silenced for %d turns.
#AQUAMARINE#Shockstaff#LAST#: Sheathe your shield in lightning and attack all enemies in radius 3, dealing %d%% shield damage as lightning and gaining a barrier absorbing an amount of damage equal to 100%% of the highest damage dealt for 6 turns.
#AQUAMARINE#Boltgun#LAST#: Fire a blast of flechettes from your shield at all enemies in radius 7, dealing %d%% shield damage as acid. %d flechettes remain embedded in each target for 6 turns, and when struck by a melee or ranged attack a flechette will detonate and cause acid damage equal to 50%% of the shield damage dealt.
These attacks will not trigger Counterstrike.
The chance to silence will increase with your Steampower.]], [[你使用重裝武器技術強化你的盾牌，在你裝備重裝武器的時候進行格擋，會觸發以下的特殊效果。
#AQUAMARINE#噴火器#LAST#: 在火焰噴射器攻擊半徑範圍內，釋放出燃燒的嗆人濃煙。被擊中的敵人會受到 %d%% 火焰盾牌傷害，並被沉默 %d 回合。
#AQUAMARINE#電擊棒#LAST#: 將盾牌注入閃電，攻擊半徑 3 碼範圍內的所有敵人，造成 %d%% 閃電盾牌傷害，並獲得相當於最高傷害值 100%% 的傷害吸收護盾，持續 6 回合。
#AQUAMARINE#爆矢槍#LAST#: 從盾牌中發射出一團鏢彈，攻擊 7 碼半徑範圍內的所有敵人，造成 %d%% 酸性盾牌傷害。目標身上會插滿 %d 枚毒鏢，持續 6 回合。被插毒鏢的敵人受到近戰或遠程攻擊的時候，毒鏢會爆炸，造成相當於盾牌造成的傷害 50%% 的酸性傷害。
這些攻擊不會觸發反擊效果。
沉默機率受蒸汽強度加成。]], "tformat")
t("Safety Override", "武器過載", "talent name")
t("%s resists the stun!", "%s抵抗了震懾！", "logSeen")
t("%s slams into something solid, emitting a pulse of stunning lightning!", "%s擊中了某物，放出一股震懾閃電衝擊!", "logSeen")
t([[Push your heavy weapon beyond its normal limits to trigger a powerful effect. This will immediately disable your heavy weapon and expends all remaining ammunition.
#AQUAMARINE#Flamethrower#LAST#: Detonate your fuel tanks, creating a radius 4 explosion that launches you to a chosen tile in range %d. Enemies caught within the explosion take %0.2f fire damage, and further fire damage equal to %d%% of their current burning damage from the volatile fuel.
#AQUAMARINE#Shockstaff#LAST#: Drive your staff into the ground, discharging all remaining power to deal %d%% shockstaff damage as lightning in radius %d. Those struck will be knocked back %d tiles, and if they strike a wall they will emit a static pulse dealing %0.2f lightning damage in radius 1 and stunning them for 5 turns.
#AQUAMARINE#Boltgun#LAST#: Overcharge your boltgun, firing a single deadly bolt dealing %d%% steamgun damage as acid in a piercing line. For each negative physical, magical, or mental effect on the target, they take an additional %d%% damage (to a maximum of %d%%) and the duration of each negative effect is increased by %d turns.]], [[突破你重裝武器的潛能，觸發一個強大的效果。這會立刻使你停止使用重裝武器，並消耗掉所有的彈藥。
#AQUAMARINE#噴火器#LAST#: 引爆你的油箱，產生一場半徑爲 4 的爆炸，將你推到指定 %d 碼內的某格內。被爆炸擊中的敵人將會受到 %0.2f 火焰傷害，並且在不穩定的油料的助燃下，額外受到相當於當前燃燒傷害 %d%% 的傷害。
#AQUAMARINE#電擊棒#LAST#: 用電擊棒重擊地面，釋放所有的電力，在 %d 碼範圍內造成 %d%% 閃電電擊棒傷害。被擊中的目標會被擊退 %d 碼，如果他們被擊退到牆上，這會產生一個靜電脈衝，在半徑 1 碼範圍內造成 %0.2f 閃電傷害，並被震懾 5 回合。
#AQUAMARINE#爆矢槍#LAST#: 超載你的爆矢槍，發射一枚致命的彈藥，穿透一條直線造成 %d%% 蒸汽槍傷害。被擊中的目標身上每有一個物理、魔法或精神負面效果，就會額外受到 %d%% 傷害（最多 %d%% ），並且它們身上的負面效果的持續時間會增加 %d 回合。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/inscriptions.lua"

t("\
Its effects scale with your %s stat.", "\
效果隨你的%s屬性提升。", "tformat")
t("Implant: Steam Generator", "植入物: 蒸汽製造機", "talent name")
t([[Steam generator that permanently creates %0.1f steam per turn.
		Can be activated for an instant burst of %d steam.]], [[蒸汽製造機每回合製造 %0.1f 點蒸汽。
		能直接使用，立即製造 %d 蒸汽。]], "tformat")
t("steam %d", "蒸汽 %d", "tformat")
t("Implant: Medical Injector", "植入物: 藥物注射器", "talent name")
t("#LIGHT_BLUE#Medical injector selected to be used first by salves.", "#LIGHT_BLUE#已將醫用注射器設置爲藥劑的首選注射器。", "saySimple")
t("This medical injector will now be used first if available when using medical salves.", "這個藥物注射器是使用藥劑的時候的首選注射器。", "logPlayer")
t("Medical injector allows using therapeutics with %d%% efficiency and cooldown mod of %d%%.", "該藥物注射器注射藥物效率爲 %d%% ，冷卻時間修正爲 %d%% 。", "tformat")
t("efficiency %d%% / cooldown %d%%", "效率 %d%% / 冷卻時間 %d%%", "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/magnetism.lua"

t("Static Shock", "靜電震擊", "talent name")
t([[Using your Block talent surrounds you and your minions in a static barrier for 4 turns, increasing all resistances by %d%%. If an enemy deals damage to you or your minions, the barrier will shock them for %d%% of your shield damage.
		This effect cannot damage the same target more than once per turn, and will not interact with Counterstrike.
You now also use your Cunning in place of Strength when equipping shields as well as when calculating shield damage.]], [[當你使用格擋技能的時候，你會在自己和召喚物身邊產生一個靜電屏障，增加所有抗性 %d%% ，持續 4 回合。如果有敵人此時攻擊你或召喚物，屏障會電擊它們，造成 %d%% 你的盾牌傷害。
		這一效果每回合最多隻能對一個目標傷害一次，並且不會消耗反擊效果。
你裝備盾牌和計算盾牌攻擊傷害的時候，用靈巧代替力量要求。]], "tformat")
t("Magnetic Field", "磁性力場", "talent name")
t("You require a shield for this talent.", "你需要一面盾牌才能使用這一技能。", "logPlayer")
t("#Source# shatters '#Target#'.", "#Source#擊落了'#Target#'。", "logCombat")
t([[You project a powerful blast of magnetic energy from your shield in radius %d around you. Enemies caught within are knocked back %d tiles and take %d%% shield damage as lightning, and any projectiles will be destroyed.
		While this talent is not on cooldown, you also project a magnetic field from your shield, reducing the speed of incoming projectiles by %d%% and your chance to be critically hit by %d%%.]], [[你從盾牌中發射出強大的磁性能量衝擊波，半徑爲 %d 碼範圍。所有被擊中的敵人會被擊退 %d 碼，並受到 %d%% 閃電盾牌傷害。所有的拋射物也會被摧毀。
		當這一技能不處於冷卻時間的時候，你會從盾牌中發射出一個磁性力場，降低所有瞄準你的拋射物速度 %d%% ，並且你被暴擊的機率降低 %d%% 。]], "tformat")
t("Capacitor Discharge", "電力放出", "talent name")
t([[Mount capacitors to your shield that dampen the impact of attacks, increasing block value by %d%% and storing 100%% of the damage blocked as an electrical charge (to a maximum of %d).
Activating this ability discharges blocked damage, firing a bolt of lightning dealing %d%% shield damage as lightning to the first target, then projecting a bolt of lightning that arcs to %d other targets dealing lightning damage equal to the stored amount.
If at maximum charge, this also dazes for 2 turns and the shield strike is a guarenteed critical hit.
The maximum damage you can absorb will increase with your Steampower.]], [[將電容器放置在你的盾牌上，它們可以減弱攻擊的影響。增加 %d%% 的格擋值，並將 100%% 格擋的傷害轉化爲電力充能（最多充能 %d 點）。
啓動這一技能將會放出格擋的傷害，併發射出一道閃電衝擊，對第一個目標造成 %d%% 閃電盾牌傷害，併產生一股電弧，對最多 %d 個其他目標產生相當於你存儲的傷害量的傷害。
如果你的傷害充能滿了，被擊中的目標還會被眩暈 2 回合，且盾牌攻擊必定暴擊。
你能夠吸收的最大傷害量受蒸汽強度加成。]], "tformat")
t("Lightning Web", "閃電之網", "talent name")
t("lightning web", "閃電之網", "_t")
t([[Project a radius 3 electric field from your shield lasting %d turns. Enemies within this field will take an automatic shield strike for %d%% lightning damage each turn, while allies will gain flat damage reduction equal to %d%% (%d) of block value.
		All damage reduced by this effect will be stored for Capacitor Discharge.]], [[從你的盾牌中發射出一個半徑爲 3 的電網，持續 %d 回合。所有被電網覆蓋的敵人將會每回合受到一次自動的盾牌攻擊，造成 %d%% 閃電武器傷害。而被覆蓋的隊友會獲得相當於 %d%% 格擋值（%d)的直接傷害減免。
		所有被這一效果減免的傷害會被計入電力放出技能所存儲的傷害。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/mecharachnid.lua"

t("disarmed", "被繳械", "_t")
t("no ammo", "沒有彈藥", "_t")
t("bad ammo", "彈藥錯誤", "_t")
t("incompatible missile launcher", "導彈發射器不兼容", "_t")
t("incompatible ammo", "彈藥不兼容", "_t")
t("no shooter", "沒有發射器", "_t")
t("Mecharachnid Link", "機械蜘蛛鏈接", "talent name")
t("Link to the summoner.", "鏈接到召喚者", "_t")
t("Self-destruction", "自爆", "talent name")
t([[The mecharachnid self-destructs, destroying itself and generating a blast of fire in a radius of %d, doing %0.2f fire damage.
		This spell is only usable when the mecharachnid's master is dead.]], [[機械蜘蛛引爆自己，摧毀機械蜘蛛並在 %d 碼範圍內產生一個火焰爆炸，造成 %0.2f 火焰傷害。 
		這個技能只有機械蜘蛛的主人死亡時能夠使用。]], "tformat")
t("A heavily armored mechachnical spider, armed to the teeth with advanced weaponry.", "一隻裝備的牙齒的機械蜘蛛，裝備重甲和先進的武器。", "_t")
t("Your mecharachnid is out of sight; you cannot establish direct control.", "你的機械蜘蛛在視野外，你無法建立直接控制。", "logPlayer")
t("Mecharachnid", "機械蜘蛛", "talent name")
t("mecharachnid", "機械蜘蛛", "_t")
t("%s (servant of %s)", "%s (%s的僕人)", "tformat")
t("mecharachnid (servant of %s)", "機械蜘蛛 (%s的僕人)", "tformat")
t("Not enough space to invoke!", "沒有足夠的空間召喚！", "logPlayer")
t("Your mecharachnid is not dead.", "你的機械蜘蛛沒有死。", "logPlayer")
t([[You build a mighty mechanical arachnid to assist you in combat. You can equip the mecharachnid with 2 steamguns, ammunition, and armor of your choice.
If your mecharachnid is dead, this will resurrect it with %d%% of its maximum life. Your mecharachnid is automatically rebuilt at full life when combat ends.
Your mecharachnid has level %d Steamgun Mastery, Combat Accuracy and Armor Training. The mecharachnid uses Dexterity instead of Strength to equip armor.
The mecharachnid has an inbuilt teleportation device that will recall it to you when combat ends if it is not nearby.]], [[你建造一臺強大的機械蜘蛛，和你並肩作戰。你可以給機械蜘蛛裝備 2 把蒸汽槍，彈藥，以及任何你喜歡的護甲。
如果機械蜘蛛死了，這一技能會重建它，並恢復它 %d%% 的最大生命值。你的機械蜘蛛會在戰鬥結束後快速重建，恢復全部生命值。
你的機械蜘蛛獲得 %d 級蒸汽槍掌握、強化命中和重甲訓練技能。機械蜘蛛使用敏捷代替力量裝備護甲。
機械蜘蛛帶有一個內置的傳送裝置，如果在戰鬥結束後它不在你的附近，會自動傳送到你的身邊。]], "tformat")
t("Stormcoil Generator", "風暴線圈發電機", "talent name")
t("You equip your mecharachnid with a stormcoil generator, a mechanical device that projects a powerful electrical field. On taking a hit greater than 15%% of its maximum life, the excess damage will be reduced by %d%% and converted into energy, giving your mecharachnid %d%% increased global speed for 2 turns.", "你給機械蜘蛛裝備風暴線圈發電機，這一裝置可以產生強大的電力場。當受到超過最大生命值 15%% 的傷害的時候，超過的傷害將會被降低 %d%% ，並被轉化爲能量，增加機械蜘蛛 %d%% 的整體速度，持續 2 回合。", "tformat")
t("Mecharachnid Chassis", "機械蜘蛛底盤", "talent name")
t("Assault", "強襲", "_t")
t("Armament", "武裝", "_t")
t("#LIGHT_RED#You must not be in combat to change the chassis.", "#LIGHT_RED#你必須在戰鬥外才能切換底盤。", "logPlayer")
t("#LIGHT_RED#Your mecharachnid must not be in combat to change its chassis.", "#LIGHT_RED#你的機械蜘蛛必須在戰鬥外才能切換底盤。", "logPlayer")
t("#LIGHT_RED#Your mecharachnid is already in chassis %s.", "#LIGHT_RED#你的機械蜘蛛已經處於%s底盤。", "logPlayer")
t("Mecharachnid chassis changed to: #GOLD#%s", "機械蜘蛛底盤切換爲: #GOLD#%s", "logPlayer")
t("You require your mecharachnid to be adjacent, and must be out of combat.", "你需要你的機械蜘蛛在你身邊，並且在戰鬥外。", "logPlayer")
t([[You craft a new chassis for your mecharachnid, allowing you to tailor it to different situations. Each chassis grants the mecharachnid a new talent category, the ability to attach a weapon to their tail, as well as granting them %d class talent points to spend in a new category based off their chassis.

		You can choose from the 2 chassis below by activating this talent outside of combat (default chassis: Assault)
		- Assault: An armored chassis focused on close combat and defenses, specialising in wielding a steamsaw.
		- Armament: A heavily armed chassis focused on ranged combat, specialising in wielding an additional steamgun.

		Tail weapons do not attack by default, and are instead used for special talents.]], [[你給機械蜘蛛裝備了新的底盤，讓他們可以適用於不同的場合。這些底盤可以給機械蜘蛛帶來一個新的技能大系，讓它們可以在尾部裝備一把武器，並且它們獲得 %d 職業技能點，用於加點在底盤所給予的新技能上。
		
		在戰鬥外，你可以使用這個技能，來從兩種底盤中選擇一種（默認底盤：強襲）
		- 強襲：重視近身格鬥和防禦能力的裝甲底盤，尾部裝備蒸汽鏈鋸。
		- 武裝：重視遠程攻擊的強火力地盤，尾部裝備一把額外的蒸汽槍。
		
		尾部武器平常不會攻擊，只會用於特殊的技能攻擊。]], "tformat")
t("Mecharachnid Piloting", "駕駛機械蜘蛛", "talent name")
t("You require your mecharachnid to be adjacent.", "你需要你的機械蜘蛛在你身邊。", "logPlayer")
t("Leap into your mecharachnid, assuming direct control of it for %d turns. While piloting it, all damage dealt is increased by %d%%, resistances are increased by %d%%, and all of its talents cooldown twice as fast.", "跳入機械蜘蛛，直接控制它 %d 回合。當控制它的時候，它所造成的所有傷害增加 %d%% ， 抗性增加 %d%% ，所有技能冷卻時間減半。", "tformat")
t("steamtech", "蒸汽科技", "talent category")
t("armament", "武裝", "talent type")
t("Ranged combat mecharachnid abilities.", "機械蜘蛛的遠程戰鬥技能。", "_t")
t("assault", "強襲", "talent type")
t("Close combat mecharachnid abilities.", "機械蜘蛛的近身戰鬥技能。", "_t")
t("Overrun", "超速撞擊", "talent name")
t("You require a tail-mounted steamsaw for this talent.", "你必須要尾部安裝蒸汽鏈鋸才能使用這一技能。", "logPlayer")
t("Your mecharachnid cannot do that currently.", "你的機械蜘蛛目前不能這麼做。", "logPlayer")
t("#Source# provokes #Target# to attack it.", "#Source#強制#Target#攻擊它", "logCombat")
t([[You rush to the target and strike with your tailsaw, dealing %d%% damage and taunting enemies within radius %d.
		You now also use your Dexterity in place of Strength when equipping Steamsaws as well as when calculating weapon damage, and have your Steamsaw damage increased by %d%% and Physical Power by %d.]], [[你衝向敵人，用尾部蒸汽鏈鋸進行攻擊，造成 %d%% 傷害，並嘲諷半徑 %d 碼內的所有敵人。
		裝備蒸汽鏈鋸的時候，你使用敏捷代替力量值計算裝備需求和計算武器傷害，並且增加你蒸汽鏈鋸的傷害 %d%% ，物理強度 %d 。]], "tformat")
t("Defensive Protocol", "防禦協議", "talent name")
t("Enhancements to your mecharachnid combat skill increases your melee and ranged evasion by %d%%, and causes you to automatically strike adjacent enemies with your tailsaw for %d%% damage each turn.", "強化機械蜘蛛的近身戰鬥能力，增加 %d%% 概率躲閃近戰和遠程攻擊，你每回合會自動用尾部的蒸汽鏈鋸打擊臨近的敵人，造成 %d%% 傷害。", "tformat")
t("Pincer Strike", "鋼爪鉗制", "talent name")
t("#Target# resists the pincer strike from #Source#!", "#Target#抵抗了#Source#的鋼爪鉗制！", "logCombat")
t("You strike the target with your tailsaw for %d%% damage. If this hits, you attempt to clamp them with your pincers for %d turns. This pins, reduces their attack, spell and mind speed by %d%%, and lets you make a free, unavoidable strike with your tailsaw against them each turn for %d%% damage. This ends if you move more than 1 tile from the target.", "你用蒸汽鏈鋸打擊敵人，造成 %d%% 傷害。如果攻擊命中，你會試圖鉗制住敵人 %d 回合。這會定身它們，降低他們 %d%% 戰鬥、法術和精神速度，並且每回合你會用蒸汽鏈鋸對它們進行一次自動的，無法迴避的打擊，造成 %d%% 傷害。如果你離敵人的距離超過 1 碼，該技能自動終止。", "tformat")
t("Automated Repair System", "自動修復系統", "talent name")
t([[On falling below 0 life, you engage an automated repair mode. While in this mode you cannot act, but can survive below -%d life, heal for %0.1f life each turn and have all resistances increased by %d%%. This will last until you are destroyed or until you are fully healed.
		This effect has a cooldown.]], [[當生命值降低到 0 點以下的時候，你會啓動自動修理模式。在自動修理模式下，你不能活動，生命值下限爲 -%d ，每回合恢復 %0.1f 生命值，並且所有抗性增加 %d%% 。這一效果直到你的生命值完全恢復或者你被摧毀纔會終止。
		這一效果具有冷卻時間。]], "tformat")
t("Gauss Cannon", "電磁炮", "talent name")
t("You require a tail-mounted steamgun for this talent.", "你必須要尾部安裝蒸汽槍才能使用這一技能。", "logPlayer")
t([[Fire a charged shot at the farthest target with your tail-mounted steamgun that pierces through your enemies, ignoring armor and dealing %d%% weapon damage as lightning.
		This takes no time to use.]], [[用尾部蒸汽槍發射充能射擊，攻擊離你最遠的敵人，擊穿路徑上所有敵人，無視護甲，造成 %d%% 閃電武器傷害。
		使用這一技能不需要消耗時間。]], "tformat")
t("Magnetic Accelerator", "磁性加速", "talent name")
t("You must have an empty space to leap to.", "你必須有一塊空地才能跳躍過去。", "logPlayer")
t([[Improved power output increases the speed of your projectiles by %d%%, critical damage by %d%%, and allows you to automatically reload each turn.
		In addition, you can instantly activate this talent to gain a sudden burst of speed, moving to a tile in range %d.]], [[增強你的能量輸出，你的拋射物速度加快 %d%% ，暴擊傷害增加 %d%% ，你每回合會自動填彈。
		另外，你可以主動激活這一技能，獲得超人的移動速度，立刻移動到 %d 碼範圍內的某個格子內。]], "tformat")
t("Haywire Missiles", "導彈亂射", "talent name")
t("You require a steamgun for this talent.", "你需要一把蒸汽槍才能使用這一技能。", "logPlayer")
t([[Fires a barrage of charged missiles from your tail-mounted steamgun at a radius %d area, dealing %d%% steamgun damage as lightning as well as dazing those within for 2 turns.
		The daze chance increases with your Accuracy.]], [[用尾部蒸汽槍發射導彈彈幕，在半徑 %d 碼區域內造成 %d%% 閃電蒸汽槍傷害，並眩暈目標 2 回合。
		震懾機率受命中率加成。]], "tformat")
t("Advanced Targeting System", "高級瞄準", "talent name")
t([[Enhancements to your targeting systems give all ranged attacks a %d%% chance to trigger an immediate shot from your tail-mounted steamgun for 100%% damage as lightning.
		In addition, your physical and lightning resistance penetration is increased by %d%%.]], [[強化你的瞄準能力，你的所有遠程攻擊有 %d%% 機率觸發一次尾部蒸汽槍的射擊，造成 100%% 閃電武器傷害。
		另外，你的物理和閃電傷害抗性穿透增加 %d%% 。]], "tformat")
t("Tail Attachment", "尾部武器", "talent name")
t("%s mounts %s to its tail.", "%s將%s裝備到尾部。", "logSeen")
t("Attach which item?", "裝備哪一件物品？", "_t")
t("Attach the chosen weapon to your tail.", "將選擇的武器裝備到尾部。", "_t")

------------------------------------------------
section "tome-orcs/data/talents/steam/mechstar.lua"

t("Metalstar", "金屬靈晶", "talent name")
t([[Quickly aggregate particles of metal around your mindstar and focus psionic energies into it.
		The metal explodes like shrapnel, knocking back (%d away) and dazing (%d duration) all foes in radius %d.]], [[迅速將金屬粒子聚集在靈晶周圍，並將靈能聚焦於其中。
		金屬粒子將產生大爆炸，擊退（ %d 碼）並眩暈（ %d 回合）半徑 %d 內所有敵人。
		]], "tformat")
t("Bloodstar", "血液靈晶", "talent name")
t([[When you fire your metalstar, your also establish a psionic bloodlink with the shrapnel still inside for %d turns.
		Each turn the victims are drained for %0.2f physical damage, half of which heals you (each additional victim healing is reduced by half).
		If the victim move more than twice away from the radius of Metalstar (currently %d) the effect stops.
		This damage does not break daze and increases with your Steampower.]], [[每次你使用靈晶射擊時，你將與靈晶碎片建立血液靈能聯繫，持續 %d 回合。
		每回合目標將受到 %0.2f 物理傷害，一半傷害值將轉化爲治療。
		每增加一名額外目標，其帶來的治療量進一步減半。
		當目標距離超過金屬靈晶範圍（當前 %d ）的兩倍時，效果中止。
		該傷害不會打斷眩暈效果，受蒸汽強度加成。]], "tformat")
t("Steamstar", "蒸汽靈晶", "talent name")
t([[Your bloodstar effect also burns part of your victim's flesh, dealing %0.2f fire damage.
		The intensity of the fire generates steam which you psionically absorb through gestalt, providing %d steam each turn (each additional victim steam generation is reduced by 66%%).
		This damage does not break daze and increases with your Steampower.]], [[你的血液靈晶效果同時造成 %0.2f 火焰傷害。
		火焰同時產生蒸汽，每回合提供 %d 蒸汽，從每個額外目標處獲得的蒸汽數量減少 66%% 。
		該傷害不會打斷眩暈效果，受蒸汽強度加成。]], "tformat")
t("Deathstar", "死亡靈晶", "talent name")
t("When you use a shoot class talent to hit a creature affected by bloodstar an other shoot talent will have its current cooldown reduced by %d turns.", "每次你使用射擊類技能命中一個被血液靈晶影響的目標時，隨機另一項冷卻中的射擊類技能冷卻時間減少 %d 回合。", "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/other.lua"

t("Medical Injector", "藥物注射器", "talent name")
t("Medical Urgency Vest", "醫療急救背心", "talent name")
t("#LIGHT_BLUE#Medical Urgency Vest selected to be used first by salves.", "#LIGHT_BLUE#已將醫療急救背心設置爲藥劑的首選注射器。", "saySimple")
t("This medical injector will now be used first if available when using medical salves.", "這個藥物注射器是使用藥劑的時候的首選注射器。", "logPlayer")
t("The medical urgency vest allows using therapeutics with %d%% efficiency and cooldown mod of %d%%.", "該藥物注射器注射藥物效率爲 %d%% ，冷卻時間修正爲 %d%% 。", "tformat")
t("Life Support", "生命支持系統", "talent name")
t("#LIGHT_BLUE#Life Support Suit selected to be used first by salves.", "#LIGHT_BLUE#已將生命支持服設置爲藥劑的首選注射器。", "saySimple")
t("The life support suit allows using therapeutics with %d%% efficiency and cooldown mod of %d%%.", "生命支持系統允許使用藥物效率爲 %d%% ，冷卻時間修正爲 %d%% 。", "tformat")
t("Create Tinker", "製造道具", "talent name")
t("Allows you to create tinkers.", "使用該技能來製造藥劑、附着物等道具", "_t")
t("Weapon Automaton: One Handed", "武裝機器人：單手模式", "talent name")
t("You cannot use %s without a one handed melee weapon in your inventory!", "你的物品欄裏面沒有單手武器，無法使用%s！", "logPlayer")
t("Select a weapon for your Automaton", "選擇用於武裝機器人的武器", "_t")
t("Weapon Automaton: %s", "武器機器人: %s", "tformat")
t("An Automaton wielding a chosen weapon.", "手握武器的武裝機器人。", "_t")
t("#F53CBE#%s runs out of power.", "#F53CBE#%s能量耗盡。", "logSeen")
t("Summon", "召喚", "_t")
t([[Deploy a Weapon Automaton based on a selected one handed melee item.  The Automaton will wield the selected weapon and drop it when it times out or is destroyed.  Aside from the weapon selected, the Automaton will scale off Tinker talent levels, your own stats, and other things that will be described in this tooltip at some point.  
		]], [[部署一個裝備單手武器的武裝機器人。武裝機器人將自動選擇武器 ,武器不會掉落。選中時 ,武裝機器人將自動匹配技能等級 ,你的狀態和其他數據都會被描述。	 
		]], "tformat")
t("Hand Cannon", "手炮", "talent name")
t("You have no ammo!", "你沒有子彈!", "logPlayer")
t([[Fires your ammo at an enemy in range %d for %d%% weapon damage.  If this tinker is made of voratun you will fire an additional shot.
			This shot is a ranged melee attack but will use the ranged procs of your ammo as well.]], [[向在 %d 碼範圍內的一個敵人開火造成 %d%% 的武器傷害。如果手炮是由沃瑞鉭鋼製作的，你能多一次額外的射擊。射擊是遠程攻擊將會觸發彈藥特效。
]], "tformat")
t("Fatal Attractor", "致命誘餌", "talent name")
t("Not enough space to summon!", "沒有足夠的空間召喚。", "logPlayer")
t("fatal attractor", "致命誘敵裝置", "_t")
t("A psionic contraption that reflects damage and forces things to attack it.", "一個反射傷害並迫使物體攻擊的靈能裝置。", "_t")
t([[Quickly create a psionic-enhanced metal contraption that lures all your foes to it and reflects %d%% of the damage it takes to its attackers.
		The contraption will have %d life and last 5 turns.
		Damage, life, resists, and armor scale with your Steampower.]], [[快速創建一個靈能增強金屬誘餌，引誘敵人反彈 %d%% 攻擊者的傷害。
誘餌有 %d 生命值，持續 5 回合。
傷害、生命值、抗性和護甲值取決於你的蒸汽強度。
]], "tformat")
t("Rocket Boots", "火箭靴", "talent name")
t([[Activate the rocket boots, firing huge flames from your boots increasing your movement speed by %d%%.
		Each movement will leave a trail of flames doing %0.2f fire damage for 4 turns.
		Doing any other actions will break the effect.
		#{italic}#Burninate them all!#{normal}#]], [[激活火箭靴，從你的靴子上發射巨大的火焰，增加你的移動速度 %d%% 。
每次移動都會留下一道火焰持續 4 回合的傷害爲 %0.2f 的火焰。
做任何其他行動都會打斷效果。
#{italic}#燒燬他們 !#{normal}#]], "tformat")
t("Iron Grip", "鐵腕", "talent name")
t("%s resists the iron grip!", "%s抵抗了鐵腕抓取！", "logSeen")
t([[Activate the pistons to crush your target for %d turns and dealing %d%% unarmed melee damage.
		While the target is held it can not move and its armour and defense are reduced by %d.
		#{italic}#Crush their bones!#{normal}#]], [[激活活塞碾壓你的目標 %d 回合，並造成 %d%% 的徒手傷害 .
被碾壓的目標會被定身，且其護甲和閃避減少 %d 。
#{italic}#壓碎他們的骨頭 !#{normal}#]], "tformat")
t("Spring Grapple", "彈簧飛爪", "talent name")
t("%s resists the pin!", "%s抵抗了定身！", "logSeen")
t("Grab the target and pull them towards you, striking for %d%% unarmed melee damage, and if you hit, pinning them for %d turns.", [[抓住目標把目標向你拉攏，造成 %d%% 的徒手傷害，如果命中，目標定身 %d 回合。
]], "tformat")
t("Toxic Cannister Launcher", "毒罐發射裝置", "talent name")
t("toxic cannister", "毒罐", "_t")
t("A smelly cannister.", "一個放出氣味的罐子。", "_t")
t([[Launch a cannister filled with toxic gas at a location.
		Every 2 turns the cannister emits a poison cloud of radius 3 around it each turn.
		The poison does %0.2f nature damage over 5 turns.
		The cannister has %d life and lasts 8 turns. When it ends or is destroyed a last cloud is created.
		Damage, life, resists, and armor scale with your Steampower.
		Damage and penetration are inherited from the creator.]], [[發射一個充滿有毒氣體的罐子。
每 2 回合在此周圍發出一個半徑爲 3 碼的毒霧。
毒霧在 5 回合內造成 %0.2f 的自然傷害。
發生器有 %d 點生命值持續 8 回合。當它被摧毀或持續時間結束會發出最後一片毒霧。
傷害，生命值，抗性和護甲值取決於你的蒸汽強度。
從創造者處繼承傷害和穿透。]], "tformat")
t("Steam Powered Armour", "蒸汽動力裝甲", "talent name")
t([[Activate the armour's active defense system.
		A flow of electricity covers your armour to attenuate the force of energy attacks while small steam engines move key pieces of the armour to attenuate physical attacks.
		All damage except mind damage is reduced by a flat %d.
		In addition the electric power of the armour sometimes leaks, each turn there is a 50%% chance to produce a electrical arc toward a foe, dealing %0.2f to %0.2f lightning damage to all foes in radius 1.
		The effects increase with your Steampower.]], [[激活盔甲的主動防禦系統。
　　你的盔甲被電流的覆蓋。他會減弱的對你的物理攻擊。
   除了精神傷害所有傷害直接減少 %d 點。
   盔甲有時會漏電，每回合有 50%% 的機率電擊周圍 1 碼範圍內的目標，造成 %0.2f 到 %0.2f 點閃電傷害。
  效果受蒸汽強度加成。]], "tformat")
t("Viral Needlegun", "病毒針槍", "talent name")
t([[You fire a cone of blighted needles, hitting everything in a frontal cone of radius %d for %0.2f physical damage.
		Each creature hit has a %d%% chance of being infected by a random disease, doing %0.2f blight damage and reducing either Constitution, Strength or Dexterity by %d for 20 turns.
		The damage and disease effects increase with your Steampower.]], [[你射出一片枯萎的針，打擊 %d 碼錐形範圍內的目標，造成 %0.2f 的物理傷害。
每個命中目標都有 %d%% 機率感染一種隨機疾病，造成 %0.2f 枯萎傷害同時降低體質，力量或敏捷 %d 點持續 20 回合。
		傷害和疾病效果受蒸汽強度加成 ]], "tformat")
t("Sand Shredder", "砂土粉碎", "talent name")
t("%s shreds through sandwalls!", "%s 挖開沙牆!", "logSeen")
t("You shred pieces of sandwalls. Brrrmmm!.", "你碎裂了沙牆。布魯——！", "_t")
t("Flamethrower", "火焰噴射器", "talent name")
t([[Throw a cone of flame with radius %d
		The damage will increase with your Steampower.]], [[在 %d 碼範圍內放出錐形火焰
		傷害受蒸汽強度加成。]], "tformat")
t("Mass Repair", "大規模修復", "talent name")
t([[Throw a cone of healing with radius %d, healing other mechanical creatures (steam spiders) for %d.
		The healing will increase with your Steampower.]], [[釋放一片錐形半徑 %d 碼的修理器 ,修復機械生物 (蒸汽蜘蛛 ) %d 生命值。
　　治療量受蒸汽強度加成。]], "tformat")
t("Arcane Disruption Wave", "奧術干擾波 ", "talent name")
t([[Let out a technopsionic wave that silences for %d turns all those affected in a radius of %d, including the user.
		The silence chance will increase with your Steampower.]], [[製造一場奧術干擾波，沉默 %d 碼範圍內受影響的目標 %d 回合，包括使用者。
沉默機率受蒸汽強度加成。]], "tformat")
t("Mind Crush", "精神碾壓", "talent name")
t("%s resists the mental assault!", "%s抵抗了精神攻擊！", "logSeen")
t([[Shatters the mind of your victim, giving you full control over its actions for 6 turns.
		When the effect ends, you pull out your mind and the victim's body collapses, dead.
		This effect does not work on rares, bosses, or undead.
		.]], [[粉碎你的受害者的內心 ,給你完全控制其行爲 6 回合。
　　當效果結束時 ,你抽出了自己的思維，受害者的身體會崩潰 , 死亡。
　　稀有怪、boss 、亡靈不受控制。
		]], "tformat")
t("Shocking Touch", "電擊之觸", "talent name")
t([[Touch a creature to release a nasty electrical charge into them, doing %0.2f lightning damage.
		If this tinker is above tier 1, the electricity can arc to another target up to 2 tiles away.
		The number of enemies hit is at most the tinker tier.
		The damage increases with your Steampower.]], [[接觸生物釋放電流 ,造成 %0.2f 閃電傷害。
如果這個插件材質大於 1 級 ,電弧可以傳遞到 2 碼範圍內的另一個目標。
觸電的敵人數目不會大於插件材質等級。
傷害受蒸汽強度加成。]], "tformat")
t("Flash Powder", "閃光粉", "talent name")
t("%s resists the blinding light!", "%s抵抗了致盲！", "logSeen")
t([[Throw a handful of dust that rapidly oxidises, releasing a blinding light.
		Creatures in a cone of radius %d are blinded for %d turns.
		The blindness effect is applied with your Steampower.]], [[扔一把塵土 ,迅速氧化 ,釋放出眩目的光芒。
　　致盲錐形半徑 %d 碼內的生物 %d 回合。
   致盲強度受蒸汽強度加成。]], "tformat")
t("Itching Powder", "癢癢粉", "talent name")
t("%s resists the itching powder!", "%s 抵抗了癢癢粉！", "logSeen")
t([[Throw a handful of dust that is very itchy to touch.
		Creatures in a cone of radius %d are itchy for %d turns, causing them to fail talents %d%% of the time.
		The itchiness effect is applied with your Steampower.]], [[釋放一把癢癢粉。
　　錐形半徑 %d 碼內的生物 %d 回合內很癢 ,導致它們釋放技能 %d%% 機率失敗。
   致癢強度受蒸汽強度加成。]], "tformat")
t("Thunder Grenade", "閃電榴彈", "talent name")
t("%s resists the explosion!", "%s 抵抗了爆炸!", "logSeen")
t([[Throw a grenade at your foes, dealing %0.2f physical damage in radius %d.
		Creatures hit will also be stunned for %d turns.
		The stun effect is applied with your Steampower.]], [[向你的敵人投擲手榴彈 ,造成 %0.2f 物理傷害，半徑 %d 碼。
　　目標也會震懾 %d 回合。
　　震懾強度受蒸汽強度加成。]], "tformat")
t("Project Saw", "發射鏈鋸", "talent name")
t([[You activate hidden springs to project a saw towards your foes.
		Any creature caught in the beam takes %0.2f physical damage and bleeds for half more in 5 turns.
		The damage increases with your Steampower.]], [[你激活隱藏的彈簧來彈射一個你的敵人。任何生物被抓後造成 %0.2f 物理傷害和 5 回合內一半的流血傷害。
傷害受蒸汽強度加成。]], "tformat")
t("Voltaic Bolt", "閃電球", "talent name")
t([[Fires a bolt of lightning, doing %0.2f lightning damage.
		The damage will increase with your Steampower.]], [[釋放一個閃電球，造成 %0.2f 閃電傷害。
傷害受蒸汽強度加成。]], "tformat")
t("Voltaic Sentry", "伏特守衛", "talent name")
t("volatic sentry", "伏特守衛", "_t")
t("A strange device. Your hair stands on end when you approach.", "一個奇怪的裝置。當你走近時，你的頭髮豎起來了。", "_t")
t([[Place an electrically charged sentry device at a location.
		Every turn it will fire a bolt of electricity at a nearby enemy.
		The bolts do %0.2f lightning damage.
		The sentry has %d life and lasts 10 turns.
		Damage, life, resists, and armor scale with your Steampower.
		Damage and penetration are inherited from the creator.]], [[在某個位置處放置一個帶電的哨兵裝置。
每一個回合，它會向附近的敵人發射一個閃電球。
閃電球造成 %0.2f 閃電傷害。
哨兵有 %d 的生命，持續 10 回合。]], "tformat")
t("Explosive Shell", "爆炸彈", "talent name")
t("You require a steamgun for this talent.", "你需要一把蒸汽槍才能使用這一技能。", "logPlayer")
t([[You fire a special explosive shot with your steamgun(s) at a spot within range.
		When each shot reaches its target, it does normal steamgun damage and explodes within radius %d, which does %0.2f physical damage.
		This talent does not use ammo as it is the ammo.]], [[你使用蒸汽槍在射程內製造一場特殊的爆炸。
　　當每一個彈片擊中它的目標 ,造成正常蒸汽槍傷害和半徑 %d 碼內的爆炸，造成 %0.2f 的物理傷害 ,
　　這個技能不使用彈藥。]], "tformat")
t("Flare Shell", "閃光彈", "talent name")
t([[You fire a special explosive shot with your steamgun(s) at a spot within range.
		When each shot reaches its target, it does normal steamgun damage and explodes within radius %d, which lights up the area and blinds for %d turns.
		This talent does not use ammo as it is the ammo.]], [[你使用蒸汽槍在射程內製造一場特殊的爆炸。
　　當每一個彈片擊中它的目標 ,造成正常蒸汽槍傷害和半徑 %d 碼內的爆炸，致盲 %d 回合。
　　這個技能不使用彈藥。]], "tformat")
t("Incendiary Shell", "燃燒彈", "talent name")
t("clusterbomb", "集束炸彈", "_t")
t([[You fire a special explosive shot with your steamgun(s) at a spot within range.
		When each shot reaches its target, it does normal steamgun damage and releases %d explosive charges in a radius of 2.
		These charges will shortly explode for %0.2f fire damage in a radius of 1.
		This talent does not use ammo as it is the ammo.]], [[你使用蒸汽槍在射程內製造一場特殊的爆炸。
　　當每一個彈片擊中它的目標 ,造成正常蒸汽槍傷害和半徑 2 碼內的燃燒，傷害 %d 。
   這燃燒不持久 ,馬上燃燒半徑爲 1 碼，造成 %0.2f 火焰傷害。
　　這個技能不使用彈藥。]], "tformat")
t("Solid Shell", "固實彈", "talent name")
t("%s is knocked back!", "%s 被擊退。", "logSeen")
t("%s resists the knockback!", "%s抵抗了擊退！", "logSeen")
t([[You fire a special solid shot with your steamgun(s) at a target for %d%% physical weapon damage.
		The weight of the shot will knock the target back %d tiles.
		This talent does not use ammo as it is the ammo.]], [[你使用蒸汽槍發射特殊固體打擊目標造成 %d%% 武器傷害。
　　擊退目標 %d 碼。
   這個技能不使用彈藥 ]], "tformat")
t("Impaler Shell", "穿刺彈", "talent name")
t([[You fire a special stake shot with your steamgun(s) at a target for %d%% physical weapon damage.
		The weight of the shot will knock the target back 2 tiles and they will be pinned for %d turns.
		This talent does not use ammo as it is the ammo.]], [[你使用蒸汽槍發射特殊彈藥打擊目標造成 %d%% 武器傷害。
擊退目標 2 碼並定身 %d 回合。
   這個技能不使用彈藥 ]], "tformat")
t("Saw Shell", "鏈鋸彈", "talent name")
t([[You fire a special steamsaw shot with your steamgun(s) at a target for %d%% physical weapon damage.
		The steamsaw will cut into the target, doing %d%% physical weapon damage over 5 turns.
		This talent does not use ammo as it is the ammo.]], [[你使用蒸汽槍發射特殊彈藥打擊目標造成 %d%% 武器傷害。
鏈鋸會切割目標，在 5 回合內造成 %d%% 武器傷害 
這個技能不使用彈藥 ]], "tformat")
t("Hook Shell", "鉤鏈彈", "talent name")
t("%s resists the pull!", "%s抵抗了拖動!", "logSeen")
t([[You fire a special hook shot with your steamgun(s) at a target creature or location.
		If you target a creature, they are pulled up to %d tiles towards you.
		If you target an empty tile, you are pulled up to %d tiles towards it.
		This talent does not use ammo as it is the ammo.]], [[你使用蒸汽槍發射特殊彈藥打擊目標或某處 
如果你的目標是一個生物，他們被拉向你 %d 碼 
如果你的目標是一個空地，你會被拉向空地 %d 碼 
這個技能不使用彈藥 ]], "tformat")
t("Magnetic Shell", "磁性彈", "talent name")
t([[You fire a special magnetic shot with your steamgun(s) at a target for normal weapon damage.
		The shot will magnetise the target for %d turns. This lowers their defense and increases fatigue by %d.
		This talent does not use ammo as it is the ammo.
		Effect strength scales with Steampower.]], [[你使用蒸汽槍發射特殊彈藥打擊目標造成正常武器傷害。
目標將磁化 %d 回合。這降低了他們的閃避和疲勞 %d 。
這個技能不使用彈藥 
技能效果受蒸汽強度加成。]], "tformat")
t("Voltaic Shell", "伏特彈", "talent name")
t([[You fire a special voltaic shot with your steamgun(s) at a target for 100%% weapon damage as lightning.
		The shot will release powerful electrical currents at up to %d nearby enemies. 
		Each bolt does %0.2f lightning damage.
		This talent does not use ammo as it is the ammo.
		Bolt damage scales with Steampower.]], [[你使用蒸汽槍發射特殊彈藥打擊目標造成 100%% 閃電武器傷害。
這將釋放強大的電流，打擊周圍 %d 的敵人。
每個閃電球造成 %0.2f 的閃電傷害 
這個技能不使用彈藥 
閃電球傷害受蒸汽強度加成。]], "tformat")
t("Antimagic Shell", "反魔彈", "talent name")
t([[You fire a special antimagic shot with your steamgun(s) at a target for 100%% normal weapon damage.
		The shot will release antimagic sap on the target, doing %0.2f arcane resource burn damage.
		This talent does not use ammo as it is the ammo.
		Sap damage scales with Steampower.]], [[你使用蒸汽槍發射特殊彈藥打擊目標造成 100%% 武器傷害。
造成 %0.2f 奧術燃燒。
這個技能不使用彈藥。
奧術燃燒傷害取決於蒸汽強度。]], "tformat")
t("Botanical Shell", "植物彈", "talent name")
t([[You fire a special botanical shot with your steamgun(s) at a target for 100%% weapon damage as nature.
		The shot will release spores which grow into Nourishing Moss in a radius of %d for %d turns.
		Each turn the moss deals %0.2f nature damage to each foe within its radius.
		This moss has vampiric properties and heals the user for %d%% of the damage done.
		This talent does not use ammo as it is the ammo.
		Moss damage scales with Steampower.]], [[你使用蒸汽槍發射特殊彈藥打擊目標造成 100%% 自然武器傷害。
將釋放孢子生長成半徑 %d 的苔蘚 %d 回合。
每回合苔蘚造成 %0.2f 自然傷害對半徑內的每一個敵人。
這種苔蘚有吸血特性，傷害的 %d%% 治癒使用者。 
這個技能不使用彈藥 
苔蘚傷害受蒸汽強度加成。]], "tformat")
t("Corrosive Shell", "腐蝕彈", "talent name")
t([[You fire a special corrosive shot with your steamgun(s) at a target for %d%% weapon damage as acid.
		The acid released by the shot will also corrode the target, reducing its accuracy, defense and armour by %d.
		This talent does not use ammo as it is the ammo.
		Corrosion strength scales with Steampower.]], [[你使用蒸汽槍發射特殊彈藥打擊目標造成 %d%% 酸性武器傷害。
釋放的酸也會腐蝕的目標，降低其命中，閃避和護甲 %d 。
這個技能不使用彈藥。
腐蝕強度受蒸汽強度加成。]], "tformat")
t("Toxic Shell", "毒氣彈", "talent name")
t("%s resists the toxin!", "%s 抵抗了劇毒！", "logSeen")
t([[You fire a special toxic shot with your steamgun(s) at a target for 100%% weapon damage as blight.
		The shot will release heavy metals into the target, inflicting %0.2f blight damage per turn and reducing their global speed by %d%% for %d turns.
		This talent does not use ammo as it is the ammo.
		Toxin strength scales with Steampower.]], [[你使用蒸汽槍發射特殊彈藥打擊目標造成 100%% 枯萎武器傷害。
向目標釋放重金屬，造成每回合 %0.2f 枯萎傷害，並且降低整體速度 %d%% %d 回合 .
這個技能不使用彈藥。
枯萎傷害受蒸汽強度加成。]], "tformat")
t("Moss Tread", "苔蘚之踏", "talent name")
t([[For %d turns, you lay down Grasping Moss where you walk or stand.
		The moss is placed automatically every step and lasts %d turns.
		Each turn the moss deals %0.2f nature damage to each foe standing on it.
		This moss is very thick and sticky causing all foes passing through it have their movement speed reduced by %d%% and have a %d%% chance to be pinned to the ground for 4 turns.
		The damage scales with your Steampower.]], [[在 %d 回合內，你在行走或站立時放置苔蘚 
   每回合自動放置苔蘚，持續 %d 回合。
　　每個苔蘚對站在它上面的每一個敵人造成 %0.2f 自然傷害。
　　這個苔蘚很厚 ,導致粘住所有踩過它的敵人。
　　降低移動速度 %d%% 並且有 %d%% 機會被定身 4 回合。
   傷害受蒸汽強度加成。]], "tformat")
t("Arcane Dynamo", "奧術發電機", "talent name")
t([[Allows the use of Technomancy spells.
		Grants a magical steam reserve that regenerates %d steam per 10 mana spent.
		Grants Spellpower based on current steam level (currently %d; %d%% steam filled).
		Outside of combat, you relax and let your steam reserve slowly wither away.
		#{italic}#Metal Arcane Power!#{normal}#]], [[允許使用科技法術，
		獲得一個魔法的蒸汽儲備，每消耗10點法力值獲得 %d 蒸汽。
		根據當前蒸汽等級獲得法術強度（目前 %d ； 充滿了 %d%% 蒸汽）
		在戰鬥外，你放鬆了控制，蒸汽儲備會逐漸消退。
		#{italic}#金屬奧術力量！#{normal}#]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/physics.lua"

t("Smith", "鐵匠", "talent name")
t([[Allows you to create smithed tinkers of level %d.
		You will learn a new schematic at level 1.
		Each other talent level, you have a 20%% chance to learn one more random schematic, if you have not gained it by level 5 you are guaranteed it (unless all are known).
		%s]], [[允許你製造 %d 等級的鐵匠道具。
			1 級時必定獲得一個配方。之後每一級有 20%% 的概率獲得一個新配方。如果到 5 級還沒有獲得第二個新配方，就必定再獲得一個新配方。
		%s]], "tformat")
t("Mechanical", "機械", "talent name")
t([[Allows you to create mechanical tinkers of level %d.
		You will learn a new schematic at level 1.
		Each other talent level, you have a 20%% chance to learn one more random schematic, if you have not gained it by level 5 you are guaranteed it (unless all are known).
		%s]], [[允許你製造 %d 等級的機械道具。
			1 級時必定獲得一個配方。之後每一級有 20%% 的概率獲得一個新配方。如果到 5 級還沒有獲得第二個新配方，就必定再獲得一個新配方。
		%s]], "tformat")
t("Electricity", "電子", "talent name")
t([[Allows you to create electrical tinkers of level %d.
		You will learn a new schematic at level 1.
		Each other talent level, you have a 20%% chance to learn one more random schematic, if you have not gained it by level 5 you are guaranteed it (unless all are known).
		%s]], [[允許你製造 %d 等級的電子道具。
			1 級時必定獲得一個配方。之後每一級有 20%% 的概率獲得一個新配方。如果到 5 級還沒有獲得第二個新配方，就必定再獲得一個新配方。
		%s]], "tformat")
t("Compact Steam Tank", "蒸汽容量強化", "talent name")
t("Increases the capacity of your steam tank by %d.", "增加你的蒸汽容量 %d 。", "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/psytech-gunnery.lua"

t("Psyshot", "靈能射手", "talent name")
t([[Increases weapon damage by %d%% and Physical Power by 30 when using steamguns.
		When your bullets hit a target you instinctively reach out to the impact and use the kinetic force to project a mindstar attack doing %d%% damage (guaranteed hit), if you wield one in the offhand.
		This projection requires a pure mindstar; it will not work if extended into a psiblade.

		Also activable for a shot that deals %d%% weapon damage as mind damage.]], [[當使用蒸汽槍時，增加 30 物理強度和 %d%% 武器傷害。
		當你的子彈擊中目標時，你利用動能將副手的靈晶射出，造成 %d%% 武器傷害（必定命中），
		當開啓心靈利刃時，靈晶無法被射出。
		能主動使用，造成 %d%% 精神武器傷害。]], "tformat")
t("Boiling Shot", "沸騰射擊", "talent name")
t("You require a steamgun for this talent.", "你需要一把蒸汽槍才能使用這一技能。", "logPlayer")
t([[Using psionic energies you overheat your shot, making it deal %d%% damage.
		If the shot hits a wet foe it will vaporize, removing the wet effect and dealing %0.2f fire damage in a radius 4.]], [[使用靈能加熱子彈，造成 %d%% 武器傷害。
		子彈命中處於溼潤狀態的目標時將氣化，除去溼潤狀態，在半徑 4 範圍內造成 %0.2f 火焰傷害。
		]], "tformat")
t("Blunt Shot", "遲鈍射擊", "talent name")
t("Fire a relatively low-powered shot at a foe doing %d%% weapon damage, if it hits a cone-shaped shockwave of radius 4 emanates from the impact, stunning it and all creatures caught inside for %d turns.", [[發射相對低能量的子彈，造成 %d%% 武器傷害。
		子彈命中時將產生 4 碼錐形衝擊波，震懾範圍內所有生物 %d 回合。]], "tformat")
t("Vacuum Shot", "真空射擊", "talent name")
t([[Attach a psionic steam device to a shot doing %d%% weapon damage.
		When it hits a foe the device activates, violently sucking all the air nearby, pulling in all creatures in radius %d.]], [[將靈能蒸汽裝置安裝在子彈上，造成 %d%% 武器傷害。
		子彈命中時，將抽取周圍空氣，吸引半徑 %d 範圍內所有生物。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/sawmaiming.lua"

t("To The Arms", "切臂", "talent name")
t("You require a steamsaw for this talent.", "你需要一把蒸汽鏈鋸才能使用這以技能。", "logPlayer")
t([[Hits the target on the arms with one rotating saw doing %d%% damage and trying to maim it for %d turns.
		Maimed foes deal %d%% less damage.
		The chance improves with your Physical power.
		#{italic}#Cutting your foes has never been so simple!#{normal}#]], [[用鏈鋸攻擊目標手臂，造成 %d%% 武器傷害並嘗試致殘目標 %d 回合。
		致殘狀態的敵人造成的傷害減少 %d%% 。
		致殘機率受物理強度影響。
		#{italic}#殺人如砍瓜切菜 !#{normal}#]], "tformat")
t("Bloodstream", "涌血", "talent name")
t([[You "gently" slam your saws into the wounds of a creature, dealing %d%% weapon damage and deepening the wounds.
		All bleeding wounds durations are increased by %d turns and the damage by %d%% (this may be done only once per bleeding effect).
		When this happens a gush of blood is projected in a narrow cone of radius 4, dealing %0.2f physical damage to all creatures.
		The power and damage improves with your Steampower.
		#{italic}#The marvels of technology, now at the service of true butchery!#{normal}#]], [[你 " 輕柔 " 地將鏈鋸放在目標的傷口上，造成 %d%% 武器傷害並加深傷口。
		所有流血傷口持續時間增加 %d 回合，傷害增加 %d%% （每項流血最多觸發一次）。
		效果觸發時，血流將噴射而出，對 4 碼錐形範圍內所有生物造成 %0.2f 物理傷害。
		傷害受蒸汽強度加成。 
		#{italic}#一切技術，皆爲屠殺 !#{normal}#]], "tformat")
t("Spinal Break", "斷脊", "talent name")
t([[You try to sever the spine of your foe, reducing its global speed by %d%% for 4 turns and dealing %d%% weapon damage.
		The power of the blow also removes up to %d physical effects.
		If your talent level is at least 3 %d physical or magical sustains are also removed.
		#{italic}#Break them, grind them, mow them down!#{normal}#]], [[你嘗試撕裂敵人的脊柱，減少其 %d%% 整體速度 4 回合，並造成 %d%% 武器傷害。
		同時敵人將失去 %d 項物理效果。
		技能等級 3 時，同時除去 %d 項物理或魔法維持技能。
		#{italic}#切碎他們，折磨他們，收割他們！#{normal}#]], "tformat")
t("Goresplosion", "爆屍", "talent name")
t([[When you kill a foe you place small explosives with shrapnels inside its body, making it explode in radius %d.
		Any foes hit will bleed for %0.2f damage per turn for 6 turns. The shrapnels also damage the vocal cords (or related organ), silencing them for %d turns.
		#{italic}#Use the finest of wartech now: shrapnels. For blood and mayhem!#{normal}#]], [[每次擊殺敵人時，將爆炸物和榴彈封入屍體，引發一場半徑 %d 的大爆炸。
		任何被擊中的敵人將在 6 回合內受到 %0.2f 流血傷害。
		同時榴彈將損傷他們的發聲器官，沉默 %d 回合。
		#{italic}#使用戰爭技術的精華——榴彈。爲了製造血和騷亂！#{normal}#]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/steam.lua"

t("Steam Pool", "蒸汽能量池", "talent name")
t("Allows you to have a steam pool. Steam is used to use most steamtech equipments and powers.", "讓你有一個蒸汽池。蒸汽用於大多數蒸汽技術裝備和能力。", "_t")
t("inscriptions", "紋身和符文", "talent category")
t("implants", "植入體", "talent type")
t("Steamtech directly embedded on the skin.", "直接嵌入皮膚的蒸汽技術。", "_t")
t("steamtech", "蒸汽科技", "talent category")
t("other", "其他", "talent type")
t("Tinkers with stuff.", "製造東西。", "_t")
t("physics", "物理", "talent type")
t("Learn the mechanical side of steamtech.", "學習機械方面的蒸汽技術。", "_t")
t("chemistry", "化學", "talent type")
t("Learn the chemistry side of steamtech.", "學習化學方面的蒸汽技術。", "_t")
t("blacksmith", "鐵匠", "talent type")
t("All this metalworking has improved you.", "你經歷的金屬工作強化了你。", "_t")
t("engineering", "工程師", "talent type")
t("You don't just know how tinkering works, you know all the interesting details too!", "你不僅瞭解插件的工作方式，還知道插件的細節！", "_t")
t("butchery", "屠殺", "talent type")
t("Strap saws to your arms and rush into battle!", "揮舞鏈鋸，衝進戰場！", "_t")
t("sawmaiming", "鏈鋸", "talent type")
t("Use steam powered saws to their maximum efficiency! Maim! Cut! Shred!", "最大限度使用蒸汽動力鏈鋸！致殘！切裂！肢解！", "_t")
t("battlefield management", "戰地控制", "talent type")
t("Use steam powered saws to maneuver around the battlefield, gaining strategic advantage.", "使用蒸汽動力鏈鋸在戰場上機動，獲得戰略優勢。", "_t")
t("battle machinery", "戰術機械", "talent type")
t("Use steam powered engines to tilt the battle in your favour.", "使用蒸汽動力引擎使戰鬥向你有利的方向傾斜。", "_t")
t("automated butchery", "自動化屠殺", "talent type")
t("Improve your saws and tinkers with automated processes to help shred your foes.", "使用自動化技術改進你的鏈鋸和插件，幫助你粉碎敵人", "_t")
t("furnace", "熔爐", "talent type")
t("Harness the power of fire.", "掌握火焰的力量。", "_t")
t("gunner training", "槍支訓練", "talent type")
t("Use steam powered guns to rain bullets of death on your foes!  (Learning these talents allow you to fire two steamguns at once.)", "用蒸汽槍向你的敵人發射致命的子彈！（學習這些技能可以讓你同時用兩把蒸汽槍開火。）", "_t")
t("gunslinging", "槍手", "talent type")
t("Use advanced marksmanship to confound and overwhelm your foes!  (Learning these talents allow you to fire two steamguns at once.)", "使用先進的射擊技巧來迷惑和壓倒你的敵人！（學習這些技能可以讓你同時用兩把蒸汽槍開火。）", "_t")
t("bullets mastery", "子彈掌握", "talent type")
t("Use various kinds of technology to temporarily enhance your bullets.  (Learning these talents allow you to fire two steamguns at once.)", "使用各種技術暫時強化你的子彈。（學習這些技能可以讓你同時用兩把蒸汽槍開火。）", "_t")
t("avoidance", "閃避", "talent type")
t("Using various enhancements of your cloak you are able to manage incoming damage.", "使用各種能力強化你的斗篷，減少對你的傷害。", "_t")
t("elusiveness", "狡詐", "talent type")
t("Incredible feats of slipperiness!", "令人難以置信的滑技！", "_t")
t("automation", "自動化", "talent type")
t("Use small automated devices to control the battlefield.", "使用小型自動設備掌控戰場。", "_t")
t("psytech gunnery", "靈能射擊", "talent type")
t("Meld your psionic powers with awesome steamtech! For mayhem!", "將你的靈能與超棒的蒸汽科技融合！爲了混亂！", "_t")
t("thoughts of iron", "鋼鐵意志", "talent type")
t("Apply some of your formidable willpower through steam devices.", "通過蒸汽裝置運用你強大的意志力。", "_t")
t("mechstar", "機械靈晶", "talent type")
t("Control your mindstar and infuse it with steamtech.", "掌握你的靈晶，並用蒸汽科技強化它", "_t")
t("dread", "夢魘", "talent type")
t("Behold the mechanized horrors.", "掌握機械化的恐怖。", "_t")
t("magnetism", "磁化", "talent type")
t("Use the power of electricity to supercharge your shield.", "使用電力的力量超載你的盾牌。", "_t")
t("demolition", "爆破", "talent type")
t("The use of high explosives.", "使用高爆炸藥的能力。", "_t")
t("gadgets", "工具", "talent type")
t("Cunning devices to augment your combat skill.", "用來增強你戰鬥能力的靈巧裝置。", "_t")
t("heavy weapons", "重裝武器", "talent type")
t("Wield powerful steamtech tools of destruction.", "裝備用來毀滅的強大蒸汽科技工具", "_t")
t("turrets", "炮臺", "talent type")
t("Deploy steam powered turrets to assist you in combat.", "部署蒸汽驅動的炮臺，在戰鬥中爲你提供協助。", "_t")
t("The various kinds of turrets.", "各種類型的炮臺。", "_t")
t("artillery", "火炮", "talent type")
t("Advanced explosive weaponry.", "高級爆炸武器。", "_t")
t("mecharachnid", "機械蜘蛛", "talent type")
t("Build and deploy a powerful mechanical arachnid to assist you.", "建造和部署強大的機械蜘蛛來幫助你。", "_t")
t("chemical warfare", "化學武器", "talent type")
t("Unleash toxic steamtech weaponry on your enemies.", "對你的敵人釋放劇毒的蒸汽武器。", "_t")
t("#VIOLET#EUREKA!", "#VIOLET#我發現了!", "log")
t("#VIOLET#EUREKA!#WHITE# Schematic learnt: #LIGHT_BLUE#%s", "#VIOLET#我發現了!#WHITE# 已學習配方: #LIGHT_BLUE#%s", "saySimple")
t("This talent is required for the following tinkers (you still need to learn/find the schematics):", "該技能是製造下列附着物的必要條件（你仍然需要找到/學會相應配方）：", "_t")
t(" #LIGHT_BLUE#(known)#LAST#", " #LIGHT_BLUE#(已學會)#LAST#", "_t")
t("#{italic}#* ...perhaps more to discover...#{normal}#", "#{italic}#* ...可能還可以找到更多...#{normal}#", "_t")

------------------------------------------------
section "tome-orcs/data/talents/steam/thoughts-of-iron.lua"

t("Molten Iron Blood", "鐵水血液", "talent name")
t([[Using psionic energies you temporarily alter your blood, turning it into molten iron.
		When affected by molten blood all creatures that hit you in melee take %0.2f fire damage, all your resistances are increased by %d%% and all new detrimental effects on you have their duration reduced by %d%%.
		Damage increases with your Steampower.
		]], [[使用靈能改變你的血液，使之成爲融化的鐵水。
		任何近戰攻擊你的生物將受到 %0.2f 火焰傷害。
		你全體傷害抗性增加 %d%% ，同時所有新負面狀態持續時間下降 %d%% 。
		]], "tformat")
t("Mind Drones", "精神雄蜂", "talent name")
t([[Melding psionics with steamtech you create 5 mind drones at your sides that fly towards your target.
		If they encounter a creature they will latch on it and bore into its skull for 6 turns, disrupting its thoughts.
		Disrupted creatures have %d%% chances to fail to use talents and suffer a -%d%% reduction to fear and sleep immunity.]], [[將靈能和蒸汽科技結合，你在身邊製造 5 只精神雄蜂飛向目標。
		雄蜂接觸到生物時，將進入其大腦 6 回合，干擾思考能力。 
		受影響的生物有 %d%% 機率使用技能失敗，同時恐懼和睡眠免疫減少 %d%% 。]], "tformat")
t("Psionic Mirror", "靈能之鏡", "talent name")
t([[You cleanse your mind of %d mental debuffs.
		Cleansed effects will be randomly sent to closeby foes (range 5, subject to a mental save).]], "解除 %d 項負面精神狀態，並將每個狀態隨機轉移至半徑 5 以內的敵人上。", "tformat")
t("Mind Injection", "精神注射", "talent name")
t("#LIGHT_BLUE#Mind Injection selected to be used first by salves.", "#LIGHT_BLUE#已將精神注射設置爲藥劑的首選注射器。", "saySimple")
t("This medical injector will now be used first if available when using medical salves.", "這個藥物注射器是使用藥劑的時候的首選注射器。", "logPlayer")
t("By using a direct psionic link to your body you can use even more therapeutics. This talent acts as an extra medical injector with %d%% efficiency and %d%% cooldown mod.", "與身體建立直接的靈能鏈接，讓你使用藥劑更有效率。這一技能相當於一個具有 %d%% 效果修正和 %d%% 冷卻係數修正的額外注射器。", "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/turrets.lua"

t("Deploy Turret", "部署炮臺", "talent name")
t([[You are able to deploy turrets, stationary constructs that defend you in combat. Turrets last 10 turns, have a 20 turn cooldown, and deploying a turret places the others on a 5 turn cooldown.
You learn new turrets as you invest in this talent.

At raw talent level 1 you can use Steamgun turrets, which fire at a random target nearby for %d%% steamgun damage. These shots bypass allies.
At raw talent level 3 you can use Flame turrets, which deal fire damage to enemies in a radius 3 cone. Flame turrets gain %d bonus armor and 30%% resistance to all damage.
At raw talent level 4 you can use Medic turrets, which emit a healing mist that restores %d life to allies and reduces the duration of newly applied detrimental effects by %d%%.
This talent also increases the Dexterity, Constitution and Cunning of all Turrets by %d.

All turrets gain bonus armor equal to 1/2 your level, are immune to all detrimental effects, and inherit your increased damage, resistance penetration, Steampower, Physical Power, and Accuracy.
The stat bonus as well as the damage and healing dealt by Flame and Medic Turrets will increase with your Steampower.]], [[你學會了部署炮臺的能力。炮臺是固定的建築物，可以幫助你作戰。炮臺持續 10 回合，部署任何一個炮臺，都會讓其他炮臺技能進入 5 回合冷卻時間。
學習該技能還會讓你學會新的炮臺類型。
原始技能等級 1 時，你可以使用蒸汽槍炮臺，會向周圍的隨機敵人開火，造成 %d%% 蒸汽槍傷害。這一射擊可以穿過友軍。
原始技能等級 3 時，你可以使用火焰炮臺，會噴出半徑 3 碼的扇形火焰。火焰炮臺具有 %d 額外護甲值，並對所有傷害有 30%% 抗性。
原始技能等級 4 時，你可以使用醫療炮臺，會放出治療霧氣，恢復所有友軍 %d 生命值，並降低新獲得的負面效果的持續時間 %d%% 。
這一技能同時會增加你所有炮臺 %d 的敏捷、體質和靈巧值。
所有炮臺會獲得相當於你等級 1/2 的額外護甲，免疫所有異常狀態，繼承你的傷害加成、傷害穿透、蒸汽強度、物理強度和命中率。
屬性值加成、火焰炮臺的傷害和醫療炮臺的治療受蒸汽強度加成。]], "tformat")
t("Steamgun Turret", "蒸汽槍炮臺", "talent name")
t("Not enough space to summon!", "沒有足夠的空間召喚。", "logPlayer")
t("steamgun turret", "蒸汽槍炮臺", "_t")
t("An automated turret equipped with a steamgun.", "一個裝備蒸汽槍的自動炮臺。", "_t")
t("Turret", "炮臺", "_t")
t("Deploy a turret mounted with a steamgun that fires at foes within range for %d%% steamgun damage. The turret gains +%d Dexterity, Constitution and Cunning and %0.2f Steamgun Mastery.", "部署一個裝備蒸汽槍的炮臺，會自動射擊射程內的敵人，造成 %d%% 蒸汽槍傷害。炮臺具有 +%d 額外敏捷、體質、靈巧值和 %0.2f 蒸汽槍精通。", "tformat")
t("Rocket Launcher", "火箭發射器", "talent name")
t("You require a steamgun for this talent.", "你需要一把蒸汽槍才能使用這一技能。", "logPlayer")
t("Fire a missile dealing steamgun damage as fire in radius 2.", "發射導彈，在 2 碼範圍內造成火焰蒸汽槍傷害。", "tformat")
t("Dual Steamgun", "炮臺雙槍", "talent name")
t("Gain a second steamgun that deals %d%% damage.", "獲得第二把蒸汽槍，這把槍可以造成 %d%% 傷害。", "tformat")
t("Flame Turret", "火焰炮臺", "talent name")
t("flame turret", "火焰炮臺", "_t")
t("An automated turret equiped with a flamethrower.", "一個裝備火焰噴射器的自動炮臺", "_t")
t("Deploy a turret mounted with a flamethrower, scorching nearby targets. The turret gains +%d Dexterity, Constitution and Cunning.", "部署一個裝備噴火器的炮臺，會灼燒周圍的敵人。炮臺具有 +%d 額外敏捷、體質和靈巧值。", "tformat")
t("Flamethrower", "火焰噴射器", "talent name")
t([[Throw a cone of flame with radius %d, dealing %0.2f fire damage.
		The damage will increase with your Steampower.]], [[噴射出半徑 %d 碼扇形的火焰，造成 %0.2f 火焰傷害。
		傷害受蒸汽強度加成。]], "tformat")
t("Flame Vortex", "火焰旋渦", "talent name")
t([[Project a radius %d vortex of superheated air, dealing %0.2f fire damage and pulling targets towards you.
		The damage will increase with your Steampower.]], [[在半徑 %d 碼範圍內噴出灼熱空氣構成的漩渦，造成 %0.2f 火焰傷害，把所有敵人拉近你。
		傷害受蒸汽強度加成。]], "tformat")
t("Medic Turret", "醫療炮臺", "talent name")
t("medic turret", "醫療炮臺", "_t")
t("An automated turret emitting a healing mist.", "一個可以噴射治療迷霧的自動炮臺", "_t")
t("Deploy a turret that emits a healing mist in radius 3. The turret gains +%d Dexterity, Constitution and Cunning.", "部署一個在 3 碼範圍內噴出治療之霧的炮臺。炮臺具有 +%d 額外敏捷、體質和靈巧值。", "tformat")
t("Overclock", "炮臺超載", "talent name")
t([[Send a surge of power into all turrets in sight, extending their duration by %d turns and granting them a charged shield absorbing %d damage for 10 turns. While the shield holds, each turn the turret will project a bolt of lightning dealing %0.2f lightning damage to a random enemy in radius 6, with a 25%% chance to daze.
		The effects will increase with your Steampower.]], [[向視野內所有炮臺注入能量，增加他們 %d 回合的持續時間，並且讓他們獲得一個吸收 %d 傷害的護盾，持續 10 回合。在護盾消失之前，每個炮臺都會向半徑 6 碼內的隨機敵人發射閃電彈，造成 %0.2f 閃電傷害，並有 25%% 的機率眩暈敵人。
		這一效果隨蒸汽強度提升。]], "tformat")
t("Upgrade", "炮臺升級", "talent name")
t([[Upgrade the target turret, granting it %d%% increased maximum life and enhanced abilities based on type:
		Steamgun: Gains a second steamgun dealing %d%% damage, and every 3 turns will fire a rocket dealing %d%% steamgun damage as fire in radius 2.
		Flame: Increases damage by %d%%, range by %d, and every 3 turns will project a vortex of superheated air that drags targets within range %d towards the turret as well as dealing normal flamethrower damage.
		Medic: Increases healing on affected targets by %d%%, and has a %d%% chance to cleanse a negative effect each turn.]], [[升級目標炮臺，使其獲得 %d%% 最大生命值，並根據其類型，獲得以下的特殊能力：
		蒸汽槍炮臺: 獲得第二把造成 %d%% 傷害的蒸汽槍，每 3 回合會發射一枚火箭，在 2 碼半徑內造成 %d%% 蒸汽槍傷害。
		火焰炮臺: 增加 %d%% 傷害和 %d 射程，每過 3 回合，會在 %d 碼範圍內噴出灼熱蒸汽的漩渦，將所有敵人拉向炮臺，並造成標準噴火傷害。
		醫療炮臺: 增加對目標的治療量 %d%% ，且每回合有 %d%% 機率清除目標身上一個負面效果。]], "tformat")
t("Hunker Down", "炮臺守衛", "talent name")
t("guardian turret", "守衛炮臺", "_t")
t("An advanced turret equipped with dual steamguns.", "一個裝備雙蒸汽槍的高級炮臺。", "_t")
t([[Deploy a defensive emplacement around you, summoning 2 guardian turrets in adjacent tiles for %d turns. Guardian turrets redirect %d%% of all damage taken by other adjacent allies (other than fellow guardian turrets) to themselves, and each is armed with a powerful turret capable of firing piercing bullets.
			Guardian Turrets gain %0.2f ranks in Steamgun Mastery based on your Hunker Down talent level.]], [[進入守備模式，在身邊召喚 2 個守衛炮臺，持續 %d 回合。守衛炮臺會將身邊盟友（不包括其他守衛炮臺）所受到所有傷害的 %d%% 轉移到自己身上，並且它們裝備有強力的電磁炮，可以發射貫穿敵人的子彈。
		守衛炮臺具有 %0.2f 蒸汽槍精通技能，技能等級取決於你炮臺守衛技能等級]], "tformat")
t("Gauss Cannon", "電磁炮", "talent name")
t("Fire your twin-linked gauss cannons, dealing 100%% steamgun damage as lightning in a piercing beam that bypasses all armor. This does not harm friendly targets.", "發射你的雙聯電磁炮，在一條貫穿直線上造成 100%% 閃電蒸汽槍傷害，無視護甲。這一效果不會傷害友好目標。", "tformat")

------------------------------------------------
section "tome-orcs/data/talents/uber/const.lua"

t("Subcutaneous Metallisation", "金屬內皮", "talent name")
t([[When your life dips below 50%% of your total life an automated process turns some of your lower skin layers (or other internal organs) into a thick metallic layer for 6 turns.
		While the effect lasts all damage done to you is reduced by a flat amount equal to 100%% of your Constitution.
		This effect can only trigger once every %d turns.]], [[當你的生命值降到總生命的 50%% 以下時，一個自動程序將會把你的一部分內層皮膚（或別的什麼器官）傳化爲緻密的金屬內層 6 回合。
		在效果持續期間，你受到的所有傷害都將被減少等於你體質 100%% 的數值。
		該效果最多每 %d 回合觸發一次。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/uber/cun.lua"

t("Master of Disasters", "災難之主", "talent name")
t([[You are adept at wreaking havoc onto your foes!
		Any time you deal damage to a creature you apply the Incoming Disasters effect for 20 turns.
		Each time you (or any others) would try to apply a cross-tier effect to this creature, you also try to apply the other two.
		In addition your physical, steam, spell and mind powers are increased by %d.
		The powers increase scales of your Cunning.]], [[你很擅長給你的敵人帶來災難！
		任何時候你對一個生物造成傷害，你會對它施加災難臨近效果，持續20回合。
		每次你（或任何其他目標）嘗試對這個生物施加越層效果時，也將嘗試施加其他兩個越層效果。
		此外，你的物理，蒸汽，法術和精神強度增加 %d 。
		強度增加值受靈巧值加成。]], "tformat")
t("Rak'Shor's Cunning", "拉克·肖的狡詐", "talent name")
t("Quaffed the Blood of Undeath, not already undead and not antimagic.", "喝下不死之血，不是不死族，也不是反魔", "_t")
t("Rak'Shor's Cunning", "拉克·肖的狡詐", "_t")
t([[#GREY#Applying you cunning plans, you escape death by turning to undeath in an instant!

#{italic}#You may now choose to customize your undead appearance, this can not be changed afterwards.]], [[#GREY#你使用了你狡猾的計劃，瞬間將自己轉化成不死族逃避死亡。

#{italic}#你可以現在選擇自定義你的不死族外觀，之後不能改變。]], "_t")
t("Cosmetic Options", "外觀設置", "_t")
t("Customize Appearance", "自定義外形", "_t")
t("Use Default", "使用默認", "_t")
t("Rak'Shor's Cunning (Skeleton)", "拉克·肖的狡詐 (骷髏)", "_t")
t("Rak'Shor's Cunning (Ghoul)", "拉克·肖的狡詐 (食屍鬼)", "_t")
t([[Set up some cunning contingency plans in case of death.
		If you die you will have the option to raise back from the dead once, by becoming a ghoul or a skeleton (you can choose which).
		When rising this way you will keep access to your racial tree and gain access to the ghoul or skeleton racial tree with 2 levels of each talents already learnt.
		As undead will not able to use infusions anymore.
		If you choose to become a skeleton, the Re-assemble talent will consider that you already used your resurrection.]], [[準備一個應對死亡的應急方案。
		如果你死了，你可以選擇從死亡歸來，代價則是你將成爲一個骷髏或者食屍鬼（由你選擇）。
		當你選擇以這種方法復活時，你保留你的種族技能樹，並獲得骷髏或者食屍鬼的種族技能樹，且每個種族技能獲得2個技能點。
		作爲一個亡靈，你無法使用紋身。
		如果你選擇成爲骷髏，重組技能將會認定你已經復活過一次了。]], "tformat")
t("All steamtech criticals reduce the remaining cooldown of a random steamtech talent by 1.", "所有的蒸汽暴擊減少隨機的 1 個冷卻中的蒸汽科技技能 1 回合冷卻時間。", "_t")

------------------------------------------------
section "tome-orcs/data/talents/uber/dex.lua"

t("Automated Reflex System", "自動化反射系統", "talent name")
t("Have gained the #{italic}#Matrix Style#{normal}# achievement with this or any previous character for the current difficulty & permadeath settings.", "當前或之前的角色在當前難度與模式下解鎖過 #{italic}#黑客帝國#{normal}# 這個成就。", "_t")
t([[A small automatic detection system is always looking for incoming projectiles, when one is about to hit you it injects drugs into your system to boost your reactivity, granting you a free turn.
		This effect can not happen more than once every 5 turns.]], [[在身上安裝一個小型自動投射物監測系統。每當一個投射物即將擊中你時，它會注射藥物來強化你的反應能力，給你一個額外回合。
		這個效果最短每 5 回合觸發一次。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/uber/mag.lua"

t("Arcane Amplification Drone Effect", "奧術增幅裝置效果", "talent name")
t("Spell damage done to it ripples in radius 4 doing 130% arcane damage.", "其受到的法術傷害轉化爲波紋 , 對半徑 4 內的所有目標造成等同於該傷害 130% 的奧術傷害。", "_t")
t("Arcane Amplification Drone", "奧術增幅裝置", "talent name")
t("Have gained the #{italic}#Tales of the Spellblaze#{normal}# achievement with this or any previous character for the current difficulty & permadeath settings.", "當前或之前的角色在當前難度與模式下解鎖過 #{italic}#大災變的故事#{normal}# 這個成就。", "_t")
t("Not enough space to summon!", "沒有足夠的空間召喚。", "logPlayer")
t("arcane amplification drone", "奧術增福裝置", "_t")
t("Any spell damage you deal to it will ripple around in radius 4 as 160% arcane damage.", "其受到的法術傷害轉化爲波紋 , 對半徑 4 內的所有目標造成等同於該傷害 160% 的奧術傷害。", "_t")
t([[You create an Arcane Amplification Drone at the selected location for 3 turns.
		When you cast a spell that damages the drone it will ripple the damage as 130%% arcane damage of the initial hit in radius 4.]], [[你在目標地點放置一個持續 3 回合的奧術增幅裝置。
		每當你釋放的法術對其造成傷害時，增幅裝置把傷害轉化爲波紋對半徑 4 內的所有目標造成等同於該傷害 130%% 的奧術傷害。]], "tformat")
t("Technomancer", "科技法師", "talent name")
t("Unlocked the Technomancer evolution", "解鎖科技法師職業進階", "_t")
t("Technomancer", "科技法師", "_t")
t("Occult Technomancy", "科技法術：玄機", "_t")
t("These talents focus on arcane and temporal damage, using a super-spinned steamsaw to rip holes in reality.", "這一系技能專注於奧術和時空傷害，使用超高速旋轉的蒸汽鏈鋸切裂現實。", "_t")
t("Galvanic Technomancy", "科技法術：放電", "_t")
t("These talents focus on fire and lightning damage, strategically placing galvanic rods to create fields of death and stuns.", "這一系技能專注於火焰和閃電傷害，通過放置放電柱來創造電擊力場，震懾並殺死敵人。", "_t")
t("Terrene Technomancy", "科技法術：寒巖", "_t")
t("These talents focus on cold and physical damage, summoning micro spiderbots to harass and pin their foes or protect themselves.", "這一系技能專注於寒冷和物理傷害，召喚微型蜘蛛機器人，干擾並定身敵人，或是用於保護自己。", "_t")
t("Choose your free Technomancy unlock?", "選擇你免費解鎖的科技法術？", "_t")
t([[Available talents:
]], [[可用技能：
]], "_t")
t([[Technomancers are Archmages that dabble in steam technology to enhance their already formidable arsenal of spells.
		Once this class evolution is taken, you gain the following:
		- Arcane Dynamo tinker schematic
		- Steamtech/Physics category (unlocked)
		- Steamtech/Chemistry category (locked)
		- An Automated Portable Extractor (A.P.E.)
		- One point in the Physics talent Smith and two in Mechanical and Electricity
		- Spell/Galvanic Technomancy category (locked) - deals with fire and lightning
		- Spell/Terrene Technomancy category (locked) - deals with earth and water
		- Spell/Occult Technomancy category (locked) - deals with time and arcane
		- The ability to unlock one of the three Technomancy categories for free

		Once put in a robe, the Arcane Dynamo will regenerate Steam each time mana is spent and increase Spellpower based on current steam level.

		#{bold}#As soon as this evolution is used you will need to craft the Arcane Dynamo to place in a robe to benefit from all the powers of the Technomancer.#{normal}#]], [[科技法師是一些特殊的元素法師，他精通於蒸汽科技，用科技的力量來強化他們已經足夠強大的法術力量。
		當你選擇這一項進階職業的時候，你獲得以下能力：
		- 奧術發電機插件配方
		- 蒸汽/物理系 （已解鎖）
		- 蒸汽/化學系 （未解鎖）
		- 一個便攜式自動材料提取儀。
		- 1級鐵匠技能，2級機械和電子技能。
		- 法術/科技法術：放電系 （未解鎖） - 使用火焰和閃電
		- 法術/科技法術：寒巖系 （未解鎖） - 使用土和水
		- 法術/科技法術：玄機系 （未解鎖） - 使用時間和奧術
		- 你可以免費解鎖三個科技法術系的其中之一。

		當你裝備長袍的時候，奧術發電機會在你消耗法力值的時候自動產生蒸汽，並根據蒸汽等級提升法術強度。
		#{bold}#當你完成這職業進階的時候，你應該儘快製造一個奧術發電機，裝備在長袍中，以使用科技法術的力量。#{normal}#]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/uber/str.lua"

t("Pain Enhancement System", "痛苦強化系統", "talent name")
t("Earned the achievement 'Size Matters' on this character.", "當前角色解鎖了‘傷害很重要’成就。", "_t")
t("When you deal a critical hit your embedded system activates, increasing all your primary stats except Strength by 50%% of your Strength for 6 turns.", "系統將會在你暴擊時啓動，在 6 回合內你的全屬性( 力量除外 ) 將會增加等同於你 50%% 力量的值。", "tformat")

------------------------------------------------
section "tome-orcs/data/talents/uber/wil.lua"

t("Range Amplification Device", "射程增幅裝置", "talent name")
t("Have a light radius of 10 or more", "光照範圍爲10或以上", "_t")
t([[Activate a special focusing device that extends all your ranged spells and psionic powers range by 3 (only works on those with range 2 or more and up to 10 max).
		The use of this device is very strenuous, increasing fatigue by 20%% while active.]], [[啓動一個特殊的聚焦裝置來使你的所有遠程魔法和精神技能射程延長 3 （僅對射程至少爲 2 的技能生效，且上限爲 10 ）。
		使用這個裝置非常的費力，啓動時會增加 20%% 疲勞。]], "tformat")

