section "tome-orcs/data/timed_effects/floor.lua"

t("Warm", "溫暖", "_t")
t("The target is warm from the campfire. Increasing steam regeneration by 6/turn, stun immunity by 30% and stamina regeneration by 4/turn.", "目標被營火溫暖。蒸汽回覆 +6 ，震懾免疫 +30% ，體力回覆 + 4。", "_t")
t("Sun Radiance", "日光", "_t")
t("The target is under the effect of the sun. Increasing lite and sight radius by 2, blindness immunity by 30%, stealth seeing by 20 and light resistance by 30%.", "目標處於陽光的效果下。增加 2 點照明和視野， 30% 目盲免疫 , 20看穿潛行能力和 30% 光系抗性。", "_t")
t("Moon Radiance", "月光", "_t")
t("The target is under the effect of the moons. Decreasing lite and sight radius by 1, increasing stun immunity by 30%, granting 10 stealth and darkness resistance by 30%.", "目標處於月光的效果下。減少 1 點照明和視野，獲得 30% 震懾免疫 , 10 潛行能力和 30% 暗影抗性。", "_t")

