section "tome-orcs/data/timed_effects/magical.lua"

t("disease", "疾病", "effect subtype")
t("blight", "枯萎", "effect subtype")
t("Viral Injection", "病毒注射", "_t")
t("The target is infected by a disease, reducing its highest %d stats by %d and doing %0.2f blight damage per turn.", "目標被疾病感染， %d 屬性下降 %d ，每回合受到 %0.2f 枯萎傷害。", "tformat")
t("#Target# is injected with a pathogen!", "#Target#被病原體注射！", "_t")
t("#Target# is free from the pathogen.", "#Target#脫離病原體。", "_t")
t("arcane", "奧術", "effect subtype")
t("shield", "護盾", "effect subtype")
t("Steam Shield", "蒸汽護盾", "_t")
t("The target is surrounded by a magical steam shield, absorbing %d/%d damage and burning attackers for %d fire damage before it crumbles.", "目標被魔法蒸氣護盾包圍，吸收 %d/%d 傷害，獲得 %d 火焰反擊傷害。", "tformat")
t("A shield forms around #target#.", "#Target#的周圍產生了一道護盾。", "_t")
t("+Shield", "+護盾", "_t")
t("The shield around #target# crumbles.", "#Target#周圍的護盾消失了。", "_t")
t("-Shield", "-護盾", "_t")
t("dark", "黑暗", "effect subtype")
t("light", "光系", "effect subtype")
t("Twilit Echoes", "微光迴響", "_t")
t("The target feels the echoes of all light and dark damage it takes. Light damage slows the target by %0.2f%% per point of damage dealt, up to a maximum of %d%% at %d damage. Dark damage creates an effect at the tile for %d turns which deals %d%% of the damage dealt each turn. It will be refreshed as long as the target continues taking damage from it or another source.", "目標感受到光暗傷害的迴響。每點光明傷害減速 %0.2f%% ,最高 %d%% （ %d 傷害）。暗影傷害在該地格 %d 回合內每回合造成 %d%% 傷害，每次受到傷害時將刷新效果。", "tformat")
t("slow", "減速", "effect subtype")
t("Echoed Light", "光明迴響", "_t")
t("The light damage the target has taken is echoed, slowing them by %d%%. Taking additional damage while Twilit Echoes is active will refresh and increase the slow up to a maximum of %d%%.", "目標受到的光系傷害迴響了，減速 %d%% 。在微光迴響期間受到更多傷害將會刷新持續時間並增加減速效果，最大疊加到 %d%% 。", "tformat")
t("temporal", "時空", "effect subtype")
t("Mirror Worlded", "鏡像世界", "_t")
t("This unit will flip spaces soon.", "該單位即將切換空間。", "_t")
t("That space is occupied!", "這個空間被佔據了！", "logPlayer")
t("celestial", "天空", "effect subtype")
t("Starscape", "星界領域", "_t")
t("Has summoned the starscape, slowing all creatures 67%.", "召喚星界，減速所有生物 67% 。", "_t")
t("corruption", "墮落", "effect subtype")
t("Vampiric Surge", "吸血狂潮", "_t")
t("This unit is recovering %d%% of all damage it deals as health.", "將自己造成的 %d%% 傷害值轉化爲治療。", "tformat")
t("#Target# is overflowing with dark power!", "#Target# 充滿了黑暗能量!", "_t")
t("+Vamp Surge", "+吸血狂潮", "_t")
t("#Target#'s dark aura fades.", "#Target#的黑暗領域消退了。", "_t")
t("-Vamp Surge", "-吸血狂潮", "_t")
t("chronomancy", "時空", "effect subtype")
t("Temporal Ripples", "時空漣漪", "_t")
t("Attackers dealing damage will be healed for %d%% of the damage done.", "攻擊者將 %d%% 傷害值轉化爲治療。", "tformat")
t("#Target# is fluctuating in time!", "#Target# 在時光中波動!", "_t")
t("#Target# is no longer fluctuating.", "#Target# 不再波動。", "_t")
t("undead", "亡靈", "effect subtype")
t("Death Momentum", "死亡波動", "_t")
t("You have %d charges.", "疊加次數：%d 。", "tformat")
t("steam", "蒸汽", "effect subtype")
t("technomancy", "科技法術", "effect subtype")
t("Ethereal Steam", "虛幻蒸汽", "_t")
t("Deals %0.2f occult damage per turn and each time a talent is used, the caster regens one turn of a random cooldown.", "每回合受到 %0.2f 玄機傷害，每當其使用一個技能，這一狀態施加者隨機一個技能減少一回合冷卻。", "tformat")
t("#Target# covered in arcane-infused steam!", "#Target#被奧術蒸汽覆蓋！", "_t")
t("#Target# is free from the steam.", "#Target#脫離蒸汽影響。", "_t")
t("Ethereal Link", "虛幻連接", "_t")
t("While Ethereal Steam exists the cooldown of Metaphasic Spin is reduced to 6.", "當虛幻蒸汽效果存在的時候，相位旋轉技能冷卻時間降低到6回合。", "tformat")
t("Metaphasic Echoes", "相位迴響", "_t")
t("Project your saw along the leftover breaches.", "將你的鏈鋸從裂縫中投影出去。", "tformat")
t("Spiderbots Shield", "蜘蛛機器人護盾", "_t")
t("%d spiderbots are protecting you, each with %d life. Current top spiderbot has %d life remaining.", "%d 個蜘蛛機器人正在保護你，每個具有 %d 生命值。目前頂上的蜘蛛機器人還有 %d 生命值。", "tformat")
t("#Target# covered with micro spiderbots!", "#Target#被迷你蜘蛛機器人覆蓋！", "_t")
t("#Target# is no longer protected by spiderbots.", "#Target#不再被蜘蛛機器人保護。", "_t")
t("#SLATE#(%d to spiderbot - destructed)#LAST#", "#SLATE#(%d到蜘蛛機器人-摧毀)#LAST#", "tformat")
t("#SLATE#(%d to spiderbot)#LAST#", "#SLATE#(%d到蜘蛛機器人)#LAST#", "tformat")
t("spell", "法術", "effect subtype")
t("Electron Incantation", "電子充能", "_t")
t("Arcane Dynamo returns %d more steam per 10 mana spent.", "奧術發電機每消耗 10 法力值多產生 %d 蒸汽。", "tformat")
t("Defensive Circuit: Dynamo Boost", "防禦電路：發電機強化", "_t")
t("Defensive Circuit: Resistances Boost", "防禦電路：抗性強化", "_t")
t("All resistances increased by %d%%.", "所有傷害抗性提升 %d%% 。", "tformat")

