t("disrupt", "干擾", "effect subtype")
t("Mind Drone", "精神雄蜂", "_t")
t("Talents fail chance %d%%, fear and sleep immunity reduced by %d%%.", "技能失敗率 %d%%, 恐懼和睡眠免疫下降 %d%%。", "tformat")
t("A mind drone bores into #Target#!", "一個精神雄蜂飛入#Target#!", "_t")
t("#Target# is free from the mind drone.", "#Target#脫離精神雄蜂影響。", "_t")
