t("#Target# is no longer hiding in smoke.", "#Target# 不再隱藏於煙霧中.", "_t")
t("-Smoke Cover", "-煙霧覆蓋", "_t")
t("Magnetised", "磁化", "_t")
t("The target has been magnetised, reducing defense by %d and increasing fatigue by %d.", "目標被磁化，閃避下降 %d，疲勞增加 %d。", "tformat")
t("#Target# is magnetised.", "#Target# 被磁化了.", "_t")
t("+Magnetised", "+磁化", "_t")
t("#Target# is free from the magnetism.", "#Target# 從磁化中解脫.", "_t")
t("-Magnetised", "-磁化", "_t")
t("blood", "血", "effect subtype")
t("drain", "吸血", "effect subtype")
t("heal", "治療", "effect subtype")
t("Bloodstar", "血液靈晶", "_t")
t("Continuously drain blood, dealing %0.2f physical damage per turn and healing the caster for half of it.", "持續吸血，每回合受到 %0.2f 物理傷害並治療攻擊者一半傷害值。", "tformat")
t("#Target# is caught in the bloodstar.", "#Target# 被血液靈晶抓住了.", "_t")
t("#Target# is free from the bloodstar.", "#Target# 從血液靈晶中解脫.", "_t")
t("Heartrended", "心臟切割", "_t")
t("Vicious cut that bleeds, doing %0.2f physical damage per turn.", "惡毒的傷口在流血，每回合造成 %0.2f 物理傷害。", "tformat")
t("#Target# starts to bleed.", "#Target#開始流血。", "_t")
t("+Bleeds", "+流血", "_t")
t("#Target# stops bleeding.", "#Target#停止流血。", "_t")
t("-Bleeds", "-流血", "_t")
t("poison", "毒素", "effect subtype")
t("blight", "枯萎", "effect subtype")
t("Metal Poisoning", "金屬中毒", "_t")
t("The target is poisoned with heavy metals, taking %0.2f blight damage per turn and decreasing their global speed by %d%%.", "目標重金屬中毒，每回合受到 %0.2f 枯萎傷害，整體速度下降 %d%% 。", "tformat")
t("#Target# is poisoned!", "#Target#中毒了！", "_t")
t("+Metal Poisoning", "+金屬中毒", "_t")
t("#Target# is no longer poisoned.", "#Target#中毒效果消失。", "_t")
t("-Metal Poisoning", "-金屬中毒", "_t")
t("moss", "苔蘚", "effect subtype")
t("Moss Tread", "苔蘚之踏", "_t")
t("You lay moss where you walk.", "腳下長出苔蘚。", "tformat")
t("+Moss", "+苔蘚", "_t")
t("-Moss", "-苔蘚", "_t")
t("Stimulus", "興奮劑", "_t")
t("Resisting pain, reducing all incoming damage by %0.2f. When the effect ends, take %d un-resistable damage.", "抵抗疼痛，受到的傷害減少 %0.2f。效果結束後受到 %d 點不可阻擋的傷害。", "tformat")
t("maimed", "被致殘", "effect subtype")
t("To The Arms", "切臂", "_t")
t("Damage reduced by %d%%.", "你造成的傷害減少%d%%。", "tformat")
t("#Target# is suffering and fails to concentrate on dealing damage.", "#Target# 忍受痛苦，不能集中精力製造傷害.", "_t")
t("#Target# is suffering less.", "#Target# 不再忍受折磨。", "_t")
t("acid", "酸性", "effect subtype")
t("Acid Burn", "酸液灼燒", "_t")
t("The target has been splashed with acid, taking %0.2f acid damage per turn.", "目標被酸液濺射，每回合受到 %0.2f 酸性傷害。", "tformat")
t("#Target# is covered in acid!", "#Target#被酸液覆蓋！", "_t")
t("#Target# is free from the acid.", "#Target#身上的酸液消失了。", "_t")
t("lightning", "閃電", "effect subtype")
t("Static Shield", "靜電力場", "_t")
t("The target is surrounded by a static shield, increasing all resistances by %d%% and causing attacks against them to trigger a shield attack for %d%% damage as lightning.", "目標被靜電力場包圍，增加所有抗性 %d%% ，對它們的攻擊將會觸發 %d%% 閃電護盾傷害的反擊。", "tformat")
t("A static shield forms around #target#.", "靜電力場環繞着#target#。", "_t")
t("+Static Shield", "+靜電力場", "_t")
t("The static shield around #target# crumbles.", "#Target#周圍的靜電力場破碎了。", "_t")
t("-Static Shield", "-靜電力場", "_t")
t("Lightning Web", "閃電之網", "_t")
t("The target is surrounded by a crackling web of lightning, reducing all damage taken by %d.", "目標被閃電之網覆蓋，減少所受到的所有傷害 %d 。", "tformat")
t("#LIGHT_BLUE#(%d lightning web)#LAST#", "#LIGHT_BLUE#(%d閃電之網)#LAST#", "tformat")
t("Incendiary Grenade", "燃燒榴彈", "_t")
t("The target is burning for %d fire damage each turn and taking %d%% increased damage from all sources.", "目標被點燃，每回合受到 %d 火焰傷害，所受到的所有傷害增加 %d%% 。", "tformat")
t("Healing Mist", "治癒之霧", "_t")
t("Newly applied status effects durations are reduced by %d%%.", "新加的負面效果的持續時間減少 %d%% 。", "tformat")
t("#ORCHID#%s has recovered!#LAST#", "#ORCHID#%s恢復了!#LAST#", "logSeen")
t("shield", "護盾", "effect subtype")
t("Overclock", "炮臺超載", "_t")
t("The target is surrounded by a charged shield, absorbing %d/%d damage before it crumbles. While this holds, they will project a bolt of lightning against a random enemy within range 7 each turn for %0.2f lightning damage.", "目標被充能護盾覆蓋，在破碎前可以吸收 %d/%d 傷害。當護盾存在時，他們每回合會朝 7 碼範圍內的隨機敵人發射閃電彈，造成 %0.2f 閃電傷害。", "tformat")
t("#target# surges with power!", "#target#力量強化!", "_t")
t("+Overclock", "+炮臺超載", "_t")
t("#target# looks less powerful.", "#target#力量消退了。", "_t")
t("-Overclock", "-炮臺超載", "_t")
t("#SLATE#(%d absorbed)#LAST#", "#SLATE#(%d 護盾吸收)#LAST#", "tformat")
t("Your shield crumbles under the damage!", "你的護盾在攻擊下被打破！", "logPlayer")
t("sense", "感知", "effect subtype")
t("Hypervision Goggles", "強化視覺護目鏡", "_t")
t("Improves senses, allowing the detection of enemies in radius %d and increasing resistance penetration by %d%%.", "強化感知，偵測半徑 %d 碼範圍內的所有敵人，增加抗性穿透 %d%% 。", "tformat")
t("AED", "電擊除顫器", "_t")
t("If life is brought below 0, cancels the attack, heals for %d and deals %0.2f lightning damage in radius %d as well as dazing for 2 turns.", "當你的生命值降低到 0 時，取消這一致死攻擊，恢復 %d 生命值，並在 %d 碼範圍內造成 %0.2f 閃電傷害，眩暈他們 2 回合。", "tformat", {1,3,2})
t("#Target# prepares their AED!", "#Target#準備電擊除顫器!", "_t")
t("+AED", "+電擊除顫器", "_t")
t("#Target#'s AED deactivates.", "#Target#的電擊除顫器解除了。", "_t")
t("-AED", "-電擊除顫器", "_t")
t("%s's AED triggers!", "%s的電擊除顫器觸發了!", "logSeen")
t("Burning Phosphorous", "易燃火焰", "_t")
t("The target is covered in burning chemicals, taking %0.2f fire damage each turn. Subsequent shots deal %0.2f fire damage, and if they fall below 25%% life they have a %d%% chance to panic.", "目標被燃燒的化學物質所覆蓋，每回合受到 %0.2f 火焰傷害。之後的射擊將會造成 %0.2f 火焰傷害，若目標降低到 25%% 生命值以下，他們有 %d%% 的機率慌亂逃跑。", "tformat")
t("#F53CBE#%s resists the fear.", "#F53CBE#%s抵抗恐懼。", "logSeen")
t("#F53CBE#%s panics and flees from %s!", "#F53CBE#%s恐懼，試圖逃離%s！", "logSeen")
t("#F53CBE#%s panics but fails to flee from %s!", "#F53CBE#%s恐懼，未能逃離%s！", "logSeen")
t("Scorched", "灼燒", "_t")
t("Fire resistance decreased by %d%%.", "火焰傷害抗性降低%d%%。", "tformat")
t("#Target# is scorched.", "#Target#被火焰灼燒。", "_t")
t("#Target# is no longer scorched.", "#Target#不再被灼燒。", "_t")
t("grapple", "抓取", "effect subtype")
t("Pincer Strike", "鋼爪鉗制", "_t")
t("The target is grappled by %s, pinning them, reducing attack, spell and mind speed by %d%% and subjecting them to an automatic tailsaw strike each turn for %d%% damage.", "目標被 %s 抓取，被定身，降低戰鬥、法術和精神速度 %d%% ，並每回合受到一次自動的尾部鏈鋸打擊，造成 %d%% 傷害。", "tformat")
t("%s clamps its pincers down on #Target#!", "%s使用鋼爪鉗制#Target#!", "tformat")
t("+Pincer Strike", "+鋼爪鉗制", "_t")
t("#Target# is free from %s's pincers.", "#Target#脫離%s的鋼爪。", "tformat")
t("-Pincer Strike", "-鋼爪鉗制", "_t")
t("#Source# #LIGHT_RED#strikes down at#LAST# #Target#!", "#Source# #LIGHT_RED#打擊#LAST# #Target#!", "logCombat")
t("Reactive Armor", "反應式裝甲", "_t")
t("Next melee or ranged attack that deals more than 8%% of maximum life is reduced by %d%% and triggers a radius %d conal explosion dealing %d%% steamgun damage. %d stacks remaining.", "下一次受到的近戰或遠程傷害若大於最大生命值的 8%% ，則會降低 %d%% 傷害，並觸發一次半徑爲 %d 的扇形爆炸，造成 %d%% 蒸汽槍傷害。 剩餘 %d 層疊加。", "tformat")
t("#LIGHT_BLUE#(%d reactive armor)#LAST#", "#LIGHT_BLUE#(%d 反應式裝甲)#LAST#", "tformat")
t("Grenade Barrage", "榴彈轟炸", "_t")
t("Attack speed increased by %d%%. Next %d shot(s) trigger a grenade.", "攻擊速度增加 %d%% 。下 %d 次射擊會觸發榴彈射擊。", "tformat")
t("#Target# loads a magazine of grenades.", "#Target#裝載一大包榴彈。", "_t")
t("+Grenade Barrage", "+榴彈轟炸", "_t")
t("Miasma Adaptation", "適應瘴氣", "_t")
t("Immune to miasma engine effects.", "免疫瘴氣引擎效果。", "_t")
t("Miasma Engine", "瘴氣引擎", "_t")
t("The target is surrounded by a toxic cloud or radius %d. Enemies within will suffer %d%% talent failure, %d%% reduced healing, and take %0.2f additional acid damage from melee and ranged attacks.", "目標被半徑爲 %d 的瘴氣毒雲包圍。被困在其中的敵人會有 %d%% 的技能失敗機率， 降低%d%% 治療效果，並且在受到近戰和遠程攻擊的時候受到 %0.2f 額外酸性傷害。", "tformat")
t("Smogscreen", "蔽目毒雲", "_t")
t("%d%% chance to fully absorb any damaging actions.", "%d%% 機率完全吸收任何傷害。", "tformat")
t("Miasma", "瘴氣", "_t")
t("Affected by toxic chemicals. Has %d%% talent failure, %d%% reduced healing, and takes %0.2f additional acid damage from melee and ranged attacks.", "被有毒化學物質影響。 %d%% 技能失敗率，降低 %d%% 治療效果，受到近戰或遠程攻擊的時候受到額外 %0.2f 酸性傷害。", "tformat")
t("Death From Above", "死亡天降", "_t")
t("Hovering in place, gaining %d%% evasion, %d%% movement speed and launching a powerful rocket barrage each turn.", "目標懸浮在空中，獲得 %d%% 躲閃概率， %d%% 移動速度，每回合可以發射強力的火箭彈幕。", "tformat")
t("#Target# takes flight!", "#Target#起飛！", "_t")
t("+Death From Above", "+死亡天降", "_t")
t("#Target# lands.", "#Target# 落地。", "_t")
t("-Death From Above", "-死亡天降", "_t")
t("Corrosive Flechette", "腐蝕性毒鏢", "_t")
t("%d corrosive flechettes are embedded in the target. Each melee and ranged attack against them will cause a flechette to burst for %0.2f acid damage", "目標身上插着 %d 枚腐蝕性毒鏢。任何近戰或物理攻擊都會引發毒鏢爆炸，造成 %0.2f 酸性傷害。", "tformat")

------------------------------------------------
section "tome-orcs/data/tinkers/chemistry.lua"

t("Winterchill Edge", "寒冬之刃", "_t")
t("Heat is energy.  Using your knowledge of physics, chemistry, and blacksmithing you can add a chilling edge to your weapons.  While the damage this deals is relatively small each blow will also cause your enemies to lose one tenth of a turn.", "熱量也是一種能量。使用你的物理學、化學和鍛造只是你可以在你的武器上增加寒冷的刀鋒。儘管每擊的傷害不高，它還會讓你的敵人失去十分之一個回合。", "_t")
t("Acid Groove", "酸液之槽", "_t")
t("Allows your weapon to spray caustic acid on hit, reducing armor.", "讓你的武器在擊中時噴出腐蝕性的酸液，降低敵人護甲。", "_t")
t("Brain Cap", "腦帽", "_t")
t("By mounting a brain in a jar in a stralite frame this marvel will increases your mental resistances and allow you to emit a powerful magic disrupting wave.", "通過把一個大腦裝進沃瑞鉭罐子裏，這個裝置可以增加你的精神抗性並讓你可以發射出強大的魔法干擾波。", "_t")
t("Brain Flare", "腦耀", "_t")
t("By mounting a brain in a jar in a stralite frame this marvel will increases your mental resistances and to invade your foe's minds, taking control.", "通過把一個大腦裝進沃瑞鉭罐子裏，這個裝置可以增加你的精神抗性並讓你可以侵入其他人的精神，操縱它們的軀體。", "_t")
t("Waterproof Coating", "防水塗層", "_t")
t("Old cloak not keeping you as dry as it used to? A waterproof coating it just what you need!", "舊的披風不能讓你保持乾爽？防水塗層，這就是你想要的！", "_t")
t("Fireproof Coating", "防火塗層", "_t")
t("New cloak doesn't have all the resistances you wanted? A fireproof coating it just what you need!", "新的披風沒有你想要的抗性？防水塗層，這就是你想要的！", "_t")
t("Flash Powder", "閃光粉", "_t")
t("What is better than throwing sand in someone's face? Throwing sand that shines as bright as the Sun!", "有什麼比往別人臉上扔沙更有效？扔出會像太陽一樣閃耀的沙子！", "_t")
t("Itching Powder", "癢癢粉", "_t")
t("The 'Crawling Ants' itching powder will distract your enemies from any complicated actions.", "這個“爬行的螞蟻”牌癢癢粉能夠分散你敵人的注意力，讓他們無法完成複雜的行動。", "_t")
t("Rogue's Gallery", "盜賊畫廊", "_t")
t("Lined with reactive mechanisms, this cloak is equipped for any situation you might possibly encounter, and several you couldn't possibly encounter!", "內襯各種機械裝置，這件披風包含着讓你可以應對任何你有可能或不可能遇到的情況的特殊裝備！", "_t")
t("flash powder", "閃光粉", "_t")
t("fire opal", "火焰石", "_t")
t("pearl", "珍珠", "_t")
t("diamond", "鑽石", "_t")
t("bloodstone", "血滴石", "_t")
t("Rustproof Coating", "防鏽塗層", "_t")
t("Protects your armour from nasty corrosives like swamp, sea spray, acids, orc sweat, drake saliva...", "保護你的裝甲免受各種討厭的腐蝕物侵襲，包括沼澤、浪花、酸、獸人的汗液、龍涎…", "_t")
t("Alchemist's Helper", "鍊金助手", "_t")
t("An ingenius collection of tough no-spill pockets allows you to keep all those dangerous reagents close at hand. (increases acid, fire, nature and blight damage.)", "這些堅韌的口袋可以讓你隨身攜帶各種危險的試劑。（增加酸性、火焰、自然和枯萎傷害）", "_t")
t("Black Light Emitter", "黑光發射裝置", "_t")
t("Make the invisible visible.", "使隱形之物現身。", "_t")

------------------------------------------------
section "tome-orcs/data/tinkers/electricity.lua"

t("Lightning Coil", "閃電線圈", "_t")
t("Lightning coils can be attached to melee weapons to generate a short range beam of electricity on melee crits.", "閃電線圈可以被安裝在近戰武器上，在近戰暴擊時施放短程的閃電。", "_t")
t("Mana Coil", "魔力線圈", "_t")
t("Mana coils can be attached to staves to improve mana regeneration and cast a lightning spell on spell hits.", "魔力線圈可以被安裝在法杖上，增加法力回覆並在法術暴擊時施放閃電法術。", "_t")
t("sapphire", "青玉", "_t")
t("Arcane Dynamo", "奧術發電機", "_t")
t("Arcane Dynamos build a bridge between arcane forces and steamtech, regenerating steam supplies when casting spells and allowing the use of Technomancy.", "奧術發電機在奧術力量和蒸汽技術之間架起一座橋樑，在施法時產生蒸汽，並允許使用科技法術。", "_t")
t("amethyst", "紫水晶", "_t")
t("Shocking Touch", "電擊之觸", "_t")
t("Gives you the Electric Touch. Higher tiers will chain.", "讓你的碰觸附帶閃電。材質等級較高時，閃電可以連鎖。", "_t")
t("Deflection Field", "折射力場儀", "_t")
t("Protect yourself with the Power of Magnetism! Attach this device to your belt and watch those bullets miss every time! (not guaranteed to work every time)", "使用磁場的力量保護你！在你的腰帶上安裝這個設備，然後輕鬆躲過子彈吧！（不保證每次都奏效）", "_t")
t("Galvanic Retributor", "電力反擊裝置", "_t")
t("Fortify your shield with electricity and prepare to unleash GALVANIC RETRIBUTION against your attackers!", "使用電力強化你的盾牌，準備向攻擊你的人施放雷電的反擊吧！", "_t")
t("Shocking Edge", "電擊之刃", "_t")
t("Attaching a capacitor to your weapon in just the right way is a great way to shock your enemies.", "在你的武器上安裝一個電容器，電擊那些被你擊中的敵人。", "_t")
t("Steamsaw: Stormcutter", "蒸汽鏈鋸：風暴切割者", "_t")
t("The pinnacle of steamsaws technology. Every one of your hits will unleash the power of the storm onto your foes, chaining between them and stunning them!", "蒸汽鏈鋸技術的巔峯之作。你的每一擊將會在敵人的身上施放風暴的力量，在他們的身上連鎖並震懾他們！", "_t")
t("shocking edge", "電擊之觸", "_t")
t("fire opal", "火焰石", "_t")
t("pearl", "珍珠", "_t")
t("diamond", "鑽石", "_t")
t("bloodstone", "血滴石", "_t")
t("Voltaic Sentry", "伏特守衛", "_t")
t("Just drop it down and watch the sparks fly when your enemies get near.", "把它放在地上，它會自動電擊走近的敵人。", "_t")
t("Mental Stimulator", "精神刺激裝置", "_t")
t("Supercharge your thinking and give your brain a boost with the Mental Stimulator!", "強化你的思考能力，加速你的大腦！", "_t")
t("Power Distributor", "能量分配裝置", "_t")
t("The Power Distributor V2 ensures you have the energy where and when you need it, without any of the side effects like V1 had.", "能量分配器V2可以確保你在任何需要的時候擁有充足的能源，並且不會像V1那樣有什麼負面作用。", "_t")
t("White Light Emitter", "白光發射裝置", "_t")
t("Add more light to your light!", "給你的燈具加點光亮！", "_t")

------------------------------------------------
section "tome-orcs/data/tinkers/explosive.lua"

t("Thunderclap Coating", "霹靂塗層", "_t")
t("Coat your weapon in a substance that will react destructively on impact, causing your attacks to burst out in an area.", "在你的武器上覆蓋一種物質，它會在撞擊時造成破壞性的化學反應，讓你的攻擊在區域內迸射出衝擊波。", "_t")
t("Steamgun", "蒸汽槍", "_t")
t("Dismantle any one sling, add some amazing steampower to it and make a powerful steamgun to fire a bullet hell at your foes!", "拆解一個投石索，在上面附帶上強大的蒸汽力量，把它改造出可以射出子彈的強大蒸汽槍！", "_t")
t("a sling (not unique)", "一把投石索（非神器）", "_t")
t("Convert which sling?", "轉換哪一把投石索？", "_t")
t("Converted %s into %s", "將%s轉換成%s", "log")
t("Headlamp", "頭燈", "_t")
t("So much more convenient than a lantern on your waist.", "頭上有個燈真方便啊。", "_t")
t("Ablative Armour", "反應式裝甲", "_t")
t("Reinforcing your armour with explosions isn't as crazy as it sounds!  Adds armor and resists very large hits.", "使用爆炸物強化你的護甲？完全有可能！這種特殊的塗層能夠增加你的護甲值並緩衝特別大的傷害。", "_t")
t("Incendiary Groove", "燃燒油槽", "_t")
t("A special reservoir seeps liquid fire onto the weapon, adding fire damage and setting the ground on fire when you hit.", "一個特殊的儲藏罐將可燃的液體灌入武器的槽中，讓它的攻擊附帶火焰傷害並在擊中時在地上留下火焰。", "_t")
t("Thunder Grenade", "閃電榴彈", "_t")
t("Small radius, but stuns quite well.", "爆炸範圍不大，但是震懾效果不錯。", "_t")
t("Steamgun: Payload", "蒸汽槍：荷載", "_t")
t("The pinnacle of steamguns technology. Critical strikes with this gun will feel like a massive explosion of flames! And it actually will be one!", "蒸汽槍技術的巔峯之作。用這把槍暴擊就像發射出一團爆炸的大火球！而且真的會有大火球被髮射出來！", "_t")
t("incendiary groove", "燃燒油槽", "_t")
t("fire opal", "火焰石", "_t")
t("pearl", "珍珠", "_t")
t("diamond", "鑽石", "_t")
t("bloodstone", "血滴石", "_t")
t("Explosive Shell", "爆炸彈", "_t")
t("A special shot that explodes on impact.", "擊中時可以造成猛烈爆炸的特殊彈頭。", "_t")
t("Flare Shell", "閃光彈", "_t")
t("A special shot that releases intense light on impact.", "擊中時可以發出強光的特殊彈頭。", "_t")
t("Solid Shell", "固實彈", "_t")
t("A special shot that packs a punch.", "很重的特殊彈頭。", "_t")
t("Saw Shell", "鏈鋸彈", "_t")
t("A special shot that slices 'n' dices.", "附帶鏈鋸的特殊彈頭。", "_t")
t("Magnetic Shell", "磁性彈", "_t")
t("A special shot that magnetises on impact.", "擊中時可以產生磁場的特殊彈頭。", "_t")
t("Antimagic Shell", "反魔彈", "_t")
t("A special shot filled with antimagic sap.", "灌注了反魔能量的特殊彈頭。", "_t")
t("Corrosive Shell", "腐蝕彈", "_t")
t("A special shot that releases acid on impact.", "擊中時可以流出酸液的特殊彈頭。", "_t")
t("Hook Shell", "鉤鏈彈", "_t")
t("A special shot moving yourself, or others quickly.", "可以讓你或被擊中的目標快速被拉向對方的特殊彈頭。", "_t")
t("Voltaic Shell", "伏特彈", "_t")
t("A special shot that releases electricity on impact.", "擊中時可以放出電流的特殊彈頭。", "_t")
t("Botanical Shell", "植物彈", "_t")
t("A special shot grows moss on impact.", "擊中時會長出苔蘚的特殊彈頭。", "_t")
t("Toxic Shell", "毒氣彈", "_t")
t("A special shot that contains a deadly toxin.", "帶有致命毒素的特殊彈頭。", "_t")

------------------------------------------------
section "tome-orcs/data/tinkers/mechanical.lua"

t("Rocket Boots", "火箭靴", "_t")
t("Attach small steam rocket to your boots, granting faster movement and leaving a trail of fire to burn those foolish enough to follow you.", "在你的腳下綁上小型的蒸汽火箭，給你更快的移動速度並燒灼那些跟在你背後的傻子。", "_t")
t("Hand Cannon", "手炮", "_t")
t("Allows you to fire your equipped shot or arrow ammo via your gloves.", "讓你可以用手套發射你裝備的子彈或箭矢。", "_t")
t("Fatal Attractor", "致命誘餌", "_t")
t("Creates a small psionic device that will taunt nearby enemies and reflect damage received.", "製造一個小型的靈能裝置，它會吸引周圍敵人的注意力並反彈受到的傷害。", "_t")
t("Iron Grip", "鐵腕", "_t")
t("Attach powerful steam-powered pistons to your gloves, giving you a tight grip on your weapon (preventing disarming) and allowing you to crush a foe, pinning it and reducing its defense and armour.", "在你的手套上附加強力的蒸汽活塞，讓你緊抓你的武器（免疫繳械）並讓你可以扼制一個敵人，定身它並降低它的閃避和護甲。", "_t")
t("Spring Grapple", "彈簧飛爪", "_t")
t("Attach a spring loaded mechanism to your gloves, allowing you to drag enemies into melee range and deliver a quick blow, pinning them in front of you.", "在你的手套上安裝一個彈簧，讓你可以將敵人拉到身邊並快速打出一擊，讓他在你的面前被定身。", "_t")
t("Steam Powered Armour", "蒸汽動力裝甲", "_t")
t("Using small steam engines and the miracles of the latest automation discoveries you are able to create a Steam Powered Armour. A full plate armour that helps your movement and has intrinsic protection mechanisms.", "使用小型蒸汽機和你最新發現的自動化技術，你可以製造蒸汽動力裝甲。這個板甲增強你的行動能力並提供強大的防護能力。", "_t")
t("lightning coil", "閃電線圈", "_t")
t("fire opal", "火焰石", "_t")
t("pearl", "珍珠", "_t")
t("diamond", "鑽石", "_t")
t("bloodstone", "血滴石", "_t")
t("Saw Projector", "鏈鋸發射裝置", "_t")
t("A mechanical device for launching a spinning buzzsaw! What else could you want?", "這個機械裝置可以發射出一個旋轉的鏈鋸飛盤！你還指望什麼呢？", "_t")
t("Kinetic Stabiliser", "動能穩定裝置", "_t")
t("Helps keep your feet on the ground, but still allows mobility.", "可以把你的腳牢牢固定在地上，但不會影響你的移動能力。", "_t")

------------------------------------------------
section "tome-orcs/data/tinkers/smith.lua"

t("Steamsaw", "蒸汽鏈鋸", "_t")
t("Dismantle any one handed sword/axe/mace, add some amazing steampower to it and make a powerful steamsaw to shred your foes to pieces!", "拆解一件單手劍/斧/錘，在上面加入令人驚異的蒸汽能力，讓它變成可以把你的敵人撕成碎片的蒸汽鏈鋸！", "_t")
t("a one handed sword/axe/mace (not unique, without a special damage type)", "一把單手劍/斧/錘（非神器，沒有特殊傷害類型）", "_t")
t("Convert which weapon?", "轉換哪一把武器？", "_t")
t("Converted %s into %s", "將%s轉換成%s", "log")
t("Focus Lens", "聚焦透鏡", "_t")
t("A simple contraption consisting of a gem and some metal to enhance your sight, detection and infravision! At tier 4 it even allows you to fight while blinded. #{italic}#Amazing!#{normal}#", "由寶石和金屬組成的簡單裝置，可以增強你的視覺範圍、夜視能力和檢測隱形的能力！在材質等級4以上時，他還能讓你獲得心眼的能力！#{italic}#太神奇了！#{normal}#", "_t")
t("citrine", "黃水晶", "_t")
t("aquamarine", "海藍寶石", "_t")
t("quartz", "石英", "_t")
t("ruby", "紅寶石", "_t")
t("diamond", "鑽石", "_t")
t("Toxic Cannister Launcher", "毒罐發射裝置", "_t")
t("Amaze your friends with this cannister launcher which lets you project deadly poison clouds with but a wave of your hand. #{italic}#Deadly!#{normal}#", "讓你的朋友嘖嘖稱奇吧！手輕輕一揮，一隻能噴出噴射致死的有毒雲霧的毒氣罐就會被髮射出去！#{italic}#太強大了#{normal}#", "_t")
t("Viral Needlegun", "病毒針槍", "_t")
t("Blight is not dirty to a Tinker, it is useful! By combining blighted materials with a simple mechanical gun, you can fire a low damaging attack that infects foes with terrible diseases.", "對工匠來說，受人厭惡枯萎元素卻可能有很大的作用。通過將飽含枯萎能量的材料整合進這把簡單的機械槍中，你可以發射出能夠使敵人感染上可怕疾病的針擊。", "_t")
t("Razor Edge", "銳利刀片", "_t")
t("Properly working and tempering a metal can make it harder than normal, and hold a sharper edge.", "經過精心地回火鍛造可以讓金屬比以前更加堅韌，擁有更加銳利的刀鋒。", "_t")
t("Armour Reinforcement", "裝甲加固", "_t")
t("Want more defense? Wear more armour!", "想要更強的防禦？再加一層裝甲不就行了。", "_t")
t("Crystal Edge", "水晶刀刃", "_t")
t("Adding a crystal blade to your weapon will make it the flashiest around! (with added light damage and increased critical multiplier)", "在你的武器上安裝水晶刀刃可以讓它閃閃發光！（還能附加光系傷害並增加暴擊係數）", "_t")
t("Crystal Plating", "水晶鍍層", "_t")
t("Boring armour not fancy enough? Bling it up with crystal plating!  Increases all of your base stats.", "覺得你的舊裝備不夠絢？用這個水晶鍍層就行了！增加你所有的基礎屬性。", "_t")
t("Hands of Creation", "創造之手", "_t")
t("From your hands have been wrought incredible works. Your works have been forged in fire, and so have you.", "你的手中曾經創造出了無數驚人的作品，烈火中觸摸無數作品的雙手也被熾焰所圍繞。", "_t")
t("shocking touch", "電擊之觸", "_t")
t("fire opal", "火焰石", "_t")
t("pearl", "珍珠", "_t")
t("bloodstone", "血滴石", "_t")
t("Spike Attachment", "附着尖刺", "_t")
t("Adding metal spikes to anything makes it more dangerous. (and also unwieldy and inconvenient)", "在任何東西上加上尖刺都會使它變得更加危險（但穿起來也更加不方便了）", "_t")
t("Silver Filigree", "銀質花邊", "_t")
t("In addition to making a weapon look more fancy, it also makes it more deadly against undead and other nasties.", "這不僅讓武器變得更加花哨，純銀也可以有效地對抗亡靈和其他恐怖的東西。", "_t")
t("Back Support", "脊椎牽引裝置", "_t")
t("Just what you need to support your back when lifting heavy things; like armour, weapons or Yetis.", "當你手拿着武器、重甲或者一隻雪人這類重物時候，這個東西能有效分擔你身上的重量。", "_t")
t("Grounding Strap", "接地導線", "_t")
t("Keeping yourself grounded is very important, especially around lightning mages.  Increases lightning and stun resistance.", "當你面對雷電法師的時候，保持自己的接地狀態是很重要的。提高閃電傷害抗性和震懾抗性。", "_t")

------------------------------------------------
section "tome-orcs/data/tinkers/therapeutics.lua"

t("Healing Salve", "治療藥劑", "_t")
t([[A powerful healing salve.
To be used with the medical injector implant.]], [[一個強大的治療藥劑。
你需要通過植入物：藥物注射來使用他。]], "_t")
t("Pain Suppressor Salve", "痛苦壓制藥劑", "_t")
t([[A powerful salve that steels your body for a while, letting you survive below 0 life while increasing resistances.
To be used with the medical injector implant.]], [[一個可以增強你體格的堅韌程度的強大藥劑，它可以讓你在0生命值以下時仍然存活，並提升你的傷害抗性。
你需要通過植入物：藥物注射來使用他。]], "_t")
t("Frost Salve", "寒霜藥劑", "_t")
t([[A powerful salve that can clean physical detrimental effects from your body and grant a frost aura (cold, darkness and nature affinity).
To be used with the medical injector implant.]], [[一個可以清除你身上的負面物理效果並獲得一個寒霜光環（增加寒冷、暗影和自然傷害吸收）的強大藥劑。
你需要通過植入物：藥物注射來使用他。]], "_t")
t("Fiery Salve", "烈火藥劑", "_t")
t([[A powerful salve that can clean magical detrimental effects from your body and grant a fiery aura (fire, light and lightning affinity).
To be used with the medical injector implant.]], [[一個可以清除你身上的負面魔法效果並獲得一個烈火光環（火焰、光系、閃電傷害吸收）的強大藥劑。
你需要通過植入物：藥物注射來使用他。]], "_t")
t("Water Salve", "靜水藥劑", "_t")
t([[A powerful salve that can clean mental detrimental effects from your body and grant a water aura (blight, mind and acid affinity).
To be used with the medical injector implant.]], [[一個可以清除你身上的負面精神效果並獲得一個靜水光環（枯萎、精神、酸性傷害吸收）的強大藥劑。
你需要通過植入物：藥物注射來使用他。]], "_t")
t("Unstoppable Force Salve", "勢不可擋藥劑", "_t")
t([[A powerful salve that makes you more resilient to physical, mental and magic effects and grants increased healing.
To be used with the medical injector implant.]], [[一個增強你對物理、精神和魔法效果的抵抗能力並增加你的治療效果的強大藥劑。
你需要通過植入物：藥物注射來使用他。]], "_t")
t("frost salve", "寒霜藥劑", "_t")
t("fiery salve", "烈火藥劑", "_t")
t("water salve", "靜水藥劑", "_t")
t("Poison Groove", "淬毒凹槽", "_t")
t("Poison grooves can be attached to weapons to apply a stacking poison on attacks.  While this is ideal for stacking simple damage, you can't help but wonder if you could inflict stronger effects with more knowledge..", "淬毒凹槽可以被附加到武器上讓你的攻擊附帶一個可疊加的毒性效果。儘管這個毒性效果已經足夠強大了，不過如果你有更多的知識或許可以造成更好的效果…", "_t")
t("Viral Injector", "病毒之槽", "_t")
t("Viral grooves allow your weapons to apply an infectious agent on contact, dealing immediate blight damage and reducing their highest stat.  While this strain is effective it lacks the ability to spread or adapt to its hosts weaknesses.  Perhaps there are better methods to be found.", "病毒之槽可以讓你的武器攻擊附帶病毒效果，立即造成枯萎傷害並降低他們最高的數值。儘管這個方法行之有效，但它缺乏傳播和適應宿主的弱點的能力。或許還有更好的方法…", "_t")
t("Life Support Suit", "生命支持服", "_t")
t("Apply your extensive therapeutics knowledge to try and defeat death itself!", "應用你廣泛的醫療知識，擊敗死亡本身！", "_t")
t("unstoppable force salve", "勢不可擋藥劑", "_t")
t("fire opal", "火焰石", "_t")
t("pearl", "珍珠", "_t")
t("diamond", "鑽石", "_t")
t("bloodstone", "血滴石", "_t")
t("Second Skin", "第二皮膚", "_t")
t("Not only does it help seal wounds, protecting you from bleeding and enhancing your healing, it also protects from armour chafe!", "它不僅能幫助密封傷口，防止你流血並增強你的治療效果，他還能夠減少盔甲的摩擦！", "_t")
t("Air Recycler", "空氣循環裝置", "_t")
t("Helps keep your airway open and lets you hold your breath longer.", "有助於清新空氣並讓你屏息時間更長。", "_t")
t("Moss Tread", "苔蘚之踏", "_t")
t("Where you walk nature grows! Well moss. Sticky moss.", "你走到哪裏，哪裏就一片綠蔭…雖然那是粘粘的苔蘚。", "_t")
t("Fungal Web", "真菌之網", "_t")
t("This mesh of fungal threads absorbs nutrients for salves to provide you with added healing!", "這些網狀的菌絲能吸收藥劑中的能量爲你提供額外的治療。", "_t")

------------------------------------------------
section "tome-orcs/data/tinkers.lua"

t("smith", "鐵匠", "_t")
t("mechanical", "機械", "_t")
t("electricity", "電子學", "_t")
t("therapeutics", "治療學", "_t")
t("chemistry", "化學", "_t")
t("explosives", "爆炸學", "_t")

