section "tome-orcs/data/zones/cave-hatred/npcs.lua"

t("undead", "亡靈", "entity type")
t("shadow", "陰影", "entity subtype")
t("shadow of pain", "痛之影", "entity name")
t("A shadowy embodiment of pain.", "一團由痛苦具現成的陰影。", "_t")
t("shadow of hate", "恨之影", "entity name")
t("A shadowy embodiment of hate.", "一團由恨意具現成的陰影。", "_t")
t("shadow of despair", "惘之影", "entity name")
t("A shadowy embodiment of despair.", "一團由絕望具現成的陰影。", "_t")
t("shadow of remorse", "悔之影", "entity name")
t("A shadowy embodiment of remorse.", "一團由悔恨具現成的陰影。", "_t")
t("shadow of guilt", "罪之影", "entity name")
t("A shadowy embodiment of guilt.", "一團由罪怨具現成的陰影。", "_t")
t("shadow of anger", "怒之影", "entity name")
t("A shadowy embodiment of anger.", "一團由憤怒具現成的陰影。", "_t")
t("human", "人類", "entity subtype")
t("Crimson Templar John", "深紅騎士約翰", "entity name")
t([[Where you once saw a warrior bathed in light, whom in an other life you could have even respected, you now see only hatred.
This warrior's once glowing armor now emits a sinister crimson light. As he marches towards you can see his eyes, they are empty.]], [[這位曾經沐浴在陽光下的戰士，一位你曾經尊敬的勇士，現在已經被仇恨所吞噬。
這個戰士曾經閃耀着光輝的護甲已經被陰沉的血紅色掩蓋。他徑直向你衝來，只見他的眼神空洞無物。]], "_t")
t([[Where you once saw a warrior bathed in light, whom in an other life you could have even respected, you now see only hatred.
This warrior's once glowing armor now emits a sinister crimson light. As he marches towards your foes you can see his eyes, they are empty.]], [[這位曾經沐浴在陽光下的戰士，一位你曾經尊敬的勇士，現在已經被仇恨所吞噬。
這個戰士曾經閃耀着光輝的護甲已經被陰沉的血紅色掩蓋。他徑直衝向你的敵人，只見他的眼神空洞無物。]], "_t")

------------------------------------------------
section "tome-orcs/data/zones/cave-hatred/objects.lua"

t("schematic: Rogue's Gallery", "配方：盜賊畫廊", "entity name")

