section "tome-orcs/data/zones/dominion-port/npcs.lua"

t("Admiral Korbek", "海軍上將庫貝克", "entity name")
t("This old troll stands tall and proud in somewhat ornate clothing; it's clear he is an important figure. He holds in his right hand a wicked looking blade, and in his left hand what seems to be an antique handgun.", "這隻年長的巨魔昂首挺胸，身穿華麗的服裝；不用說，他一定是一個重要人物。它右手持一把邪惡長劍，左手拿着一把古色古香的手槍。", "_t")
t("reptile", "爬行動物", "entity type")
t("mutant snake", "變異蛇", "entity name")
