t("Captured Yeti Behemoth", "被捕獲的雪人巨獸。", "entity name")
t("This yeti towers over even the trolls. Blind rage maddens its eyes.", "這隻巨大的雪人遠遠高出附近的巨魔，極度的狂怒讓它變得瘋狂。", "_t")

