t("Way into the caves", "通往洞穴的道路", "entity name")
t("Farportal: Last Hope", "遠古傳送門：至最後的希望", "entity name")
t([[A farportal is a way to travel incredible distances in the blink of an eye. They usually require an external item to use. You have no idea if it is even two-way.
This one seems to go near the town of Last Hope in Maj'Eyal.]], [[ 傳送門是可以在眨眼間將你傳送出很遠距離的工具。它們通常需要一件關鍵道具來激活。你不知道這道門是否爲雙向的。 
 這扇門似乎通向馬基·埃亞爾大陸上最後的希望之所在區域。]], "_t")
t("#VIOLET#You enter the swirling portal and in the blink of an eye you set foot on the outskirts of Last Hope, with no trace of the portal...", "#VIOLET#你進入了傳送漩渦，一眨眼功夫你回到了最後的希望的郊外，傳送的蹤跡再不可尋……", "_t")
