section "tome-orcs/data/zones/gem/npcs.lua"

t("Haze Commander Parmor", "陰霾指揮官帕默", "entity name")
t("The Commander of the G.E.M. this noble looking giant looks down upon you in contempt. She wields two huge rotating saws still covered in various horror entrails.", "G.E.M.的指揮官。這個高貴的巨人用藐視的眼神居高臨下地看着你。她手裏拿着兩個巨大的旋轉圓鋸，上面還帶有恐魔的內臟。", "_t")
t("Half-Mechanized Yeti", "半機械化雪人", "entity name")
t("Whoever tortured and tormented this yeti did an amazing job of pain and destruction. As you gaze upon its fur you notice several vital spots reinforced with stralite plating. One of its arms has been replaced with a steamsaw.", "雖然不知道是誰把這個雪人折磨成這樣，它的確變成了一個恐怖的殺戮機器。當你凝視着它的皮毛，你注意到它身上的重要部分都被藍鋯石裝甲所覆蓋。他的一隻手臂也被替換成了蒸汽鏈鋸。", "_t")

