section "tome-orcs/data/zones/kaltor-shop/npcs.lua"

t("Arch-Merchant Kaltor", "大商人卡托爾", "entity name")
t("A well dressed giant, covered in gold, gems and fineries. Also wielding nasty looking guns at his sides. He seems to look strangely friendly while eyeing your gold purse.", "一個精心打扮的巨人，身穿珠光寶氣的外衣。他的手中拿着着兩把奇怪的槍。不過奇怪的是，他看起來對你比較友好，並盯上了你裝滿錢的錢包。", "_t")
t("Kaltor", "卡托爾", "_t")
t("As Kaltor falls you quickly grab a big golden key from his waist. Surely this opens the chests.", "卡托爾倒下時，你迅速從他腰間取走了一把巨大的黃金鑰匙。顯然這能打開他的寶箱。", "_t")

------------------------------------------------
section "tome-orcs/data/zones/kaltor-shop/objects.lua"

t("Pressure-enhanced Slashproof Combat Suit", "壓力感應式作戰服", "entity name")
t("steam-enhanced leather coat", "蒸汽強化皮衣", "_t")
t("A simple leather armour of excellent facture that has been craftily enhanced with hidden miniature steam engines to enhance reflexes and provide safety features.", "簡約的皮甲背後隱藏着精巧的系統，能感應壓力啓動，確保安全性能。", "_t")
t("When you take a hit of more than 10% of your total life the suit's motors activate for the next turn, displacing you before any blow could hit you.", "當你受到超過10%總生命值的傷害後，引擎啓動，下回合內，每次受到攻擊時，將自動移位來避免傷害。", "_t")
t("Brilliant Auto-loading Orc Expeller", "自動充能式獸人驅逐裝置", "entity name")
t("expensive gun", "昂貴的槍", "_t")
t("A finely crafted gun, designed specifically to kill orcs. And giants somehow!", "精心打造的槍，專爲殺獸人而設計。偶爾也殺殺巨人。", "_t")

