section "tome-orcs/data/zones/krimbul/npcs.lua"

t("Nektosh the One-Horned", "獨角者納克託什", "entity name")
t("A withered Whitehoof, with two horns that curve over his head and spiral into a cone.  The tip of his \"horn\" glows intensely, but is slowly fading; he acts confident, but his darting, wild eyes reveal panic behind them.", "一個乾癟的白蹄，他的兩隻角在頭上彎曲成螺旋形合併起來。他頭上的角發出強烈的閃光，但閃光逐漸消退。他努力讓自己顯得充滿自信，但他飄忽不定的眼神展露出了內心的恐懼。", "_t")
t("KNOW MY POWER, FOOLISH MORTAL!", "感受我的力量吧，愚蠢的犯人！", "_t")
t("Stop--  stop moving and this will be over before you can feel pain!  STOP!", "停…停下不要動，這樣你在死前就不會感受到任何痛苦！停下！", "_t")
t("No...  come on, come on, there has to be something left...", "不要……來啊，來啊，肯定還能剩下一點…", "_t")
t("...it's gone...  FINE!  I don't need that power to destroy you!", "……全都沒有了……好吧！我不需要這種力量也能摧毀你！", "_t")

------------------------------------------------
