t("horned helm", "長角的頭盔", "_t")
t("You always thought his horns looked kind of stupid, to be honest.", "實話實說，你覺得他的角看上去有點蠢。", "_t")
t("Increases your maximum stacks of Death Momentum by 1.", "增加死亡波紋的上限1。", "_t")
t("#DARK_BLUE#This helm is your birthright! Deathright? Whichever.", "#DARK_BLUE#這頭盔是你與生俱來的權利！死神？管他的！", "logPlayer")

