section "tome-orcs/data/zones/palace-fumes/npcs.lua"

t("giant", "巨人", "entity type")
t("steam", "蒸汽", "entity subtype")
t("Council Member Nashal", "議會成員納沙爾", "entity name")
t("The noble features on the face of this giantess contrast heavily with the evil grin she carries and the huge rotating saws on her arms.", "這位女巨人高貴的面容與她邪惡的微笑和手中旋轉的巨大鏈鋸形成了鮮明的反差", "_t")
t("Council Member Tormak", "議會成員托馬克", "entity name")
t("A master in all things arcane, Tormak stands in your way, steadfast in his resolution to crush you under his mighty spells.", "作爲一位奧術領域的大師，托馬克正站在你的面前，試圖用它強大的法術粉碎你。", "_t")
t("Council Member Pendor", "議會成員潘多爾", "entity name")
t("Wielding two huge steamguns this giant is amazingly elusive and agile for his size. Oh and very deadly!", "這位手拿兩把巨大的蒸汽槍的巨人卻表現出令人吃驚的敏捷和難以捉摸。十分致命！", "_t")
t("Council Member Palaquie", "議會成員帕拉奎", "entity name")
t("Standing proud, the giantess wields both a steamgun and a mindstar, as the bullets fly you can feel a powerful mental pressure on your mind, numbing you.", "這位女巨人驕傲的站在你面前，手中拿着蒸汽槍和靈晶，當子彈飛來時，你感覺一股強大的精神力向你衝來。", "_t")
t("Council Member Tantalos", "議會成員坦塔羅斯", "entity name")
t("It seems like a safe assumption that the highest elected official of the Atmos Tribe was not always a hideous, titanic abomination, reminiscent of the few images of Sher'Tul you have seen, with a combination of unnatural appearance and sickening gurgling noises that revulses you on every level from intellectual and moral disgust, all the way down to a primal instinct that roars wordlessly in your mind with a fear and hatred older than any language.  If he was, his campaign's gerrymandering talents must have been legendary.", "我們應該假設氣之部族的最高官員應該並不是一個面目可憎的巨大怪物。他讓你聯想起你對夏·圖爾人的模糊印象，但這不自然的外觀和令人作嘔的咕嚕聲讓你從理性到情感的每一個層面都充滿厭惡。憎惡這種恐怖生物的原始本能似乎潛藏於你的心靈中，比一切語言都要古老。如果他真的是的話…好吧，他還真是個賄選高手。", "_t")
t("construct", "機關", "entity type")
t("mechanical", "機械", "entity subtype")
t("steam defence turret", "蒸汽防禦炮臺", "entity name")
t([[This appears to be mechanized pedestal.
Two steamguns mounted on its top constantly swivel back and forth, seeking enemies of the Atmos.]], [[這似乎是機械化的底座。
兩個蒸汽槍安裝在它的頂部，不斷來回旋轉，尋找氣之部族的敵人。]], "_t")

