t("Ruined Cave", "廢棄洞穴", "_t")
t("This cave looks very solid and stable. You can probably leave items here for later.", "這個洞穴看起來非常堅固和穩定。你可以把東西留在這裏，以供以後使用。", "_t")

------------------------------------------------
section "tome-orcs/data/zones/slumbering-caves/npcs.lua"

t("Amakthel's Hand", "阿馬克泰爾的頭部", "entity name")
t("god", "神", "entity type")
t("eyal", "埃亞爾", "entity subtype")
t([[You never thought this could even exist. You certainly never thought you'd encounter it. But this is true, in front of you stands a piece of Amakthel himself.
The god that myths say was slain by the Sher'tul, themselves nothing but a myth.
But there it is, half alive, half dead but you can feel his thoughts in your head, there is no mistake: #{bold}#The Dead God is here!#{normal}#]], [[你從沒想象這樣的事情居然會發生，你不相信你居然會遇到它。但是這是真的，在你面前矗立着的就是阿馬克泰爾肢體的一部分。
神話說，夏·圖爾人殺死了阿馬克泰爾，他們已經消逝在神話中。
但是他就在這裏，處於生死交接的沉眠中。你可以在腦海中感受到他的思維，沒有錯：#{bold}#已死之神就在這裏！#{normal}#]], "_t")
t("Amakthel's Mouth", "阿馬克泰爾的嘴", "entity name")
t("#PURPLE#%s shouts: 'YOU DO NOT GET AWAY!'", "#PURPLE#%s叫着: '你逃不掉的!'", "saySimple")
t("#PURPLE#%s shouts: 'YOU DO NOT GET AWAY!'", "#PURPLE#%s叫着: '你逃不掉的!'", "log")
t("Amakthel's Eye", "阿馬克泰爾的眼睛", "entity name")
t("spiked tentacle", "尖刺觸手", "entity name")
t("A huge tentacle, ready to crush you with its many spikes.", "一個巨大的觸手，準備用他的尖刺粉碎你。", "_t")
t("oozing tentacle", " 粘液觸手。", "entity name")
t("Ooze pours out of this disgusting tentacle.", "粘液從這個噁心的觸手中滲出。", "_t")
t("eyed tentacle", "帶眼觸手", "entity name")
t("A single malevolent eye is set atop this tentacle. And it watches you.", "觸手上長着一隻惡毒的眼睛。它正緊盯着你。", "_t")
t("Sher'Tul High Priest", "夏·圖爾高階祭司", "entity name")
t("shertul", "夏·圖爾", "entity subtype")
t("So they do exist! Sher'Tul! The stuff of myth and legends. The stuff of terror. The stuff of nightmares. The stuff of unlimited power. The race that turned on the gods of old and actually won. This one seems intent on resurrecting Amakthel, the most powerful of all the gods. You do not know why but this cannot happen or all Orcs, and the world, will be doomed.", "夏·圖爾人！他們是存在的！神話和傳奇的來源，遠古的恐怖和噩夢，擁有無盡力量的強大生物，他們的種族曾經戰勝了古神。這隻夏·圖爾人似乎想要復活阿馬克泰爾，最強的神。你不知道他爲什麼要這麼做，但你知道，如果他的陰謀得逞，獸人乃至整個世界都會遭受滅頂之災。", "_t")
t("#CRIMSON#%s awakens and empowers %s!", "#CRIMSON#%s醒來了，強化了%s！", "saySimple")

------------------------------------------------
section "tome-orcs/data/zones/slumbering-caves/objects.lua"

t("a journal", "一份記錄", "entity name")
t("A journal.", "一份記錄。", "_t")
t("Gardanion, the Light of God", "Gardanion，神之光輝", "entity name")
t("pure white amulet", "純白項鍊", "_t")
t([["#{italic}#When Amakthel arrived, he created the Sun and brought life to this world.
You carry a piece of His Sun with you now. Do not forget who gave it to you, lest you become like those wretched fools who would forsake Him.#{normal}#"]], [["#{italic}#阿馬克泰爾降臨，他創造了太陽，爲世界帶來生命。
現在，你帶着他的一片太陽。不要忘了是誰將它給予你，以免讓你變成和那些拋棄他的可憐蟲一樣。#{normal}#"]], "_t")
t("When worn, gives you an additional prodigy point.", "裝備時，獲得一點覺醒技能點。", "_t")
t("#GOLD#The light of the Amulet envelops you, then subsides. You feel stronger. (+1 Prodigy Points)", "#GOLD#神的光輝充盈着你的全身，然後漸漸消退。你感覺更加強大了。(+1覺醒點)", "logPlayer")
t("#GOLD#The light of the Amulet envelops you, then subsides. You feel stronger. (+1 Prodigy Points)", "#GOLD#神的光輝充盈着你的全身，然後漸漸消退。你感覺更加強大了。(+1覺醒點)", "saySimple")

