section "tome-orcs/data/zones/sunwall-observatory/npcs.lua"

t("elf", "精靈", "entity subtype")
t("Star Gazer", "觀星者", "entity name")
t("This astromancer radiates the power of all celestial bodies. You can discern a distinct elven shape under the hood and robes.", "這個星術師放射着天體的強大能量。你可以在飛舞的長袍下面前辨認出精靈的身形。", "_t")
t("Astral-Infused Yeti", "星辰雪人", "entity name")
t("You wonder how this yeti can have wandered so far from its native habitat in the Clork Peninsula. You also wonder what happened to it that produced the celestial energies-wielding creature you angrily marching towards you.", "你想知道爲什麼雪人會從它在克拉克半島的棲息地跋山涉水來到這裏。你還想知道爲什麼這個被注入了強大的天空力量的雪人會憤怒地向你衝來。", "_t")

------------------------------------------------
section "tome-orcs/data/zones/sunwall-observatory/objects.lua"

t("a journal", "一份記錄", "entity name")
t("A journal.", "一份記錄。", "_t")
t("Cap of the Undisturbed Mind", "平靜思維之帽", "entity name")
t("red cap", "紅色的帽子", "_t")
t([[To prevent losing your mental health when gazing at the horrors of the Void there are still living brain tissues embedded into this cap.
With it you can spend your time stargazing without fear.]], [[爲了避免在凝視恐怖的虛空時損傷精神，這頂帽子上鑲嵌有存活的大腦組織。
帶上它，你能隨意仰望星空。]], "_t")
t("Allows you to resist the most terrible assaults on your mind.", "讓你抵抗最可怕的精神攻擊。", "_t")
