t("#FFD700#St. power#FFFFFF#: ", "#FFD700#蒸汽強度#FFFFFF#: ", "_t")
t("Kruk Invasion", "克魯克入侵", "_t")
t("You can not recall until you have placed the bomb at the tunnel's end!", "你只有在隧道盡頭防止炸彈之後，才能啓用迴歸之杖。", "_t")
t("scroll", "卷軸", "_t")
t("This parchment contains some lore.", "這張卷軸裏包含了一些手札。", "_t")
t("time-warped paper scrap", "被時間扭曲的紙片", "_t")
